/**
 * Tests that {@link UpdateTeamScoreFn} {@link org.apache.beam.sdk.transforms.DoFn} outputs
 * correctly per window and per key.
 */
@Test
public void testScoreUpdatesPerWindow() {
    TestStream<KV<String, GameActionInfo>> createEvents = TestStream.create(KvCoder.of(StringUtf8Coder.of(), AvroCoder.of(GameActionInfo.class))).advanceWatermarkTo(baseTime).addElements(event(TestUser.RED_ONE, 50, Duration.standardMinutes(1)), event(TestUser.RED_TWO, 50, Duration.standardMinutes(2)), event(TestUser.RED_ONE, 50, Duration.standardMinutes(3)), event(TestUser.RED_ONE, 60, Duration.standardMinutes(6)), event(TestUser.RED_TWO, 60, Duration.standardMinutes(7))).advanceWatermarkToInfinity();
    Duration teamWindowDuration = Duration.standardMinutes(5);
    PCollection<KV<String, Integer>> teamScores = p.apply(createEvents).apply(Window.<KV<String, GameActionInfo>>into(FixedWindows.of(teamWindowDuration))).apply(ParDo.of(new UpdateTeamScoreFn(100)));
    String redTeam = TestUser.RED_ONE.getTeam();
    IntervalWindow window1 = new IntervalWindow(baseTime, teamWindowDuration);
    IntervalWindow window2 = new IntervalWindow(window1.end(), teamWindowDuration);
    PAssert.that(teamScores).inWindow(window1).containsInAnyOrder(KV.of(redTeam, 100));
    PAssert.that(teamScores).inWindow(window2).containsInAnyOrder(KV.of(redTeam, 120));
    p.run().waitUntilFinish();
}

