@Test
public void testPipelineMetrics() throws IOException {
    DefaultPipelineLauncher launcher = DefaultPipelineLauncher.builder(null).build();
    final String timeMetrics = "run_time";
    final String counterMetrics = "counter";
    final long numElements = 1000L;
    pipeline.apply(GenerateSequence.from(0).to(numElements)).apply(ParDo.of(new TimeMonitor<>(IOLoadTestBase.BEAM_METRICS_NAMESPACE, timeMetrics))).apply(ParDo.of(new IOLoadTestBase.CountingFn<>(counterMetrics)));
    PipelineLauncher.LaunchConfig options = PipelineLauncher.LaunchConfig.builder("test-bigquery-write").setSdk(PipelineLauncher.Sdk.JAVA).setPipeline(pipeline).addParameter("runner", "DirectRunner").build();
    PipelineLauncher.LaunchInfo launchInfo = launcher.launch("", "", options);
    long currentTime = System.currentTimeMillis();
    long startTime = launcher.getBeamMetric(launchInfo.jobId(), PipelineMetricsType.STARTTIME, timeMetrics);
    long endTime = launcher.getBeamMetric(launchInfo.jobId(), PipelineMetricsType.ENDTIME, timeMetrics);
    long runTime = launcher.getBeamMetric(launchInfo.jobId(), PipelineMetricsType.RUNTIME, timeMetrics);
    long count = launcher.getBeamMetric(launchInfo.jobId(), PipelineMetricsType.COUNTER, counterMetrics);
    // check the validity of time metrics: start time and end time metrics is within 1 minute of
    // current
    assertTrue(String.format("start time metrics (%s) is not around current time", Instant.ofEpochMilli(startTime)), Math.abs(startTime - currentTime) < 10_000);
    assertTrue(String.format("start time metrics (%s) is not around current time", Instant.ofEpochMilli(endTime)), Math.abs(endTime - currentTime) < 10_000);
    assertTrue("run time should be greater than 0", runTime > 0);
    assertEquals(numElements, count);
}

