@Test
public void testSpannerWriteAndRead() throws IOException {
    PipelineLauncher.LaunchInfo writeInfo = testWrite();
    PipelineOperator.Result writeResult = pipelineOperator.waitUntilDone(createConfig(writeInfo, Duration.ofMinutes(configuration.pipelineTimeout)));
    assertNotEquals(PipelineOperator.Result.LAUNCH_FAILED, writeResult);
    PipelineLauncher.LaunchInfo readInfo = testRead();
    PipelineOperator.Result result = pipelineOperator.waitUntilDone(createConfig(readInfo, Duration.ofMinutes(configuration.pipelineTimeout)));
    assertNotEquals(PipelineOperator.Result.LAUNCH_FAILED, result);
    assertEquals(PipelineLauncher.JobState.DONE, pipelineLauncher.getJobStatus(project, region, readInfo.jobId()));
    double numRecords = pipelineLauncher.getMetric(project, region, readInfo.jobId(), getBeamMetricsName(PipelineMetricsType.COUNTER, READ_ELEMENT_METRIC_NAME));
    assertEquals(configuration.numRecords, numRecords, 0.5);
    // export metrics
    MetricsConfiguration metricsConfig = MetricsConfiguration.builder().setInputPCollection("Map records.out0").setInputPCollectionV2("Map records/ParMultiDo(GenerateMutations).out0").setOutputPCollection("Counting element.out0").setOutputPCollectionV2("Counting element/ParMultiDo(Counting).out0").build();
    try {
        exportMetricsToBigQuery(writeInfo, getMetrics(writeInfo, metricsConfig));
        exportMetricsToBigQuery(readInfo, getMetrics(readInfo, metricsConfig));
    } catch (ParseException | InterruptedException e) {
        throw new RuntimeException(e);
    }
}

/**
 * Run stress test with configurations specified by TestProperties.
 */
@Test
public void runTest() throws IOException, ParseException, InterruptedException {
    if (configuration.exportMetricsToInfluxDB) {
        influxDBSettings = InfluxDBSettings.builder().withHost(configuration.influxHost).withDatabase(configuration.influxDatabase).withMeasurement(configuration.influxMeasurement + "_" + testConfigName).get();
    }
    PipelineLauncher.LaunchInfo writeInfo = generateDataAndWrite();
    PipelineOperator.Result writeResult = pipelineOperator.waitUntilDone(createConfig(writeInfo, Duration.ofMinutes(configuration.pipelineTimeout)));
    assertNotEquals(PipelineOperator.Result.LAUNCH_FAILED, writeResult);
    PipelineLauncher.LaunchInfo readInfo = readData();
    PipelineOperator.Result readResult = pipelineOperator.waitUntilDone(createConfig(readInfo, Duration.ofMinutes(configuration.pipelineTimeout)));
    assertNotEquals(PipelineOperator.Result.LAUNCH_FAILED, readResult);
    try {
        double writeNumRecords = pipelineLauncher.getMetric(project, region, writeInfo.jobId(), getBeamMetricsName(PipelineMetricsType.COUNTER, WRITE_ELEMENT_METRIC_NAME));
        double readNumRecords = pipelineLauncher.getMetric(project, region, readInfo.jobId(), getBeamMetricsName(PipelineMetricsType.COUNTER, READ_ELEMENT_METRIC_NAME));
        // Assert that writeNumRecords equals or greater than readNumRecords since there might be
        // duplicates when testing big amount of data
        assertTrue(writeNumRecords >= readNumRecords);
    } finally {
        // clean up write streaming pipeline
        if (pipelineLauncher.getJobStatus(project, region, writeInfo.jobId()) == PipelineLauncher.JobState.RUNNING) {
            pipelineLauncher.cancelJob(project, region, writeInfo.jobId());
        }
    }
    // export metrics
    MetricsConfiguration writeMetricsConfig = MetricsConfiguration.builder().setInputPCollection("Map records.out0").setInputPCollectionV2("Map records/ParMultiDo(GenerateMutations).out0").setOutputPCollection("Counting element.out0").setOutputPCollectionV2("Counting element/ParMultiDo(Counting).out0").build();
    MetricsConfiguration readMetricsConfig = MetricsConfiguration.builder().setOutputPCollection("Counting element.out0").setOutputPCollectionV2("Counting element/ParMultiDo(Counting).out0").build();
    exportMetrics(writeInfo, writeMetricsConfig, configuration.exportMetricsToInfluxDB, influxDBSettings);
    exportMetrics(readInfo, readMetricsConfig, configuration.exportMetricsToInfluxDB, influxDBSettings);
}

