@Test
public void testTextIOWriteThenRead() throws IOException {
    TextIO.TypedWrite<String, Object> write = TextIO.write().to(filePrefix).withOutputFilenames().withCompression(Compression.valueOf(configuration.compressionType));
    if (configuration.numShards > 0) {
        write = write.withNumShards(configuration.numShards);
    }
    writePipeline.apply("Read from source", Read.from(new SyntheticBoundedSource(configuration))).apply("Map records", ParDo.of(new MapKVToString())).apply("Write content to files", write);
    readPipeline.apply(TextIO.read().from(filePrefix + "*")).apply("Counting element", ParDo.of(new CountingFn<>(READ_ELEMENT_METRIC_NAME)));
    PipelineLauncher.LaunchConfig writeOptions = PipelineLauncher.LaunchConfig.builder("write-textio").setSdk(PipelineLauncher.Sdk.JAVA).setPipeline(writePipeline).addParameter("runner", configuration.runner).addParameter("maxNumWorkers", TestProperties.getProperty("maxNumWorkers", "10", TestProperties.Type.PROPERTY)).build();
    PipelineLauncher.LaunchInfo writeInfo = pipelineLauncher.launch(project, region, writeOptions);
    PipelineOperator.Result writeResult = pipelineOperator.waitUntilDone(createConfig(writeInfo, Duration.ofMinutes(configuration.pipelineTimeout)));
    // Fail the test if pipeline failed or timeout.
    assertThatResult(writeResult).isLaunchFinished();
    PipelineLauncher.LaunchConfig readOptions = PipelineLauncher.LaunchConfig.builder("read-textio").setSdk(PipelineLauncher.Sdk.JAVA).setPipeline(readPipeline).addParameter("runner", configuration.runner).addParameter("maxNumWorkers", TestProperties.getProperty("maxNumWorkers", "10", TestProperties.Type.PROPERTY)).build();
    PipelineLauncher.LaunchInfo readInfo = pipelineLauncher.launch(project, region, readOptions);
    PipelineOperator.Result readResult = pipelineOperator.waitUntilDone(createConfig(readInfo, Duration.ofMinutes(configuration.pipelineTimeout)));
    // Fail the test if pipeline failed or timeout.
    assertThatResult(readResult).isLaunchFinished();
    // check metrics
    double numRecords = pipelineLauncher.getMetric(project, region, readInfo.jobId(), getBeamMetricsName(PipelineMetricsType.COUNTER, READ_ELEMENT_METRIC_NAME));
    assertEquals(configuration.numRecords, numRecords, 0.5);
    // export metrics
    MetricsConfiguration metricsConfig = MetricsConfiguration.builder().setInputPCollection("Map records.out0").setInputPCollectionV2("Map records/ParMultiDo(MapKVToString).out0").setOutputPCollection("Counting element.out0").setOutputPCollectionV2("Counting element/ParMultiDo(Counting).out0").build();
    try {
        exportMetricsToBigQuery(writeInfo, getMetrics(writeInfo, metricsConfig));
        exportMetricsToBigQuery(readInfo, getMetrics(readInfo, metricsConfig));
    } catch (ParseException | InterruptedException e) {
        throw new RuntimeException(e);
    }
}

