}

@Test
public void testDeltaAndCumulative() {
    cell.add("a");
    cell.add("b", "c");
    cell.add("b", "d");
    cell.add("a", "a");
    BoundedTrieData cumulative = cell.getCumulative();
    assertEquals(BoundedTrieResult.create(ImmutableSet.of(Arrays.asList("a", "a", String.valueOf(false)), Arrays.asList("b", "d", String.valueOf(false)), Arrays.asList("b", "c", String.valueOf(false)))), cumulative.extractResult());
    assertThat(cell.getDirty().beforeCommit(), equalTo(true));
    cell.getDirty().afterCommit();
    assertThat(cell.getDirty().beforeCommit(), equalTo(false));
    // adding new value changes the cell
    cell.add("b", "a");
    BoundedTrieData newCumulative = cell.getCumulative();
    assertEquals(newCumulative.extractResult(), BoundedTrieResult.create(ImmutableSet.of(Arrays.asList("a", "a", String.valueOf(false)), Arrays.asList("b", "d", String.valueOf(false)), Arrays.asList("b", "c", String.valueOf(false)), Arrays.asList("b", "a", String.valueOf(false)))));
    // but not previously obtained cumulative value
    assertEquals(cumulative.extractResult(), BoundedTrieResult.create(ImmutableSet.of(Arrays.asList("a", "a", String.valueOf(false)), Arrays.asList("b", "d", String.valueOf(false)), Arrays.asList("b", "c", String.valueOf(false)))));
    assertThat("Adding a new value made the cell dirty", cell.getDirty().beforeCommit(), equalTo(true));
}

