@Test
public void testBoundedTrieDataCombine() {
    BoundedTrieData empty = new BoundedTrieData();
    BoundedTrieData singletonA = new BoundedTrieData(ImmutableList.of("a", "a"));
    BoundedTrieData singletonB = new BoundedTrieData(ImmutableList.of("b", "b"));
    BoundedTrieNode lotsRoot = new BoundedTrieNode();
    lotsRoot.addAll(Arrays.asList(Arrays.asList("c", "c"), Arrays.asList("d", "d")));
    BoundedTrieData lots = new BoundedTrieData(lotsRoot);
    assertEquals(BoundedTrieResult.empty(), empty.extractResult());
    empty = empty.combine(singletonA);
    assertEquals(BoundedTrieResult.create(ImmutableSet.of(Arrays.asList("a", "a", String.valueOf(false)))), empty.extractResult());
    singletonA = singletonA.combine(empty);
    assertEquals(BoundedTrieResult.create(ImmutableSet.of(Arrays.asList("a", "a", String.valueOf(false)))), singletonA.extractResult());
    singletonA = singletonA.combine(singletonB);
    assertEquals(BoundedTrieResult.create(ImmutableSet.of(Arrays.asList("a", "a", String.valueOf(false)), Arrays.asList("b", "b", String.valueOf(false)))), singletonA.extractResult());
    singletonA = singletonA.combine(lots);
    assertEquals(BoundedTrieResult.create(ImmutableSet.of(Arrays.asList("a", "a", String.valueOf(false)), Arrays.asList("b", "b", String.valueOf(false)), Arrays.asList("c", "c", String.valueOf(false)), Arrays.asList("d", "d", String.valueOf(false)))), singletonA.extractResult());
    lots = lots.combine(singletonA);
    assertEquals(BoundedTrieResult.create(ImmutableSet.of(Arrays.asList("a", "a", String.valueOf(false)), Arrays.asList("b", "b", String.valueOf(false)), Arrays.asList("c", "c", String.valueOf(false)), Arrays.asList("d", "d", String.valueOf(false)))), lots.extractResult());
}

