@Test
public void testCounterDeltas() {
    MetricsContainerImpl container = new MetricsContainerImpl("step1");
    CounterCell c1 = container.getCounter(MetricName.named("ns", "name1"));
    CounterCell c2 = container.getCounter(MetricName.named("ns", "name2"));
    assertThat("All counters should not start dirty", container.getUpdates().counterUpdates(), emptyIterable());
    c1.inc(5L);
    assertThat("Dirty counter should be committed", container.getUpdates().counterUpdates(), containsInAnyOrder(metricUpdate("name1", 5L)));
    container.commitUpdates();
    assertThat("After commit no counters should be dirty", container.getUpdates().counterUpdates(), emptyIterable());
    c1.inc(5L);
    c2.inc(4L);
    assertThat(container.getUpdates().counterUpdates(), containsInAnyOrder(metricUpdate("name1", 10L), metricUpdate("name2", 4L)));
    assertThat("Since we haven't committed, updates are still included", container.getUpdates().counterUpdates(), containsInAnyOrder(metricUpdate("name1", 10L), metricUpdate("name2", 4L)));
    container.commitUpdates();
    assertThat("After commit there are no updates", container.getUpdates().counterUpdates(), emptyIterable());
    c1.inc(8L);
    assertThat(container.getUpdates().counterUpdates(), contains(metricUpdate("name1", 18L)));
    CounterCell dne = container.tryGetCounter(MetricName.named("ns", "dne"));
    assertEquals(dne, null);
}

