@Test
public void testReset() {
    MetricsContainerStepMap attemptedMetrics = new MetricsContainerStepMap();
    attemptedMetrics.update(STEP1, metricsContainer);
    attemptedMetrics.update(STEP2, metricsContainer);
    attemptedMetrics.update(STEP2, metricsContainer);
    MetricResults metricResults = asAttemptedOnlyMetricResults(attemptedMetrics);
    MetricQueryResults allres = metricResults.allMetrics();
    assertCounter(COUNTER_NAME, allres, STEP1, VALUE, false);
    assertDistribution(DISTRIBUTION_NAME, allres, STEP1, DistributionResult.create(VALUE * 3, 2, VALUE, VALUE * 2), false);
    assertGauge(GAUGE_NAME, allres, STEP1, GaugeResult.create(VALUE, Instant.now()), false);
    assertStringSet(STRING_SET_NAME, allres, STEP1, StringSetResult.create(ImmutableSet.of(FIRST_STRING, SECOND_STRING)), false);
    assertBoundedTrie(BOUNDED_TRIE_NAME, allres, STEP1, BoundedTrieResult.create(ImmutableSet.of(ImmutableList.of(FIRST_STRING, SECOND_STRING, String.valueOf(false)))), false);
    assertCounter(COUNTER_NAME, allres, STEP2, VALUE * 2, false);
    assertDistribution(DISTRIBUTION_NAME, allres, STEP2, DistributionResult.create(VALUE * 6, 4, VALUE, VALUE * 2), false);
    assertGauge(GAUGE_NAME, allres, STEP2, GaugeResult.create(VALUE, Instant.now()), false);
    assertStringSet(STRING_SET_NAME, allres, STEP2, StringSetResult.create(ImmutableSet.of(FIRST_STRING, SECOND_STRING)), false);
