@Test
public void testUserDistribution() throws Exception {
    SimpleMonitoringInfoBuilder builder = new SimpleMonitoringInfoBuilder();
    builder.setUrn(MonitoringInfoConstants.Urns.USER_DISTRIBUTION_INT64);
    builder.setLabel(MonitoringInfoConstants.Labels.NAME, "myName");
    builder.setLabels(ImmutableMap.of(MonitoringInfoConstants.Labels.NAMESPACE, "myNamespace", MonitoringInfoConstants.Labels.PTRANSFORM, "myStep"));
    assertNull(builder.build());
    builder.setInt64DistributionValue(DistributionData.create(10, 2, 1, 9));
    // Pass now that the spec is fully met.
    MonitoringInfo monitoringInfo = builder.build();
    assertTrue(monitoringInfo != null);
    assertEquals(MonitoringInfoConstants.Urns.USER_DISTRIBUTION_INT64, monitoringInfo.getUrn());
    assertEquals("myName", monitoringInfo.getLabelsOrDefault(MonitoringInfoConstants.Labels.NAME, ""));
    assertEquals("myNamespace", monitoringInfo.getLabelsOrDefault(MonitoringInfoConstants.Labels.NAMESPACE, ""));
    assertEquals(MonitoringInfoConstants.TypeUrns.DISTRIBUTION_INT64_TYPE, monitoringInfo.getType());
    DistributionData data = MonitoringInfoEncodings.decodeInt64Distribution(monitoringInfo.getPayload());
    assertEquals(10L, data.sum());
    assertEquals(2L, data.count());
    assertEquals(9L, data.max());
    assertEquals(1L, data.min());
}

@Test
public void testExecutionTimeUrnsBuildMonitoringInfos() throws Exception {
    String testPTransformId = "pTransformId";
    HashMap<String, String> labelsMetadata = new HashMap<String, String>();
    labelsMetadata.put(MonitoringInfoConstants.Labels.PTRANSFORM, testPTransformId);
    SimpleExecutionState startState = new SimpleExecutionState(ExecutionStateTracker.START_STATE_NAME, MonitoringInfoConstants.Urns.START_BUNDLE_MSECS, labelsMetadata);
    SimpleExecutionState processState = new SimpleExecutionState(ExecutionStateTracker.PROCESS_STATE_NAME, MonitoringInfoConstants.Urns.PROCESS_BUNDLE_MSECS, labelsMetadata);
    SimpleExecutionState finishState = new SimpleExecutionState(ExecutionStateTracker.FINISH_STATE_NAME, MonitoringInfoConstants.Urns.FINISH_BUNDLE_MSECS, labelsMetadata);
    SimpleStateRegistry testObject = new SimpleStateRegistry();
    testObject.register(startState);
    testObject.register(processState);
    testObject.register(finishState);
    List<MonitoringInfo> testOutput = testObject.getExecutionTimeMonitoringInfos();
    List<Matcher<MonitoringInfo>> matchers = new ArrayList<Matcher<MonitoringInfo>>();
    SimpleMonitoringInfoBuilder builder = new SimpleMonitoringInfoBuilder();
    builder.setUrn(MonitoringInfoConstants.Urns.START_BUNDLE_MSECS);
    builder.setInt64SumValue(0);
    builder.setLabel(MonitoringInfoConstants.Labels.PTRANSFORM, testPTransformId);
    matchers.add(MonitoringInfoMatchers.matchSetFields(builder.build()));
    // Check for execution time metrics for the testPTransformId
    builder = new SimpleMonitoringInfoBuilder();
    builder.setUrn(MonitoringInfoConstants.Urns.PROCESS_BUNDLE_MSECS);
    builder.setInt64SumValue(0);
    builder.setLabel(MonitoringInfoConstants.Labels.PTRANSFORM, testPTransformId);
    matchers.add(MonitoringInfoMatchers.matchSetFields(builder.build()));
    builder = new SimpleMonitoringInfoBuilder();
    builder.setUrn(MonitoringInfoConstants.Urns.FINISH_BUNDLE_MSECS);
    builder.setInt64SumValue(0);
    builder.setLabel(MonitoringInfoConstants.Labels.PTRANSFORM, testPTransformId);
    matchers.add(MonitoringInfoMatchers.matchSetFields(builder.build()));
    for (Matcher<MonitoringInfo> matcher : matchers) {
        assertThat(testOutput, Matchers.hasItem(matcher));
    }
}

