@Test
public void testDeltaAndCumulative() {
    cell.add("pubsub");
    cell.add("bq", "spanner");
    assertEquals(cell.getCumulative().stringSet(), ImmutableSet.of("spanner", "pubsub", "bq"));
    assertEquals("getCumulative is idempotent", cell.getCumulative().stringSet(), ImmutableSet.of("spanner", "pubsub", "bq"));
    assertThat(cell.getDirty().beforeCommit(), equalTo(true));
    cell.getDirty().afterCommit();
    assertThat(cell.getDirty().beforeCommit(), equalTo(false));
    cell.add("gcs");
    assertEquals(cell.getCumulative().stringSet(), ImmutableSet.of("spanner", "pubsub", "bq", "gcs"));
    assertThat("Adding a new value made the cell dirty", cell.getDirty().beforeCommit(), equalTo(true));
}

