/**
 * Demonstrates that attempting to output an element before the timestamp of the current element
 * with zero {@link DoFn#getAllowedTimestampSkew() allowed timestamp skew} throws.
 */
@Test
public void testBackwardsInTimeNoSkew() {
    SkewingDoFn fn = new SkewingDoFn(Duration.ZERO);
    DoFnRunner<Duration, Duration> runner = new SimpleDoFnRunner<>(null, fn, NullSideInputReader.empty(), new ListOutputManager(), new TupleTag<>(), Collections.emptyList(), mockStepContext, null, Collections.emptyMap(), WindowingStrategy.of(new GlobalWindows()), DoFnSchemaInformation.create(), Collections.emptyMap());
    runner.startBundle();
    // An element output at the current timestamp is fine.
    runner.processElement(WindowedValues.timestampedValueInGlobalWindow(Duration.ZERO, new Instant(0)));
    Exception exception = assertThrows(UserCodeException.class, () -> {
        // An element output before (current time - skew) is forbidden
        runner.processElement(WindowedValues.timestampedValueInGlobalWindow(Duration.millis(1L), new Instant(0)));
    });
    assertThat(exception.getCause(), isA(IllegalArgumentException.class));
    assertThat(exception.getMessage(), allOf(containsString("must be no earlier"), containsString(String.format("timestamp of the current input or timer (%s)", new Instant(0).toString())), containsString(String.format("the allowed skew (%s)", PeriodFormat.getDefault().print(Duration.ZERO.toPeriod())))));
}

