/**
 * Demonstrates that getWatermark for a transform that takes multiple inputs is held to the
 * minimum watermark across all of its inputs.
 */
@Test
public void getWatermarkForMultiInputTransform() {
    CommittedBundle<byte[]> secondPcollectionBundle = multiWindowedBundle(impulseToFlatten, new byte[1]);
    manager.updateWatermarks(null, TimerUpdate.empty(), graph.getProducer(impulseToFlatten), null, Collections.<CommittedBundle<?>>singleton(secondPcollectionBundle), BoundedWindow.TIMESTAMP_MAX_VALUE);
    manager.refreshAll();
    // We didn't do anything for the first source, so we shouldn't have progressed the watermark
    TransformWatermarks firstSourceWatermark = manager.getWatermarks(graph.getProducer(impulse));
    assertThat(firstSourceWatermark.getOutputWatermark(), not(greaterThan(BoundedWindow.TIMESTAMP_MIN_VALUE)));
    // the Second Source output all of the elements so it should be done (with a watermark at the
    // end of time).
    TransformWatermarks secondSourceWatermark = manager.getWatermarks(graph.getProducer(impulseToFlatten));
    assertThat(secondSourceWatermark.getOutputWatermark(), not(lessThan(BoundedWindow.TIMESTAMP_MAX_VALUE)));
    // We haven't consumed anything yet, so our watermark should be at the beginning of time
    TransformWatermarks transformWatermark = manager.getWatermarks(graph.getProducer(flattened));
    assertThat(transformWatermark.getInputWatermark(), not(greaterThan(BoundedWindow.TIMESTAMP_MIN_VALUE)));
    assertThat(transformWatermark.getOutputWatermark(), not(greaterThan(BoundedWindow.TIMESTAMP_MIN_VALUE)));
    CommittedBundle<byte[]> flattenedBundleSecondCreate = multiWindowedBundle(flattened, new byte[1]);
    // We have finished processing the bundle from the second PCollection, but we haven't consumed
    // anything from the first PCollection yet; so our watermark shouldn't advance
    manager.updateWatermarks(secondPcollectionBundle, TimerUpdate.empty(), graph.getProducer(flattened), secondPcollectionBundle.withElements(Collections.emptyList()), Collections.<CommittedBundle<?>>singleton(flattenedBundleSecondCreate), BoundedWindow.TIMESTAMP_MAX_VALUE);
    TransformWatermarks transformAfterProcessing = manager.getWatermarks(graph.getProducer(flattened));
    manager.updateWatermarks(secondPcollectionBundle, TimerUpdate.empty(), graph.getProducer(flattened), secondPcollectionBundle.withElements(Collections.emptyList()), Collections.<CommittedBundle<?>>singleton(flattenedBundleSecondCreate), BoundedWindow.TIMESTAMP_MAX_VALUE);
    manager.refreshAll();
    assertThat(transformAfterProcessing.getInputWatermark(), not(greaterThan(BoundedWindow.TIMESTAMP_MIN_VALUE)));
    assertThat(transformAfterProcessing.getOutputWatermark(), not(greaterThan(BoundedWindow.TIMESTAMP_MIN_VALUE)));
    Instant firstCollectionTimestamp = new Instant(10000);
    CommittedBundle<byte[]> firstPcollectionBundle = timestampedBundle(impulse, TimestampedValue.of(new byte[5], firstCollectionTimestamp));
    // the source is done, but elements are still buffered. The source output watermark should be
    // past the end of the global window
    manager.updateWatermarks(null, TimerUpdate.empty(), graph.getProducer(impulse), null, Collections.<CommittedBundle<?>>singleton(firstPcollectionBundle), BoundedWindow.TIMESTAMP_MAX_VALUE);
    manager.refreshAll();
    TransformWatermarks firstSourceWatermarks = manager.getWatermarks(graph.getProducer(impulse));
    assertThat(firstSourceWatermarks.getOutputWatermark(), not(lessThan(BoundedWindow.TIMESTAMP_MAX_VALUE)));
    // We still haven't consumed any of the first source's input, so the watermark should still not
    // progress
    TransformWatermarks flattenAfterSourcesProduced = manager.getWatermarks(graph.getProducer(flattened));
    assertThat(flattenAfterSourcesProduced.getInputWatermark(), not(greaterThan(firstCollectionTimestamp)));
    assertThat(flattenAfterSourcesProduced.getOutputWatermark(), not(greaterThan(firstCollectionTimestamp)));
    // We have buffered inputs, but since the PCollection has all of the elements (has a WM past the
    // end of the global window), we should have a watermark equal to the min among buffered
    // elements
    TransformWatermarks withBufferedElements = manager.getWatermarks(graph.getProducer(flattened));
    assertThat(withBufferedElements.getInputWatermark(), equalTo(firstCollectionTimestamp));
    assertThat(withBufferedElements.getOutputWatermark(), equalTo(firstCollectionTimestamp));
    CommittedBundle<?> completedFlattenBundle = bundleFactory.createBundle(flattened).commit(BoundedWindow.TIMESTAMP_MAX_VALUE);
    manager.updateWatermarks(firstPcollectionBundle, TimerUpdate.empty(), graph.getProducer(flattened), firstPcollectionBundle.withElements(Collections.emptyList()), Collections.<CommittedBundle<?>>singleton(completedFlattenBundle), BoundedWindow.TIMESTAMP_MAX_VALUE);
    manager.refreshAll();
    TransformWatermarks afterConsumingAllInput = manager.getWatermarks(graph.getProducer(flattened));
    assertThat(afterConsumingAllInput.getInputWatermark(), not(lessThan(BoundedWindow.TIMESTAMP_MAX_VALUE)));
    assertThat(afterConsumingAllInput.getOutputWatermark(), not(greaterThan(BoundedWindow.TIMESTAMP_MAX_VALUE)));
}

/**
 * Demonstrates that getWatermark for a transform that takes multiple inputs is held to the
 * minimum watermark across all of its inputs.
 */
@Test
public void getWatermarkMultiIdenticalInput() {
    PCollection<byte[]> impulse = p.apply(Impulse.create());
    PCollection<byte[]> multiConsumer = PCollectionList.of(impulse).and(impulse).apply(Flatten.pCollections());
    DirectGraphVisitor graphVisitor = new DirectGraphVisitor();
    p.traverseTopologically(graphVisitor);
    DirectGraph graph = graphVisitor.getGraph();
    AppliedPTransform<?, ?, ?> theFlatten = graph.getProducer(multiConsumer);
    WatermarkManager<AppliedPTransform<?, ?, ?>, ? super PCollection<?>> tstMgr = WatermarkManager.create(clock, graph, AppliedPTransform::getFullName);
    CommittedBundle<Void> root = bundleFactory.<Void>createRootBundle().add(WindowedValues.valueInGlobalWindow(null)).commit(clock.now());
    CommittedBundle<byte[]> createBundle = bundleFactory.createBundle(impulse).add(WindowedValues.timestampedValueInGlobalWindow(new byte[1], new Instant(33536))).commit(clock.now());
    Map<AppliedPTransform<?, ?, ?>, Collection<CommittedBundle<?>>> initialInputs = ImmutableMap.<AppliedPTransform<?, ?, ?>, Collection<CommittedBundle<?>>>builder().put(graph.getProducer(impulse), Collections.singleton(root)).build();
    tstMgr.initialize((Map) initialInputs);
    tstMgr.updateWatermarks(root, TimerUpdate.empty(), graph.getProducer(impulse), null, Collections.singleton(createBundle), BoundedWindow.TIMESTAMP_MAX_VALUE);
    tstMgr.refreshAll();
    TransformWatermarks flattenWms = tstMgr.getWatermarks(theFlatten);
    assertThat(flattenWms.getInputWatermark(), equalTo(new Instant(33536)));
    tstMgr.updateWatermarks(createBundle, TimerUpdate.empty(), theFlatten, null, Collections.emptyList(), BoundedWindow.TIMESTAMP_MAX_VALUE);
    tstMgr.refreshAll();
    assertThat(flattenWms.getInputWatermark(), equalTo(new Instant(33536)));
    tstMgr.updateWatermarks(createBundle, TimerUpdate.empty(), theFlatten, null, Collections.emptyList(), BoundedWindow.TIMESTAMP_MAX_VALUE);
