    CommittedBundle<byte[]> impulseBundle = timestampedBundle(impulse, TimestampedValue.of(new byte[1], new Instant(1_000_000L)), TimestampedValue.of(new byte[2], new Instant(1234L)), TimestampedValue.of(new byte[3], new Instant(-1000L)));
