    CommittedBundle<KV<String, byte[]>> keyBundle = timestampedBundle(keyed, TimestampedValue.of(KV.of("MyKey", new byte[1]), new Instant(1_000_000L)), TimestampedValue.of(KV.of("MyKey", new byte[2]), new Instant(1234L)), TimestampedValue.of(KV.of("MyKey", new byte[3]), new Instant(-1000L)));
