/**
 * Demonstrates that updateWatermarks in the presence of late data is monotonic.
 */
@Test
public void updateWatermarkWithLateData() {
    Instant sourceWatermark = new Instant(1_000_000L);
    CommittedBundle<byte[]> impulseBundle = timestampedBundle(impulse, TimestampedValue.of(new byte[1], sourceWatermark), TimestampedValue.of(new byte[2], new Instant(1234L)));
    manager.updateWatermarks(null, TimerUpdate.empty(), graph.getProducer(impulse), null, Collections.<CommittedBundle<?>>singleton(impulseBundle), sourceWatermark);
    CommittedBundle<KV<String, byte[]>> keyBundle = timestampedBundle(keyed, TimestampedValue.of(KV.of("MyKey", new byte[1]), sourceWatermark), TimestampedValue.of(KV.of("MyKey", new byte[2]), new Instant(1234L)));
    // Finish processing the on-time data. The watermarks should progress to be equal to the source
    manager.updateWatermarks(impulseBundle, TimerUpdate.empty(), graph.getProducer(keyed), impulseBundle.withElements(Collections.emptyList()), Collections.<CommittedBundle<?>>singleton(keyBundle), BoundedWindow.TIMESTAMP_MAX_VALUE);
    manager.refreshAll();
    TransformWatermarks onTimeWatermarks = manager.getWatermarks(graph.getProducer(keyed));
    assertThat(onTimeWatermarks.getInputWatermark(), equalTo(sourceWatermark));
    assertThat(onTimeWatermarks.getOutputWatermark(), equalTo(sourceWatermark));
    CommittedBundle<byte[]> lateDataBundle = timestampedBundle(impulse, TimestampedValue.of(new byte[3], new Instant(-1000L)));
    // the late data arrives in a downstream PCollection after its watermark has advanced past it;
    // we don't advance the watermark past the current watermark until we've consumed the late data
    manager.updateWatermarks(null, TimerUpdate.empty(), graph.getProducer(impulse), impulseBundle.withElements(Collections.emptyList()), Collections.<CommittedBundle<?>>singleton(lateDataBundle), new Instant(2_000_000L));
    manager.refreshAll();
    TransformWatermarks bufferedLateWm = manager.getWatermarks(graph.getProducer(impulse));
    assertThat(bufferedLateWm.getOutputWatermark(), equalTo(new Instant(2_000_000L)));
    // The input watermark should be held to its previous value (not advanced due to late data; not
    // moved backwards in the presence of watermarks due to monotonicity).
    TransformWatermarks lateDataBufferedWatermark = manager.getWatermarks(graph.getProducer(keyed));
    assertThat(lateDataBufferedWatermark.getInputWatermark(), not(lessThan(sourceWatermark)));
    assertThat(lateDataBufferedWatermark.getOutputWatermark(), not(lessThan(sourceWatermark)));
    CommittedBundle<KV<String, byte[]>> lateKeyedBundle = timestampedBundle(keyed, TimestampedValue.of(KV.of("MyKey", new byte[3]), new Instant(-1000L)));
    manager.updateWatermarks(lateDataBundle, TimerUpdate.empty(), graph.getProducer(keyed), lateDataBundle.withElements(Collections.emptyList()), Collections.<CommittedBundle<?>>singleton(lateKeyedBundle), BoundedWindow.TIMESTAMP_MAX_VALUE);
    manager.refreshAll();
}

