    newDoFnOperator.cleanUp();
    assertThat(stripStreamRecordFromWindowedValue(newHarness.getOutput()), contains(WindowedValues.valueInGlobalWindow("finishBundle"), WindowedValues.valueInGlobalWindow("d"), WindowedValues.valueInGlobalWindow("finishBundle")));
