@Test
public void testCheckpointBufferingWithMultipleBundles() throws Exception {
    FlinkPipelineOptions options = FlinkPipelineOptions.defaults();
    options.setMaxBundleSize(10L);
    options.setCheckpointingInterval(1L);
    options.setStreaming(true);
    TupleTag<String> outputTag = new TupleTag<>("main-output");
    StringUtf8Coder coder = StringUtf8Coder.of();
    WindowedValues.ValueOnlyWindowedValueCoder<String> windowedValueCoder = WindowedValues.getValueOnlyCoder(coder);
    DoFnOperator.MultiOutputOutputManagerFactory<String> outputManagerFactory = new DoFnOperator.MultiOutputOutputManagerFactory<>(outputTag, WindowedValues.getFullCoder(StringUtf8Coder.of(), GlobalWindow.Coder.INSTANCE), new SerializablePipelineOptions(options));
    Supplier<DoFnOperator<String, String, String>> doFnOperatorSupplier = () -> new DoFnOperator<>(new IdentityDoFn<>(), "stepName", windowedValueCoder, Collections.emptyMap(), outputTag, Collections.emptyList(), outputManagerFactory, WindowingStrategy.globalDefault(), new HashMap<>(), /* side-input mapping */
    Collections.emptyList(), /* side inputs */
    options, null, null, DoFnSchemaInformation.create(), Collections.emptyMap());
    DoFnOperator<String, String, String> doFnOperator = doFnOperatorSupplier.get();
    OneInputStreamOperatorTestHarness<WindowedValue<String>, WindowedValue<String>> testHarness = new OneInputStreamOperatorTestHarness<>(doFnOperator);
    testHarness.open();
    // start a bundle
    testHarness.processElement(new StreamRecord<>(WindowedValues.valueInGlobalWindow("regular element")));
    // This callback will be executed in the snapshotState function in the course of
    // finishing the currently active bundle. Everything emitted in the callback should
    // be buffered and not sent downstream.
    doFnOperator.setBundleFinishedCallback(() -> {
        try {
            // Clear this early for the test here because we want to finish the bundle from within
            // the callback which would otherwise cause an infinitive recursion
            doFnOperator.setBundleFinishedCallback(null);
            testHarness.processElement(new StreamRecord<>(WindowedValues.valueInGlobalWindow("trigger another bundle")));
            doFnOperator.invokeFinishBundle();
            testHarness.processElement(new StreamRecord<>(WindowedValues.valueInGlobalWindow("check that the previous element is not flushed")));
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    });
    OperatorSubtaskState snapshot = testHarness.snapshot(0, 0);
    // Check that we have only the element which was emitted before the snapshot
    assertThat(stripStreamRecordFromWindowedValue(testHarness.getOutput()), contains(WindowedValues.valueInGlobalWindow("regular element")));
    // Check that we would flush the buffered elements when continuing to run
    testHarness.processWatermark(Long.MAX_VALUE);
    assertThat(stripStreamRecordFromWindowedValue(testHarness.getOutput()), contains(WindowedValues.valueInGlobalWindow("regular element"), WindowedValues.valueInGlobalWindow("trigger another bundle"), WindowedValues.valueInGlobalWindow("check that the previous element is not flushed")));
    testHarness.close();
    // Check that we would flush the buffered elements when restoring from a checkpoint
    OneInputStreamOperatorTestHarness<WindowedValue<String>, WindowedValue<String>> testHarness2 = new OneInputStreamOperatorTestHarness<>(doFnOperatorSupplier.get());
    testHarness2.initializeState(snapshot);
    testHarness2.open();
    testHarness2.processElement(new StreamRecord<>(WindowedValues.valueInGlobalWindow("after restore")));
    assertThat(stripStreamRecordFromWindowedValue(testHarness2.getOutput()), contains(WindowedValues.valueInGlobalWindow("trigger another bundle"), WindowedValues.valueInGlobalWindow("check that the previous element is not flushed"), WindowedValues.valueInGlobalWindow("after restore")));
}

