@Test
public void testWatermark() throws Exception {
    ManuallyTriggeredScheduledExecutorService executor = new ManuallyTriggeredScheduledExecutorService();
    try (FlinkUnboundedSourceReader<KV<Integer, Integer>> reader = (FlinkUnboundedSourceReader<KV<Integer, Integer>>) createReader(executor, -1L)) {
        List<FlinkSourceSplit<KV<Integer, Integer>>> splits = createSplits(2, 10, 0);
        RecordsValidatingOutput validatingOutput = new RecordsValidatingOutput(splits);
        reader.start();
        reader.addSplits(splits);
        // Poll 3 records from split 0 and 2 records from split 1.
        for (int i = 0; i < 5; i++) {
            reader.pollNext(validatingOutput);
        }
        Map<String, TestSourceOutput> sourceOutputs = validatingOutput.createdSourceOutputs();
        assertEquals("There should be 2 source outputs created.", 2, sourceOutputs.size());
        assertNull(sourceOutputs.get("0").watermark());
        assertNull(sourceOutputs.get("1").watermark());
        // Trigger the periodic task marking the watermark emission flag.
        executor.triggerScheduledTasks();
        // Poll one more time to actually emit the watermark. Getting record value 2 from split_1.
        reader.pollNext(validatingOutput);
        assertEquals(3, sourceOutputs.get("0").watermark().getTimestamp());
        assertEquals(2, sourceOutputs.get("1").watermark().getTimestamp());
        // Poll one more time to ensure no additional watermark is emitted. Getting record value 3
        // from split_0.
        reader.pollNext(validatingOutput);
        assertEquals(3, sourceOutputs.get("0").watermark().getTimestamp());
        assertEquals(2, sourceOutputs.get("1").watermark().getTimestamp());
        // Trigger the task to mark the watermark emission flag again.
        executor.triggerScheduledTasks();
        // Poll to actually emit the watermark. Getting (split_1 -> 3).
        reader.pollNext(validatingOutput);
        assertEquals(4, sourceOutputs.get("0").watermark().getTimestamp());
        assertEquals(3, sourceOutputs.get("1").watermark().getTimestamp());
    }
}

@Test
public void testWatermarkOnEmptySource() throws Exception {
    ManuallyTriggeredScheduledExecutorService executor = new ManuallyTriggeredScheduledExecutorService();
    AtomicReference<Instant> watermark = new AtomicReference<>(BoundedWindow.TIMESTAMP_MIN_VALUE);
    ReaderOutput<WindowedValue<ValueWithRecordId<KV<Integer, Integer>>>> output = new ReaderOutput<WindowedValue<ValueWithRecordId<KV<Integer, Integer>>>>() {

        @Override
        public void collect(WindowedValue<ValueWithRecordId<KV<Integer, Integer>>> unused) {
        }

        @Override
        public void collect(WindowedValue<ValueWithRecordId<KV<Integer, Integer>>> unused, long l) {
        }

        @Override
        public void emitWatermark(Watermark w) {
            watermark.compareAndSet(BoundedWindow.TIMESTAMP_MIN_VALUE, Instant.ofEpochMilli(w.getTimestamp()));
        }

        @Override
        public void markIdle() {
        }

        @Override
        public SourceOutput<WindowedValue<ValueWithRecordId<KV<Integer, Integer>>>> createOutputForSplit(String s) {
            return this;
        }

        @Override
        public void releaseOutputForSplit(String s) {
        }

        @Override
        public void markActive() {
        }
    };
    Instant now = Instant.now();
    try (FlinkUnboundedSourceReader<KV<Integer, Integer>> reader = (FlinkUnboundedSourceReader<KV<Integer, Integer>>) createReader(executor, -1L)) {
        List<FlinkSourceSplit<KV<Integer, Integer>>> splits = createEmptySplits(2);
        reader.start();
        reader.addSplits(splits);
        reader.notifyNoMoreSplits();
        for (int i = 0; i < 4; i++) {
            assertEquals(InputStatus.NOTHING_AVAILABLE, reader.pollNext(output));
        }
        // move first reader to 'now'
        ((EmptyUnboundedSource<KV<Integer, Integer>>) splits.get(0).getBeamSplitSource()).setWatermark(now);
        // force trigger timeout
        executor.triggerScheduledTasks();
        for (int i = 0; i < 4; i++) {
            assertEquals(InputStatus.NOTHING_AVAILABLE, reader.pollNext(output));
        }
        // check we have emitted watermark
        assertEquals(now, watermark.get());
        // move first reader to end of time
        ((EmptyUnboundedSource<KV<Integer, Integer>>) splits.get(0).getBeamSplitSource()).setWatermark(BoundedWindow.TIMESTAMP_MAX_VALUE);
        for (int i = 0; i < 4; i++) {
            assertEquals(InputStatus.NOTHING_AVAILABLE, reader.pollNext(output));
        }
        // move the second reader to end of time
        ((EmptyUnboundedSource<KV<Integer, Integer>>) splits.get(1).getBeamSplitSource()).setWatermark(BoundedWindow.TIMESTAMP_MAX_VALUE);
        assertEquals(InputStatus.END_OF_INPUT, reader.pollNext(output));
    }
}

