@Test
public void getDataflowRunnerInfo() throws Exception {
    DataflowRunnerInfo info = DataflowRunnerInfo.getDataflowRunnerInfo();
    String version = info.getLegacyEnvironmentMajorVersion();
    // Validate major version is a number
    assertTrue(String.format("Legacy environment major version number %s is not a number", version), version.matches("\\d+"));
    version = info.getFnApiEnvironmentMajorVersion();
    // Validate major version is a number
    assertTrue(String.format("FnAPI environment major version number %s is not a number", version), version.matches("\\d+"));
    // Validate container versions do not contain the property name.
    assertThat("legacy container version invalid", info.getFnApiDevContainerVersion(), not(containsString("dataflow.legacy_container_version")));
    assertThat("FnAPI container version invalid", info.getLegacyDevContainerVersion(), not(containsString("dataflow.fnapi_container_version")));
    // Validate container base repository does not contain the property name
    // (indicating it was not filled in).
    assertThat("container repository invalid", info.getContainerImageBaseRepository(), not(containsString("dataflow.container_base_repository")));
    for (String property : new String[] { "java.vendor", "java.version", "os.arch", "os.name", "os.version" }) {
        assertEquals(System.getProperty(property), info.getProperties().get(property));
    }
}

