/**
 * If gcloud gets stuck, test that {@link DefaultGcpRegionFactory#getRegionFromGcloudCli(long)}
 * times out instead of blocking forever.
 */
@Test(timeout = 10000L)
public void testGetRegionFromGcloudCliTimeout() {
    try (MockedStatic<DefaultGcpRegionFactory> mocked = mockStatic(DefaultGcpRegionFactory.class, CALLS_REAL_METHODS)) {
        mocked.when(DefaultGcpRegionFactory::startGcloud).thenReturn(new Process() {

            @Override
            public OutputStream getOutputStream() {
                return new OutputStream() {

                    @Override
                    public void write(int b) {
                        // Do nothing.
                    }
                };
            }

            @Override
            public InputStream getInputStream() {
                return new InputStream() {

                    @Override
                    public int read() {
                        // Return EOF immediately.
                        return -1;
                    }
                };
            }

            @Override
            public InputStream getErrorStream() {
                return new InputStream() {

                    @Override
                    public int read() {
                        // Never return EOF to create an infinite loop.
                        try {
                            // Sleep so we don't buffer too many bytes and run out of memory.
                            Thread.sleep(1000);
                        } catch (InterruptedException e) {
                            // Ignore.
                        }
                        return 0;
                    }
                };
            }

            @Override
            public int waitFor() {
                // Unused.
                return 0;
            }

            @Override
            public int exitValue() {
                throw new IllegalThreadStateException("This mock process never terminates.");
            }

            @Override
            public void destroy() {
                // Do nothing.
            }
        });
        assertThrows(TimeoutException.class, () -> DefaultGcpRegionFactory.getRegionFromGcloudCli(1L));
    }
}

