@Test
public void testUpdateAndSnapshots_MultipleThreads() {
    int numRunnables = 200;
    ExecutorService executor = Executors.newFixedThreadPool(numRunnables);
    HistogramData.BucketType bucketType = HistogramData.ExponentialBuckets.of(1, 10);
    LockFreeHistogram histogram = new LockFreeHistogram(MetricName.named("name", "namespace"), bucketType);
    List<UpdateHistogramCallable> callables = new ArrayList<>();
    for (int i = 0; i < numRunnables; i++) {
        callables.add(new UpdateHistogramCallable(histogram, i));
    }
    long totalValuesRecorded = 0;
    try {
        List<Future<Long>> futures = executor.invokeAll(callables);
        for (Future<Long> future : futures) {
            totalValuesRecorded += future.get();
        }
    } catch (Exception e) {
        return;
    }
    Optional<LockFreeHistogram.Snapshot> finalSnapshot = histogram.getSnapshotAndReset();
    if (finalSnapshot.isPresent()) {
        totalValuesRecorded += finalSnapshot.get().totalCount();
    }
    assertThat(totalValuesRecorded, equalTo(numRunnables * UpdateHistogramCallable.numValuesRecorded()));
}

@Test
public void testOutputStreamRollover() throws IOException {
    DataflowWorkerLoggingMDC.setJobId("testJobId");
    ByteArrayOutputStream first = new ByteArrayOutputStream();
    ByteArrayOutputStream second = new ByteArrayOutputStream();
    LogRecord record = createLogRecord("test.message", null);
    String expected = "{\"timestamp\":{\"seconds\":0,\"nanos\":1000000},\"severity\":\"INFO\"," + "\"message\":\"test.message\",\"thread\":\"2\",\"job\":\"testJobId\"," + "\"logger\":\"LoggerName\"}" + System.lineSeparator();
    FixedOutputStreamFactory factory = new FixedOutputStreamFactory(first, second);
    DataflowWorkerLoggingHandler handler = new DataflowWorkerLoggingHandler(factory, expected.length() + 1);
    // Using |expected|+1 for size limit means that we will rollover after writing 2 log messages.
    // We thus expect to see 2 messsages written to 'first' and 1 message to 'second',
    handler.publish(record);
    handler.publish(record);
    handler.publish(record);
    assertEquals(expected + expected, new String(first.toByteArray(), StandardCharsets.UTF_8));
    assertEquals(expected, new String(second.toByteArray(), StandardCharsets.UTF_8));
}

