@Test
public void testWriteDynamicDestinations() throws Exception {
    Windmill.WorkItemCommitRequest.Builder outputBuilder = Windmill.WorkItemCommitRequest.newBuilder().setKey(ByteString.copyFromUtf8("key")).setWorkToken(0);
    when(mockContext.getOutputBuilder()).thenReturn(outputBuilder);
    Map<String, Object> spec = new HashMap<>();
    spec.put(PropertyNames.OBJECT_TYPE_NAME, "PubsubDynamicSink");
    spec.put(PropertyNames.PUBSUB_TIMESTAMP_ATTRIBUTE, "ts");
    spec.put(PropertyNames.PUBSUB_ID_ATTRIBUTE, "id");
    CloudObject cloudSinkSpec = CloudObject.fromSpec(spec);
    PubsubDynamicSink sink = (PubsubDynamicSink) SinkRegistry.defaultRegistry().create(cloudSinkSpec, WindowedValues.getFullCoder(VoidCoder.of(), IntervalWindow.getCoder()), null, mockContext, null).getUnderlyingSink();
    Sink.SinkWriter<WindowedValue<PubsubMessage>> writer = sink.writer();
    List<Windmill.Message> expectedMessages1 = Lists.newArrayList();
    List<Windmill.Message> expectedMessages2 = Lists.newArrayList();
    List<Windmill.Message> expectedMessages3 = Lists.newArrayList();
    for (int i = 0; i < 10; ++i) {
        int baseTimestamp = i * 10;
        byte[] payload1 = String.format("value_%d_%d", i, 1).getBytes(StandardCharsets.UTF_8);
        byte[] payload2 = String.format("value_%d_%d", i, 2).getBytes(StandardCharsets.UTF_8);
        byte[] payload3 = String.format("value_%d_%d", i, 3).getBytes(StandardCharsets.UTF_8);
        expectedMessages1.add(Windmill.Message.newBuilder().setTimestamp(baseTimestamp * 1000).setData(Pubsub.PubsubMessage.newBuilder().setData(ByteString.copyFrom(payload1)).build().toByteString()).build());
        expectedMessages2.add(Windmill.Message.newBuilder().setTimestamp((baseTimestamp + 1) * 1000).setData(Pubsub.PubsubMessage.newBuilder().setData(ByteString.copyFrom(payload2)).build().toByteString()).build());
        expectedMessages3.add(Windmill.Message.newBuilder().setTimestamp((baseTimestamp + 2) * 1000).setData(Pubsub.PubsubMessage.newBuilder().setData(ByteString.copyFrom(payload3)).build().toByteString()).build());
        writer.add(WindowedValues.timestampedValueInGlobalWindow(new PubsubMessage(payload1, null).withTopic("topic1"), new Instant(baseTimestamp)));
        writer.add(WindowedValues.timestampedValueInGlobalWindow(new PubsubMessage(payload2, null).withTopic("topic2"), new Instant(baseTimestamp + 1)));
        writer.add(WindowedValues.timestampedValueInGlobalWindow(new PubsubMessage(payload3, null).withTopic("topic3"), new Instant(baseTimestamp + 2)));
    }
    writer.close();
    Windmill.WorkItemCommitRequest expectedCommit = Windmill.WorkItemCommitRequest.newBuilder().setKey(ByteString.copyFromUtf8("key")).setWorkToken(0).addPubsubMessages(Windmill.PubSubMessageBundle.newBuilder().setTopic("topic1").setTimestampLabel("ts").setIdLabel("id").setWithAttributes(true).addAllMessages(expectedMessages1)).addPubsubMessages(Windmill.PubSubMessageBundle.newBuilder().setTopic("topic2").setTimestampLabel("ts").setIdLabel("id").setWithAttributes(true).addAllMessages(expectedMessages2)).addPubsubMessages(Windmill.PubSubMessageBundle.newBuilder().setTopic("topic3").setTimestampLabel("ts").setIdLabel("id").setWithAttributes(true).addAllMessages(expectedMessages3)).build();
    assertEquals(expectedCommit, outputBuilder.build());
}

