@Test
public void testReaderCache() throws IOException {
    // Test basic caching expectations
    readerCache.cacheReader(WindmillComputationKey.create(C_ID, KEY_1, SHARDING_KEY), 1, 0, reader1);
    readerCache.cacheReader(WindmillComputationKey.create(C_ID, KEY_2, SHARDING_KEY), 2, 0, reader2);
    assertEquals(reader1, readerCache.acquireReader(WindmillComputationKey.create(C_ID, KEY_1, SHARDING_KEY), 1, 1));
    assertNull(readerCache.acquireReader(WindmillComputationKey.create(C_ID_1, KEY_1, SHARDING_KEY), 1, 1));
    assertNull(readerCache.acquireReader(WindmillComputationKey.create(C_ID, KEY_1, SHARDING_KEY_1), 1, 1));
    // Trying to override existing reader should throw
    try {
        readerCache.cacheReader(WindmillComputationKey.create(C_ID, KEY_2, SHARDING_KEY), 2, 2, reader1);
        fail("Exception should have been thrown");
    } catch (RuntimeException expected) {
        // expected
    }
    // And it should not have overwritten the old value
    assertEquals(reader2, readerCache.acquireReader(WindmillComputationKey.create(C_ID, KEY_2, SHARDING_KEY), 2, 3));
    assertNull("acquireReader(WindmillComputationKey.create() should remove matching entry", readerCache.acquireReader(WindmillComputationKey.create(C_ID, KEY_2, SHARDING_KEY), 2, 4));
    // Make sure computationId is part of the cache key
    readerCache.cacheReader(WindmillComputationKey.create(C_ID_1, KEY_1, SHARDING_KEY), 1, 5, reader2);
    assertEquals(reader2, readerCache.acquireReader(WindmillComputationKey.create(C_ID_1, KEY_1, SHARDING_KEY), 1, 6));
    // Make sure sharding key is part of the cache key
    readerCache.cacheReader(WindmillComputationKey.create(C_ID, KEY_1, SHARDING_KEY_1), 1, 0, reader3);
    assertEquals(reader3, readerCache.acquireReader(WindmillComputationKey.create(C_ID, KEY_1, SHARDING_KEY_1), 1, 1));
}

@Test
public void testInvalidation() throws IOException {
    readerCache.cacheReader(WindmillComputationKey.create(C_ID, KEY_1, SHARDING_KEY), 1, 0, reader1);
    readerCache.cacheReader(WindmillComputationKey.create(C_ID, KEY_2, SHARDING_KEY), 2, 0, reader2);
    readerCache.cacheReader(WindmillComputationKey.create(C_ID, KEY_2, SHARDING_KEY_1), 2, 0, reader3);
    readerCache.invalidateReader(WindmillComputationKey.create(C_ID, KEY_1, SHARDING_KEY));
    verify(reader1).close();
    // Verify IOException during close is not thrown (it is logged).
    doThrow(new IOException("swallowed")).when(reader2).close();
    readerCache.invalidateReader(WindmillComputationKey.create(C_ID, KEY_2, SHARDING_KEY));
    // Make sure a runtime exception is not swallowed
    doThrow(new RuntimeException("expected")).when(reader3).close();
    try {
        readerCache.invalidateReader(WindmillComputationKey.create(C_ID, KEY_2, SHARDING_KEY_1));
        fail("Exception should have been thrown");
    } catch (RuntimeException e) {
        assertEquals("expected", e.getMessage());
    }
}

@Test
public void testReaderCacheExpiration() throws IOException, InterruptedException {
    // Make sure cache closes the reader soon after expiry (as long as readerCache is accessed).
    Duration cacheDuration = Duration.millis(10);
    // Create a cache with short expiry period.
    ReaderCache readerCache = new ReaderCache(cacheDuration, Runnable::run);
    readerCache.cacheReader(WindmillComputationKey.create(C_ID, KEY_1, SHARDING_KEY), 1, 0, reader1);
    readerCache.cacheReader(WindmillComputationKey.create(C_ID, KEY_2, SHARDING_KEY), 2, 0, reader2);
    Stopwatch stopwatch = Stopwatch.createStarted();
    while (stopwatch.elapsed(TimeUnit.MILLISECONDS) < 2 * cacheDuration.getMillis()) {
        Thread.sleep(1);
    }
    // Trigger clean up with a lookup, non-existing key is ok.
    readerCache.acquireReader(WindmillComputationKey.create(C_ID, KEY_3, SHARDING_KEY), 3, 0);
    verify(reader1).close();
}

@Test
public void testReaderCacheRetries() throws IOException, InterruptedException {
    ReaderCache readerCache = new ReaderCache(Duration.standardMinutes(1), Runnable::run);
    readerCache.cacheReader(WindmillComputationKey.create(C_ID, KEY_1, SHARDING_KEY), 1, 1, reader1);
    // Same cache token should not recover the reader from the cache.
    assertNull(readerCache.acquireReader(WindmillComputationKey.create(C_ID, KEY_1, SHARDING_KEY), 1, 1));
    readerCache.cacheReader(WindmillComputationKey.create(C_ID, KEY_1, SHARDING_KEY), 1, 1, reader2);
    assertEquals(reader2, readerCache.acquireReader(WindmillComputationKey.create(C_ID, KEY_1, SHARDING_KEY), 1, 20));
    readerCache.cacheReader(WindmillComputationKey.create(C_ID, KEY_1, SHARDING_KEY), 1, 20, reader2);
    // Stale cache token should not recover the reader from the cache.
    assertNull(readerCache.acquireReader(WindmillComputationKey.create(C_ID, KEY_1, SHARDING_KEY), 1, 3));
    verify(reader1).close();
    verify(reader2).close();
}

