@Test
public void testIgnoreRetriedKeys() throws Exception {
    final int numIters = 4;
    List<ParallelInstruction> instructions = Arrays.asList(makeSourceInstruction(StringUtf8Coder.of()), makeDoFnInstruction(blockingFn, 0, StringUtf8Coder.of()), makeSinkInstruction(StringUtf8Coder.of(), 0));
    StreamingDataflowWorker worker = makeWorker(defaultWorkerParams().setInstructions(instructions).publishCounters().build());
    worker.start();
    for (int i = 1; i <= numIters; ++i) {
        server.whenGetWorkCalled().thenReturn(makeInput(i, TimeUnit.MILLISECONDS.toMicros(i), keyStringForIndex(i), i)).// Also add work for a different shard of the same key.
        thenReturn(makeInput(i + 1000, TimeUnit.MILLISECONDS.toMicros(i), keyStringForIndex(i), i + 1000));
    }
    // Wait for keys to schedule.  They will be blocked.
    BlockingFn.counter().acquire(numIters * 2);
    // Re-add the work, it should be ignored due to the keys being active.
    for (int i = 1; i <= numIters; ++i) {
        // Same work token.
        server.whenGetWorkCalled().thenReturn(makeInput(i, TimeUnit.MILLISECONDS.toMicros(i), keyStringForIndex(i), i)).thenReturn(makeInput(i + 1000, TimeUnit.MILLISECONDS.toMicros(i), keyStringForIndex(i), i + 1000));
    }
    // Give all added calls a chance to run.
    server.waitForEmptyWorkQueue();
    for (int i = 1; i <= numIters; ++i) {
        // Different work token same keys.
        server.whenGetWorkCalled().thenReturn(makeInput(i + numIters, TimeUnit.MILLISECONDS.toMicros(i), keyStringForIndex(i), i));
    }
    // Give all added calls a chance to run.
    server.waitForEmptyWorkQueue();
    // Release the blocked calls.
    BlockingFn.blocker().countDown();
    // Verify the output
    Map<Long, Windmill.WorkItemCommitRequest> result = server.waitForAndGetCommits(numIters * 3);
    for (int i = 1; i <= numIters; ++i) {
        assertTrue(result.containsKey((long) i));
        assertEquals(makeExpectedOutput(i, TimeUnit.MILLISECONDS.toMicros(i), keyStringForIndex(i), i, keyStringForIndex(i)).build(), removeDynamicFields(result.get((long) i)));
        assertTrue(result.containsKey((long) i + 1000));
        assertEquals(makeExpectedOutput(i + 1000, TimeUnit.MILLISECONDS.toMicros(i), keyStringForIndex(i), i + 1000, keyStringForIndex(i)).build(), removeDynamicFields(result.get((long) i + 1000)));
        assertTrue(result.containsKey((long) i + numIters));
        assertEquals(makeExpectedOutput(i + numIters, TimeUnit.MILLISECONDS.toMicros(i), keyStringForIndex(i), i, keyStringForIndex(i)).build(), removeDynamicFields(result.get((long) i + numIters)));
    }
    // Re-add the work, it should process due to the keys no longer being active.
    for (int i = 1; i <= numIters; ++i) {
        server.whenGetWorkCalled().thenReturn(makeInput(i + numIters * 2, TimeUnit.MILLISECONDS.toMicros(i), keyStringForIndex(i), i));
    }
    result = server.waitForAndGetCommits(numIters);
    worker.stop();
    for (int i = 1; i <= numIters; ++i) {
