    ArgumentCaptor<Consumer<StreamingGlobalConfig>> observerCaptor = ArgumentCaptor.forClass(Consumer.class);
    worker.start();
    verify(mockGlobalConfigHandle, atLeastOnce()).registerConfigObserver(observerCaptor.capture());
    List<Consumer<StreamingGlobalConfig>> observers = observerCaptor.getAllValues();
    assertTrue("Worker should start with FanOutStreamingEngineWorkerHarness", worker.getStreamingWorkerHarness() instanceof FanOutStreamingEngineWorkerHarness);
    // Prepare WorkerMetadataResponse
    server.injectWorkerMetadata(WorkerMetadataResponse.newBuilder().setMetadataVersion(1).addWorkEndpoints(WorkerMetadataResponse.Endpoint.newBuilder().setBackendWorkerToken("workerToken1").setDirectEndpoint(serverEndpoint).build()).build());
