    assertTrue(result.containsKey(1L));
    // Switch to Directpath.
    StreamingGlobalConfig directPathConfig = StreamingGlobalConfig.builder().setUserWorkerJobSettings(Windmill.UserWorkerRunnerV1Settings.newBuilder().setConnectivityType(ConnectivityType.CONNECTIVITY_TYPE_DIRECTPATH).build()).build();
    for (Consumer<StreamingGlobalConfig> observer : observers) {
        observer.accept(directPathConfig);
    }
    // Wait for the harnessSwitchExecutor to complete the switch.
    Future<?> directPathSwitchFuture = harnessSwitchExecutor.submit(() -> {
    });
    // Wait for the dummy task to complete. The dummy task will be executed after
    // switchStreamingWorkerHarness has completed.
    directPathSwitchFuture.get(30, TimeUnit.SECONDS);
    assertTrue("Worker should switch to FanOutStreamingEngineWorkerHarness", worker.getStreamingWorkerHarness() instanceof FanOutStreamingEngineWorkerHarness);
    // Switch to Cloudpath again.
    cloudPathConfig = StreamingGlobalConfig.builder().setUserWorkerJobSettings(Windmill.UserWorkerRunnerV1Settings.newBuilder().setConnectivityType(ConnectivityType.CONNECTIVITY_TYPE_CLOUDPATH).build()).build();
    for (Consumer<StreamingGlobalConfig> observer : observers) {
        observer.accept(cloudPathConfig);
    }
    cloudPathSwitchFuture = harnessSwitchExecutor.submit(() -> {
    });
    cloudPathSwitchFuture.get(30, TimeUnit.SECONDS);
    assertTrue("Worker should switch back to SingleSourceWorkerHarness", worker.getStreamingWorkerHarness() instanceof SingleSourceWorkerHarness);
    // Process some work with CloudPath again.
    server.whenGetWorkCalled().thenReturn(makeInput(2, 2000));
    result = server.waitForAndGetCommits(1);
    assertEquals(2, result.size());
    assertTrue(result.containsKey(2L));
    worker.stop();
}

