    Counter<Long, ?> c9 = counterFactory.distribution(CounterName.named("c9"));
    assertThat(c1.extractUpdate(true, DataflowCounterUpdateExtractor.INSTANCE), allOf(hasName("c1"), hasKind("SUM"), hasIntegerValue(0)));
    c1.addValue(123L).addValue(-13L);
