    assertThat(c2.extractUpdate(true, DataflowCounterUpdateExtractor.INSTANCE), allOf(hasName("c2"), hasKind("MAX"), hasDoubleValue(Double.NEGATIVE_INFINITY)));
    c2.getAndReset();
