    c4.addValue(Math.PI).addValue(Math.E).addValue(Math.sqrt(2));
    assertThat(c4.extractUpdate(true, DataflowCounterUpdateExtractor.INSTANCE), allOf(hasName("c4"), hasKind("MEAN"), hasDoubleSum(Math.PI + Math.E + Math.sqrt(2)), hasDoubleCount(3)));
    c4.addValue(2.0).addValue(5.0);
    assertThat(c4.extractUpdate(true, DataflowCounterUpdateExtractor.INSTANCE), allOf(hasDoubleSum(7.0), hasDoubleCount(2)));
    assertThat(c5.extractUpdate(true, DataflowCounterUpdateExtractor.INSTANCE), allOf(hasName("c5"), hasKind("MIN"), hasIntegerValue(Integer.MAX_VALUE)));
    c5.addValue(123).addValue(-13);
    assertThat(c5.extractUpdate(true, DataflowCounterUpdateExtractor.INSTANCE), hasIntegerValue(-13));
    assertThat(c6.extractUpdate(true, DataflowCounterUpdateExtractor.INSTANCE), allOf(hasName("c6"), hasKind("AND"), hasBooleanValue(true)));
    c6.addValue(false);
    assertThat(c6.extractUpdate(true, DataflowCounterUpdateExtractor.INSTANCE), hasBooleanValue(false));
    assertThat(c7.extractUpdate(true, DataflowCounterUpdateExtractor.INSTANCE), allOf(hasName("c7"), hasKind("OR"), hasBooleanValue(false)));
    c7.addValue(true);
    assertThat(c7.extractUpdate(true, DataflowCounterUpdateExtractor.INSTANCE), hasBooleanValue(true));
    c8.addValue(1).addValue(2).addValue(3).addValue(4).addValue(5);
    assertThat(c8.extractUpdate(true, DataflowCounterUpdateExtractor.INSTANCE), allOf(hasName("c8"), hasKind("MEAN"), hasIntegerSum(15), hasIntegerCount(5)));
    c9.addValue(1L).addValue(0L).addValue(1L).addValue(9L).addValue(19L);
    assertThat(c9.extractUpdate(true, DataflowCounterUpdateExtractor.INSTANCE), allOf(hasName("c9"), hasKind("DISTRIBUTION"), hasDistribution(CounterFactory.CounterDistribution.builder().minMax(0L, 19L).count(5L).sum(30L).sumOfSquares(444f).firstBucketOffset(0).buckets(Lists.newArrayList(1L, 2L, 0L, 1L, 1L)).build())));
}

@Test
public void testSplitIntToLong() {
    // high bits negative max, low bits 0
    assertEquals(0x80000000_00000000L, DataflowCounterUpdateExtractor.splitIntToLong(createSplitInt(Integer.MIN_VALUE, 0L)));
    // high bits 0, low bits 0
    assertEquals(0x00000000_00000000L, DataflowCounterUpdateExtractor.splitIntToLong(createSplitInt(0, 0L)));
    // high bits positive max, low bits 0
    assertEquals(0x7fffffff_00000000L, DataflowCounterUpdateExtractor.splitIntToLong(createSplitInt(Integer.MAX_VALUE, 0L)));
    // high bits negative, low bits max
    assertEquals(0x80000000_ffffffffL, DataflowCounterUpdateExtractor.splitIntToLong(createSplitInt(Integer.MIN_VALUE, 0xffffffffL)));
    // high bits 0, low bits max
    assertEquals(0x00000000_ffffffffL, DataflowCounterUpdateExtractor.splitIntToLong(createSplitInt(0, 0xffffffffL)));
    // high bits positive, low bits max
    assertEquals(0x7fffffff_ffffffffL, DataflowCounterUpdateExtractor.splitIntToLong(createSplitInt(Integer.MAX_VALUE, 0xffffffffL)));
}

