public void testCommit_handlesFailedCommits() {
    Set<CompleteCommit> completeCommits = Collections.newSetFromMap(new ConcurrentHashMap<>());
    workCommitter = createWorkCommitter(completeCommits::add);
    List<Commit> commits = new ArrayList<>();
    for (int i = 1; i <= 10; i++) {
        Work work = createMockWork(i);
        // Fail half of the work.
        if (i % 2 == 0) {
            work.setFailed();
        }
        WorkItemCommitRequest commitRequest = WorkItemCommitRequest.newBuilder().setKey(work.getWorkItem().getKey()).setShardingKey(work.getWorkItem().getShardingKey()).setWorkToken(work.getWorkItem().getWorkToken()).setCacheToken(work.getWorkItem().getCacheToken()).build();
        commits.add(Commit.create(commitRequest, createComputationState("computationId-" + i), work));
    }
    workCommitter.start();
    commits.parallelStream().forEach(workCommitter::commit);
    Map<Long, WorkItemCommitRequest> committed = fakeWindmillServer.waitForAndGetCommits(commits.size() / 2);
    waitForExpectedSetSize(completeCommits, 10);
    for (Commit commit : commits) {
        if (commit.work().isFailed()) {
            assertThat(completeCommits).contains(asCompleteCommit(commit, Windmill.CommitStatus.ABORTED));
            assertThat(committed).doesNotContainKey(commit.work().getWorkItem().getWorkToken());
