@Test
public void testGetWorkTimingInfosTracker_calculatesTransitToUserWorkerTimeFromDispatcher() {
    GetWorkTimingInfosTracker tracker = new GetWorkTimingInfosTracker(() -> 50);
    List<Windmill.GetWorkStreamTimingInfo> infos = new ArrayList<>();
    for (int i = 0; i <= 3; i++) {
        infos.add(Windmill.GetWorkStreamTimingInfo.newBuilder().setEvent(Windmill.GetWorkStreamTimingInfo.Event.GET_WORK_CREATION_START).setTimestampUsec(0).build());
        infos.add(Windmill.GetWorkStreamTimingInfo.newBuilder().setEvent(Windmill.GetWorkStreamTimingInfo.Event.GET_WORK_CREATION_END).setTimestampUsec(10000).build());
        infos.add(Windmill.GetWorkStreamTimingInfo.newBuilder().setEvent(Windmill.GetWorkStreamTimingInfo.Event.GET_WORK_RECEIVED_BY_DISPATCHER).setTimestampUsec((i + 11) * 1000).build());
        infos.add(Windmill.GetWorkStreamTimingInfo.newBuilder().setEvent(Windmill.GetWorkStreamTimingInfo.Event.GET_WORK_FORWARDED_BY_DISPATCHER).setTimestampUsec((i + 16) * 1000).build());
        tracker.addTimingInfo(infos);
        infos.clear();
    }
    // durations for each chunk:
    // GET_WORK_IN_WINDMILL_WORKER: 10, 10, 10, 10
    // GET_WORK_IN_TRANSIT_TO_DISPATCHER: 1, 2, 3, 4 -> sum to 10
    // GET_WORK_IN_TRANSIT_TO_USER_WORKER: 34, 33, 32, 31 -> sum to 130
    Map<Windmill.LatencyAttribution.State, Windmill.LatencyAttribution> latencies = new HashMap<>();
    ImmutableList<Windmill.LatencyAttribution> attributions = tracker.getLatencyAttributions();
    assertEquals(3, attributions.size());
    for (Windmill.LatencyAttribution attribution : attributions) {
        latencies.put(attribution.getState(), attribution);
    }
    assertEquals(10L, latencies.get(Windmill.LatencyAttribution.State.GET_WORK_IN_WINDMILL_WORKER).getTotalDurationMillis());
    // elapsed time from 10 -> 50;
    long elapsedTime = 40;
    // sumDurations: 1 + 2 + 3 + 4 + 34 + 33 + 32 + 31;
    long sumDurations = 140;
    assertEquals(Math.min(4, (long) (elapsedTime * (10.0 / sumDurations))), latencies.get(Windmill.LatencyAttribution.State.GET_WORK_IN_TRANSIT_TO_DISPATCHER).getTotalDurationMillis());
    assertEquals(Math.min(34, (long) (elapsedTime * (130.0 / sumDurations))), latencies.get(Windmill.LatencyAttribution.State.GET_WORK_IN_TRANSIT_TO_USER_WORKER).getTotalDurationMillis());
}

