@Test
public void testRequestKeyedData_sendOnShutdownStreamThrowsWindmillStreamShutdownException() {
    GrpcGetDataStream getDataStream = createGetDataStream();
    int numSendThreads = 5;
    ExecutorService getDataStreamSenders = Executors.newFixedThreadPool(numSendThreads);
    CountDownLatch waitForSendAttempt = new CountDownLatch(1);
    // These will block until they are successfully sent.
    List<CompletableFuture<Void>> sendFutures = IntStream.range(0, 5).sequential().mapToObj(i -> (Runnable) () -> {
        // Prevent some threads from sending until we close the stream.
        if (i % 2 == 0) {
            try {
                waitForSendAttempt.await();
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            }
        }
        try {
            getDataStream.requestKeyedData("computationId", createTestRequest(i));
        } catch (WindmillStreamShutdownException e) {
            throw new RuntimeException(e);
        }
    }).// Run the code above on multiple threads.
    map(runnable -> CompletableFuture.runAsync(runnable, getDataStreamSenders)).collect(Collectors.toList());
    getDataStream.shutdown();
    // Free up waiting threads so that they can try to send on a closed stream.
    waitForSendAttempt.countDown();
    for (int i = 0; i < numSendThreads; i++) {
        CompletableFuture<Void> sendFuture = sendFutures.get(i);
        try {
            // Wait for future to complete.
            sendFuture.join();
        } catch (Exception ignored) {
        }
        if (i % 2 == 0) {
            assertTrue(sendFuture.isCompletedExceptionally());
            ExecutionException e = assertThrows(ExecutionException.class, sendFuture::get);
            assertThat(e).hasCauseThat().hasCauseThat().isInstanceOf(WindmillStreamShutdownException.class);
        }
    }
}

@Test
public void testRequestKeyedData_multipleRequestsSameWorkItemSeparateBatches() throws InterruptedException {
    GrpcGetDataStream getDataStream = createGetDataStream();
    FakeWindmillGrpcService.GetDataStreamInfo streamInfo = waitForConnectionAndConsumeHeader();
    final CountDownLatch requestStarter = new CountDownLatch(1);
    // Get a bunch of threads ready to send a request with the same work token. These should racily
    // attempt to batch but be prevented due to work token separation logic.
    // These will block until they are successfully sent.
    List<CompletableFuture<Windmill.KeyedGetDataResponse>> futures = new ArrayList<>();
    final Windmill.KeyedGetDataRequest keyedGetDataRequest = createTestRequest(1);
    for (int i = 0; i < 10; ++i) {
        futures.add(CompletableFuture.supplyAsync(() -> {
            try {
                requestStarter.await();
                return getDataStream.requestKeyedData("computationId", keyedGetDataRequest);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }));
    }
    // Unblock and verify that 10 requests are made and not batched.
    requestStarter.countDown();
    for (int i = 0; i < 10; ++i) {
        Windmill.StreamingGetDataRequest request = streamInfo.requests.take();
        assertEquals(1, request.getRequestIdCount());
        assertEquals(keyedGetDataRequest, request.getStateRequest(0).getRequests(0));
    }
    // Send the responses.
    Windmill.KeyedGetDataResponse keyedGetDataResponse = createTestResponse(1);
    for (int i = 0; i < 10; ++i) {
        streamInfo.responseObserver.onNext(Windmill.StreamingGetDataResponse.newBuilder().addRequestId(i + 1).addSerializedResponse(keyedGetDataResponse.toByteString()).build());
    }
    for (CompletableFuture<Windmill.KeyedGetDataResponse> future : futures) {
        assertThat(future.join()).isEqualTo(keyedGetDataResponse);
    }
    getDataStream.shutdown();
}

