@Test
public void testWindmillApplianceGrpcDeadlineInterceptor() {
    Windmill.GetWorkResponse getWorkResponse = Windmill.GetWorkResponse.newBuilder().addWork(Windmill.ComputationWorkItems.newBuilder().setComputationId("someComputation1").build()).build();
    serviceRegistry.addService(new WindmillApplianceGrpc.WindmillApplianceImplBase() {

        @Override
        public void getWork(Windmill.GetWorkRequest request, StreamObserver<Windmill.GetWorkResponse> responseObserver) {
            responseObserver.onNext(getWorkResponse);
            responseObserver.onCompleted();
        }
    });
    ClientInterceptor testInterceptor = new ClientInterceptor() {

        Deadline deadline;

        @Override
        public <ReqT, RespT> ClientCall<ReqT, RespT> interceptCall(MethodDescriptor<ReqT, RespT> methodDescriptor, CallOptions callOptions, Channel channel) {
            assertNotNull(callOptions.getDeadline());
            if (deadline != null) {
                // We want to assert that a new deadline is being created on every call since
                // deadlines are absolute.
                assertNotEquals(deadline, callOptions.getDeadline());
            }
            deadline = callOptions.getDeadline();
            // Just forward the call once we record the deadline
            return channel.newCall(methodDescriptor, callOptions);
        }
    };
    Channel inprocessChannel = ClientInterceptors.intercept(InProcessChannelBuilder.forName("Fake server for " + getClass()).directExecutor().build(), testInterceptor);
    this.client = GrpcWindmillServer.newApplianceTestInstance(inprocessChannel, new FakeWindmillStubFactoryFactory(new FakeWindmillStubFactory(() -> (ManagedChannel) inprocessChannel)));
    Windmill.GetWorkResponse response1 = client.getWork(GetWorkRequest.getDefaultInstance());
    Windmill.GetWorkResponse response2 = client.getWork(GetWorkRequest.getDefaultInstance());
    // Assert that the request/responses are being forwarded correctly.
    assertEquals(response1, getWorkResponse);
    assertEquals(response2, getWorkResponse);
}

