public void testStaleWorkItem() throws Exception {
    TestStateTag tag = new TestStateTag("tag2");
    WindmillStateCache.ForKeyAndFamily keyCache = cache.forComputation(COMPUTATION).forKey(COMPUTATION_KEY, 0L, 2L).forFamily(STATE_FAMILY);
