    long beginning = SortedListRange.getDefaultInstance().getStart();
    long end = SortedListRange.getDefaultInstance().getLimit();
    Future<Iterable<TimestampedValue<Integer>>> orderedListFuture = underTest.orderedListFuture(Range.closedOpen(beginning, end), STATE_KEY_1, STATE_FAMILY, INT_CODER);
    // This should be the final part of the response, and we should process it successfully.
    Future<Instant> watermarkFuture = underTest.watermarkFuture(STATE_KEY_1, STATE_FAMILY);
    Mockito.verifyNoMoreInteractions(mockWindmill);
    ByteString invalidByteString = ByteString.copyFrom(BaseEncoding.base16().decode("FFFF"));
    Windmill.Value invalidValue = intValue(0).toBuilder().setData(invalidByteString).build();
    Windmill.KeyedGetDataRequest.Builder expectedRequest = Windmill.KeyedGetDataRequest.newBuilder().setKey(DATA_KEY).setShardingKey(SHARDING_KEY).setWorkToken(WORK_TOKEN).setMaxBytes(WindmillStateReader.MAX_KEY_BYTES).addValuesToFetch(Windmill.TagValue.newBuilder().setTag(STATE_KEY_1).setStateFamily(STATE_FAMILY).build()).addBagsToFetch(Windmill.TagBag.newBuilder().setTag(STATE_KEY_1).setStateFamily(STATE_FAMILY).setFetchMaxBytes(WindmillStateReader.INITIAL_MAX_BAG_BYTES)).addTagValuePrefixesToFetch(Windmill.TagValuePrefixRequest.newBuilder().setTagPrefix(STATE_KEY_PREFIX).setStateFamily(STATE_FAMILY).setFetchMaxBytes(WindmillStateReader.MAX_TAG_VALUE_PREFIX_BYTES)).addSortedListsToFetch(Windmill.TagSortedListFetchRequest.newBuilder().setTag(STATE_KEY_1).setStateFamily(STATE_FAMILY).addFetchRanges(SortedListRange.newBuilder().setStart(beginning).setLimit(end)).setFetchMaxBytes(WindmillStateReader.MAX_ORDERED_LIST_BYTES)).addWatermarkHoldsToFetch(Windmill.WatermarkHold.newBuilder().setTag(STATE_KEY_1).setStateFamily(STATE_FAMILY));
    Windmill.KeyedGetDataResponse.Builder response = Windmill.KeyedGetDataResponse.newBuilder().setKey(DATA_KEY).addValues(Windmill.TagValue.newBuilder().setTag(STATE_KEY_1).setStateFamily(STATE_FAMILY).setValue(invalidValue)).addBags(Windmill.TagBag.newBuilder().setTag(STATE_KEY_1).setStateFamily(STATE_FAMILY).addValues(invalidByteString)).addTagValuePrefixes(Windmill.TagValuePrefixResponse.newBuilder().setTagPrefix(STATE_KEY_PREFIX).setStateFamily(STATE_FAMILY).addTagValues(Windmill.TagValue.newBuilder().setTag(STATE_KEY_1).setStateFamily(STATE_FAMILY).setValue(invalidValue))).addTagSortedLists(Windmill.TagSortedListFetchResponse.newBuilder().setTag(STATE_KEY_1).setStateFamily(STATE_FAMILY).addEntries(SortedListEntry.newBuilder().setValue(invalidByteString).setSortKey(5000).setId(5)).addFetchRanges(SortedListRange.newBuilder().setStart(beginning).setLimit(end))).addWatermarkHolds(Windmill.WatermarkHold.newBuilder().setTag(STATE_KEY_1).setStateFamily(STATE_FAMILY).addTimestamps(5000000).addTimestamps(6000000));
    Mockito.when(mockWindmill.getStateData(COMPUTATION, expectedRequest.build())).thenReturn(response.build());
    Mockito.verifyNoMoreInteractions(mockWindmill);
    try {
        valueFuture.get();
        fail("Expected RuntimeException");
    } catch (Exception e) {
        assertThat(e.toString(), Matchers.containsString("Unable to decode value"));
    }
    try {
        bagFuture.get();
        fail("Expected RuntimeException");
    } catch (Exception e) {
        assertThat(e.toString(), Matchers.containsString("Error parsing bag"));
    }
    try {
        orderedListFuture.get();
        fail("Expected RuntimeException");
    } catch (Exception e) {
        assertThat(e.toString(), Matchers.containsString("Error parsing ordered list"));
    }
    try {
        valuePrefixFuture.get();
        fail("Expected RuntimeException");
    } catch (Exception e) {
        assertThat(e.toString(), Matchers.containsString("Error parsing tag value prefix"));
    }
    assertThat(watermarkFuture.get(), Matchers.equalTo(new Instant(5000)));
}

