@Test
public void windowing() {
    PCollection<KV<String, Iterable<Integer>>> got = pipeline.apply(Create.of(1, 2, 100, 101, 102, 123)).apply(WithTimestamps.of(t -> Instant.ofEpochSecond(t))).apply(WithKeys.of("k")).apply(Window.into(FixedWindows.of(Duration.standardSeconds(10)))).apply(GroupByKey.create());
    List<KV<String, Iterable<Integer>>> want = Arrays.asList(KV.of("k", Arrays.asList(1, 2)), KV.of("k", Arrays.asList(100, 101, 102)), KV.of("k", Collections.singletonList(123)));
    PAssert.that(got).containsInAnyOrder(want);
    pipeline.run();
}

