@Test
public void testSamzaRunnerWithDefaultMetrics() {
    // TODO(https://github.com/apache/beam/issues/32208)
    assumeTrue(System.getProperty("java.version").startsWith("1."));
    SamzaPipelineOptions options = PipelineOptionsFactory.create().as(SamzaPipelineOptions.class);
    InMemoryMetricsReporter inMemoryMetricsReporter = new InMemoryMetricsReporter();
    options.setMetricsReporters(ImmutableList.of(inMemoryMetricsReporter));
    options.setRunner(TestSamzaRunner.class);
    options.setEnableTransformMetrics(true);
    TestSamzaRunner testSamzaRunner = TestSamzaRunner.fromOptions(options);
    Pipeline pipeline = Pipeline.create(options);
    // Create a pipeline
    PCollection<KV<String, Long>> output = pipeline.apply("Mock data", Create.of(KV.of("bad-key", KV.of("a", 97)), KV.of("hello", KV.of("a", 97)), KV.of("hello", KV.of("b", 42)), KV.of("hello", KV.of("c", 12)))).apply("Filter valid keys", Filter.by(x -> x.getKey().equals("hello"))).apply(Values.create()).apply("Fixed-window", Window.into(FixedWindows.of(Duration.standardSeconds(10)))).apply(Count.perKey());
    // check pipeline is working fine
    PAssert.that(output).containsInAnyOrder(KV.of("a", 1L), KV.of("b", 1L), KV.of("c", 1L));
    testSamzaRunner.run(pipeline);
    Map<String, Metric> pTransformContainerMetrics = inMemoryMetricsReporter.getMetricsRegistry("samza-container-1").getGroup("SamzaBeamTransformMetrics");
    Map<String, Metric> pTransformTaskMetrics = inMemoryMetricsReporter.getMetricsRegistry("TaskName-Partition 0").getGroup("SamzaBeamTransformMetrics");
    // SamzaTransformMetrics group must be initialized
    assertFalse(pTransformTaskMetrics.isEmpty());
    assertFalse(pTransformContainerMetrics.isEmpty());
    // Throughput Metrics are Per container by default
    assertEquals(4, ((Counter) pTransformContainerMetrics.get("Mock_data_Read_CreateSource_-num-output-messages")).getCount());
    assertEquals(4, ((Counter) pTransformContainerMetrics.get("Filter_valid_keys_ParDo_Anonymous__ParMultiDo_Anonymous_-num-input-messages")).getCount());
    // One message is dropped from filter
    assertEquals(3, ((Counter) pTransformContainerMetrics.get("Filter_valid_keys_ParDo_Anonymous__ParMultiDo_Anonymous_-num-output-messages")).getCount());
    assertEquals(3, ((Counter) pTransformContainerMetrics.get("Values_Values_Map_ParMultiDo_Anonymous_-num-input-messages")).getCount());
    assertEquals(3, ((Counter) pTransformContainerMetrics.get("Values_Values_Map_ParMultiDo_Anonymous_-num-output-messages")).getCount());
    assertEquals(3, ((Counter) pTransformContainerMetrics.get("Fixed_window_Window_Assign-num-input-messages")).getCount());
    assertEquals(3, ((Counter) pTransformContainerMetrics.get("Fixed_window_Window_Assign-num-output-messages")).getCount());
    assertEquals(3, ((Counter) pTransformContainerMetrics.get("Combine_perKey_Count_-num-input-messages")).getCount());
    assertEquals(3, ((Counter) pTransformContainerMetrics.get("Combine_perKey_Count_-num-output-messages")).getCount());
    // Throughput Metrics are per container by default
    assertNotNull(pTransformContainerMetrics.get("Filter_valid_keys_ParDo_Anonymous__ParMultiDo_Anonymous_-handle-message-ns"));
    assertNotNull(pTransformContainerMetrics.get("Values_Values_Map_ParMultiDo_Anonymous_-handle-message-ns"));
    assertNotNull(pTransformContainerMetrics.get("Combine_perKey_Count_-handle-message-ns"));
    // Watermark Metrics are Per task by default
    assertTrue(((Gauge<Long>) pTransformTaskMetrics.get("Mock_data_Read_CreateSource_-output-watermark-ms")).getValue() >= 0);
    assertNotNull(pTransformTaskMetrics.get("Filter_valid_keys_ParDo_Anonymous__ParMultiDo_Anonymous_-output-watermark-ms"));
    assertNotNull(pTransformTaskMetrics.get("Values_Values_Map_ParMultiDo_Anonymous_-output-watermark-ms"));
    assertNotNull(pTransformTaskMetrics.get("Combine_perKey_Count_-output-watermark-ms"));
}

@Test
public void testSamzaInputAndOutputMetricOp() {
    final WindowedValue<String> windowedValue = WindowedValues.timestampedValueInGlobalWindow("value-1", new Instant());
    final WindowedValue<String> windowedValue2 = WindowedValues.timestampedValueInGlobalWindow("value-2", new Instant());
    final WatermarkMessage watermarkMessage = new WatermarkMessage(BoundedWindow.TIMESTAMP_MAX_VALUE.getMillis());
    OpEmitter<String> opEmitter = mock(OpEmitter.class);
    doNothing().when(opEmitter).emitElement(any());
    doNothing().when(opEmitter).emitWatermark(any());
    Counter inputCounter = new Counter("filter-input-counter");
    Counter outputCounter = new Counter("filter-output-counter");
    Gauge<Long> watermarkProgress = new Gauge<>("filter-output-watermark", 0L);
    Gauge<Long> cacheSize = new Gauge<>("filter-arrival-time-cache-size", 0L);
    Timer latency = new Timer("filter-latency");
    SamzaTransformMetrics samzaTransformMetrics = mock(SamzaTransformMetrics.class);
    doNothing().when(samzaTransformMetrics).register(any(), any());
    when(samzaTransformMetrics.getTransformInputThroughput("filter")).thenReturn(inputCounter);
    when(samzaTransformMetrics.getTransformOutputThroughput("filter")).thenReturn(outputCounter);
    when(samzaTransformMetrics.getTransformWatermarkProgress("filter")).thenReturn(watermarkProgress);
    when(samzaTransformMetrics.getTransformLatencyMetric("filter")).thenReturn(latency);
    when(samzaTransformMetrics.getTransformCacheSize("filter")).thenReturn(cacheSize);
    SamzaTransformMetricRegistry samzaTransformMetricRegistry = spy(new SamzaTransformMetricRegistry(samzaTransformMetrics));
    samzaTransformMetricRegistry.register("filter", "dummy-pvalue.in", mock(Context.class));
    samzaTransformMetricRegistry.register("filter", "dummy-pvalue.out", mock(Context.class));
    SamzaMetricOp<String> inputMetricOp = new SamzaMetricOp<>("dummy-pvalue.in", "filter", SamzaMetricOpFactory.OpType.INPUT, samzaTransformMetricRegistry);
    inputMetricOp.processElement(windowedValue, opEmitter);
    inputMetricOp.processElement(windowedValue2, opEmitter);
    inputMetricOp.processWatermark(new Instant(watermarkMessage.getTimestamp()), opEmitter);
    // Input throughput must be updated
    assertEquals(2, inputCounter.getCount());
    // Avg arrival time for the PValue must be updated
    assertTrue(samzaTransformMetricRegistry.getAverageArrivalTimeMap("filter").get("dummy-pvalue.in").containsKey(watermarkMessage.getTimestamp()));
    SamzaMetricOp<String> outputMetricOp = new SamzaMetricOp<>("dummy-pvalue.out", "filter", SamzaMetricOpFactory.OpType.OUTPUT, samzaTransformMetricRegistry);
    outputMetricOp.init(ImmutableList.of("dummy-pvalue.in"), ImmutableList.of("dummy-pvalue.out"));
    outputMetricOp.processElement(windowedValue, opEmitter);
    outputMetricOp.processElement(windowedValue2, opEmitter);
    outputMetricOp.processWatermark(new Instant(watermarkMessage.getTimestamp()), opEmitter);
    // Output throughput must be updated
    assertEquals(2, outputCounter.getCount());
    // Output watermark must be updated
    assertEquals(watermarkMessage.getTimestamp(), watermarkProgress.getValue().longValue());
    // Latency must be positive
    assertTrue(latency.getSnapshot().getAverage() > 0);
    // Cache size must be 0
    assertEquals(0, cacheSize.getValue().intValue());
}

