    assertTrue(1000 == latency.getSnapshot().getAverage());
    // Check the avg arrival time is cleared
    assertFalse(samzaTransformMetricRegistry.getAverageArrivalTimeMapForGBK("Count.perKey").containsKey(first));
    assertFalse(samzaTransformMetricRegistry.getAverageArrivalTimeMapForGBK("Count.perKey").containsKey(second));
