    TestStream.Builder<Integer> testStream = TestStream.create(VarIntCoder.of()).addElements(TimestampedValue.of(1, new Instant(1000))).addElements(TimestampedValue.of(2, new Instant(2000))).advanceWatermarkTo(new Instant(3000)).addElements(TimestampedValue.of(10, new Instant(1000))).advanceWatermarkTo(new Instant(10000));
