    acc = agg.reduce(acc, windowedValue(2, at(16)));
    assertThat(acc, equalsToMap(KV.of(intervalWindow(0, 15), pair(at(10), 1)), KV.of(intervalWindow(5, 20), pair(at(16), 3)), KV.of(intervalWindow(10, 25), pair(at(16), 3)), KV.of(intervalWindow(15, 30), pair(at(16), 2))));
