@Test
public void testMerge() {
    Map<IntervalWindow, MutablePair<Instant, Integer>> acc;
    assertThat(agg.merge(agg.zero(), agg.zero()), equalTo(agg.zero()));
    acc = mapOf(KV.of(intervalWindow(0, 15), pair(at(0), 1)));
    assertThat(agg.merge(acc, agg.zero()), equalTo(acc));
    assertThat(agg.merge(agg.zero(), acc), equalTo(acc));
    acc = agg.merge(acc, acc);
    assertThat(acc, equalsToMap(KV.of(intervalWindow(0, 15), pair(at(0), 1 + 1))));
    acc = agg.merge(acc, mapOf(KV.of(intervalWindow(5, 20), pair(at(5), 3))));
    assertThat(acc, equalsToMap(KV.of(intervalWindow(0, 15), pair(at(0), 1 + 1)), KV.of(intervalWindow(5, 20), pair(at(5), 3))));
    acc = agg.merge(mapOf(KV.of(intervalWindow(10, 25), pair(at(10), 4))), acc);
    assertThat(acc, equalsToMap(KV.of(intervalWindow(0, 15), pair(at(0), 1 + 1)), KV.of(intervalWindow(5, 20), pair(at(5), 3)), KV.of(intervalWindow(10, 25), pair(at(10), 4))));
}

@Test
public void testReduce() {
    AccT acc;
    acc = agg.reduce(agg.zero(), sessionValue(10, at(0)));
    assertThat(acc, equalsToMap(KV.of(sessionWindow(0), pair(at(0), 10))));
    // 2nd session after 1st
    acc = agg.reduce(acc, sessionValue(7, at(20)));
    assertThat(acc, equalsToMap(KV.of(sessionWindow(0), pair(at(0), 10)), KV.of(sessionWindow(20), pair(at(20), 7))));
    // merge into 2nd session
    acc = agg.reduce(acc, sessionValue(6, at(18)));
    assertThat(acc, equalsToMap(KV.of(sessionWindow(0), pair(at(0), 10)), KV.of(sessionWindow(18, 35), pair(at(20), 7 + 6))));
    // merge into 2nd session
    acc = agg.reduce(acc, sessionValue(5, at(21)));
    assertThat(acc, equalsToMap(KV.of(sessionWindow(0), pair(at(0), 10)), KV.of(sessionWindow(18, 36), pair(at(21), 7 + 6 + 5))));
    // 3rd session after 2nd
    acc = agg.reduce(acc, sessionValue(2, NOW.plus(standardMinutes(45))));
    assertThat(acc, equalsToMap(KV.of(sessionWindow(0), pair(at(0), 10)), KV.of(sessionWindow(18, 36), pair(at(21), 7 + 6 + 5)), KV.of(sessionWindow(45), pair(at(45), 2))));
    // merge with 1st and 2nd
    acc = agg.reduce(acc, sessionValue(1, at(10)));
    assertThat(acc, equalsToMap(KV.of(sessionWindow(0, 36), pair(at(21), 10 + 7 + 6 + 5 + 1)), KV.of(sessionWindow(45), pair(at(45), 2))));
}

@Test
public void testMerge() {
    AccT acc;
    assertThat(agg.merge(agg.zero(), agg.zero()), equalTo(agg.zero()));
    acc = accOf(KV.of(sessionWindow(0), pair(at(0), 1)));
    assertThat(agg.merge(acc, agg.zero()), equalTo(acc));
    assertThat(agg.merge(agg.zero(), acc), equalTo(acc));
    acc = agg.merge(acc, acc);
    assertThat(acc, equalsToMap(KV.of(sessionWindow(0), pair(at(0), 1 + 1))));
    acc = agg.merge(acc, accOf(KV.of(sessionWindow(20), pair(at(20), 2))));
    assertThat(acc, equalsToMap(KV.of(sessionWindow(0), pair(at(0), 1 + 1)), KV.of(sessionWindow(20), pair(at(20), 2))));
    acc = agg.merge(accOf(KV.of(sessionWindow(40), pair(at(40), 3))), acc);
    assertThat(acc, equalsToMap(KV.of(sessionWindow(0), pair(at(0), 1 + 1)), KV.of(sessionWindow(20), pair(at(20), 2)), KV.of(sessionWindow(40), pair(at(40), 3))));
    acc = agg.merge(acc, accOf(KV.of(sessionWindow(10), pair(at(10), 4))));
    assertThat(acc, equalsToMap(KV.of(sessionWindow(0, 35), pair(at(20), 1 + 1 + 2 + 4)), KV.of(sessionWindow(40), pair(at(40), 3))));
    acc = agg.merge(accOf(KV.of(sessionWindow(5, 45), pair(at(30), 5))), acc);
    assertThat(acc, equalsToMap(KV.of(sessionWindow(0, 55), pair(at(40), 1 + 1 + 2 + 4 + 3 + 5))));
}

