@Test
public void testCountDependentTransformsOnSideOutputs() {
    SparkPipelineOptions options = contextRule.createPipelineOptions();
    Pipeline pipeline = Pipeline.create(options);
    TupleTag<String> passOutTag = new TupleTag<>("passOut");
    TupleTag<Long> lettersCountOutTag = new TupleTag<>("lettersOut");
    TupleTag<Long> wordCountOutTag = new TupleTag<>("wordsOut");
    PCollectionTuple result = pipeline.apply(Create.of("foo", "baz")).apply(ParDo.of(new DoFn<String, String>() {

        @ProcessElement
        public void processElement(ProcessContext processContext) {
            String element = processContext.element();
            processContext.output(element);
            processContext.output(lettersCountOutTag, (long) Objects.requireNonNull(element).length());
            processContext.output(wordCountOutTag, 1L);
        }
    }).withOutputTags(passOutTag, TupleTagList.of(Lists.newArrayList(lettersCountOutTag, wordCountOutTag))));
    // consume main output and words side output. leave letters side output left alone
    result.get(wordCountOutTag).setCoder(VarLongCoder.of()).apply(Sum.longsGlobally());
    result.get(lettersCountOutTag).setCoder(VarLongCoder.of());
    result.get(passOutTag).apply(ParDo.of(new DoFn<String, String>() {

        @ProcessElement
        public void processElement(ProcessContext processContext) {
            // do nothing
        }
    }));
    EvaluationContext ctxt = new EvaluationContext(contextRule.getSparkContext(), pipeline, options);
    TransformTranslator.Translator translator = new TransformTranslator.Translator();
    pipeline.traverseTopologically(new DependentTransformsVisitor(translator, ctxt));
    assertEquals(1, ctxt.getPCollectionConsumptionMap().get(result.get(passOutTag)).intValue());
    assertEquals(1, ctxt.getPCollectionConsumptionMap().get(result.get(wordCountOutTag)).intValue());
    assertEquals(0, ctxt.getPCollectionConsumptionMap().get(result.get(lettersCountOutTag)).intValue());
}

@Test
public void testLowHighWatermarksAdvance() {
    Instant instant = new Instant(0);
    // low == high.
    GlobalWatermarkHolder.add(1, new SparkWatermarks(instant.plus(Duration.millis(5)), instant.plus(Duration.millis(5)), instant));
    GlobalWatermarkHolder.advance();
    // low < high.
    GlobalWatermarkHolder.add(1, new SparkWatermarks(instant.plus(Duration.millis(10)), instant.plus(Duration.millis(15)), instant.plus(Duration.millis(100))));
    GlobalWatermarkHolder.advance();
    // assert watermarks in Broadcast.
    SparkWatermarks currentWatermarks = GlobalWatermarkHolder.get(0L).get(1);
    assertThat(currentWatermarks.getLowWatermark(), equalTo(instant.plus(Duration.millis(10))));
    assertThat(currentWatermarks.getHighWatermark(), equalTo(instant.plus(Duration.millis(15))));
    assertThat(currentWatermarks.getSynchronizedProcessingTime(), equalTo(instant.plus(Duration.millis(100))));
    // assert illegal watermark advance.
    thrown.expect(IllegalStateException.class);
    thrown.expectMessage(RegexMatcher.matches("Low watermark " + INSTANT_PATTERN + " cannot be later then high watermark " + INSTANT_PATTERN));
    // low > high -> not allowed!
    GlobalWatermarkHolder.add(1, new SparkWatermarks(instant.plus(Duration.millis(25)), instant.plus(Duration.millis(20)), instant.plus(Duration.millis(200))));
    GlobalWatermarkHolder.advance();
}

@Test
public void testSynchronizedTimeMonotonic() {
    Instant instant = new Instant(0);
    GlobalWatermarkHolder.add(1, new SparkWatermarks(instant.plus(Duration.millis(5)), instant.plus(Duration.millis(10)), instant));
    GlobalWatermarkHolder.advance();
    thrown.expect(IllegalStateException.class);
    thrown.expectMessage("Synchronized processing time must advance.");
    // no actual advancement of watermarks - fine by Watermarks
    // but not by synchronized processing time.
    GlobalWatermarkHolder.add(1, new SparkWatermarks(instant.plus(Duration.millis(5)), instant.plus(Duration.millis(10)), instant));
    GlobalWatermarkHolder.advance();
}

