@Ignore("Very flaky: https://github.com/apache/beam/issues/34945")
public void testStreamingSideInputAsIterableView() {
    final PipelineFunction pipelineFunction = (PipelineOptions options) -> {
        final Instant baseTimestamp = new Instant(0);
        final Pipeline p = Pipeline.create(options);
        final PCollectionView<Iterable<Long>> streamingSideInput = p.apply("Streaming Side Input As Iterable View", new StreamingSideInputAsIterableView(baseTimestamp));
        final PAssertFn pAssertFn = new PAssertFn();
        pAssertFn.streamingSideInputAsIterableView = streamingSideInput;
        p.apply("Main Input", GenerateSequence.from(0).withRate(1, Duration.millis(500)).withTimestampFn(e -> baseTimestamp.plus(Duration.millis(e * 100)))).apply("StreamingSideInputAssert", ParDo.of(pAssertFn).withSideInput("streaming-side-input", streamingSideInput));
        return p;
    };
    final PipelineResult result = run(pipelineFunction, Optional.of(new Instant(1000)), true);
    final Iterable<MetricResult<DistributionResult>> distributions = result.metrics().queryMetrics(MetricsFilter.builder().addNameFilter(MetricNameFilter.inNamespace(PAssertFn.class)).build()).getDistributions();
    final MetricResult<DistributionResult> streamingIterSideInputMetricResult = Iterables.find(distributions, dist -> dist.getName().getName().equals("streaming_iter_side_input_distribution"));
