public void serializableAccumulatorSerializationTest() throws IOException, ClassNotFoundException {
    Iterable<WindowedValue<Integer>> accumulatedValue = Arrays.asList(winVal(0), winVal(1), winVal(3), winVal(4));
    final WindowedValues.FullWindowedValueCoder<Integer> wvaCoder = WindowedValues.FullWindowedValueCoder.of(BigEndianIntegerCoder.of(), GlobalWindow.Coder.INSTANCE);
    final IterableCoder<WindowedValue<Integer>> iterAccumCoder = IterableCoder.of(wvaCoder);
    ValueAndCoderLazySerializable<Iterable<WindowedValue<Integer>>> accUnderTest = ValueAndCoderLazySerializable.of(accumulatedValue, iterAccumCoder);
    ByteArrayOutputStream inMemOut = new ByteArrayOutputStream();
    ObjectOutputStream oos = new ObjectOutputStream(inMemOut);
    oos.writeObject(accUnderTest);
    ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(inMemOut.toByteArray()));
    @SuppressWarnings("unchecked")
    ValueAndCoderLazySerializable<Iterable<WindowedValue<Integer>>> materialized = (ValueAndCoderLazySerializable<Iterable<WindowedValue<Integer>>>) ois.readObject();
    assertEquals(accumulatedValue, materialized.getOrDecode(iterAccumCoder));
}

