    ValueAndCoderLazySerializable<Iterable<WindowedValue<Integer>>> accUnderTest = ValueAndCoderLazySerializable.of(accumulatedValue, iterAccumCoder);
    ValueAndCoderKryoSerializer kryoSerializer = new ValueAndCoderKryoSerializer();
    Kryo kryo = new Kryo();
    kryo.register(ValueAndCoderLazySerializable.class, kryoSerializer);
    ByteArrayOutputStream inMemOut = new ByteArrayOutputStream();
    Output out = new Output(inMemOut);
    kryo.writeObject(out, accUnderTest);
    out.close();
    Input input = new Input(new ByteArrayInputStream(inMemOut.toByteArray()));
    @SuppressWarnings("unchecked")
    ValueAndCoderLazySerializable<Iterable<WindowedValue<Integer>>> materialized = (ValueAndCoderLazySerializable<Iterable<WindowedValue<Integer>>>) kryo.readObject(input, ValueAndCoderLazySerializable.class);
