@Test
public void testEncodingPositionReorderFields() throws Exception {
    Schema schema1 = Schema.builder().addNullableField("f_int32", FieldType.INT32).addNullableField("f_string", FieldType.STRING).build();
    Schema schema2 = Schema.builder().addNullableField("f_string", FieldType.STRING).addNullableField("f_int32", FieldType.INT32).build();
    schema2.setEncodingPositions(ImmutableMap.of("f_int32", 0, "f_string", 1));
    Row row = Row.withSchema(schema1).withFieldValue("f_int32", 42).withFieldValue("f_string", "hello world!").build();
    Row expected = Row.withSchema(schema2).withFieldValue("f_int32", 42).withFieldValue("f_string", "hello world!").build();
    ByteArrayOutputStream os = new ByteArrayOutputStream();
    RowCoder.of(schema1).encode(row, os);
    Row decoded = RowCoder.of(schema2).decode(new ByteArrayInputStream(os.toByteArray()));
    assertEquals(expected, decoded);
}

@Test
public void testEncodingPositionReorderFieldsWithNulls() throws Exception {
    Schema schema1 = Schema.builder().addNullableField("f_int32", FieldType.INT32).addNullableField("f_string", FieldType.STRING).build();
    Schema schema2 = Schema.builder().addNullableField("f_string", FieldType.STRING).addNullableField("f_int32", FieldType.INT32).build();
    schema2.setEncodingPositions(ImmutableMap.of("f_int32", 0, "f_string", 1));
    Row schema1row = Row.withSchema(schema1).withFieldValue("f_int32", null).withFieldValue("f_string", "hello world!").build();
    Row schema2row = Row.withSchema(schema2).withFieldValue("f_int32", null).withFieldValue("f_string", "hello world!").build();
    ByteArrayOutputStream os = new ByteArrayOutputStream();
    RowCoder.of(schema1).encode(schema1row, os);
    Row schema1to2decoded = RowCoder.of(schema2).decode(new ByteArrayInputStream(os.toByteArray()));
    assertEquals(schema2row, schema1to2decoded);
    os.reset();
    RowCoder.of(schema2).encode(schema2row, os);
    Row schema2to1decoded = RowCoder.of(schema1).decode(new ByteArrayInputStream(os.toByteArray()));
    assertEquals(schema1row, schema2to1decoded);
}

@Test
public void testEncodingPositionReorderViaStaticOverride() throws Exception {
    Schema schema1 = Schema.builder().addNullableField("failsafeTableRowPayload", FieldType.STRING).addByteArrayField("payload").addNullableField("timestamp", FieldType.INT32).addNullableField("unknownFieldsPayload", FieldType.STRING).build();
    UUID uuid = UUID.randomUUID();
    schema1.setUUID(uuid);
    Row row = Row.withSchema(schema1).addValues("", "hello world!".getBytes(StandardCharsets.UTF_8), 1, "").build();
    ByteArrayOutputStream os = new ByteArrayOutputStream();
    RowCoder.of(schema1).encode(row, os);
    // Pretend that we are restarting and want to recover from persisted state with a compatible
    // schema using the
    // overridden encoding positions.
    RowCoder.clearGeneratedRowCoders();
    RowCoder.overrideEncodingPositions(uuid, ImmutableMap.of("failsafeTableRowPayload", 0, "payload", 1, "timestamp", 2, "unknownFieldsPayload", 3));
    Schema schema2 = Schema.builder().addByteArrayField("payload").addNullableField("timestamp", FieldType.INT32).addNullableField("unknownFieldsPayload", FieldType.STRING).addNullableField("failsafeTableRowPayload", FieldType.STRING).build();
    schema2.setUUID(uuid);
    Row expected = Row.withSchema(schema2).addValues("hello world!".getBytes(StandardCharsets.UTF_8), 1, "", "").build();
    Row decoded = RowCoder.of(schema2).decode(new ByteArrayInputStream(os.toByteArray()));
    assertEquals(expected, decoded);
}

