@Category(NeedsRunner.class)
public void testMatchAndMatchAll() throws IOException {
    Path firstPath = tmpFolder.newFile("first").toPath();
    Path secondPath = tmpFolder.newFile("second").toPath();
    int firstSize = 37;
    int secondSize = 42;
    long firstModified = 1541097000L;
    long secondModified = 1541098000L;
    Files.write(firstPath, new byte[firstSize]);
    Files.write(secondPath, new byte[secondSize]);
    Files.setLastModifiedTime(firstPath, FileTime.fromMillis(firstModified));
    Files.setLastModifiedTime(secondPath, FileTime.fromMillis(secondModified));
    MatchResult.Metadata firstMetadata = metadata(firstPath, firstSize, firstModified);
    MatchResult.Metadata secondMetadata = metadata(secondPath, secondSize, secondModified);
    PAssert.that(p.apply("Match existing", FileIO.match().filepattern(tmpFolder.getRoot().getAbsolutePath() + "/*"))).containsInAnyOrder(firstMetadata, secondMetadata);
    PAssert.that(p.apply("Match existing with provider", FileIO.match().filepattern(p.newProvider(tmpFolder.getRoot().getAbsolutePath() + "/*")))).containsInAnyOrder(firstMetadata, secondMetadata);
    PAssert.that(p.apply("Create existing", Create.of(tmpFolder.getRoot().getAbsolutePath() + "/*")).apply("MatchAll existing", FileIO.matchAll())).containsInAnyOrder(firstMetadata, secondMetadata);
    PAssert.that(p.apply("Match non-existing ALLOW", FileIO.match().filepattern(tmpFolder.getRoot().getAbsolutePath() + "/blah").withEmptyMatchTreatment(EmptyMatchTreatment.ALLOW))).empty();
    PAssert.that(p.apply("Create non-existing", Create.of(tmpFolder.getRoot().getAbsolutePath() + "/blah")).apply("MatchAll non-existing ALLOW", FileIO.matchAll().withEmptyMatchTreatment(EmptyMatchTreatment.ALLOW))).empty();
    PAssert.that(p.apply("Match non-existing ALLOW_IF_WILDCARD", FileIO.match().filepattern(tmpFolder.getRoot().getAbsolutePath() + "/blah*").withEmptyMatchTreatment(EmptyMatchTreatment.ALLOW_IF_WILDCARD))).empty();
    PAssert.that(p.apply("Create non-existing wildcard + explicit", Create.of(tmpFolder.getRoot().getAbsolutePath() + "/blah*")).apply("MatchAll non-existing ALLOW_IF_WILDCARD", FileIO.matchAll().withEmptyMatchTreatment(EmptyMatchTreatment.ALLOW_IF_WILDCARD))).empty();
    PAssert.that(p.apply("Create non-existing wildcard + default", Create.of(tmpFolder.getRoot().getAbsolutePath() + "/blah*")).apply("MatchAll non-existing default", FileIO.matchAll())).empty();
    p.run();
}

