@Test
@Category({ NeedsRunner.class, UsesUnboundedSplittableParDo.class })
public void testMatchWatchForNewFiles() throws IOException, InterruptedException {
    // Write some files to a "source" directory.
    final Path sourcePath = tmpFolder.getRoot().toPath().resolve("source");
    sourcePath.toFile().mkdir();
    Files.write(sourcePath.resolve("first"), new byte[42]);
    Files.write(sourcePath.resolve("second"), new byte[37]);
    Files.write(sourcePath.resolve("third"), new byte[99]);
    // Create a "watch" directory that the pipeline will copy files into.
    final Path watchPath = tmpFolder.getRoot().toPath().resolve("watch");
    watchPath.toFile().mkdir();
    PCollection<MatchResult.Metadata> matchMetadata = p.apply("match filename through match", FileIO.match().filepattern(watchPath.resolve("*").toString()).continuously(Duration.millis(100), Watch.Growth.afterTimeSinceNewOutput(Duration.standardSeconds(1))));
    PCollection<MatchResult.Metadata> matchAllMetadata = p.apply("create for matchAll new files", Create.of(watchPath.resolve("*").toString())).apply("match filename through matchAll", FileIO.matchAll().continuously(Duration.millis(100), Watch.Growth.afterTimeSinceNewOutput(Duration.standardSeconds(1))));
    PCollection<MatchResult.Metadata> matchUpdatedMetadata = p.apply("match updated", FileIO.match().filepattern(watchPath.resolve("first").toString()).continuously(Duration.millis(100), Watch.Growth.afterTimeSinceNewOutput(Duration.standardSeconds(1)), true));
    PCollection<MatchResult.Metadata> matchAllUpdatedMetadata = p.apply("create for matchAll updated files", Create.of(watchPath.resolve("*").toString())).apply("matchAll updated", FileIO.matchAll().continuously(Duration.millis(100), Watch.Growth.afterTimeSinceNewOutput(Duration.standardSeconds(1)), true));
    // write one file at the beginning. This will trigger the first output for matchAll
    Files.copy(sourcePath.resolve("first"), watchPath.resolve("first"), new StandardCopyOption[] { StandardCopyOption.COPY_ATTRIBUTES });
    // using matchMetadata outputs to trigger file copy on-the-fly
    matchMetadata = matchMetadata.apply(MapElements.into(TypeDescriptors.kvs(TypeDescriptors.strings(), TypeDescriptor.of(MatchResult.Metadata.class))).via((metadata) -> KV.of("dumb key", metadata))).apply(ParDo.of(new CopyFilesFn(sourcePath, watchPath)));
    assertEquals(PCollection.IsBounded.UNBOUNDED, matchMetadata.isBounded());
    assertEquals(PCollection.IsBounded.UNBOUNDED, matchAllMetadata.isBounded());
    assertEquals(PCollection.IsBounded.UNBOUNDED, matchUpdatedMetadata.isBounded());
    assertEquals(PCollection.IsBounded.UNBOUNDED, matchAllUpdatedMetadata.isBounded());
    // We fetch lastModifiedTime from the files in the "source" directory to avoid a race condition
    // with the writer thread.
    List<MatchResult.Metadata> expectedMatchNew = Arrays.asList(metadata(watchPath.resolve("first"), 42, lastModifiedMillis(sourcePath.resolve("first"))), metadata(watchPath.resolve("second"), 37, lastModifiedMillis(sourcePath.resolve("second"))), metadata(watchPath.resolve("third"), 99, lastModifiedMillis(sourcePath.resolve("third"))));
    PAssert.that(matchMetadata).containsInAnyOrder(expectedMatchNew);
    PAssert.that(matchAllMetadata).containsInAnyOrder(expectedMatchNew);
    List<String> expectedMatchUpdated = Arrays.asList("first", "first", "first");
    PCollection<String> matchUpdatedCount = matchUpdatedMetadata.apply("pick up match file name", MapElements.into(TypeDescriptors.strings()).via((metadata) -> metadata.resourceId().getFilename()));
    PAssert.that(matchUpdatedCount).containsInAnyOrder(expectedMatchUpdated);
    // Check watch for file updates. Compare only filename since modified time of copied files are
    // uncontrolled.
    List<String> expectedMatchAllUpdated = Arrays.asList("first", "first", "first", "second", "second", "third");
    PCollection<String> matchAllUpdatedCount = matchAllUpdatedMetadata.apply("pick up matchAll file names", MapElements.into(TypeDescriptors.strings()).via((metadata) -> metadata.resourceId().getFilename()));
    PAssert.that(matchAllUpdatedCount).containsInAnyOrder(expectedMatchAllUpdated);
    p.run();
}

@Test
@Category(NeedsRunner.class)
public void testRead() throws IOException {
    final String path = tmpFolder.newFile("file").getAbsolutePath();
    final String pathGZ = tmpFolder.newFile("file.gz").getAbsolutePath();
    Files.write(new File(path).toPath(), "Hello world".getBytes(StandardCharsets.UTF_8));
    try (Writer writer = new OutputStreamWriter(new GZIPOutputStream(new FileOutputStream(pathGZ)), StandardCharsets.UTF_8)) {
        writer.write("Hello world");
    }
    PCollection<MatchResult.Metadata> matches = p.apply("Match", FileIO.match().filepattern(path));
    PCollection<FileIO.ReadableFile> decompressedAuto = matches.apply("Read AUTO", FileIO.readMatches().withCompression(Compression.AUTO));
    PCollection<FileIO.ReadableFile> decompressedDefault = matches.apply("Read default", FileIO.readMatches());
    PCollection<FileIO.ReadableFile> decompressedUncompressed = matches.apply("Read UNCOMPRESSED", FileIO.readMatches().withCompression(Compression.UNCOMPRESSED));
    for (PCollection<FileIO.ReadableFile> c : Arrays.asList(decompressedAuto, decompressedDefault, decompressedUncompressed)) {
        PAssert.thatSingleton(c).satisfies(input -> {
            assertEquals(path, input.getMetadata().resourceId().toString());
            assertEquals("Hello world".length(), input.getMetadata().sizeBytes());
            assertEquals(Compression.UNCOMPRESSED, input.getCompression());
            assertTrue(input.getMetadata().isReadSeekEfficient());
            try {
                assertEquals("Hello world", input.readFullyAsUTF8String());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
            return null;
        });
    }
    PCollection<MatchResult.Metadata> matchesGZ = p.apply("Match GZ", FileIO.match().filepattern(pathGZ));
    PCollection<FileIO.ReadableFile> compressionAuto = matchesGZ.apply("Read GZ AUTO", FileIO.readMatches().withCompression(Compression.AUTO));
    PCollection<FileIO.ReadableFile> compressionDefault = matchesGZ.apply("Read GZ default", FileIO.readMatches());
    PCollection<FileIO.ReadableFile> compressionGzip = matchesGZ.apply("Read GZ GZIP", FileIO.readMatches().withCompression(Compression.GZIP));
    for (PCollection<FileIO.ReadableFile> c : Arrays.asList(compressionAuto, compressionDefault, compressionGzip)) {
        PAssert.thatSingleton(c).satisfies(input -> {
            assertEquals(pathGZ, input.getMetadata().resourceId().toString());
            assertFalse(input.getMetadata().sizeBytes() == "Hello world".length());
            assertEquals(Compression.GZIP, input.getCompression());
            assertFalse(input.getMetadata().isReadSeekEfficient());
            try {
                assertEquals("Hello world", input.readFullyAsUTF8String());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
            return null;
        });
    }
    p.run();
}

@Test
public void testFilenameFnResolution() throws Exception {
    FileIO.Write.FileNaming foo = (window, paneInfo, numShards, shardIndex, compression) -> "foo";
    String expected = FileSystems.matchNewResource("test", true).resolve("foo", RESOLVE_FILE).toString();
    assertEquals("Filenames should be resolved within a relative directory if '.to' is invoked", expected, getDefaultFileName(FileIO.writeDynamic().to("test").withNaming(o -> foo)));
    assertEquals("Filenames should be resolved within a relative directory if '.to' is invoked", expected, getDefaultFileName(FileIO.write().to("test").withNaming(foo)));
    assertEquals("Filenames should be resolved as the direct result of the filenaming function if '.to' " + "is not invoked", "foo", getDefaultFileName(FileIO.writeDynamic().withNaming(o -> foo)));
    assertEquals("Filenames should be resolved as the direct result of the filenaming function if '.to' " + "is not invoked", "foo", getDefaultFileName(FileIO.write().withNaming(foo)));
    assertEquals("Default to the defaultNaming if a filenaming isn't provided for a non-dynamic write", "output-00000-of-00000", resolveFileNaming(FileIO.write()).getFilename(GlobalWindow.INSTANCE, PaneInfo.ON_TIME_AND_ONLY_FIRING, 0, 0, Compression.UNCOMPRESSED));
    assertEquals("Default Naming should take prefix and suffix into account if provided", "foo-00000-of-00000.bar", resolveFileNaming(FileIO.write().withPrefix("foo").withSuffix(".bar")).getFilename(GlobalWindow.INSTANCE, PaneInfo.ON_TIME_AND_ONLY_FIRING, 0, 0, Compression.UNCOMPRESSED));
    assertEquals("Filenames should be resolved within a relative directory if '.to' is invoked, " + "even with default naming", FileSystems.matchNewResource("test", true).resolve("output-00000-of-00000", RESOLVE_FILE).toString(), resolveFileNaming(FileIO.write().to("test")).getFilename(GlobalWindow.INSTANCE, PaneInfo.ON_TIME_AND_ONLY_FIRING, 0, 0, Compression.UNCOMPRESSED));
}

