@Test
@Category({ NeedsRunner.class, UsesUnboundedPCollections.class, UsesUnboundedSplittableParDo.class })
public void testWatermarkAdvanceOnClaimFail() {
    // NOTE: this test is supposed to run only against DirectRunner
    // as for other runners it might not be working the interception of watermark
    // through the STATIC_INSTANT_LIST_MAP
    int numElements = 1000;
    final String uuid = UUID.randomUUID().toString();
    List<Instant> interceptedWatermark = STATIC_INSTANT_LIST_MAP.computeIfAbsent(uuid, tmp -> new ArrayList<>());
    PCollection<Long> counted = pipeline.apply(newUnboundedReadInterceptingWatermark(numElements, (Serializable & Consumer<Instant>) instant -> STATIC_INSTANT_LIST_MAP.get(uuid).add(instant))).apply(Window.<Long>into(new GlobalWindows()).discardingFiredPanes().triggering(AfterWatermark.pastEndOfWindow())).apply(Count.globally());
    PAssert.that(counted).containsInAnyOrder((long) numElements);
    pipeline.run().waitUntilFinish();
    // verify that the observed watermark gradually moves
    assertThat(interceptedWatermark.size(), greaterThanOrEqualTo(numElements));
    Instant watermark = interceptedWatermark.get(0);
    for (int i = 1; i < interceptedWatermark.size(); i++) {
        assertThat("Watermarks should be non-decreasing sequence, got " + interceptedWatermark, !watermark.isAfter(interceptedWatermark.get(i)));
        watermark = interceptedWatermark.get(i);
    }
}

