@Test
public void testWrapSegment() {
    Map<String, String> testCases = ImmutableMap.<String, String>builder().put("apache-beam", "apache-beam").put("`apache-beam`", "```apache-beam```").put("apache.beam", "`apache.beam`").put("apache:beam", "`apache:beam`").put("apache beam", "`apache beam`").put("apache`beam", "`apache``beam`").put("apache` beam", "`apache`` beam`").put("`apache-beam", "```apache-beam`").put("apache-beam`", "`apache-beam```").put("`apache beam`", "```apache beam```").put("apache\tbeam", "`apache\tbeam`").put("apache\nbeam", "`apache\nbeam`").build();
    testCases.forEach((key, value) -> {
        Iterable<String> fqnPartsIterator = Lineage.getFQNParts("apache", null, ImmutableList.of(key), null);
        String fqnPartsString = getFqnPartsString(fqnPartsIterator);
        assertEquals("apache:" + value, fqnPartsString);
    });
    testCases.forEach((key, value) -> {
        Iterable<String> fqnPartsIterator = Lineage.getFQNParts("apache", "beam", ImmutableList.of(key), null);
        String fqnPartsString = getFqnPartsString(fqnPartsIterator);
        assertEquals("apache:beam:" + value, fqnPartsString);
    });
    testCases.forEach((key, value) -> {
        Iterable<String> fqnPartsIterator = Lineage.getFQNParts("apache", "beam", ImmutableList.of(key, key), null);
        String fqnPartsString = getFqnPartsString(fqnPartsIterator);
        assertEquals("apache:beam:" + value + "." + value, fqnPartsString);
    });
}

@Test
public void getFQNParts() {
    Iterable<String> simpleFQN = Lineage.getFQNParts("system", null, ImmutableList.of("project", "dataset", "table"), null);
    assertEquals("system:project.dataset.table", getFqnPartsString(simpleFQN));
    Iterable<String> subTypeFQN = Lineage.getFQNParts("system", "topic", ImmutableList.of("project", "topicid"), null);
    assertEquals("system:topic:project.topicid", getFqnPartsString(subTypeFQN));
