@Test
public void testSortedMethodIncludesAllSchemaFields() {
    // This test is most likely to break when new Schema object attributes are added. It is designed
    // this way to make sure that the Schema::sorted() method is updated to return a full sorted
    // copy.
    // Schema object attributes that are accounted for in Schema::sorted().
    // Note: Only the appropriate ones are copied over.
    List<String> attributesAccountedForInSorted = Arrays.asList("fieldIndices", "encodingPositions", "encodingPositionsOverridden", "fields", "hashCode", "uuid", "options");
    // Current attributes in Schema object.
    List<String> currentAttributes = Arrays.stream(Schema.class.getDeclaredFields()).filter(field -> !field.isSynthetic()).map(java.lang.reflect.Field::getName).collect(Collectors.toList());
    List<String> differences = new ArrayList<>(currentAttributes);
    differences.removeAll(attributesAccountedForInSorted);
    assertEquals(String.format("Detected attributes %s in Schema object that are not accounted for in Schema::sorted(). " + "If appropriate, sorted() should copy over these attributes as well. Either way, update this test after checking.", differences.toString()), currentAttributes, attributesAccountedForInSorted);
}

