    Schema.FieldType translated = SchemaTranslation.fieldTypeFromProto(proto);
    assertThat(translated.getLogicalType().getClass(), equalTo(fieldType.getLogicalType().getClass()));
    assertThat(translated.getLogicalType().getArgumentType(), equalTo(fieldType.getLogicalType().getArgumentType()));
    assertThat(translated.getLogicalType().getArgument(), equalTo(fieldType.getLogicalType().getArgument()));
