    // Manually add the outer-join rows to the list of expected results. Missing results from the
    // middle (pc2) PCollection are filled in with nulls. Missing events from other PCollections
    // are not. Events with key ("user2", "ar) show up in pc1 and pc3 but not in pc2, so we expect
    // the outer join to still produce those rows, with nulls for pc2. Events with key
    // ("user3", "ar) however show up in p2 and pc3, but not in pc1; since pc1 is marked for
    // full participation (no outer join), these events should not be included in the join.
    expectedJoinedRows.add(Row.withSchema(expectedSchema).addValues(Row.withSchema(CG_SCHEMA_1).addValues("user2", 7, "ar").build(), null, Row.withSchema(CG_SCHEMA_3).addValues("user2", 23, "ar").build()).build());
    expectedJoinedRows.add(Row.withSchema(expectedSchema).addValues(Row.withSchema(CG_SCHEMA_1).addValues("user2", 7, "ar").build(), null, Row.withSchema(CG_SCHEMA_3).addValues("user2", 24, "ar").build()).build());
    expectedJoinedRows.add(Row.withSchema(expectedSchema).addValues(Row.withSchema(CG_SCHEMA_1).addValues("user2", 8, "ar").build(), null, Row.withSchema(CG_SCHEMA_3).addValues("user2", 23, "ar").build()).build());
    expectedJoinedRows.add(Row.withSchema(expectedSchema).addValues(Row.withSchema(CG_SCHEMA_1).addValues("user2", 8, "ar").build(), null, Row.withSchema(CG_SCHEMA_3).addValues("user2", 24, "ar").build()).build());
    PAssert.that(joined).containsInAnyOrder(expectedJoinedRows);
    pipeline.run();
}

