    List<Row> pc2Rows = ImmutableList.of(Row.withSchema(CG_SCHEMA_1).addValues("user1", 9, "us").build(), Row.withSchema(CG_SCHEMA_1).addValues("user1", 10, "us").build(), Row.withSchema(CG_SCHEMA_1).addValues("user1", 11, "il").build(), Row.withSchema(CG_SCHEMA_1).addValues("user1", 12, "il").build(), Row.withSchema(CG_SCHEMA_1).addValues("user2", 13, "fr").build(), Row.withSchema(CG_SCHEMA_1).addValues("user2", 14, "fr").build(), Row.withSchema(CG_SCHEMA_1).addValues("user2", 15, "ar").build(), Row.withSchema(CG_SCHEMA_1).addValues("user2", 16, "ar").build(), Row.withSchema(CG_SCHEMA_1).addValues("user4", 8, "ar").build());
    PCollection<Row> pc1 = pipeline.apply("Create1", Create.of(pc1Rows)).setRowSchema(CG_SCHEMA_1);
    PCollection<Row> pc2 = pipeline.apply("Create2", Create.of(pc2Rows)).setRowSchema(CG_SCHEMA_1);
    Schema expectedSchema = Schema.builder().addNullableField(Join.LHS_TAG, Schema.FieldType.row(CG_SCHEMA_1)).addField(Join.RHS_TAG, Schema.FieldType.row(CG_SCHEMA_1)).build();
    PCollection<Row> joined = pc1.apply("right", Join.<Row, Row>rightOuterJoin(pc2).using("user", "country"));
    assertEquals(expectedSchema, joined.getSchema());
    List<Row> expectedJoinedRows = innerJoin(pc1Rows, pc2Rows, new String[] { "user", "country" }, new String[] { "user", "country" }, expectedSchema);
    expectedJoinedRows.add(Row.withSchema(expectedSchema).addValues(null, Row.withSchema(CG_SCHEMA_1).addValues("user4", 8, "ar").build()).build());
    PAssert.that(joined).containsInAnyOrder(expectedJoinedRows);
    pipeline.run();
}

