@Test
@Category({ ValidatesRunner.class, UsesTestStream.class })
public void testLateDataAccumulating() {
    Instant instant = new Instant(0);
    TestStream<Long> source = TestStream.create(VarLongCoder.of()).addElements(TimestampedValue.of(1L, instant), TimestampedValue.of(2L, instant), TimestampedValue.of(3L, instant)).advanceWatermarkTo(instant.plus(Duration.standardMinutes(6))).// These elements are late but within the allowed lateness
    addElements(TimestampedValue.of(4L, instant), TimestampedValue.of(5L, instant)).advanceWatermarkTo(instant.plus(Duration.standardMinutes(10))).// FIXME: Without advancing the watermark once more the (lower) input watermark remains
    // at 6 mins, but data in [0,5 min) won't be considered late until it passes 10 mins.
    advanceWatermarkTo(instant.plus(Duration.standardMinutes(20))).// These elements are droppably late
    addElements(TimestampedValue.of(-1L, instant), TimestampedValue.of(-2L, instant), TimestampedValue.of(-3L, instant)).advanceWatermarkToInfinity();
    PCollection<Long> windowed = p.apply(source).apply(Window.<Long>into(FixedWindows.of(Duration.standardMinutes(5))).triggering(AfterWatermark.pastEndOfWindow().withEarlyFirings(AfterProcessingTime.pastFirstElementInPane().plusDelayOf(Duration.standardMinutes(2))).withLateFirings(AfterPane.elementCountAtLeast(1))).accumulatingFiredPanes().withAllowedLateness(Duration.standardMinutes(5), ClosingBehavior.FIRE_ALWAYS));
    PCollection<Long> triggered = windowed.apply(WithKeys.of(1)).apply(GroupByKey.create()).apply(Values.create()).apply(Flatten.iterables());
    PCollection<Long> count = windowed.apply(Combine.globally(Count.<Long>combineFn()).withoutDefaults());
    PCollection<Long> sum = windowed.apply(Sum.longsGlobally().withoutDefaults());
    IntervalWindow window = new IntervalWindow(instant, instant.plus(Duration.standardMinutes(5L)));
    PAssert.that(triggered).inFinalPane(window).containsInAnyOrder(1L, 2L, 3L, 4L, 5L);
    PAssert.that(triggered).inOnTimePane(window).containsInAnyOrder(1L, 2L, 3L);
    PAssert.that(count).inWindow(window).satisfies(input -> {
        for (Long count1 : input) {
            assertThat(count1, allOf(greaterThanOrEqualTo(3L), lessThanOrEqualTo(5L)));
        }
        return null;
    });
    PAssert.that(sum).inWindow(window).satisfies(input -> {
        for (Long sum1 : input) {
            assertThat(sum1, allOf(greaterThanOrEqualTo(6L), lessThanOrEqualTo(15L)));
        }
        return null;
    });
    p.run();
}

@Test
@Category({ ValidatesRunner.class, UsesTestStreamWithProcessingTime.class })
