@Test
@Category({ ValidatesRunner.class, UsesTestStream.class, UsesTestStreamWithMultipleStages.class, UsesStatefulParDo.class })
public void testMultiStage() throws Exception {
    TestStream<String> testStream = TestStream.create(StringUtf8Coder.of()).addElements(// before
    "before").advanceWatermarkTo(// BEFORE
    Instant.ofEpochSecond(0)).addElements(// after
    TimestampedValue.of("after", Instant.ofEpochSecond(10))).// AFTER
    advanceWatermarkToInfinity();
    PCollection<String> input = p.apply(testStream);
    PCollection<String> grouped = input.apply(Window.into(FixedWindows.of(Duration.standardSeconds(1)))).apply(MapElements.into(TypeDescriptors.kvs(TypeDescriptors.strings(), TypeDescriptors.strings())).via(e -> KV.of(e, e))).apply(GroupByKey.create()).apply(Keys.create()).apply("Upper", MapElements.into(TypeDescriptors.strings()).via(String::toUpperCase)).apply("Rewindow", Window.into(new GlobalWindows()));
    PCollection<String> result = PCollectionList.of(ImmutableList.of(input, grouped)).apply(Flatten.pCollections()).apply("Key", MapElements.into(TypeDescriptors.kvs(TypeDescriptors.strings(), TypeDescriptors.strings())).via(e -> KV.of("key", e))).apply(ParDo.of(new DoFn<KV<String, String>, String>() {

        @StateId("seen")
        private final StateSpec<ValueState<String>> seenSpec = StateSpecs.value(StringUtf8Coder.of());

        @TimerId("emit")
        private final TimerSpec emitSpec = TimerSpecs.timer(TimeDomain.EVENT_TIME);

        @ProcessElement
        public void process(ProcessContext context, @StateId("seen") ValueState<String> seenState, @TimerId("emit") Timer emitTimer) {
            String element = context.element().getValue();
            if (seenState.read() == null) {
                seenState.write(element);
            } else {
                seenState.write(seenState.read() + "," + element);
            }
            emitTimer.set(Instant.ofEpochSecond(100));
        }

        @OnTimer("emit")
        public void onEmit(OnTimerContext context, @StateId("seen") ValueState<String> seenState) {
            context.output(seenState.read());
        }
    }));
    PAssert.that(result).containsInAnyOrder("before,BEFORE,after,AFTER");
    p.run().waitUntilFinish();
}

