    PCollection<String> distinctValues = p.apply(values).apply(Window.into(FixedWindows.of(Duration.standardSeconds(30)))).apply(Deduplicate.values());
    PAssert.that(distinctValues).inWindow(new IntervalWindow(base, base.plus(Duration.standardSeconds(30)))).containsInAnyOrder("k1", "k2", "k3");
