@Test
@Category(ValidatesRunner.class)
public void testFlattenInputMultipleCopies() {
    int count = 5;
    PCollection<Long> longs = p.apply("mkLines", GenerateSequence.from(0).to(count));
    PCollection<Long> biggerLongs = p.apply("mkOtherLines", GenerateSequence.from(0).to(count)).apply(MapElements.via(new SimpleFunction<Long, Long>() {

        @Override
        public Long apply(Long input) {
            return input + 10L;
        }
    }));
    PCollection<Long> flattened = PCollectionList.of(longs).and(longs).and(biggerLongs).apply(Flatten.pCollections());
    List<Long> expectedLongs = new ArrayList<>();
    for (int i = 0; i < count; i++) {
        // The duplicated input
        expectedLongs.add((long) i);
        expectedLongs.add((long) i);
        // The bigger longs
        expectedLongs.add(i + 10L);
    }
    PAssert.that(flattened).containsInAnyOrder(expectedLongs);
    p.run();
}

