/**
 * Tests that data from a processing time trigger flows through subsequent GroupByKey
 * transforms. To test this with TestStream, we check that it arrives in an early pane,
 * demonstrating that the watermark did not cause the output.
 */
@Test
@Category({ ValidatesRunner.class, UsesTestStreamWithProcessingTime.class })
public void testAfterProcessingTimeContinuationTriggerEarly() throws Exception {
    // Setting of the processing time trigger
    final long triggerMillis = 1;
    // How far we advance time for the first GBK to trigger
    final long advanceMillis = 10;
    // How far we advance time for the second GBK to trigger
    final long waitMillis = 500;
    PCollection<Integer> triggeredSums = p.apply(TestStream.create(VarIntCoder.of()).advanceWatermarkTo(new Instant(0)).addElements(42).advanceProcessingTime(Duration.millis(advanceMillis)).advanceProcessingTime(Duration.millis(waitMillis)).advanceWatermarkToInfinity()).apply(Window.<Integer>configure().triggering(Repeatedly.forever(AfterProcessingTime.pastFirstElementInPane().plusDelayOf(Duration.millis(triggerMillis)))).accumulatingFiredPanes().withOnTimeBehavior(Window.OnTimeBehavior.FIRE_IF_NON_EMPTY).withAllowedLateness(Duration.millis(0))).apply("Triggered sum", Sum.integersGlobally().withoutDefaults()).apply("Second Triggered sum", Sum.integersGlobally().withoutDefaults());
    PAssert.that(triggeredSums).inEarlyGlobalWindowPanes().containsInAnyOrder(42);
    p.run();
}

/**
 * Tests that data from a processing time trigger flows through subsequent GroupByKey
 * transforms. This version does not depend on {@link TestStream} with processing time, because
 * many runners do not support it.
 *
 * <p>Since a delay in processing time is fundamental to this test, it unfortunately must have a
 * real-time sleep. Currently the sleep is sub-second so it is acceptable delay for a unit test
 * suite.
 */
@Test
@Category({ ValidatesRunner.class, UsesTimersInParDo.class, UsesProcessingTimeTimers.class, UsesUnboundedPCollections.class })
public void testAfterProcessingTimeContinuationTriggerUsingState() throws Exception {
    final long triggerMillis = 1;
    final long waitMillis = 500;
    PCollection<Integer> triggeredSums = p.apply(GenerateSequence.from(0).to(// forces unbounded so delay cannot be fast-forwarded
    1)).apply(WithKeys.of("dummy key")).apply("output then delay", ParDo.of(new DoFn<KV<String, Long>, Integer>() {

        private static final String DELAY_TIMER = "delay";

        @TimerId(DELAY_TIMER)
        private final TimerSpec delayTimerSpec = TimerSpecs.timer(TimeDomain.EVENT_TIME);

        @ProcessElement
        public void process(@Timestamp Instant timestamp, BoundedWindow window, OutputReceiver<Integer> out, @TimerId(DELAY_TIMER) Timer delayTimer) {
            out.output(42);
            // wait a little bit while stopping downstream from firing the window
            delayTimer.set(window.maxTimestamp().minus(Duration.millis(10)));
        }

        @OnTimer(DELAY_TIMER)
        public void onDelay(@Timestamp Instant timestamp) throws InterruptedException {
            // noop, just here to force the pipeline to sleep so downstream GBK will
            // trigger
            Thread.sleep(waitMillis);
        }
    })).apply(Window.<Integer>configure().triggering(Repeatedly.forever(AfterProcessingTime.pastFirstElementInPane().plusDelayOf(Duration.millis(triggerMillis)))).accumulatingFiredPanes().withAllowedLateness(Duration.millis(0))).apply("Triggered sum", Sum.integersGlobally().withoutDefaults()).apply("Second Triggered sum", Sum.integersGlobally().withoutDefaults());
    PAssert.that(triggeredSums).inEarlyGlobalWindowPanes().containsInAnyOrder(42);
    p.run();
}

