    PCollection<KV<String, Integer>> windowedInput = p.apply(Create.timestamped(TimestampedValue.of(KV.of("foo", 1), new Instant(1)), TimestampedValue.of(KV.of("foo", 4), new Instant(4)), TimestampedValue.of(KV.of("bar", 3), new Instant(3)), TimestampedValue.of(KV.of("foo", 9), new Instant(9)))).apply(Window.into(Sessions.withGapDuration(Duration.millis(4L))));
