    // Second grouping should sum existing groupings, even those exploded, since the windows match
    // and are carried along.
    PCollection<Integer> sums = grouped.apply("Drop keys", Values.create()).apply("Explode iterables", Flatten.iterables()).apply("Map to same key", WithKeys.of("bizzle")).apply("Summed grouping", Sum.integersPerKey()).apply("Pull out sums", Values.create());
