    PAssert.that("Wrong number of elements in windows after GroupIntoBatches", countOutput).satisfies(input -> {
        Iterator<KV<String, Long>> inputIterator = input.iterator();
        long count = inputIterator.next().getValue();
        assertEquals("Wrong number of elements in global window", 2, count);
        return null;
    });
    PAssert.that("Incorrect output collection after GroupIntoBatches", outputCollection).satisfies(input -> {
        Iterator<KV<String, Iterable<String>>> inputIterator = input.iterator();
        int size1 = Iterables.size(inputIterator.next().getValue());
        assertEquals("Wrong first element batch Size", EVEN_NUM_ELEMENTS / 2, size1);
        int size2 = Iterables.size(inputIterator.next().getValue());
        assertEquals("Wrong second element batch Size", EVEN_NUM_ELEMENTS / 2, size2);
        return null;
    });
    pipeline.run().waitUntilFinish();
}

// inline `Strings.repeat()` - Java 11+ API only
@SuppressWarnings("InlineMeInliner")
@Test
@Category({ ValidatesRunner.class, NeedsRunner.class, UsesTimersInParDo.class, UsesTestStream.class, UsesStatefulParDo.class, UsesOnWindowExpiration.class })
public void testMultipleLimitsAtOnceInGlobalWindowBatchSizeCountAndBatchSizeByteSize() {
    // with using only one of the limits the result would be only 2 batches,
    // if we have 3 both limits are exercised
    List<KV<String, String>> dataToUse = Lists.newArrayList("a-1", "a-2", // batch byte size limit would be reached with the next one so "firing" current
    // batch content (BATCH_SIZE_BYTES = 25)
    "b-3" + Strings.repeat("-", 100), // batch byte size is over the limit, but we have a single element that we can't
    // split to smaller batches (BATCH_SIZE_BYTES = 25)
    "c-4", "c-5", "c-6", "c-7", "c-8", // count limit reached (BATCH_SIZE = 5)
    "d-9").stream().map(s -> KV.of("key", s)).collect(Collectors.toList());
    // to ensure ordered processing
    TestStream.Builder<KV<String, String>> streamBuilder = TestStream.create(KvCoder.of(StringUtf8Coder.of(), StringUtf8Coder.of())).advanceWatermarkTo(Instant.EPOCH);
    long offset = 0L;
    for (KV<String, String> kv : dataToUse) {
        streamBuilder = streamBuilder.addElements(TimestampedValue.of(kv, Instant.EPOCH.plus(Duration.standardSeconds(offset))));
        offset++;
    }
    // fire them all at once
    TestStream<KV<String, String>> stream = streamBuilder.advanceWatermarkToInfinity();
    PCollection<KV<String, Iterable<String>>> collection = pipeline.apply("Input data", stream).apply(GroupIntoBatches.<String, String>ofSize(BATCH_SIZE).withByteSize(BATCH_SIZE_BYTES)).// set output coder
    setCoder(KvCoder.of(StringUtf8Coder.of(), IterableCoder.of(StringUtf8Coder.of())));
    PAssert.that("Incorrect batch size in one or more elements", collection).satisfies(new SerializableFunction<Iterable<KV<String, Iterable<String>>>, Void>() {

        private void assertExpectedBatchPrefix(Iterable<KV<String, Iterable<String>>> listToCheck) {
            for (KV<String, Iterable<String>> element : listToCheck) {
                Set<String> batchPrefixes = Streams.stream(element.getValue()).map(s -> Iterables.get(Splitter.on('-').split(s), 0)).collect(Collectors.toSet());
                assertEquals("Found invalid batching: " + listToCheck, 1, batchPrefixes.size());
            }
        }

        @Override
        public Void apply(Iterable<KV<String, Iterable<String>>> input) {
            assertTrue(checkBatchSizes(input));
            assertTrue(checkBatchByteSizes(input));
            assertExpectedBatchPrefix(input);
            assertEquals(Lists.newArrayList(2, 1, 5, 1), Streams.stream(input).map(KV::getValue).map(Iterables::size).collect(Collectors.toList()));
            return null;
        }
    });
    pipeline.run();
}

