@Test
public void testMapWithFailuresDisplayData() {
    InferableFunction<Integer, Integer> inferableFn = new InferableFunction<Integer, Integer>() {

        @Override
        public Integer apply(Integer input) {
            return input;
        }

        @Override
        public void populateDisplayData(DisplayData.Builder builder) {
            builder.add(DisplayData.item("foo", "baz"));
        }
    };
    InferableFunction<ExceptionElement<Integer>, String> exceptionHandler = new InferableFunction<ExceptionElement<Integer>, String>() {

        @Override
        public String apply(ExceptionElement<Integer> input) throws Exception {
            return "";
        }

        @Override
        public void populateDisplayData(DisplayData.Builder builder) {
            builder.add(DisplayData.item("bar", "buz"));
        }
    };
    MapWithFailures<?, ?, ?> mapWithFailures = MapElements.via(inferableFn).exceptionsVia(exceptionHandler);
    assertThat(DisplayData.from(mapWithFailures), hasDisplayItem("class", inferableFn.getClass()));
    assertThat(DisplayData.from(mapWithFailures), hasDisplayItem("exceptionHandler.class", exceptionHandler.getClass()));
    assertThat(DisplayData.from(mapWithFailures), hasDisplayItem("foo", "baz"));
    assertThat(DisplayData.from(mapWithFailures), hasDisplayItem("bar", "buz"));
}

