@Test
@Category(ValidatesRunner.class)
public void testReadAndWriteMultiOutput() {
    List<MyPojo> pojoList = Lists.newArrayList(new MyPojo("a", 1), new MyPojo("b", 2), new MyPojo("c", 3));
    Schema schema1 = Schema.builder().addStringField("string_field").addInt32Field("integer_field").build();
    Schema schema2 = Schema.builder().addStringField("string2_field").addInt32Field("integer2_field").build();
    Schema schema3 = Schema.builder().addStringField("string3_field").addInt32Field("integer3_field").build();
    TupleTag<MyPojo> firstOutput = new TupleTag<>("first");
    TupleTag<MyPojo> secondOutput = new TupleTag<>("second");
    PCollectionTuple tuple = pipeline.apply(Create.of(pojoList).withSchema(schema1, TypeDescriptor.of(MyPojo.class), o -> Row.withSchema(schema1).addValues(o.stringField, o.integerField).build(), r -> new MyPojo(r.getString("string_field"), r.getInt32("integer_field")))).apply("first", ParDo.of(new DoFn<MyPojo, MyPojo>() {

        @ProcessElement
        public void process(@Element Row row, MultiOutputReceiver r) {
            r.getRowReceiver(firstOutput).output(Row.withSchema(schema2).addValues(row.getString(0), row.getInt32(1)).build());
            r.getRowReceiver(secondOutput).output(Row.withSchema(schema3).addValues(row.getString(0), row.getInt32(1)).build());
        }
    }).withOutputTags(firstOutput, TupleTagList.of(secondOutput)));
    tuple.get(firstOutput).setSchema(schema2, TypeDescriptor.of(MyPojo.class), o -> Row.withSchema(schema2).addValues(o.stringField, o.integerField).build(), r -> new MyPojo(r.getString("string2_field"), r.getInt32("integer2_field")));
    tuple.get(secondOutput).setSchema(schema3, TypeDescriptor.of(MyPojo.class), o -> Row.withSchema(schema3).addValues(o.stringField, o.integerField).build(), r -> new MyPojo(r.getString("string3_field"), r.getInt32("integer3_field")));
    PCollection<String> output1 = tuple.get(firstOutput).apply("second", ParDo.of(new DoFn<MyPojo, String>() {

        @ProcessElement
        public void process(@Element Row row, OutputReceiver<String> r) {
            r.output(row.getString("string2_field") + ":" + row.getInt32("integer2_field"));
        }
    }));
    PCollection<String> output2 = tuple.get(secondOutput).apply("third", ParDo.of(new DoFn<MyPojo, String>() {

        @ProcessElement
        public void process(@Element Row row, OutputReceiver<String> r) {
            r.output(row.getString("string3_field") + ":" + row.getInt32("integer3_field"));
        }
    }));
    PAssert.that(output1).containsInAnyOrder("a:1", "b:2", "c:3");
    PAssert.that(output2).containsInAnyOrder("a:1", "b:2", "c:3");
    pipeline.run();
}

