    PCollection<Long> outputs = pipeline.apply(Create.of(Arrays.asList(0L, BoundedWindow.TIMESTAMP_MIN_VALUE.getMillis(), GlobalWindow.INSTANCE.maxTimestamp().getMillis()))).apply("AssignTimestampToValue", ParDo.of(new TestOutputTimestampDoFn<>())).apply("ReassignToMinimumTimestamp", ParDo.of(new DoFn<Long, Long>() {

        @ProcessElement
        public void reassignTimestamps(ProcessContext context, @Element Long element) {
            // Shift the latest element as far backwards in time as the model permits
            context.outputWithTimestamp(element, BoundedWindow.TIMESTAMP_MIN_VALUE);
        }

        @Override
        public Duration getAllowedTimestampSkew() {
            return Duration.millis(Long.MAX_VALUE);
        }
    }));
    PAssert.that(outputs).satisfies(input -> {
        // This element is not shifted backwards in time. It must be present in the output.
        assertThat(input, hasItem(BoundedWindow.TIMESTAMP_MIN_VALUE.getMillis()));
        for (Long elem : input) {
            // Sanity check the outputs. 0L and the end of the global window are shifted
            // backwards in time and theoretically could be dropped.
            assertThat(elem, anyOf(equalTo(BoundedWindow.TIMESTAMP_MIN_VALUE.getMillis()), equalTo(GlobalWindow.INSTANCE.maxTimestamp().getMillis()), equalTo(0L)));
        }
        return null;
    });
    pipeline.run();
}

@Test
@Category({ ValidatesRunner.class, UsesTimersInParDo.class, UsesProcessingTimeTimers.class })
public void testProcessElementSkew() {
    TimestampedValues<KV<String, Duration>> input = Create.timestamped(Arrays.asList(KV.of("2", Duration.millis(1L))), Arrays.asList(1L));
    PCollection<String> noSkew = pipeline.apply("createNoSkew", input).apply("noSkew", ParDo.of(new ProcessElementTimestampSkewingDoFn(Duration.ZERO)));
    PAssert.that(noSkew).containsInAnyOrder(TIMER_ELEMENT + new Instant(0L), OUTPUT_ELEMENT + new Instant(0L));
    PCollection<String> skew = pipeline.apply("createSkew", input).apply("skew", ParDo.of(new ProcessElementTimestampSkewingDoFn(Duration.millis(2L))));
    PAssert.that(skew).containsInAnyOrder(TIMER_ELEMENT, OUTPUT_ELEMENT);
    // Check that we properly print out large allowed skews: pick allowed skew large enough to
    // trigger failure on PeriodFormat, but small enough to trigger the error.
    Duration allowedSkew = Duration.millis(Long.valueOf(Integer.MAX_VALUE) * 10000000);
    Duration offset = allowedSkew.plus(Duration.millis(2L));
    TimestampedValues<KV<String, Duration>> largeValues = Create.timestamped(Arrays.asList(KV.of("2", offset)), Arrays.asList(0L));
    PCollection<String> largeSkew = pipeline.apply("createLargeSkew", largeValues).apply("largeSkew", ParDo.of(new ProcessElementTimestampSkewingDoFn(allowedSkew)));
    PAssert.that(largeSkew).containsInAnyOrder(TIMER_ELEMENT + new Instant(0L).minus(offset), OUTPUT_ELEMENT + new Instant(0L).minus(offset));
    pipeline.run();
}

