@Category({ ValidatesRunner.class, UsesStatefulParDo.class, UsesMapState.class })
public void testMapState() {
    final String stateId = "foo";
    final String countStateId = "count";
    DoFn<KV<String, KV<String, Integer>>, KV<String, Integer>> fn = new DoFn<KV<String, KV<String, Integer>>, KV<String, Integer>>() {

        @StateId(stateId)
        private final StateSpec<MapState<String, Integer>> mapState = StateSpecs.map(StringUtf8Coder.of(), VarIntCoder.of());

        @StateId(countStateId)
        private final StateSpec<CombiningState<Integer, int[], Integer>> countState = StateSpecs.combiningFromInputInternal(VarIntCoder.of(), Sum.ofIntegers());

        @ProcessElement
        public void processElement(ProcessContext c, @Element KV<String, KV<String, Integer>> element, @StateId(stateId) MapState<String, Integer> state, @StateId(countStateId) CombiningState<Integer, int[], Integer> count, OutputReceiver<KV<String, Integer>> r) {
            KV<String, Integer> value = element.getValue();
            state.put(value.getKey(), value.getValue());
            count.add(1);
            @Nullable
            Integer max = state.get("max").read();
            state.put("max", Math.max(max == null ? 0 : max, value.getValue()));
            if (count.read() >= 4) {
                assertEquals(Integer.valueOf(97), state.get("a").read());
                Iterable<Map.Entry<String, Integer>> entriesView = state.entries().read();
                Iterable<String> keysView = state.keys().read();
                // Make sure that the cached Iterable doesn't change when new elements are added,
                // but that cached ReadableState views of the state do change.
                state.put("BadKey", -1);
                assertEquals(4, Iterables.size(entriesView));
                assertEquals(4, Iterables.size(keysView));
                assertEquals(5, Iterables.size(state.entries().read()));
                assertEquals(5, Iterables.size(state.keys().read()));
                assertEquals(Integer.valueOf(97), state.get("max").read());
                for (Map.Entry<String, Integer> entry : entriesView) {
                    r.output(KV.of(entry.getKey(), entry.getValue()));
                }
            }
        }
    };
    PCollection<KV<String, Integer>> output = pipeline.apply(Create.of(KV.of("hello", KV.of("a", 97)), KV.of("hello", KV.of("b", 42)), KV.of("hello", KV.of("b", 42)), KV.of("hello", KV.of("c", 12)))).apply(ParDo.of(fn));
    PAssert.that(output).containsInAnyOrder(KV.of("a", 97), KV.of("b", 42), KV.of("c", 12), KV.of("max", 97));
    pipeline.run();
}

