@Test
@Category({ ValidatesRunner.class, UsesTimersInParDo.class })
public void testEventTimeTimerAlignBounded() throws Exception {
    final String timerId = "foo";
    DoFn<KV<String, Long>, KV<Long, Instant>> fn = new DoFn<KV<String, Long>, KV<Long, Instant>>() {

        @TimerId(timerId)
        private final TimerSpec spec = TimerSpecs.timer(TimeDomain.EVENT_TIME);

        @ProcessElement
        public void processElement(@TimerId(timerId) Timer timer, @Timestamp Instant timestamp, OutputReceiver<KV<Long, Instant>> r) {
            timer.align(Duration.standardSeconds(1)).offset(Duration.millis(1)).setRelative();
            r.output(KV.of(3L, timestamp));
        }

        @OnTimer(timerId)
        public void onTimer(@Timestamp Instant timestamp, OutputReceiver<KV<Long, Instant>> r) {
            r.output(KV.of(42L, timestamp));
        }
    };
    PCollection<KV<Long, Instant>> output = pipeline.apply(Create.of(KV.of("hello", 37L))).apply(ParDo.of(fn));
    PAssert.that(output).containsInAnyOrder(KV.of(3L, BoundedWindow.TIMESTAMP_MIN_VALUE), KV.of(42L, BoundedWindow.TIMESTAMP_MIN_VALUE.plus(Duration.millis(1774))));
    pipeline.run();
}

@Test
@Category({ ValidatesRunner.class, UsesTimersInParDo.class })
public void testTimerReceivedInOriginalWindow() throws Exception {
    final String timerId = "foo";
    DoFn<KV<String, Integer>, BoundedWindow> fn = new DoFn<KV<String, Integer>, BoundedWindow>() {

        @TimerId(timerId)
        private final TimerSpec spec = TimerSpecs.timer(TimeDomain.EVENT_TIME);

        @ProcessElement
        public void processElement(@TimerId(timerId) Timer timer) {
            timer.offset(Duration.standardSeconds(1)).setRelative();
        }

        @OnTimer(timerId)
        public void onTimer(BoundedWindow window, OutputReceiver<BoundedWindow> r) {
            r.output(window);
        }

        @Override
        public TypeDescriptor<BoundedWindow> getOutputTypeDescriptor() {
            return (TypeDescriptor) TypeDescriptor.of(IntervalWindow.class);
        }
    };
    SlidingWindows windowing = SlidingWindows.of(Duration.standardMinutes(3)).every(Duration.standardMinutes(1));
    PCollection<BoundedWindow> output = pipeline.apply(Create.timestamped(TimestampedValue.of(KV.of("hello", 24), new Instant(0L)))).apply(Window.into(windowing)).apply(ParDo.of(fn));
    PAssert.that(output).containsInAnyOrder(new IntervalWindow(new Instant(0), Duration.standardMinutes(3)), new IntervalWindow(new Instant(0).minus(Duration.standardMinutes(1)), Duration.standardMinutes(3)), new IntervalWindow(new Instant(0).minus(Duration.standardMinutes(2)), Duration.standardMinutes(3)));
    pipeline.run();
}

/**
 * Tests that an event time timer set absolutely for the last possible moment fires and results
 * in supplementary output. The test is otherwise identical to {@link
 * #testEventTimeTimerBounded()}.
 */
@Test
@Category({ ValidatesRunner.class, UsesTimersInParDo.class })
public void testEventTimeTimerAbsolute() throws Exception {
    final String timerId = "foo";
    DoFn<KV<String, Long>, Long> fn = new DoFn<KV<String, Long>, Long>() {

        @TimerId(timerId)
        private final TimerSpec spec = TimerSpecs.timer(TimeDomain.EVENT_TIME);

        @ProcessElement
        public void processElement(@TimerId(timerId) Timer timer, BoundedWindow window, OutputReceiver<Long> r) {
            timer.set(window.maxTimestamp());
            r.output(3L);
