public void testEventTimeTimerLoop() {
    final String stateId = "count";
    final String timerId = "timer";
    final int loopCount = 5;
    DoFn<KV<String, Integer>, KV<String, Integer>> fn = new DoFn<KV<String, Integer>, KV<String, Integer>>() {

        @TimerId(timerId)
        private final TimerSpec loopSpec = TimerSpecs.timer(TimeDomain.EVENT_TIME);

        @StateId(stateId)
        private final StateSpec<ValueState<Integer>> countSpec = StateSpecs.value();

        @ProcessElement
        public void processElement(@StateId(stateId) ValueState<Integer> countState, @TimerId(timerId) Timer loopTimer) {
            countState.write(0);
            loopTimer.offset(Duration.millis(1)).setRelative();
        }

        @OnTimer(timerId)
        public void onLoopTimer(@Key String key, @StateId(stateId) ValueState<Integer> countState, @TimerId(timerId) Timer loopTimer, OutputReceiver<KV<String, Integer>> r) {
            int count = Preconditions.checkNotNull(countState.read());
            if (count < loopCount) {
                r.output(KV.of(key, count));
                countState.write(count + 1);
                loopTimer.offset(Duration.millis(1)).setRelative();
            }
        }
    };
