@Test
@Category({ ValidatesRunner.class, UsesStatefulParDo.class, UsesTimersInParDo.class, UsesTestStream.class })
public void testOutputTimestamp() {
    final String timerId = "bar";
    DoFn<KV<String, Long>, KV<String, Long>> fn1 = new DoFn<KV<String, Long>, KV<String, Long>>() {

        @TimerId(timerId)
        private final TimerSpec timer = TimerSpecs.timer(TimeDomain.EVENT_TIME);

        @ProcessElement
        public void processElement(@TimerId(timerId) Timer timer, @Timestamp Instant timestamp, OutputReceiver<KV<String, Long>> o) {
            timer.withOutputTimestamp(timestamp.plus(Duration.millis(5))).set(timestamp.plus(Duration.millis(10)));
            // Output a message. This will cause the next DoFn to set a timer as well.
            o.output(KV.of("foo", 100L));
        }

        @OnTimer(timerId)
        public void onTimer(OnTimerContext c, BoundedWindow w) {
        }
    };
    DoFn<KV<String, Long>, Long> fn2 = new DoFn<KV<String, Long>, Long>() {

        @TimerId(timerId)
        private final TimerSpec timer = TimerSpecs.timer(TimeDomain.EVENT_TIME);

        @StateId("timerFired")
        final StateSpec<ValueState<Boolean>> timerFiredState = StateSpecs.value();

        @ProcessElement
        public void processElement(@TimerId(timerId) Timer timer, @Timestamp Instant timestamp, @StateId("timerFired") ValueState<Boolean> timerFiredState) {
            Boolean timerFired = timerFiredState.read();
            assertTrue(timerFired == null || !timerFired);
            // Set a timer to 8. This is earlier than the previous DoFn's timer, but after the
            // previous
            // DoFn timer's watermark hold. This timer should not fire until the previous timer
            // fires and removes
            // the watermark hold.
            timer.set(timestamp.plus(Duration.millis(8)));
        }

        @OnTimer(timerId)
