@Category({ ValidatesRunner.class, UsesStatefulParDo.class, UsesTimersInParDo.class, UsesProcessingTimeTimers.class, UsesTestStream.class, UsesTestStreamWithProcessingTime.class, UsesTestStreamWithOutputTimestamp.class })
public void testOutputTimestampWithProcessingTime() {
    final String timerId = "foo";
    DoFn<KV<String, Long>, KV<String, Long>> fn1 = new DoFn<KV<String, Long>, KV<String, Long>>() {

        @TimerId(timerId)
        private final TimerSpec timer = TimerSpecs.timer(TimeDomain.PROCESSING_TIME);

        @ProcessElement
        public void processElement(@TimerId(timerId) Timer timer, @Timestamp Instant timestamp, OutputReceiver<KV<String, Long>> o) {
            timer.withOutputTimestamp(timestamp.plus(Duration.standardSeconds(5))).offset(Duration.standardSeconds(10)).setRelative();
            // Output a message. This will cause the next DoFn to set a timer as well.
            o.output(KV.of("foo", 100L));
        }

        @OnTimer(timerId)
        public void onTimer(OnTimerContext c, BoundedWindow w) {
        }
    };
    DoFn<KV<String, Long>, Long> fn2 = new DoFn<KV<String, Long>, Long>() {

        @TimerId(timerId)
        private final TimerSpec timer = TimerSpecs.timer(TimeDomain.EVENT_TIME);

        @StateId("timerFired")
        final StateSpec<ValueState<Boolean>> timerFiredState = StateSpecs.value();

        @ProcessElement
        public void processElement(@TimerId(timerId) Timer timer, @StateId("timerFired") ValueState<Boolean> timerFiredState) {
            Boolean timerFired = timerFiredState.read();
            assertTrue(timerFired == null || !timerFired);
            // Set a timer to 8. This is earlier than the previous DoFn's timer, but after the
            // previous
            // DoFn timer's watermark hold. This timer should not fire until the previous timer
            // fires and removes
            // the watermark hold.
            timer.set(new Instant(8));
        }

        @OnTimer(timerId)
        public void onTimer(@StateId("timerFired") ValueState<Boolean> timerFiredState, OutputReceiver<Long> o) {
            timerFiredState.write(true);
            o.output(100L);
        }
    };
    TestStream<KV<String, Long>> stream = TestStream.create(KvCoder.of(StringUtf8Coder.of(), VarLongCoder.of())).advanceProcessingTime(Duration.standardSeconds(1)).// Cause fn2 to set a timer.
    addElements(KV.of("key", 1L)).// Normally this would case fn2's timer to expire, but it shouldn't here because of
    // the output timestamp.
    advanceProcessingTime(Duration.standardSeconds(9)).advanceWatermarkTo(new Instant(11)).// If the timer fired, then this would case fn2 to fail with an assertion error.
    addElements(KV.of("key", 1L)).advanceProcessingTime(Duration.standardSeconds(100)).advanceWatermarkToInfinity();
    PCollection<Long> output = pipeline.apply(stream).apply("first", ParDo.of(fn1)).apply("second", ParDo.of(fn2));
    // result output
    PAssert.that(output).containsInAnyOrder(100L);
    pipeline.run();
}

@Test
@Category({ NeedsRunner.class, UsesTimersInParDo.class, UsesTestStream.class })
public void testRelativeTimerWithOutputTimestamp() {
    DoFn<KV<Void, String>, String> bufferFn = new DoFn<KV<Void, String>, String>() {

        @TimerId("timer")
        private final TimerSpec timerSpec = TimerSpecs.timer(TimeDomain.EVENT_TIME);

        @StateId("buffer")
        private final StateSpec<BagState<TimestampedValue<String>>> bufferSpec = StateSpecs.bag(TimestampedValue.TimestampedValueCoder.of(StringUtf8Coder.of()));

        @StateId("minStamp")
        private final StateSpec<ValueState<Instant>> minStamp = StateSpecs.value();

        @ProcessElement
        public void processElement(@Element KV<Void, String> element, @Timestamp Instant timestamp, @StateId("buffer") BagState<TimestampedValue<String>> buffer, @StateId("minStamp") ValueState<Instant> minStamp, @TimerId("timer") Timer timer) {
            minStamp.readLater();
            buffer.add(TimestampedValue.of(element.getValue(), timestamp));
            Instant currentMinStamp = minStamp.read();
            if (currentMinStamp == null || currentMinStamp.isAfter(timestamp)) {
                currentMinStamp = timestamp;
                minStamp.write(currentMinStamp);
                timer.withOutputTimestamp(currentMinStamp).offset(Duration.ZERO).setRelative();
            }
        }

        @OnTimer("timer")
        public void onTimer(OnTimerContext context, @StateId("buffer") BagState<TimestampedValue<String>> buffer, @StateId("minStamp") ValueState<Instant> minStamp, @TimerId("timer") Timer timer, OutputReceiver<String> output) {
            Instant fireTimestamp = context.fireTimestamp();
            Iterable<TimestampedValue<String>> values = buffer.read();
            Instant currentMinStamp = BoundedWindow.TIMESTAMP_MAX_VALUE;
            for (TimestampedValue<String> val : values) {
                if (fireTimestamp.isBefore(val.getTimestamp())) {
                    output.outputWithTimestamp(val.getValue(), val.getTimestamp());
                } else if (currentMinStamp.isAfter(val.getTimestamp())) {
                    currentMinStamp = val.getTimestamp();
                }
            }
            if (currentMinStamp.isBefore(BoundedWindow.TIMESTAMP_MAX_VALUE)) {
                minStamp.write(currentMinStamp);
                timer.withOutputTimestamp(currentMinStamp).offset(Duration.ZERO).setRelative();
            } else {
                minStamp.clear();
            }
        }
    };
    PCollection<KV<Void, String>> input = pipeline.apply(TestStream.create(KvCoder.of(VoidCoder.of(), StringUtf8Coder.of())).addElements(TimestampedValue.of(KV.of(null, "foo"), new Instant(1))).addElements(TimestampedValue.of(KV.of(null, "bar"), new Instant(2))).advanceWatermarkToInfinity());
    PCollection<String> result = input.apply(ParDo.of(bufferFn));
    PAssert.that(result).containsInAnyOrder("foo", "bar");
    pipeline.run();
}

