@Test
@Category({ ValidatesRunner.class, UsesUnboundedPCollections.class, UsesTestStream.class })
public void testWatermarkUpdateMidBundle() {
    DoFn<String, String> bufferDoFn = new DoFn<String, String>() {

        private final Set<KV<String, Instant>> buffer = new HashSet<>();

        @ProcessElement
        public void process(@Element String in, @Timestamp Instant ts) {
            buffer.add(KV.of(in, ts));
        }

        @FinishBundle
        public void finish(FinishBundleContext context) {
            buffer.forEach(k -> context.output(k.getKey(), k.getValue(), GlobalWindow.INSTANCE));
            buffer.clear();
        }
    };
    int numBundles = 200;
    TestStream.Builder<String> builder = TestStream.create(StringUtf8Coder.of()).advanceWatermarkTo(new Instant(0));
    List<List<TimestampedValue<String>>> bundles = IntStream.range(0, numBundles).mapToObj(r -> IntStream.range(0, r + 1).mapToObj(v -> TimestampedValue.of(String.valueOf(v), new Instant(r))).collect(Collectors.toList())).collect(Collectors.toList());
    for (List<TimestampedValue<String>> b : bundles) {
        builder = builder.addElements(b.get(0), b.subList(1, b.size()).toArray(new TimestampedValue[] {})).advanceWatermarkTo(new Instant(b.size()));
    }
    PCollection<Long> result = pipeline.apply(builder.advanceWatermarkToInfinity()).apply(ParDo.of(bufferDoFn)).apply("milliWindow", Window.into(FixedWindows.of(Duration.millis(1)))).apply("count", Combine.globally(Count.<String>combineFn()).withoutDefaults()).apply("globalWindow", Window.<Long>into(new GlobalWindows()).triggering(AfterWatermark.pastEndOfWindow()).withAllowedLateness(Duration.ZERO).discardingFiredPanes()).apply("sum", Sum.longsGlobally());
    PAssert.that(result).containsInAnyOrder((numBundles * numBundles + numBundles) / 2L);
    pipeline.run();
}

