/**
 * Tests that timestamps are preserved after applying a {@link Reshuffle} with the default {@link
 * WindowingStrategy}.
 */
@Test
@Category(ValidatesRunner.class)
public void testReshufflePreservesTimestamps() {
    PCollection<KV<String, TimestampedValue<String>>> input = pipeline.apply(Create.timestamped(TimestampedValue.of("foo", BoundedWindow.TIMESTAMP_MIN_VALUE), TimestampedValue.of("foo", new Instant(0)), TimestampedValue.of("bar", new Instant(33)), TimestampedValue.of("bar", GlobalWindow.INSTANCE.maxTimestamp())).withCoder(StringUtf8Coder.of())).apply(WithKeys.<String, String>of(input12 -> input12).withKeyType(TypeDescriptors.strings())).apply("ReifyOriginalTimestamps", Reify.timestampsInValue());
    // The outer TimestampedValue is the reified timestamp post-reshuffle. The inner
    // TimestampedValue is the pre-reshuffle timestamp.
    PCollection<TimestampedValue<TimestampedValue<String>>> output = input.apply(Reshuffle.of()).apply("ReifyReshuffledTimestamps", Reify.timestampsInValue()).apply(Values.create());
    PAssert.that(output).satisfies(input1 -> {
        for (TimestampedValue<TimestampedValue<String>> elem : input1) {
            Instant originalTimestamp = elem.getValue().getTimestamp();
            Instant afterReshuffleTimestamp = elem.getTimestamp();
            assertThat("Reshuffle must preserve element timestamps", afterReshuffleTimestamp, equalTo(originalTimestamp));
        }
        return null;
    });
    pipeline.run();
}

/**
 * Tests that window & pane info is preserved after applying a {@link Reshuffle} with the default
 * {@link WindowingStrategy}.
 */
@Test
@Category(ValidatesRunner.class)
public void testReshufflePreservesMetadata() {
    PCollection<KV<String, ValueInSingleWindow<String>>> input = pipeline.apply(Create.windowedValues(WindowedValues.of("foo", BoundedWindow.TIMESTAMP_MIN_VALUE, GlobalWindow.INSTANCE, PaneInfo.NO_FIRING), WindowedValues.of("foo", new Instant(0), GlobalWindow.INSTANCE, PaneInfo.ON_TIME_AND_ONLY_FIRING), WindowedValues.of("bar", new Instant(33), GlobalWindow.INSTANCE, PaneInfo.createPane(false, false, PaneInfo.Timing.LATE, 1, 1)), WindowedValues.of("bar", GlobalWindow.INSTANCE.maxTimestamp(), GlobalWindow.INSTANCE, PaneInfo.NO_FIRING)).withCoder(StringUtf8Coder.of()).withWindowCoder(GlobalWindow.Coder.INSTANCE)).apply(WithKeys.<String, String>of(v -> v).withKeyType(TypeDescriptors.strings())).apply("ReifyOriginalMetadata", Reify.windowsInValue());
    // The outer WindowedValue is the reified metadata post-reshuffle. The inner
    // WindowedValue is the pre-reshuffle metadata.
    PCollection<ValueInSingleWindow<ValueInSingleWindow<String>>> output = input.apply(Reshuffle.of()).apply("ReifyReshuffledMetadata", Reify.windowsInValue()).apply(Values.create());
    PAssert.that(output).satisfies(input1 -> {
        for (ValueInSingleWindow<ValueInSingleWindow<String>> elem : input1) {
            Instant originalTimestamp = elem.getValue().getTimestamp();
            Instant afterReshuffleTimestamp = elem.getTimestamp();
            assertThat("Reshuffle did not preserve element timestamp for " + elem, afterReshuffleTimestamp, equalTo(originalTimestamp));
            PaneInfo originalPaneInfo = elem.getValue().getPaneInfo();
            PaneInfo afterReshufflePaneInfo = elem.getPaneInfo();
            assertThat("Reshuffle did not preserve pane info for " + elem, afterReshufflePaneInfo, equalTo(originalPaneInfo));
            BoundedWindow originalWindow = elem.getValue().getWindow();
            BoundedWindow afterReshuffleWindow = elem.getWindow();
            assertThat("Reshuffle did not preserve window for " + elem, afterReshuffleWindow, equalTo(originalWindow));
        }
        return null;
    });
    pipeline.run();
}

