@Test
public void testTrySplit() throws Exception {
    ByteKeyRangeTracker tracker = ByteKeyRangeTracker.of(ByteKeyRange.ALL_KEYS);
    SplitResult<ByteKeyRange> res = tracker.trySplit(0.5);
    assertKeyRangeEqualExceptPadding(ByteKeyRange.of(ByteKey.EMPTY, ByteKey.of(0x80)), res.getPrimary());
    assertKeyRangeEqualExceptPadding(ByteKeyRange.of(ByteKey.of(0x80), ByteKey.EMPTY), res.getResidual());
    tracker.tryClaim(ByteKey.of(0x00));
    res = tracker.trySplit(0.5);
    assertKeyRangeEqualExceptPadding(ByteKeyRange.of(ByteKey.EMPTY, ByteKey.of(0x40)), res.getPrimary());
    assertKeyRangeEqualExceptPadding(ByteKeyRange.of(ByteKey.of(0x40), ByteKey.of(0x80)), res.getResidual());
    assertNull(tracker.trySplit(1));
}

