@Test
public void testManualWatermarkEstimator() {
    ManualWatermarkEstimator<Instant> watermarkEstimator = new WatermarkEstimators.Manual(BoundedWindow.TIMESTAMP_MIN_VALUE);
    assertEquals(BoundedWindow.TIMESTAMP_MIN_VALUE, watermarkEstimator.currentWatermark());
    watermarkEstimator.setWatermark(BoundedWindow.TIMESTAMP_MIN_VALUE);
    watermarkEstimator.setWatermark(BoundedWindow.TIMESTAMP_MIN_VALUE.plus(Duration.standardHours(2)));
    assertEquals(BoundedWindow.TIMESTAMP_MIN_VALUE.plus(Duration.standardHours(2)), watermarkEstimator.currentWatermark());
    // Make sure that even if the watermark goes backwards we report the "greatest" value we have
    // reported so far.
    watermarkEstimator.setWatermark(BoundedWindow.TIMESTAMP_MIN_VALUE.plus(Duration.standardHours(1)));
    assertEquals(BoundedWindow.TIMESTAMP_MIN_VALUE.plus(Duration.standardHours(2)), watermarkEstimator.currentWatermark());
    watermarkEstimator.setWatermark(BoundedWindow.TIMESTAMP_MAX_VALUE);
    assertEquals(BoundedWindow.TIMESTAMP_MAX_VALUE, watermarkEstimator.currentWatermark());
}

@Test
public void testWallTimeWatermarkEstimator() {
    try {
        DateTimeUtils.setCurrentMillisFixed(BoundedWindow.TIMESTAMP_MIN_VALUE.getMillis());
        WatermarkEstimator<Instant> watermarkEstimator = new WatermarkEstimators.WallTime(new Instant());
        DateTimeUtils.setCurrentMillisFixed(BoundedWindow.TIMESTAMP_MIN_VALUE.plus(Duration.millis(1)).getMillis());
        assertEquals(BoundedWindow.TIMESTAMP_MIN_VALUE.plus(Duration.millis(1)), watermarkEstimator.currentWatermark());
        DateTimeUtils.setCurrentMillisFixed(BoundedWindow.TIMESTAMP_MIN_VALUE.plus(Duration.millis(2)).getMillis());
        // Make sure that we don't mutate state even if the clock advanced
        assertEquals(BoundedWindow.TIMESTAMP_MIN_VALUE.plus(Duration.millis(1)), watermarkEstimator.getState());
        assertEquals(BoundedWindow.TIMESTAMP_MIN_VALUE.plus(Duration.millis(2)), watermarkEstimator.currentWatermark());
        assertEquals(BoundedWindow.TIMESTAMP_MIN_VALUE.plus(Duration.millis(2)), watermarkEstimator.getState());
        // Handle the case if the clock ever goes backwards. Could happen if we resumed processing
        // on a machine that had misconfigured clock or due to clock skew.
        DateTimeUtils.setCurrentMillisFixed(BoundedWindow.TIMESTAMP_MIN_VALUE.plus(Duration.millis(1)).getMillis());
        assertEquals(BoundedWindow.TIMESTAMP_MIN_VALUE.plus(Duration.millis(2)), watermarkEstimator.currentWatermark());
    } finally {
        DateTimeUtils.setCurrentMillisSystem();
    }
}

@Test
public void testMonotonicallyIncreasingWatermarkEstimator() {
    TimestampObservingWatermarkEstimator<Instant> watermarkEstimator = new WatermarkEstimators.MonotonicallyIncreasing(BoundedWindow.TIMESTAMP_MIN_VALUE);
    assertEquals(BoundedWindow.TIMESTAMP_MIN_VALUE, watermarkEstimator.currentWatermark());
    watermarkEstimator.observeTimestamp(BoundedWindow.TIMESTAMP_MIN_VALUE);
    watermarkEstimator.observeTimestamp(BoundedWindow.TIMESTAMP_MIN_VALUE.plus(Duration.standardHours(2)));
    assertEquals(BoundedWindow.TIMESTAMP_MIN_VALUE.plus(Duration.standardHours(2)), watermarkEstimator.currentWatermark());
    // Make sure that even if the watermark goes backwards we report the "greatest" value we have
