    watermarkEstimator.observeTimestamp(BoundedWindow.TIMESTAMP_MIN_VALUE.plus(Duration.standardHours(1)));
    assertEquals(BoundedWindow.TIMESTAMP_MIN_VALUE.plus(Duration.standardHours(2)), watermarkEstimator.currentWatermark());
    watermarkEstimator.observeTimestamp(BoundedWindow.TIMESTAMP_MAX_VALUE);
    assertEquals(BoundedWindow.TIMESTAMP_MAX_VALUE, watermarkEstimator.currentWatermark());
}

