@Test
@Category({ ValidatesRunner.class, UsesTriggeredSideInputs.class })
public void testTriggeredLatestSingleton() {
    IntervalWindow zeroWindow = new IntervalWindow(new Instant(0), new Instant(1000));
    PCollectionView<Long> view = pipeline.apply(GenerateSequence.from(0).withRate(1, Duration.millis(100)).withTimestampFn(Instant::new).withMaxReadTime(Duration.standardSeconds(10))).apply("Window side input", Window.<Long>into(FixedWindows.of(Duration.standardSeconds(1))).triggering(Repeatedly.forever(AfterProcessingTime.pastFirstElementInPane())).withAllowedLateness(Duration.ZERO).discardingFiredPanes()).apply(Reify.timestamps()).apply(Combine.globally(Latest.<Long>combineFn()).withoutDefaults().asSingletonView());
    final String tag = "singleton";
    PCollection<Long> pc = pipeline.apply(Impulse.create()).apply(WithTimestamps.of(impulse -> new Instant(0))).apply("Window main input", Window.into(FixedWindows.of(Duration.standardSeconds(1)))).apply(ParDo.of(new DoFn<byte[], Long>() {

        @ProcessElement
        public void process(@SideInput(tag) Long sideInput, OutputReceiver<Long> out) throws InterruptedException {
            // waiting to ensure multiple outputs to side input before reading it
            Thread.sleep(1000L);
            out.output(sideInput);
        }
    }).withSideInput(tag, view));
    PAssert.that(pc).inWindow(zeroWindow).satisfies((Iterable<Long> values) -> {
        assertThat(values, Matchers.iterableWithSize(1));
        return null;
    });
    pipeline.run();
}

