@Test
@Category({ NeedsRunner.class, UsesUnboundedSplittableParDo.class })
public void testSinglePollWithManyResults() {
    // More than the default 100 elements per checkpoint for direct runner.
    final long numResults = 3000;
    PCollection<KV<String, Integer>> res = p.apply(Create.of("a")).apply(Watch.growthOf(new PollFn<String, KV<String, Integer>>() {

        @Override
        public PollResult<KV<String, Integer>> apply(String element, Context c) throws Exception {
            String pollId = UUID.randomUUID().toString();
            List<KV<String, Integer>> output = Lists.newArrayList();
            for (int i = 0; i < numResults; ++i) {
                output.add(KV.of(pollId, i));
            }
            return PollResult.complete(Instant.now(), output);
        }
    }).withTerminationPerInput(Growth.afterTotalOf(standardSeconds(1))).withPollInterval(Duration.millis(1)).withOutputCoder(KvCoder.of(StringUtf8Coder.of(), VarIntCoder.of()))).apply("Drop input", Values.create());
    PAssert.that("Poll called only once", res.apply(Keys.create())).satisfies(pollIds -> {
        assertEquals(1, Sets.newHashSet(pollIds).size());
        return null;
    });
    PAssert.that("Yields all expected results", res.apply("Drop poll id", Values.create())).satisfies(input -> {
        assertEquals("Total number of results mismatches", numResults, Lists.newArrayList(input).size());
        assertEquals("Results are not unique", numResults, Sets.newHashSet(input).size());
        return null;
    });
    p.run();
}

@Test
public void testCoder() throws Exception {
    GrowthState pollingState = PollingGrowthState.of(ImmutableMap.of(HashCode.fromString("0123456789abcdef0123456789abcdef"), Instant.now(), HashCode.fromString("01230123012301230123012301230123"), Instant.now()), Instant.now(), "STATE");
    GrowthState nonPollingState = NonPollingGrowthState.of(Growth.PollResult.incomplete(Instant.now(), Arrays.asList("A", "B")));
    Coder<GrowthState> coder = Watch.GrowthStateCoder.of(StringUtf8Coder.of(), StringUtf8Coder.of());
    CoderProperties.coderDecodeEncodeEqual(coder, pollingState);
    CoderProperties.coderDecodeEncodeEqual(coder, nonPollingState);
}

