@Test
public void movingSum() {
    BucketingFunction f = newFunc();
    int lost = 0;
    for (int i = 0; i < 200; i++) {
        f.add(i, 1);
        if (i >= 100) {
            f.remove(i - 100);
            if (i % BUCKET_WIDTH == BUCKET_WIDTH - 1) {
                lost += BUCKET_WIDTH;
            }
        }
        assertEquals(i + 1 - lost, f.get());
    }
}

