@Test
public void writeWithRunnerDeterminedSharding() {
    ResourceId outputDirectory = LocalResources.fromString("/foo/bar", true);
    FilenamePolicy policy = DefaultFilenamePolicy.fromStandardParameters(StaticValueProvider.of(outputDirectory), DefaultFilenamePolicy.DEFAULT_UNWINDOWED_SHARD_TEMPLATE, "", false);
    WriteFiles<Integer, Void, Integer> write = WriteFiles.to(new FileBasedSink<Integer, Void, Integer>(StaticValueProvider.of(outputDirectory), DynamicFileDestinations.constant(policy)) {

        @Override
        public WriteOperation<Void, Integer> createWriteOperation() {
            return null;
        }
    });
    assertThat(PTransformMatchers.writeWithRunnerDeterminedSharding().matches(appliedWrite(write)), is(true));
    WriteFiles<Integer, Void, Integer> withStaticSharding = write.withNumShards(3);
    assertThat(PTransformMatchers.writeWithRunnerDeterminedSharding().matches(appliedWrite(withStaticSharding)), is(false));
    WriteFiles<Integer, Void, Integer> withCustomSharding = write.withSharding(Sum.integersGlobally().asSingletonView());
    assertThat(PTransformMatchers.writeWithRunnerDeterminedSharding().matches(appliedWrite(withCustomSharding)), is(false));
}

