    SerializableUtils.ensureSerializable(instance);
    AtomicInteger i = instance.get();
    i.set(10);
    assertSame(i, instance.get());
    byte[] serialized = SerializableUtils.serializeToByteArray(instance);
    MemoizingPerInstantiationSerializableSupplier<AtomicInteger> deserialized1 = (MemoizingPerInstantiationSerializableSupplier<AtomicInteger>) SerializableUtils.deserializeFromByteArray(serialized, "instance");
    assertSame(i, deserialized1.get());
    MemoizingPerInstantiationSerializableSupplier<AtomicInteger> deserialized2 = (MemoizingPerInstantiationSerializableSupplier<AtomicInteger>) SerializableUtils.deserializeFromByteArray(serialized, "instance");
    assertSame(i, deserialized2.get());
    assertEquals(10, i.get());
}

