@Test
public void testInterpolateWindowingInformation() {
    String template = String.format("str: {str}, window: {%s}, pane: {%s}, year: {%s}, month: {%s}, day: {%s}", RowStringInterpolator.WINDOW, RowStringInterpolator.PANE_INDEX, RowStringInterpolator.YYYY, RowStringInterpolator.MM, RowStringInterpolator.DD);
    RowStringInterpolator interpolator = new RowStringInterpolator(template, ROW_SCHEMA);
    Instant instant = new DateTime(2024, 8, 28, 12, 0).toInstant();
    String output = interpolator.interpolate(ValueInSingleWindow.of(ROW, instant, GlobalWindow.INSTANCE, PaneInfo.createPane(false, false, PaneInfo.Timing.ON_TIME, 2, 0)));
    String expected = String.format("str: str_value, window: %s, pane: 2, year: 2024, month: 8, day: 28", GlobalWindow.INSTANCE);
    assertEquals(expected, output);
}

