@Test
public void testStructuralValueEqual() throws Exception {
    Coder<ShardedKey<String>> coder = ShardedKey.Coder.of(StringUtf8Coder.of());
    CoderProperties.coderSerializable(coder);
    CoderProperties.structuralValueDecodeEncodeEqual(coder, ShardedKey.of(KEY, SHARD));
    CoderProperties.structuralValueDecodeEncodeEqual(coder, ShardedKey.of(KEY, EMPTY_SHARD));
    CoderProperties.structuralValueConsistentWithEquals(coder, ShardedKey.of(KEY, "shard_id".getBytes(UTF_8)), ShardedKey.of(KEY, "shard_id".getBytes(UTF_8)));
    CoderProperties.structuralValueConsistentWithEquals(coder, ShardedKey.of(KEY, new byte[0]), ShardedKey.of(KEY, new byte[0]));
}

@Test
public void testDecodeEncodeEqual() throws Exception {
    Coder<ShardedKey<String>> coder = ShardedKey.Coder.of(StringUtf8Coder.of());
    CoderProperties.coderDecodeEncodeEqual(coder, ShardedKey.of(KEY, SHARD));
    CoderProperties.coderDecodeEncodeEqual(coder, ShardedKey.of(KEY, EMPTY_SHARD));
    CoderProperties.coderConsistentWithEquals(coder, ShardedKey.of(KEY, "shard_id".getBytes(UTF_8)), ShardedKey.of(KEY, "shard_id".getBytes(UTF_8)));
    CoderProperties.coderConsistentWithEquals(coder, ShardedKey.of(KEY, new byte[0]), ShardedKey.of(KEY, new byte[0]));
    CoderProperties.coderDeterministic(coder, ShardedKey.of(KEY, "shard_id".getBytes(UTF_8)), ShardedKey.of(KEY, "shard_id".getBytes(UTF_8)));
    CoderProperties.coderDeterministic(coder, ShardedKey.of(KEY, new byte[0]), ShardedKey.of(KEY, new byte[0]));
}

