    PCollection<String> path = readPipeline.apply("Create path", Create.of(outputFile.getAbsolutePath()));
    PAssert.that(readPipeline.apply("Read", AvroIO.read(GenericClass.class).withBeamSchemas(withBeamSchemas).from(outputFile.getAbsolutePath()))).containsInAnyOrder(values);
