    PAssert.that(path.apply("MatchAllReadFiles", FileIO.matchAll()).apply("ReadMatchesReadFiles", FileIO.readMatches().withCompression(AUTO)).apply("ReadFiles", AvroIO.readFiles(GenericClass.class).withBeamSchemas(withBeamSchemas).withDesiredBundleSizeBytes(10))).containsInAnyOrder(values);
    PAssert.that(path.apply("ReadAll", AvroIO.readAll(GenericClass.class).withBeamSchemas(withBeamSchemas).withDesiredBundleSizeBytes(10))).containsInAnyOrder(values);
    PAssert.that(readPipeline.apply("Parse", AvroIO.parseGenericRecords(new ParseGenericClass()).from(outputFile.getAbsolutePath()).withCoder(AvroCoder.of(GenericClass.class)))).containsInAnyOrder(values);
    PAssert.that(readPipeline.apply("Parse withHintMatchesManyFiles", AvroIO.parseGenericRecords(new ParseGenericClass()).from(outputFile.getAbsolutePath()).withCoder(AvroCoder.of(GenericClass.class)).withHintMatchesManyFiles())).containsInAnyOrder(values);
    PAssert.that(path.apply("MatchAllParseFilesGenericRecords", FileIO.matchAll()).apply("ReadMatchesParseFilesGenericRecords", FileIO.readMatches().withDirectoryTreatment(FileIO.ReadMatches.DirectoryTreatment.PROHIBIT)).apply("ParseFilesGenericRecords", AvroIO.parseFilesGenericRecords(new ParseGenericClass()).withCoder(AvroCoder.of(GenericClass.class)).withUsesReshuffle(false).withDesiredBundleSizeBytes(10))).containsInAnyOrder(values);
    PAssert.that(path.apply("MatchAllParseFilesGenericRecordsWithShuffle", FileIO.matchAll()).apply("ReadMatchesParseFilesGenericRecordsWithShuffle", FileIO.readMatches().withDirectoryTreatment(FileIO.ReadMatches.DirectoryTreatment.PROHIBIT)).apply("ParseFilesGenericRecordsWithShuffle", AvroIO.parseFilesGenericRecords(new ParseGenericClass()).withCoder(AvroCoder.of(GenericClass.class)).withUsesReshuffle(true).withDesiredBundleSizeBytes(10))).containsInAnyOrder(values);
