@Test
@Category({ NeedsRunner.class, UsesUnboundedSplittableParDo.class })
public void testContinuouslyWriteAndReadMultipleFilepatterns() {
    SimpleFunction<Long, GenericClass> mapFn = new CreateGenericClass();
    List<GenericClass> firstValues = new ArrayList<>();
    List<GenericClass> secondValues = new ArrayList<>();
    for (int i = 0; i < 7; ++i) {
        (i < 3 ? firstValues : secondValues).add(mapFn.apply((long) i));
    }
    // Configure windowing of the input so that it fires every time a new element is generated,
    // so that files are written continuously.
    Window<Long> window = Window.<Long>into(FixedWindows.of(Duration.millis(100))).withAllowedLateness(Duration.ZERO).triggering(Repeatedly.forever(AfterPane.elementCountAtLeast(1))).discardingFiredPanes();
    readPipeline.apply("Sequence first", GenerateSequence.from(0).to(3).withRate(1, Duration.millis(300))).apply("Window first", window).apply("Map first", MapElements.via(mapFn)).apply("Write first", AvroIO.write(GenericClass.class).to(tmpFolder.getRoot().getAbsolutePath() + "/first").withNumShards(2).withWindowedWrites());
    readPipeline.apply("Sequence second", GenerateSequence.from(3).to(7).withRate(1, Duration.millis(300))).apply("Window second", window).apply("Map second", MapElements.via(mapFn)).apply("Write second", AvroIO.write(GenericClass.class).to(tmpFolder.getRoot().getAbsolutePath() + "/second").withNumShards(3).withWindowedWrites());
    // Test read(), readFiles(), readAll(), parse(), parseFilesGenericRecords() and
    // parseAllGenericRecords() with watchForNewFiles().
    PAssert.that(readPipeline.apply("Read", AvroIO.read(GenericClass.class).withBeamSchemas(withBeamSchemas).from(tmpFolder.getRoot().getAbsolutePath() + "/first*").watchForNewFiles(Duration.millis(100), Watch.Growth.afterTimeSinceNewOutput(Duration.standardSeconds(3))))).containsInAnyOrder(firstValues);
    PAssert.that(readPipeline.apply("Parse", AvroIO.parseGenericRecords(new ParseGenericClass()).from(tmpFolder.getRoot().getAbsolutePath() + "/first*").watchForNewFiles(Duration.millis(100), Watch.Growth.afterTimeSinceNewOutput(Duration.standardSeconds(3))))).containsInAnyOrder(firstValues);
    PCollection<String> paths = readPipeline.apply("Create paths", Create.of(tmpFolder.getRoot().getAbsolutePath() + "/first*", tmpFolder.getRoot().getAbsolutePath() + "/second*"));
    PAssert.that(paths.apply("Match All Read files", FileIO.matchAll().continuously(Duration.millis(100), Watch.Growth.afterTimeSinceNewOutput(Duration.standardSeconds(3)))).apply("Read Matches Read files", FileIO.readMatches().withDirectoryTreatment(FileIO.ReadMatches.DirectoryTreatment.PROHIBIT)).apply("Read files", AvroIO.readFiles(GenericClass.class).withBeamSchemas(withBeamSchemas).withDesiredBundleSizeBytes(10))).containsInAnyOrder(Iterables.concat(firstValues, secondValues));
    PAssert.that(paths.apply("Read all", AvroIO.readAll(GenericClass.class).withBeamSchemas(withBeamSchemas).watchForNewFiles(Duration.millis(100), Watch.Growth.afterTimeSinceNewOutput(Duration.standardSeconds(3))).withDesiredBundleSizeBytes(10))).containsInAnyOrder(Iterables.concat(firstValues, secondValues));
    PAssert.that(paths.apply("Match All ParseFilesGenericRecords", FileIO.matchAll().continuously(Duration.millis(100), Watch.Growth.afterTimeSinceNewOutput(Duration.standardSeconds(3)))).apply("Match Matches ParseFilesGenericRecords", FileIO.readMatches().withDirectoryTreatment(FileIO.ReadMatches.DirectoryTreatment.PROHIBIT)).apply("ParseFilesGenericRecords", AvroIO.parseFilesGenericRecords(new ParseGenericClass()).withCoder(AvroCoder.of(GenericClass.class)).withDesiredBundleSizeBytes(10))).containsInAnyOrder(Iterables.concat(firstValues, secondValues));
    PAssert.that(paths.apply("ParseAllGenericRecords", AvroIO.parseAllGenericRecords(new ParseGenericClass()).withCoder(AvroCoder.of(GenericClass.class)).watchForNewFiles(Duration.millis(100), Watch.Growth.afterTimeSinceNewOutput(Duration.standardSeconds(3))).withDesiredBundleSizeBytes(10))).containsInAnyOrder(Iterables.concat(firstValues, secondValues));
    readPipeline.run();
}

