@Test
@Category(NeedsRunner.class)
public void testAvroSinkWriteWithCustomFactory() throws Exception {
    Integer[] expectedElements = new Integer[] { 1, 2, 3, 4, 5 };
    File baseOutputFile = new File(tmpFolder.getRoot(), "prefix");
    String outputFilePrefix = baseOutputFile.getAbsolutePath();
    Schema recordSchema = SchemaBuilder.record("root").fields().requiredInt("i1").endRecord();
    AvroIO.TypedWrite<Integer, Void, Integer> write = AvroIO.<Integer, Integer>writeCustomType(Integer.class).to(outputFilePrefix).withSchema(recordSchema).withFormatFunction(f -> f).withDatumWriterFactory(f -> new DatumWriter<Integer>() {

        private DatumWriter<GenericRecord> inner = new GenericDatumWriter<>(f);

        @Override
        public void setSchema(Schema schema) {
            inner.setSchema(schema);
        }

        @Override
        public void write(Integer datum, Encoder out) throws IOException {
            GenericRecord record = new GenericRecordBuilder(f).set("i1", datum).build();
            inner.write(record, out);
        }
    }).withSuffix(".avro");
    write = write.withoutSharding();
    writePipeline.apply(Create.of(ImmutableList.copyOf(expectedElements))).apply(write);
    writePipeline.run();
    File expectedFile = new File(DefaultFilenamePolicy.constructName(FileBasedSink.convertToFileResourceIfPossible(outputFilePrefix), "", ".avro", 1, 1, null, null).toString());
    assertTrue("Expected output file " + expectedFile.getName(), expectedFile.exists());
    DataFileReader<GenericRecord> dataFileReader = new DataFileReader<>(expectedFile, new GenericDatumReader<>(recordSchema));
    List<GenericRecord> actualRecords = new ArrayList<>();
    Iterators.addAll(actualRecords, dataFileReader);
    GenericRecord[] expectedRecords = Arrays.stream(expectedElements).map(i -> new GenericRecordBuilder(recordSchema).set("i1", i).build()).toArray(GenericRecord[]::new);
    assertThat(actualRecords, containsInAnyOrder(expectedRecords));
}

