@Test
public void testDatumReaderFactoryWithGenericRecord() throws Exception {
    List<Bird> inputBirds = createRandomRecords(100);
    String filename = generateTestFile("tmp.avro", inputBirds, SyncBehavior.SYNC_DEFAULT, 0, AvroCoder.of(Bird.class), DataFileConstants.NULL_CODEC);
    AvroSource.DatumReaderFactory<GenericRecord> factory = (writer, reader) -> new GenericDatumReader<GenericRecord>(writer, reader) {

        @Override
        protected Object readString(Object old, Decoder in) throws IOException {
            return super.readString(old, in) + "_custom";
        }
    };
    AvroSource<Bird> source = AvroSource.from(filename).withParseFn(input -> new Bird((long) input.get("number"), input.get("species").toString(), input.get("quality").toString(), (long) input.get("quantity")), AvroCoder.of(Bird.class)).withDatumReaderFactory(factory);
    List<Bird> actual = SourceTestUtils.readFromSource(source, null);
    List<Bird> expected = inputBirds.stream().map(b -> new Bird(b.number, b.species + "_custom", b.quality + "_custom", b.quantity)).collect(Collectors.toList());
    assertThat(actual, containsInAnyOrder(expected.toArray()));
}

