@Test
public void testMatchNonGlobs() throws Exception {
    List<StorageObjectOrIOException> items = new ArrayList<>();
    // Files within the directory
    items.add(StorageObjectOrIOException.create(createStorageObject("gs://testbucket/testdirectory/file1name", 1L)));
    items.add(StorageObjectOrIOException.create(createStorageObject("gs://testbucket/testdirectory/dir2name/", 0L)));
    items.add(StorageObjectOrIOException.create(new FileNotFoundException()));
    items.add(StorageObjectOrIOException.create(new IOException()));
    items.add(StorageObjectOrIOException.create(createStorageObject("gs://testbucket/testdirectory/file4name", 4L)));
    List<GcsPath> gcsPaths = ImmutableList.of(GcsPath.fromUri("gs://testbucket/testdirectory/file1name"), GcsPath.fromUri("gs://testbucket/testdirectory/dir2name/"), GcsPath.fromUri("gs://testbucket/testdirectory/file2name"), GcsPath.fromUri("gs://testbucket/testdirectory/file3name"), GcsPath.fromUri("gs://testbucket/testdirectory/file4name"));
    when(mockGcsUtil.getObjects(eq(gcsPaths))).thenReturn(items);
    List<MatchResult> matchResults = gcsFileSystem.matchNonGlobs(gcsPaths);
    assertEquals(5, matchResults.size());
    assertThat(ImmutableList.of("gs://testbucket/testdirectory/file1name"), contains(toFilenames(matchResults.get(0)).toArray()));
    assertThat(ImmutableList.of("gs://testbucket/testdirectory/dir2name/"), contains(toFilenames(matchResults.get(1)).toArray()));
    assertEquals(Status.NOT_FOUND, matchResults.get(2).status());
    assertEquals(Status.ERROR, matchResults.get(3).status());
    assertThat(ImmutableList.of("gs://testbucket/testdirectory/file4name"), contains(toFilenames(matchResults.get(4)).toArray()));
}

