    assertThrows(ClassCastException.class, () -> provider.getSerializer(SHUFFLED_SCHEMA, ImmutableMap.of("protoClass", ImmutableList.class.getName())));
    assertThrows(IllegalArgumentException.class, () -> provider.getSerializer(Schema.builder().addStringField("f_NOTACTUALLYINMESSAGE").addInt32Field("f_int").addArrayField("f_float_array", FieldType.FLOAT).addDoubleField("f_double").addInt64Field("f_long").build(), ImmutableMap.of("protoClass", PayloadMessages.TestMessage.class.getName())));
}

