@Test
public void testCrossCatalogTableWriteAndRead() throws IOException {
    // create and use catalog 1
    sqlEnv.executeDdl(createCatalog("catalog_1"));
    sqlEnv.executeDdl("USE CATALOG catalog_1");
    assertEquals("catalog_1", catalogManager.currentCatalog().name());
    // create and use database inside catalog 1
    IcebergCatalog catalog = (IcebergCatalog) catalogManager.currentCatalog();
    sqlEnv.executeDdl("CREATE DATABASE my_namespace");
    sqlEnv.executeDdl("USE DATABASE my_namespace");
    assertEquals("my_namespace", catalog.currentDatabase());
    // create and write to table inside database
    String tableIdentifier = "my_namespace.my_table";
    sqlEnv.executeDdl(format("CREATE EXTERNAL TABLE %s( \n", tableIdentifier) + "   c_integer INTEGER, \n" + "   c_boolean BOOLEAN, \n" + "   c_timestamp TIMESTAMP, \n" + "   c_varchar VARCHAR \n " + ") \n" + "TYPE 'iceberg'\n");
    BeamRelNode insertNode = sqlEnv.parseQuery(format("INSERT INTO %s VALUES (", tableIdentifier) + "2147483647, " + "TRUE, " + "TIMESTAMP '2025-07-31 20:17:40.123', " + "'varchar' " + ")");
    Pipeline p1 = Pipeline.create();
    BeamSqlRelUtils.toPCollection(p1, insertNode);
    p1.run().waitUntilFinish();
    // create and use a new catalog, with a new database
    File warehouseFile2 = TEMPORARY_FOLDER.newFolder();
    assertTrue(warehouseFile2.delete());
    String warehouse2 = "file:" + warehouseFile2 + "/" + UUID.randomUUID();
    sqlEnv.executeDdl(createCatalog("catalog_2", warehouse2));
    sqlEnv.executeDdl("USE CATALOG catalog_2");
    sqlEnv.executeDdl("CREATE DATABASE other_namespace");
    sqlEnv.executeDdl("USE DATABASE other_namespace");
    assertEquals("catalog_2", catalogManager.currentCatalog().name());
    assertEquals("other_namespace", catalogManager.currentCatalog().currentDatabase());
    // insert from old catalog to new table in new catalog
    sqlEnv.executeDdl("CREATE EXTERNAL TABLE other_table( \n" + "   c_integer INTEGER, \n" + "   c_boolean BOOLEAN, \n" + "   c_timestamp TIMESTAMP, \n" + "   c_varchar VARCHAR) \n" + "TYPE 'iceberg'\n");
    BeamRelNode insertNode2 = sqlEnv.parseQuery("INSERT INTO other_table SELECT * FROM catalog_1.my_namespace.my_table");
    Pipeline p2 = Pipeline.create();
    BeamSqlRelUtils.toPCollection(p2, insertNode2);
    p2.run().waitUntilFinish();
    // switch over to catalog 1 and read table inside catalog 2
    sqlEnv.executeDdl("USE DATABASE catalog_1.my_namespace");
    BeamRelNode insertNode3 = sqlEnv.parseQuery("SELECT * FROM catalog_2.other_namespace.other_table");
    Pipeline p3 = Pipeline.create();
    PCollection<Row> output = BeamSqlRelUtils.toPCollection(p3, insertNode3);
    // validate read contents
    Schema expectedSchema = checkStateNotNull(catalog.catalogConfig.loadTable(tableIdentifier)).getSchema();
    assertEquals(expectedSchema, output.getSchema());
    PAssert.that(output).containsInAnyOrder(Row.withSchema(expectedSchema).addValues(2147483647, true, DateTime.parse("2025-07-31T20:17:40.123Z"), "varchar").build());
    p3.run().waitUntilFinish();
    assertEquals("catalog_1", catalogManager.currentCatalog().name());
    assertEquals("my_namespace", catalogManager.currentCatalog().currentDatabase());
}

@Test
public void testIsSupported() {
    ImmutableList<Pair<String, Boolean>> sqlQueries = ImmutableList.of(Pair.of("select * from TEST where unused1=100", true), Pair.of("select * from TEST where unused1 in (100, 200)", true), Pair.of("select * from TEST where unused1+10=110", true), Pair.of("select * from TEST where b", true), Pair.of("select * from TEST where unused1>100 and unused1<=200 and id<>1 and (name='two' or id=2)", true), Pair.of("select * from TEST where unused2=200", true), // Functions involving more than one column are not supported yet.
    Pair.of("select * from TEST where unused1=unused2 and id=2", false));
    for (Pair<String, Boolean> query : sqlQueries) {
        String sql = query.getLeft();
        Boolean isSupported = query.getRight();
        BeamRelNode beamRelNode = sqlEnv.parseQuery(sql);
        assertThat(beamRelNode, instanceOf(BeamCalcRel.class));
        IcebergFilter filter = new IcebergFilter(((BeamCalcRel) beamRelNode).getProgram().split().right);
        assertThat("Query: '" + sql + "' is expected to be " + (isSupported ? "supported." : "unsupported."), filter.getNotSupported().isEmpty() == isSupported);
    }
}

