@Test
public void testSQLReadWithProjectAndFilterPushDown() {
    BeamSqlEnv sqlEnv = BeamSqlEnv.builder(new InMemoryCatalogManager()).setPipelineOptions(PipelineOptionsFactory.create()).build();
    String tableIdentifier = DATASET + "." + testName.getMethodName();
    String tableName = TableName.create(tableIdentifier).getTableName();
    // 1) create Iceberg catalog
    String createCatalog = "CREATE CATALOG my_catalog \n" + "TYPE iceberg \n" + "PROPERTIES (\n" + "  'catalog-impl' = 'org.apache.iceberg.gcp.bigquery.BigQueryMetastoreCatalog', \n" + "  'io-impl' = 'org.apache.iceberg.gcp.gcs.GCSFileIO', \n" + format("  'warehouse' = '%s', \n", warehouse) + format("  'gcp_project' = '%s', \n", OPTIONS.getProject()) + "  'gcp_region' = 'us-central1')";
    sqlEnv.executeDdl(createCatalog);
    // 2) use the catalog we just created and the dataset
    sqlEnv.executeDdl("USE CATALOG my_catalog");
    sqlEnv.executeDdl("USE DATABASE " + DATASET);
    // 3) create Beam table
    String createTableStatement = format("CREATE EXTERNAL TABLE %s( \n", tableName) + "   c_integer INTEGER, \n" + "   c_float FLOAT, \n" + "   c_boolean BOOLEAN, \n" + "   c_timestamp TIMESTAMP, \n" + "   c_varchar VARCHAR \n " + ") \n" + "TYPE 'iceberg'";
    sqlEnv.executeDdl(createTableStatement);
    // 4) insert some data)
    String insertStatement = format("INSERT INTO %s VALUES ", tableName) + "(123, 1.23, TRUE, TIMESTAMP '2025-05-22 20:17:40.123', 'a'), " + "(456, 4.56, FALSE, TIMESTAMP '2025-05-25 20:17:40.123', 'b'), " + "(789, 7.89, TRUE, TIMESTAMP '2025-05-28 20:17:40.123', 'c')";
    BeamSqlRelUtils.toPCollection(writePipeline, sqlEnv.parseQuery(insertStatement));
    writePipeline.run().waitUntilFinish(Duration.standardMinutes(5));
    // 5) read with a filter
    String selectTableStatement = format("SELECT c_integer, c_varchar FROM %s where ", tableName) + "(c_boolean=TRUE and c_varchar in ('a', 'b')) or c_float > 5";
    BeamRelNode relNode = sqlEnv.parseQuery(selectTableStatement);
    PCollection<Row> output = BeamSqlRelUtils.toPCollection(readPipeline, relNode);
    assertThat(relNode, instanceOf(BeamPushDownIOSourceRel.class));
    // Unused fields should not be projected by an IO
    assertThat(relNode.getRowType().getFieldNames(), containsInAnyOrder("c_integer", "c_varchar"));
    assertThat(output.getSchema(), equalTo(Schema.builder().addNullableField("c_integer", INT32).addNullableField("c_varchar", STRING).build()));
    PAssert.that(output).containsInAnyOrder(Row.withSchema(output.getSchema()).addValues(123, "a").build(), Row.withSchema(output.getSchema()).addValues(789, "c").build());
    PipelineResult.State state = readPipeline.run().waitUntilFinish(Duration.standardMinutes(5));
    assertThat(state, equalTo(PipelineResult.State.DONE));
}

