@Test
public void testCastToDateWithCase() {
    PCollection<Row> input = pipeline.apply(Create.of(Row.withSchema(INPUT_ROW_SCHEMA).addValues(1).addValue("20181018").build()).withRowSchema(INPUT_ROW_SCHEMA));
    Schema resultType = Schema.builder().addInt32Field("f_int").addLogicalTypeField("f_date", SqlTypes.DATE).build();
    PCollection<Row> result = input.apply("sqlQuery", SqlTransform.query("SELECT f_int, 
" + "CASE WHEN CHAR_LENGTH(TRIM(f_string)) = 8 
" + "    THEN CAST (
" + "       SUBSTRING(TRIM(f_string) FROM 1 FOR 4) 
" + "        ||'-' 
" + "        ||SUBSTRING(TRIM(f_string) FROM 5 FOR 2) 
" + "        ||'-' 
