    cli.execute("CREATE CATALOG my_catalog \n" + "TYPE 'local' \n" + "PROPERTIES (\n" + "  'foo' = 'bar', \n" + "  'abc' = 'xyz', \n" + "  'beam.test.prop' = '123'\n" + ")");
