public void testSQLWrite() {
    BeamSqlEnv sqlEnv = BeamSqlEnv.inMemory(new BigQueryTableProvider());
    String createTableStatement = "CREATE EXTERNAL TABLE TEST( 
" + "   c_bigint BIGINT, 
" + "   c_tinyint TINYINT, 
" + "   c_smallint SMALLINT, 
