    final Document expectedFilter = new Document().append("$or", ImmutableList.of(new Document("c_varchar", "varchar"), new Document("c_varchar", new Document("$not", new Document("$eq", "fakeString"))))).append("c_boolean", true).append("c_integer", 2147483647);
