@Test
public void testSimpleInsert() throws Exception {
    String createCatalog = "CREATE CATALOG my_catalog TYPE `local`";
    String setCatalog = "USE CATALOG my_catalog";
    String pubsubTableString = "CREATE EXTERNAL TABLE pubsub_topic (
" + "event_timestamp TIMESTAMP, 
" + "attributes MAP<VARCHAR, VARCHAR>, 
" + "payload ROW< 
" + "             id BIGINT, 
" + "             name VARCHAR 
" + "           > 
" + ") 
" + "TYPE 'pubsub' 
" + "LOCATION '" + pubsub.topicPath() + "' 
" + "TBLPROPERTIES '{ "timestampAttributeKey" : "ts" }'";
    String bqTableString = "CREATE EXTERNAL TABLE bq_table( 
" + "   id BIGINT, 
" + "   name VARCHAR 
 " + ") 
" + "TYPE 'bigquery' 
" + "LOCATION '" + bigQuery.tableSpec() + "'";
    String insertStatement = "INSERT INTO bq_table 
" + "SELECT 
" + "  pubsub_topic.payload.id, 
" + "  pubsub_topic.payload.name 
" + "FROM pubsub_topic";
    pipeline.apply(SqlTransform.query(insertStatement).withDdlString(createCatalog).withDdlString(setCatalog).withDdlString(pubsubTableString).withDdlString(bqTableString));
    pipeline.run();
    // Block until a subscription for this topic exists
    pubsub.assertSubscriptionEventuallyCreated(pipeline.getOptions().as(GcpOptions.class).getProject(), Duration.standardMinutes(5));
    List<PubsubMessage> messages = ImmutableList.of(message(ts(1), 3, "foo"), message(ts(2), 5, "bar"), message(ts(3), 7, "baz"));
    pubsub.publish(messages);
    bigQuery.assertThatAllRows(SOURCE_SCHEMA).eventually(containsInAnyOrder(row(SOURCE_SCHEMA, 3L, "foo"), row(SOURCE_SCHEMA, 5L, "bar"), row(SOURCE_SCHEMA, 7L, "baz"))).pollFor(Duration.standardMinutes(5));
}

