@Test
public void testFillGaps() {
    List<TimestampedValue<Message>> values = ImmutableList.of(Message.ofTimestamped("key1", "value0<", Instant.ofEpochSecond(0)), Message.ofTimestamped("key2", "value0", Instant.ofEpochSecond(0)), Message.ofTimestamped("key1", "value1<", Instant.ofEpochSecond(1)), Message.ofTimestamped("key1", "value1", Instant.ofEpochSecond(1).plus(Duration.millis(1))), Message.ofTimestamped("key2", "value1<", Instant.ofEpochSecond(1)), Message.ofTimestamped("key2", "value1", Instant.ofEpochSecond(1).plus(Duration.millis(1))), Message.ofTimestamped("key1", "value3", Instant.ofEpochSecond(3)), Message.ofTimestamped("key2", "value3", Instant.ofEpochSecond(3)));
    PCollection<Message> input = pipeline.apply(Create.timestamped(values));
