@Test
public void multipleOutputYamlTransform() {
    PCollectionRowTuple output = pipeline.apply(Create.of(ALICE, BOB)).setRowSchema(INPUT_SCHEMA).apply(// TODO(https://github.com/apache/beam/pull/34595): Use Partition transform.
    // This needs to wait until the above change is in a released version of Beam.
