    assertThat(runner.assignWindows(WindowedValues.valueInGlobalWindow(1)), equalTo(WindowedValues.of(1, BoundedWindow.TIMESTAMP_MIN_VALUE, windowFn.assignWindow(BoundedWindow.TIMESTAMP_MIN_VALUE), PaneInfo.NO_FIRING)));
    assertThat(runner.assignWindows(WindowedValues.of(2, new Instant(-10L), new IntervalWindow(new Instant(-120000L), Duration.standardMinutes(3L)), PaneInfo.ON_TIME_AND_ONLY_FIRING)), equalTo(WindowedValues.of(2, new Instant(-10L), windowFn.assignWindow(new Instant(-10L)), PaneInfo.ON_TIME_AND_ONLY_FIRING)));
