@Test
public void singleInputMultipleOutputSucceeds() throws Exception {
    WindowFn<Object, IntervalWindow> windowFn = SlidingWindows.of(Duration.standardMinutes(4L)).every(Duration.standardMinutes(2L));
    AssignWindowsRunner<Integer, IntervalWindow> runner = AssignWindowsRunner.create(windowFn);
    IntervalWindow firstWindow = new IntervalWindow(new Instant(0).minus(Duration.standardMinutes(4L)), Duration.standardMinutes(4L));
    IntervalWindow secondWindow = new IntervalWindow(new Instant(0).minus(Duration.standardMinutes(2L)), Duration.standardMinutes(4L));
    IntervalWindow thirdWindow = new IntervalWindow(new Instant(0), Duration.standardMinutes(4L));
    WindowedValue<Integer> firstValue = WindowedValues.timestampedValueInGlobalWindow(-3, new Instant(-12));
    assertThat(runner.assignWindows(firstValue), equalTo(WindowedValues.of(-3, new Instant(-12), ImmutableSet.of(firstWindow, secondWindow), firstValue.getPaneInfo())));
    WindowedValue<Integer> secondValue = WindowedValues.of(3, new Instant(12), new IntervalWindow(new Instant(-12), Duration.standardMinutes(24)), PaneInfo.ON_TIME_AND_ONLY_FIRING);
    assertThat(runner.assignWindows(secondValue), equalTo(WindowedValues.of(3, new Instant(12), ImmutableSet.of(secondWindow, thirdWindow), secondValue.getPaneInfo())));
}

