@Test
public void testReuseForMultipleBundles() throws Exception {
    String localOutputId = "outputPC";
    List<WindowedValue<String>> outputValues = new ArrayList<>();
    AtomicReference<String> bundleId = new AtomicReference<>("0");
    PTransformRunnerFactoryTestContext context = PTransformRunnerFactoryTestContext.builder(INPUT_TRANSFORM_ID, RemoteGrpcPortRead.readFromPort(PORT_SPEC, localOutputId).toPTransform()).processBundleInstructionIdSupplier(bundleId::get).components(RunnerApi.Components.newBuilder().putAllPcollections(ImmutableMap.of(localOutputId, RunnerApi.PCollection.newBuilder().setCoderId(ELEMENT_CODER_SPEC_ID).build())).putAllCoders(COMPONENTS.getCodersMap()).putAllWindowingStrategies(COMPONENTS.getWindowingStrategiesMap()).build()).build();
    context.<String>addPCollectionConsumer(localOutputId, outputValues::add);
    BeamFnDataReadRunner<String> readRunner = new BeamFnDataReadRunner.Factory().addReadRunnerForPTransform(context);
    assertThat(context.getIncomingDataEndpoints().keySet(), hasSize(1));
    DataEndpoint<WindowedValue<String>> endpoint = (DataEndpoint<WindowedValue<String>>) Iterables.getOnlyElement(context.getIncomingDataEndpoints().get(PORT_SPEC.getApiServiceDescriptor()));
    // Process for bundle id 0
    assertIntermediateMonitoringDataDataChannelReadIndexEquals(context.getShortIdMap(), context.getBundleProgressReporters(), -1);
    endpoint.getReceiver().accept(valueInGlobalWindow("ABC"));
    assertIntermediateMonitoringDataDataChannelReadIndexEquals(context.getShortIdMap(), context.getBundleProgressReporters(), 0);
    endpoint.getReceiver().accept(valueInGlobalWindow("DEF"));
    assertIntermediateMonitoringDataDataChannelReadIndexEquals(context.getShortIdMap(), context.getBundleProgressReporters(), 1);
    readRunner.blockTillReadFinishes();
    assertIntermediateMonitoringDataDataChannelReadIndexEquals(context.getShortIdMap(), context.getBundleProgressReporters(), 2);
    assertFinalMonitoringDataDataChannelReadIndexEquals(context.getShortIdMap(), context.getBundleProgressReporters(), 2);
    assertThat(outputValues, contains(valueInGlobalWindow("ABC"), valueInGlobalWindow("DEF")));
    // The BundleProcessor should be released first before calling reset.
    bundleId.set(null);
    readRunner.reset();
    outputValues.clear();
    // Ensure that when we reuse the BeamFnDataReadRunner the read index is reset to -1
    // before registerInputLocation.
    assertIntermediateMonitoringDataDataChannelReadIndexEquals(context.getShortIdMap(), context.getBundleProgressReporters(), -1);
    // Process for bundle id 1
    bundleId.set("1");
    endpoint.getReceiver().accept(valueInGlobalWindow("GHI"));
    assertIntermediateMonitoringDataDataChannelReadIndexEquals(context.getShortIdMap(), context.getBundleProgressReporters(), 0);
    endpoint.getReceiver().accept(valueInGlobalWindow("JKL"));
    assertIntermediateMonitoringDataDataChannelReadIndexEquals(context.getShortIdMap(), context.getBundleProgressReporters(), 1);
    readRunner.blockTillReadFinishes();
    assertIntermediateMonitoringDataDataChannelReadIndexEquals(context.getShortIdMap(), context.getBundleProgressReporters(), 2);
    assertFinalMonitoringDataDataChannelReadIndexEquals(context.getShortIdMap(), context.getBundleProgressReporters(), 2);
    assertThat(outputValues, contains(valueInGlobalWindow("GHI"), valueInGlobalWindow("JKL")));
}

