@Test
public void testDescribeStats() throws Exception {
    Cache<WeightedValue<Integer>, ShrinkableString> cache = Caches.forMaximumBytes(1000 * MB);
    for (int i = 0; i < 100; ++i) {
        cache.computeIfAbsent(WeightedValue.of(i, MB), (key) -> new ShrinkableString("value", 2 * MB));
        cache.peek(WeightedValue.of(i, MB));
        cache.put(WeightedValue.of(100 + i, MB), new ShrinkableString("value", 2 * MB));
    }
    assertThat(cache.describeStats(), containsString("used/max 600/1000 MB"));
    assertThat(// Locale sensitive.
    cache.describeStats(), anyOf(containsString("hit 50.00%"), containsString("hit 50,00%")));
    assertThat(cache.describeStats(), containsString("lookups 200"));
    assertThat(cache.describeStats(), containsString("avg load time"));
    assertThat(cache.describeStats(), containsString("loads 100"));
    assertThat(cache.describeStats(), containsString("evictions 0"));
    // Test eviction, evict all the other 200 elements that were added
    cache.put(WeightedValue.of(1000, 100 * MB), new ShrinkableString("value", 899 * MB));
    assertThat(cache.describeStats(), containsString("used/max 999/1000 MB"));
    assertThat(cache.describeStats(), containsString("evictions 200"));
    // Test shrinking, 900 -> 450 + 100 + 55 + 1 = 606
    cache.put(WeightedValue.of(1001, MB), new ShrinkableString("value", 55 * MB));
    assertThat(cache.describeStats(), containsString("used/max 605/1000 MB"));
    assertThat(cache.describeStats(), containsString("evictions 201"));
    // Test composite key namespace is weighed as well.
    // 34 + 8 + 3 = 45 more then last used/max of 605 = 650
    Caches.subCache(cache, WeightedValue.of("subCache", 34 * MB)).put(WeightedValue.of("subCacheKey", 8 * MB), WeightedValue.of("subCacheValue", 3 * MB));
    assertThat(cache.describeStats(), containsString("used/max 650/1000 MB"));
}

/**
 * Create a Precombine that is given keyed elements and validates that the outputted elements
 * values' are accumulators that were correctly derived from the input.
 */
@Test
public void testPrecombine() throws Exception {
    PTransformRunnerFactoryTestContext context = PTransformRunnerFactoryTestContext.builder(TEST_COMBINE_ID, pTransform).components(RunnerApi.Components.newBuilder().putAllPcollections(pProto.getComponents().getPcollectionsMap()).putAllCoders(pProto.getComponents().getCodersMap()).putAllWindowingStrategies(pProto.getComponents().getWindowingStrategiesMap()).build()).build();
    // Add a consumer and output target to check output values.
    Deque<WindowedValue<KV<String, Integer>>> mainOutputValues = new ArrayDeque<>();
    context.addPCollectionConsumer(Iterables.getOnlyElement(pTransform.getOutputsMap().values()), (FnDataReceiver) (FnDataReceiver<WindowedValue<KV<String, Integer>>>) mainOutputValues::add);
    // Create runner.
    new CombineRunners.PrecombineFactory().addRunnerForPTransform(context);
    Iterables.getOnlyElement(context.getStartBundleFunctions()).run();
    // Send elements to runner and check outputs.
    mainOutputValues.clear();
    assertThat(context.getPCollectionConsumers().keySet(), containsInAnyOrder(inputPCollectionId, outputPCollectionId));
    FnDataReceiver<WindowedValue<?>> input = context.getPCollectionConsumer(inputPCollectionId);
    input.accept(valueInGlobalWindow(KV.of("A", "1")));
    input.accept(valueInGlobalWindow(KV.of("A", "2")));
    input.accept(valueInGlobalWindow(KV.of("A", "6")));
    input.accept(valueInGlobalWindow(KV.of("B", "2")));
    input.accept(valueInGlobalWindow(KV.of("C", "3")));
    Iterables.getOnlyElement(context.getFinishBundleFunctions()).run();
    // Check that all values for "A" were converted to accumulators regardless of how they were
    // combined by the Precombine optimization.
    Integer sum = 0;
    for (WindowedValue<KV<String, Integer>> outputValue : mainOutputValues) {
        if ("A".equals(outputValue.getValue().getKey())) {
            sum += outputValue.getValue().getValue();
        }
    }
    assertThat(sum, equalTo(9));
    // Check that elements for "B" and "C" are present as well.
    mainOutputValues.removeIf(elem -> "A".equals(elem.getValue().getKey()));
    assertThat(mainOutputValues, containsInAnyOrder(valueInGlobalWindow(KV.of("B", 2)), valueInGlobalWindow(KV.of("C", 3))));
}

