@Test
public void logsExceptionWithTransformId() throws Exception {
    final String pTransformId = "pTransformId";
    final String message = "testException";
    final String instructionId = "instruction";
    final Exception thrownException = new Exception(message);
    // The following is a bunch of boiler-plate to set up a local FnApiLoggingService to catch any
    // logs for later test
    // expectations.
    AtomicBoolean clientClosedStream = new AtomicBoolean();
    Collection<BeamFnApi.LogEntry> values = new ConcurrentLinkedQueue<>();
    AtomicReference<StreamObserver<BeamFnApi.LogControl>> outboundServerObserver = new AtomicReference<>();
    CallStreamObserver<BeamFnApi.LogEntry.List> inboundServerObserver = TestStreams.withOnNext((BeamFnApi.LogEntry.List logEntries) -> values.addAll(logEntries.getLogEntriesList())).withOnCompleted(() -> {
        // Remember that the client told us that this stream completed
        clientClosedStream.set(true);
        outboundServerObserver.get().onCompleted();
    }).build();
    Endpoints.ApiServiceDescriptor apiServiceDescriptor = Endpoints.ApiServiceDescriptor.newBuilder().setUrl(this.getClass().getName() + "-" + UUID.randomUUID().toString()).build();
    Server server = InProcessServerBuilder.forName(apiServiceDescriptor.getUrl()).addService(new BeamFnLoggingGrpc.BeamFnLoggingImplBase() {

        @Override
        public StreamObserver<BeamFnApi.LogEntry.List> logging(StreamObserver<BeamFnApi.LogControl> outboundObserver) {
            outboundServerObserver.set(outboundObserver);
            return inboundServerObserver;
        }
    }).build();
    server.start();
    ManagedChannel channel = InProcessChannelBuilder.forName(apiServiceDescriptor.getUrl()).build();
    // End logging boiler-plate...
    // This section is to set up the StateSampler with the expected metadata.
    ExecutionStateSampler sampler = new ExecutionStateSampler(PipelineOptionsFactory.create(), System::currentTimeMillis, null);
    ExecutionStateSampler.ExecutionStateTracker stateTracker = sampler.create();
    stateTracker.start("process-bundle");
    ExecutionStateSampler.ExecutionState state = stateTracker.create("shortId", pTransformId, pTransformId, "process");
    state.activate();
    // Track the instruction and state in the logging system. In a real run, this is set when a
    // ProcessBundlehandler
    // starts processing.
    BeamFnLoggingMDC.setInstructionId(instructionId);
    BeamFnLoggingMDC.setStateTracker(stateTracker);
    // Start the test within the logging context. This reroutes logging through to the boiler-plate
    // that was set up
    // earlier.
    try (LoggingClient ignored = LoggingClientFactory.createAndStart(PipelineOptionsFactory.create(), apiServiceDescriptor, (Endpoints.ApiServiceDescriptor descriptor) -> channel)) {
        // Set up the component under test, the FnDataReceiver, to emit an exception when it starts.
        ShortIdMap shortIds = new ShortIdMap();
        BundleProgressReporter.InMemory reporterAndRegistrar = new BundleProgressReporter.InMemory();
        PCollectionConsumerRegistry consumers = new PCollectionConsumerRegistry(stateTracker, shortIds, reporterAndRegistrar, TEST_DESCRIPTOR);
        FnDataReceiver<WindowedValue<String>> consumer = mock(FnDataReceiver.class);
        consumers.register(P_COLLECTION_A, pTransformId, pTransformId + "Name", consumer);
        FnDataReceiver<WindowedValue<String>> wrapperConsumer = (FnDataReceiver<WindowedValue<String>>) (FnDataReceiver) consumers.getMultiplexingConsumer(P_COLLECTION_A);
        doThrow(thrownException).when(consumer).accept(any());
        expectedException.expectMessage(message);
        expectedException.expect(Exception.class);
        // Run the test.
        wrapperConsumer.accept(valueInGlobalWindow("elem"));
    } finally {
        // The actual log entry has a lot of metadata that can't easily be controlled. So set the
        // entries that are needed
        // for this test and cull everything else.
        final BeamFnApi.LogEntry expectedEntry = BeamFnApi.LogEntry.newBuilder().setInstructionId(instructionId).setTransformId(pTransformId).setMessage("Failed to process element for bundle \"process-bundle\"").build();
        List<BeamFnApi.LogEntry> entries = new ArrayList<>(values);
        assertEquals(1, entries.size());
        BeamFnApi.LogEntry actualEntry = entries.get(0);
        BeamFnApi.LogEntry actualEntryCulled = BeamFnApi.LogEntry.newBuilder().setInstructionId(actualEntry.getInstructionId()).setTransformId(actualEntry.getTransformId()).setMessage(actualEntry.getMessage()).build();
        assertEquals(expectedEntry, actualEntryCulled);
        server.shutdownNow();
    }
}

@Test
public void testStateTrackerRecordsStateTransitions() throws Exception {
    ExecutionStateTracker executionStateTracker = sampler.create();
    MetricsEnvironment.setCurrentContainer(executionStateTracker.getMetricsContainer());
    PTransformFunctionRegistry testObject = new PTransformFunctionRegistry(new ShortIdMap(), executionStateTracker, Urns.START_BUNDLE_MSECS);
    final AtomicBoolean runnableAWasCalled = new AtomicBoolean();
    final AtomicBoolean runnableBWasCalled = new AtomicBoolean();
    ThrowingRunnable runnableA = new ThrowingRunnable() {

        @Override
        public void run() throws Exception {
            runnableAWasCalled.set(true);
            ExecutionStateTrackerStatus executionStateTrackerStatus = executionStateTracker.getStatus();
            assertNotNull(executionStateTrackerStatus);
            assertEquals(Thread.currentThread(), executionStateTrackerStatus.getTrackedThread());
            assertEquals("pTransformA", executionStateTrackerStatus.getPTransformId());
        }
    };
    ThrowingRunnable runnableB = new ThrowingRunnable() {

        @Override
        public void run() throws Exception {
            runnableBWasCalled.set(true);
            ExecutionStateTrackerStatus executionStateTrackerStatus = executionStateTracker.getStatus();
            assertNotNull(executionStateTrackerStatus);
            assertEquals(Thread.currentThread(), executionStateTrackerStatus.getTrackedThread());
            assertEquals("pTransformB", executionStateTrackerStatus.getPTransformId());
        }
    };
    testObject.register("pTransformA", "pTranformAName", runnableA);
    testObject.register("pTransformB", "pTranformBName", runnableB);
    executionStateTracker.start("testBundleId");
    for (ThrowingRunnable func : testObject.getFunctions()) {
        func.run();
    }
    executionStateTracker.reset();
    assertTrue(runnableAWasCalled.get());
    assertTrue(runnableBWasCalled.get());
}

@Test
public void testMetricsUponRunningFunctions() throws Exception {
    ExecutionStateTracker executionStateTracker = sampler.create();
    MetricsEnvironment.setCurrentContainer(executionStateTracker.getMetricsContainer());
    PTransformFunctionRegistry testObject = new PTransformFunctionRegistry(new ShortIdMap(), executionStateTracker, Urns.START_BUNDLE_MSECS);
    testObject.register("pTransformA", "pTranformAName", () -> TEST_USER_COUNTER.inc());
    testObject.register("pTransformB", "pTranformBName", () -> TEST_USER_COUNTER.inc(2));
    // Test both cases; when there is an existing container and where there is no container
    executionStateTracker.start("testBundleId");
    for (ThrowingRunnable func : testObject.getFunctions()) {
        func.run();
    }
    TEST_USER_COUNTER.inc(3);
    // Verify that metrics environment state is updated with pTransform's counters including the
    // unbound container when outside the scope of the function
    assertEquals(1L, (long) executionStateTracker.getMetricsContainerRegistry().getContainer("pTransformA").getCounter(TEST_USER_COUNTER.getName()).getCumulative());
    assertEquals(2L, (long) executionStateTracker.getMetricsContainerRegistry().getContainer("pTransformB").getCounter(TEST_USER_COUNTER.getName()).getCumulative());
    assertEquals(3L, (long) executionStateTracker.getMetricsContainerRegistry().getUnboundContainer().getCounter(TEST_USER_COUNTER.getName()).getCumulative());
    executionStateTracker.reset();
}

