@Test
public void testProcessElementForSizedElementAndRestriction() throws Exception {
    Pipeline p = Pipeline.create();
    addExperiment(p.getOptions().as(ExperimentalOptions.class), "beam_fn_api");
    // TODO(BEAM-10097): Remove experiment once all portable runners support this view type
    addExperiment(p.getOptions().as(ExperimentalOptions.class), "use_runner_v2");
    PCollection<String> valuePCollection = p.apply(Create.of("unused"));
    PCollectionView<String> singletonSideInputView = valuePCollection.apply(View.asSingleton());
    WindowObservingTestSplittableDoFn doFn = new WindowObservingTestSplittableDoFn(singletonSideInputView);
    valuePCollection.apply(TEST_TRANSFORM_ID, ParDo.of(doFn).withSideInputs(singletonSideInputView));
    RunnerApi.Pipeline pProto = ProtoOverrides.updateTransform(PTransformTranslation.PAR_DO_TRANSFORM_URN, PipelineTranslation.toProto(p, SdkComponents.create(p.getOptions()), true), SplittableParDoExpander.createSizedReplacement());
    String expandedTransformId = Iterables.find(pProto.getComponents().getTransformsMap().entrySet(), entry -> entry.getValue().getSpec().getUrn().equals(PTransformTranslation.SPLITTABLE_PROCESS_SIZED_ELEMENTS_AND_RESTRICTIONS_URN) && entry.getValue().getUniqueName().contains(TEST_TRANSFORM_ID)).getKey();
    RunnerApi.PTransform pTransform = pProto.getComponents().getTransformsOrThrow(expandedTransformId);
    String inputPCollectionId = pTransform.getInputsOrThrow(ParDoTranslation.getMainInputName(pTransform));
    RunnerApi.PCollection inputPCollection = pProto.getComponents().getPcollectionsOrThrow(inputPCollectionId);
    RehydratedComponents rehydratedComponents = RehydratedComponents.forComponents(pProto.getComponents());
    Coder<WindowedValue> inputCoder = WindowedValues.getFullCoder(CoderTranslation.fromProto(pProto.getComponents().getCodersOrThrow(inputPCollection.getCoderId()), rehydratedComponents, TranslationContext.DEFAULT), (Coder) CoderTranslation.fromProto(pProto.getComponents().getCodersOrThrow(pProto.getComponents().getWindowingStrategiesOrThrow(inputPCollection.getWindowingStrategyId()).getWindowCoderId()), rehydratedComponents, TranslationContext.DEFAULT));
    String outputPCollectionId = pTransform.getOutputsOrThrow("output");
    ImmutableMap<StateKey, List<String>> stateData = ImmutableMap.of(iterableSideInputKey(singletonSideInputView.getTagInternal().getId(), ByteString.EMPTY), asList("8"));
    FakeBeamFnStateClient fakeClient = new FakeBeamFnStateClient(StringUtf8Coder.of(), stateData);
    BundleSplitListener.InMemory splitListener = BundleSplitListener.InMemory.create();
    PTransformRunnerFactoryTestContext context = PTransformRunnerFactoryTestContext.builder(TEST_TRANSFORM_ID, pTransform).beamFnStateClient(fakeClient).processBundleInstructionId("57").components(RunnerApi.Components.newBuilder().putAllCoders(pProto.getComponents().getCodersMap()).putAllEnvironments(Collections.emptyMap()).putAllWindowingStrategies(pProto.getComponents().getWindowingStrategiesMap()).putAllPcollections(pProto.getComponentsOrBuilder().getPcollectionsMap()).build()).splitListener(splitListener).build();
    List<WindowedValue<String>> mainOutputValues = new ArrayList<>();
    context.addPCollectionConsumer(outputPCollectionId, (FnDataReceiver) (FnDataReceiver<WindowedValue<String>>) mainOutputValues::add);
    new FnApiDoFnRunner.Factory<>().addRunnerForPTransform(context);
    Iterables.getOnlyElement(context.getStartBundleFunctions()).run();
    mainOutputValues.clear();
    assertThat(context.getPCollectionConsumers().keySet(), containsInAnyOrder(inputPCollectionId, outputPCollectionId));
    FnDataReceiver<WindowedValue<?>> mainInput = context.getPCollectionConsumer(inputPCollectionId);
    assertThat(mainInput, instanceOf(HandlesSplits.class));
    {
        // Check that before processing an element we don't report progress
        assertNoReportedProgress(context.getBundleProgressReporters());
        mainInput.accept(valueInGlobalWindow(KV.of(KV.of("5", KV.of(new OffsetRange(5, 10), GlobalWindow.TIMESTAMP_MIN_VALUE)), 5.0)));
        // Check that after processing an element we don't report progress
        assertNoReportedProgress(context.getBundleProgressReporters());
        // Since the side input upperBound is 8 we will process 5, 6, and 7 then checkpoint.
        // We expect that the watermark advances to MIN + 7 and that the primary represents [5, 8)
        // with
        // the original watermark while the residual represents [8, 10) with the new MIN + 7
        // watermark.
        BundleApplication primaryRoot = Iterables.getOnlyElement(splitListener.getPrimaryRoots());
        DelayedBundleApplication residualRoot = Iterables.getOnlyElement(splitListener.getResidualRoots());
        assertEquals(ParDoTranslation.getMainInputName(pTransform), primaryRoot.getInputId());
        assertEquals(TEST_TRANSFORM_ID, primaryRoot.getTransformId());
        assertEquals(ParDoTranslation.getMainInputName(pTransform), residualRoot.getApplication().getInputId());
        assertEquals(TEST_TRANSFORM_ID, residualRoot.getApplication().getTransformId());
        assertEquals(valueInGlobalWindow(KV.of(KV.of("5", KV.of(new OffsetRange(5, 8), GlobalWindow.TIMESTAMP_MIN_VALUE)), 3.0)), inputCoder.decode(primaryRoot.getElement().newInput()));
        assertEquals(valueInGlobalWindow(KV.of(KV.of("5", KV.of(new OffsetRange(8, 10), GlobalWindow.TIMESTAMP_MIN_VALUE.plus(Duration.millis(7)))), 2.0)), inputCoder.decode(residualRoot.getApplication().getElement().newInput()));
        Instant expectedOutputWatermark = GlobalWindow.TIMESTAMP_MIN_VALUE.plus(Duration.millis(7));
        assertEquals(ImmutableMap.of("output", org.apache.beam.vendor.grpc.v1p69p0.com.google.protobuf.Timestamp.newBuilder().setSeconds(expectedOutputWatermark.getMillis() / 1000).setNanos((int) (expectedOutputWatermark.getMillis() % 1000) * 1000000).build()), residualRoot.getApplication().getOutputWatermarksMap());
        assertEquals(org.apache.beam.vendor.grpc.v1p69p0.com.google.protobuf.Duration.newBuilder().setSeconds(54).setNanos(321000000).build(), residualRoot.getRequestedTimeDelay());
        splitListener.clear();
        // Check that before processing an element we don't report progress
        assertNoReportedProgress(context.getBundleProgressReporters());
        mainInput.accept(valueInGlobalWindow(KV.of(KV.of("2", KV.of(new OffsetRange(0, 2), GlobalWindow.TIMESTAMP_MIN_VALUE)), 2.0)));
        // Check that after processing an element we don't report progress
        assertNoReportedProgress(context.getBundleProgressReporters());
        assertThat(mainOutputValues, contains(timestampedValueInGlobalWindow("5:5", GlobalWindow.TIMESTAMP_MIN_VALUE.plus(Duration.millis(5))), timestampedValueInGlobalWindow("5:6", GlobalWindow.TIMESTAMP_MIN_VALUE.plus(Duration.millis(6))), timestampedValueInGlobalWindow("5:7", GlobalWindow.TIMESTAMP_MIN_VALUE.plus(Duration.millis(7))), timestampedValueInGlobalWindow("2:0", GlobalWindow.TIMESTAMP_MIN_VALUE.plus(Duration.millis(0))), timestampedValueInGlobalWindow("2:1", GlobalWindow.TIMESTAMP_MIN_VALUE.plus(Duration.millis(1)))));
        assertTrue(splitListener.getPrimaryRoots().isEmpty());
        assertTrue(splitListener.getResidualRoots().isEmpty());
        mainOutputValues.clear();
    }
    {
        // Setup and launch the trySplit thread.
        ExecutorService executorService = Executors.newSingleThreadExecutor();
        Future<HandlesSplits.SplitResult> trySplitFuture = executorService.submit(() -> {
            try {
                doFn.waitForSplitElementToBeProcessed();
                // Currently processing "3" out of range [0, 5) elements.
                assertEquals(0.6, ((HandlesSplits) mainInput).getProgress(), 0.01);
                // Check that during progressing of an element we report progress
                assertReportedProgressEquals(context.getShortIdMap(), context.getBundleProgressReporters(), 3.0, 2.0);
                return ((HandlesSplits) mainInput).trySplit(0);
            } finally {
                doFn.trySplitPerformed();
            }
        });
        // Check that before processing an element we don't report progress
        assertNoReportedProgress(context.getBundleProgressReporters());
        mainInput.accept(valueInGlobalWindow(KV.of(KV.of("7", KV.of(new OffsetRange(0, 5), GlobalWindow.TIMESTAMP_MIN_VALUE)), 2.0)));
        HandlesSplits.SplitResult trySplitResult = trySplitFuture.get();
        // Check that after processing an element we don't report progress
        assertNoReportedProgress(context.getBundleProgressReporters());
        // Since the SPLIT_ELEMENT is 3 we will process 0, 1, 2, 3 then be split.
        // We expect that the watermark advances to MIN + 2 since the manual watermark estimator
        // has yet to be invoked for the split element and that the primary represents [0, 4) with
        // the original watermark while the residual represents [4, 5) with the new MIN + 2
        // watermark.
        assertThat(mainOutputValues, contains(timestampedValueInGlobalWindow("7:0", GlobalWindow.TIMESTAMP_MIN_VALUE.plus(Duration.millis(0))), timestampedValueInGlobalWindow("7:1", GlobalWindow.TIMESTAMP_MIN_VALUE.plus(Duration.millis(1))), timestampedValueInGlobalWindow("7:2", GlobalWindow.TIMESTAMP_MIN_VALUE.plus(Duration.millis(2))), timestampedValueInGlobalWindow("7:3", GlobalWindow.TIMESTAMP_MIN_VALUE.plus(Duration.millis(3)))));
        BundleApplication primaryRoot = Iterables.getOnlyElement(trySplitResult.getPrimaryRoots());
        DelayedBundleApplication residualRoot = Iterables.getOnlyElement(trySplitResult.getResidualRoots());
        assertEquals(ParDoTranslation.getMainInputName(pTransform), primaryRoot.getInputId());
        assertEquals(TEST_TRANSFORM_ID, primaryRoot.getTransformId());
        assertEquals(ParDoTranslation.getMainInputName(pTransform), residualRoot.getApplication().getInputId());
        assertEquals(TEST_TRANSFORM_ID, residualRoot.getApplication().getTransformId());
        assertEquals(valueInGlobalWindow(KV.of(KV.of("7", KV.of(new OffsetRange(0, 4), GlobalWindow.TIMESTAMP_MIN_VALUE)), 4.0)), inputCoder.decode(primaryRoot.getElement().newInput()));
        assertEquals(valueInGlobalWindow(KV.of(KV.of("7", KV.of(new OffsetRange(4, 5), GlobalWindow.TIMESTAMP_MIN_VALUE.plus(Duration.millis(2)))), 1.0)), inputCoder.decode(residualRoot.getApplication().getElement().newInput()));
        Instant expectedOutputWatermark = GlobalWindow.TIMESTAMP_MIN_VALUE.plus(Duration.millis(2));
        assertEquals(ImmutableMap.of("output", org.apache.beam.vendor.grpc.v1p69p0.com.google.protobuf.Timestamp.newBuilder().setSeconds(expectedOutputWatermark.getMillis() / 1000).setNanos((int) (expectedOutputWatermark.getMillis() % 1000) * 1000000).build()), residualRoot.getApplication().getOutputWatermarksMap());
        // We expect 0 resume delay.
        assertEquals(residualRoot.getRequestedTimeDelay().getDefaultInstanceForType(), residualRoot.getRequestedTimeDelay());
        // We don't expect the outputs to goto the SDK initiated checkpointing listener.
        assertTrue(splitListener.getPrimaryRoots().isEmpty());
        assertTrue(splitListener.getResidualRoots().isEmpty());
        mainOutputValues.clear();
        executorService.shutdown();
    }
    Iterables.getOnlyElement(context.getFinishBundleFunctions()).run();
    assertThat(mainOutputValues, empty());
    Iterables.getOnlyElement(context.getTearDownFunctions()).run();
    assertThat(mainOutputValues, empty());
    // Assert that state data did not change
    assertEquals(new FakeBeamFnStateClient(StringUtf8Coder.of(), stateData).getData(), fakeClient.getData());
}

