@Test
public void testCombiningGroupingTableEmitsCorrectValuesUnderHighCacheContention() throws Exception {
    Long[] expectedKeys = new Long[1000];
    for (int j = 1; j <= 1000; ++j) {
        expectedKeys[j - 1] = (long) j;
    }
    int numThreads = 1000;
    List<Future<?>> futures = new ArrayList<>(numThreads);
    PipelineOptions options = PipelineOptionsFactory.create();
    GlobalCombineFnRunner<Integer, Long, Long> combineFnRunner = GlobalCombineFnRunners.create(COMBINE_FN);
    Cache<Object, Object> cache = Caches.forMaximumBytes(numThreads * 50000);
    for (int i = 0; i < numThreads; ++i) {
        final int currentI = i;
        futures.add(executorService.submit(() -> {
            ArrayListMultimap<Long, Long> values = ArrayListMultimap.create();
            PrecombineGroupingTable<Long, Integer, Long> table = new PrecombineGroupingTable<>(options, Caches.subCache(cache, currentI), VarLongCoder.of(), combineFnRunner, new TestSizeEstimator(), false);
            for (int j = 1; j <= 1000; ++j) {
                table.put(valueInGlobalWindow(KV.of((long) j, j)), (input) -> values.put(input.getValue().getKey(), input.getValue().getValue()));
            }
            for (int j = 1; j <= 1000; ++j) {
                table.flush((input) -> values.put(input.getValue().getKey(), input.getValue().getValue()));
            }
            assertThat(values.keySet(), containsInAnyOrder(expectedKeys));
            for (Map.Entry<Long, Long> value : values.entries()) {
                if (value.getKey() % 2 == 0) {
                    assertThat(value.getValue(), equalTo(value.getKey() / 4));
                } else {
                    assertThat(value.getValue(), equalTo(value.getKey()));
                }
            }
            return null;
        }));
    }
    for (Future<?> future : futures) {
        future.get();
    }
}

