    String expandedTransformId = Iterables.find(pProto.getComponents().getTransformsMap().entrySet(), entry -> entry.getValue().getSpec().getUrn().equals(PTransformTranslation.SPLITTABLE_TRUNCATE_SIZED_RESTRICTION_URN) && entry.getValue().getUniqueName().contains(TEST_TRANSFORM_ID)).getKey();
    RunnerApi.PTransform pTransform = pProto.getComponents().getTransformsOrThrow(expandedTransformId);
    String inputPCollectionId = pTransform.getInputsOrThrow(ParDoTranslation.getMainInputName(pTransform));
    RunnerApi.PCollection inputPCollection = pProto.getComponents().getPcollectionsOrThrow(inputPCollectionId);
    RehydratedComponents rehydratedComponents = RehydratedComponents.forComponents(pProto.getComponents());
    Coder<WindowedValue> inputCoder = WindowedValues.getFullCoder(CoderTranslation.fromProto(pProto.getComponents().getCodersOrThrow(inputPCollection.getCoderId()), rehydratedComponents, TranslationContext.DEFAULT), (Coder) CoderTranslation.fromProto(pProto.getComponents().getCodersOrThrow(pProto.getComponents().getWindowingStrategiesOrThrow(inputPCollection.getWindowingStrategyId()).getWindowCoderId()), rehydratedComponents, TranslationContext.DEFAULT));
    String outputPCollectionId = Iterables.getOnlyElement(pTransform.getOutputsMap().values());
    FakeBeamFnStateClient fakeClient = new FakeBeamFnStateClient(StringUtf8Coder.of(), ImmutableMap.of());
    PTransformRunnerFactoryTestContext context = PTransformRunnerFactoryTestContext.builder(TEST_TRANSFORM_ID, pTransform).beamFnStateClient(fakeClient).processBundleInstructionId("57").// .pCollections(pProto.getComponentsOrBuilder().getPcollectionsMap())
    components(RunnerApi.Components.newBuilder().putAllCoders(pProto.getComponents().getCodersMap()).putAllWindowingStrategies(pProto.getComponents().getWindowingStrategiesMap()).putAllEnvironments(Collections.emptyMap()).putAllPcollections(pProto.getComponentsOrBuilder().getPcollectionsMap()).build()).// .coders(pProto.getComponents().getCodersMap())
    // .windowingStrategies(pProto.getComponents().getWindowingStrategiesMap())
    build();
    List<WindowedValue<KV<KV<String, OffsetRange>, Double>>> mainOutputValues = new ArrayList<>();
    context.addPCollectionConsumer(outputPCollectionId, (FnDataReceiver) new SplittableFnDataReceiver(mainOutputValues));
    new SplittableTruncateSizedRestrictionsDoFnRunner.Factory().addRunnerForPTransform(context);
    FnDataReceiver<WindowedValue<?>> mainInput = context.getPCollectionConsumer(inputPCollectionId);
    assertThat(mainInput, instanceOf(HandlesSplits.class));
    mainOutputValues.clear();
    BoundedWindow window1 = new IntervalWindow(new Instant(5), new Instant(10));
    BoundedWindow window2 = new IntervalWindow(new Instant(6), new Instant(11));
    BoundedWindow window3 = new IntervalWindow(new Instant(7), new Instant(12));
    // Setup and launch the trySplit thread.
    ExecutorService executorService = Executors.newSingleThreadExecutor();
    Future<SplitResult> trySplitFuture = executorService.submit(() -> {
        try {
            doFn.waitForSplitElementToBeProcessed();
            SplitResult result = ((HandlesSplits) mainInput).trySplit(0);
            Assert.assertNotNull(result);
            return result;
        } finally {
            doFn.trySplitPerformed();
        }
    });
    WindowedValue<?> splitValue = valueInWindows(KV.of(KV.of("7", KV.of(new OffsetRange(0, 6), GlobalWindow.TIMESTAMP_MIN_VALUE)), 6.0), window1, window2, window3);
    mainInput.accept(splitValue);
    SplitResult trySplitResult = trySplitFuture.get();
    // We expect that there are outputs from window1 and window2
    assertThat(mainOutputValues, contains(WindowedValues.of(KV.of(KV.of("7", KV.of(new OffsetRange(0, 3), GlobalWindow.TIMESTAMP_MIN_VALUE)), 3.0), splitValue.getTimestamp(), window1, splitValue.getPaneInfo()), WindowedValues.of(KV.of(KV.of("7", KV.of(new OffsetRange(0, 3), GlobalWindow.TIMESTAMP_MIN_VALUE)), 3.0), splitValue.getTimestamp(), window2, splitValue.getPaneInfo())));
    SplitResult expectedElementSplit = createSplitResult(0);
    BundleApplication expectedElementSplitPrimary = Iterables.getOnlyElement(expectedElementSplit.getPrimaryRoots());
    ByteStringOutputStream primaryBytes = new ByteStringOutputStream();
    inputCoder.encode(WindowedValues.of(KV.of(KV.of("7", KV.of(new OffsetRange(0, 6), GlobalWindow.TIMESTAMP_MIN_VALUE)), 6.0), splitValue.getTimestamp(), window1, splitValue.getPaneInfo()), primaryBytes);
    BundleApplication expectedWindowedPrimary = BundleApplication.newBuilder().setElement(primaryBytes.toByteString()).setInputId(ParDoTranslation.getMainInputName(pTransform)).setTransformId(TEST_TRANSFORM_ID).build();
    DelayedBundleApplication expectedElementSplitResidual = Iterables.getOnlyElement(expectedElementSplit.getResidualRoots());
    ByteStringOutputStream residualBytes = new ByteStringOutputStream();
    inputCoder.encode(WindowedValues.of(KV.of(KV.of("7", KV.of(new OffsetRange(0, 6), GlobalWindow.TIMESTAMP_MIN_VALUE)), 6.0), splitValue.getTimestamp(), window3, splitValue.getPaneInfo()), residualBytes);
    DelayedBundleApplication expectedWindowedResidual = DelayedBundleApplication.newBuilder().setApplication(BundleApplication.newBuilder().setElement(residualBytes.toByteString()).setInputId(ParDoTranslation.getMainInputName(pTransform)).setTransformId(TEST_TRANSFORM_ID).build()).build();
    assertThat(trySplitResult.getPrimaryRoots(), containsInAnyOrder(expectedWindowedPrimary, expectedElementSplitPrimary));
    assertThat(trySplitResult.getResidualRoots(), containsInAnyOrder(expectedWindowedResidual, expectedElementSplitResidual));
}

