    FakeBeamFnStateClient fakeClient = new FakeBeamFnStateClient(ImmutableMap.of(createMultimapKeyStateKey(), KV.of(ByteArrayCoder.of(), singletonList(A1)), createMultimapValueStateKey(A1), KV.of(StringUtf8Coder.of(), asList("V1", "V2"))));
    Cache<?, ?> cache = Caches.eternal();
    {
        // First user state populates the cache.
        MultimapUserState<byte[], String> userState = new MultimapUserState<>(cache, fakeClient, "instructionId", createMultimapKeyStateKey(), ByteArrayCoder.of(), StringUtf8Coder.of());
        userState.put(A2, "V1");
        userState.put(A3, "V1");
        assertThat(Iterables.toArray(userState.keys(), byte[].class), is(arrayContainingInAnyOrder(A1, A2, A3)));
        userState.asyncClose();
    }
    {
        // The next user state will load all of its contents from the cache including the mutations
        // persisted via asyncClose.
        MultimapUserState<byte[], String> userState = new MultimapUserState<>(cache, requestBuilder -> {
            throw new IllegalStateException("Unexpected call for test.");
        }, "instructionId", createMultimapKeyStateKey(), ByteArrayCoder.of(), StringUtf8Coder.of());
        assertThat(Iterables.toArray(userState.keys(), byte[].class), is(arrayContainingInAnyOrder(A1, A2, A3)));
        userState.asyncClose();
    }
}

@Test
public void testPutCached() throws Exception {
    FakeBeamFnStateClient fakeClient = new FakeBeamFnStateClient(ImmutableMap.of(createMultimapKeyStateKey(), KV.of(ByteArrayCoder.of(), singletonList(A1)), createMultimapValueStateKey(A1), KV.of(StringUtf8Coder.of(), asList("V1", "V2"))));
    Cache<?, ?> cache = Caches.eternal();
    {
        // First user state populates the cache.
        MultimapUserState<byte[], String> userState = new MultimapUserState<>(cache, fakeClient, "instructionId", createMultimapKeyStateKey(), ByteArrayCoder.of(), StringUtf8Coder.of());
        userState.put(A1, "V3");
        userState.put(A2, "V1");
        assertArrayEquals(new String[] { "V1", "V2", "V3" }, Iterables.toArray(userState.get(A1), String.class));
        userState.asyncClose();
    }
    {
        // The next user state will load all of its contents from the cache including the mutations
        // persisted via asyncClose except for A2 since it was never loaded so the mutation is
        // discarded.
        int callCount = fakeClient.getCallCount();
        MultimapUserState<byte[], String> userState = new MultimapUserState<>(cache, fakeClient, "instructionId", createMultimapKeyStateKey(), ByteArrayCoder.of(), StringUtf8Coder.of());
        assertArrayEquals(new String[] { "V1", "V2", "V3" }, Iterables.toArray(userState.get(A1), String.class));
        assertEquals(callCount, fakeClient.getCallCount());
        // We expect one call when loading A2 since the append would have been discarded since the
        // key was never fully loaded.
        assertArrayEquals(new String[] { "V1" }, Iterables.toArray(userState.get(A2), String.class));
        assertEquals(callCount + 1, fakeClient.getCallCount());
        userState.asyncClose();
    }
}

