@Test
public void testReadRange() throws Exception {
    FakeBeamFnStateClient fakeClient = new FakeBeamFnStateClient(timestampedValueCoder, ImmutableMap.of(createOrderedListStateKey("A", 1), asList(A1, B1), createOrderedListStateKey("A", 4), Collections.singletonList(A4), createOrderedListStateKey("A", 2), Collections.singletonList(A2)));
    OrderedListUserState<String> userState = new OrderedListUserState<>(Caches.noop(), fakeClient, "instructionId", createOrderedListStateKey("A"), StringUtf8Coder.of());
    Iterable<TimestampedValue<String>> stateBeforeB2 = userState.readRange(Instant.ofEpochMilli(2), Instant.ofEpochMilli(4));
    assertArrayEquals(Collections.singletonList(A2).toArray(), Iterables.toArray(stateBeforeB2, TimestampedValue.class));
    // Add a new value to an existing sort key
    userState.add(B2);
    assertArrayEquals(Collections.singletonList(A2).toArray(), Iterables.toArray(stateBeforeB2, TimestampedValue.class));
    assertArrayEquals(asList(A2, B2).toArray(), Iterables.toArray(userState.readRange(Instant.ofEpochMilli(2), Instant.ofEpochMilli(4)), TimestampedValue.class));
    // Add a new value to a new sort key
    userState.add(A3);
    assertArrayEquals(Collections.singletonList(A2).toArray(), Iterables.toArray(stateBeforeB2, TimestampedValue.class));
    assertArrayEquals(asList(A2, B2, A3).toArray(), Iterables.toArray(userState.readRange(Instant.ofEpochMilli(2), Instant.ofEpochMilli(4)), TimestampedValue.class));
    userState.asyncClose();
    assertThrows(IllegalStateException.class, () -> userState.readRange(Instant.ofEpochMilli(1), Instant.ofEpochMilli(2)));
}

