@Test
public void testAddAndClearRange() throws Exception {
    FakeBeamFnStateClient fakeClient = new FakeBeamFnStateClient(timestampedValueCoder, ImmutableMap.of(createOrderedListStateKey("A", 1), Collections.singletonList(A1), createOrderedListStateKey("A", 3), Collections.singletonList(A3), createOrderedListStateKey("A", 4), Collections.singletonList(A4)));
    OrderedListUserState<String> userState = new OrderedListUserState<>(Caches.noop(), fakeClient, "instructionId", createOrderedListStateKey("A"), StringUtf8Coder.of());
    // add to a non-existing timestamp, clear, and then add
    userState.add(A2);
    Iterable<TimestampedValue<String>> stateBeforeFirstClearRange = userState.read();
    userState.clearRange(Instant.ofEpochMilli(2), Instant.ofEpochMilli(3));
    assertArrayEquals(asList(A1, A2, A3, A4).toArray(), Iterables.toArray(stateBeforeFirstClearRange, TimestampedValue.class));
    assertArrayEquals(asList(A1, A3, A4).toArray(), Iterables.toArray(userState.read(), TimestampedValue.class));
    userState.add(B2);
    assertArrayEquals(asList(A1, A2, A3, A4).toArray(), Iterables.toArray(stateBeforeFirstClearRange, TimestampedValue.class));
    assertArrayEquals(asList(A1, B2, A3, A4).toArray(), Iterables.toArray(userState.read(), TimestampedValue.class));
    // add to an existing timestamp, clear, and then add
    userState.add(B1);
    userState.clearRange(Instant.ofEpochMilli(1), Instant.ofEpochMilli(2));
    assertArrayEquals(asList(A1, A2, A3, A4).toArray(), Iterables.toArray(stateBeforeFirstClearRange, TimestampedValue.class));
    assertArrayEquals(asList(B2, A3, A4).toArray(), Iterables.toArray(userState.read(), TimestampedValue.class));
    userState.add(B1);
    assertArrayEquals(asList(A1, A2, A3, A4).toArray(), Iterables.toArray(stateBeforeFirstClearRange, TimestampedValue.class));
    assertArrayEquals(asList(B1, B2, A3, A4).toArray(), Iterables.toArray(userState.read(), TimestampedValue.class));
    // add a duplicated value, clear, and then add
    userState.add(A3);
    userState.clearRange(Instant.ofEpochMilli(3), Instant.ofEpochMilli(4));
    assertArrayEquals(asList(A1, A2, A3, A4).toArray(), Iterables.toArray(stateBeforeFirstClearRange, TimestampedValue.class));
    assertArrayEquals(asList(B1, B2, A4).toArray(), Iterables.toArray(userState.read(), TimestampedValue.class));
    userState.add(A3);
    assertArrayEquals(asList(A1, A2, A3, A4).toArray(), Iterables.toArray(stateBeforeFirstClearRange, TimestampedValue.class));
    assertArrayEquals(asList(B1, B2, A3, A4).toArray(), Iterables.toArray(userState.read(), TimestampedValue.class));
}

