@Test
public void testUsingInterleavedReiteration() throws Exception {
    FakeBeamFnStateClient fakeBeamFnStateClient = new FakeBeamFnStateClient(StringUtf8Coder.of(), ImmutableMap.of(key("nonEmptySuffix"), asList("C", "D", "E", "F", "G", "H", "I", "J", "K"), key("emptySuffix"), asList()));
    StateBackedIterable<String> iterable = new StateBackedIterable<>(Caches.noop(), fakeBeamFnStateClient, "instruction", key(suffixKey), StringUtf8Coder.of(), prefix);
    List<Iterator<String>> iterators = new ArrayList<>();
    List<List<String>> results = new ArrayList<>();
    for (int i = 0; i < 3; ++i) {
        iterators.add(iterable.iterator());
        results.add(new ArrayList<>());
    }
    Random random = new Random(42L);
    while (!iterators.isEmpty()) {
        int current = random.nextInt(iterators.size());
        if (!iterators.get(current).hasNext()) {
            iterators.remove(current);
            assertEquals(expected, results.remove(current));
        } else {
            results.get(current).add(iterators.get(current).next());
        }
    }
}

@Test
public void testByteObservingStateBackedIterable() throws Exception {
    FakeBeamFnStateClient fakeBeamFnStateClient = new FakeBeamFnStateClient(StringUtf8Coder.of(), ImmutableMap.of(key("nonEmptySuffix"), asList("C", "D", "E", "F", "G", "H", "I", "J", "K"), key("emptySuffix"), asList()));
    StateBackedIterable<String> iterable = new StateBackedIterable<>(Caches.noop(), fakeBeamFnStateClient, "instruction", key(suffixKey), StringUtf8Coder.of(), prefix);
    StateBackedIterable.Coder<String> coder = new StateBackedIterable.Coder<>(() -> Caches.noop(), fakeBeamFnStateClient, () -> "instructionId", StringUtf8Coder.of());
    assertTrue(coder.isRegisterByteSizeObserverCheap(iterable));
    TestByteObserver observer = new TestByteObserver();
    coder.registerByteSizeObserver(iterable, observer);
    assertTrue(observer.getIsLazy());
    long iterateBytes = Streams.stream(iterable).mapToLong(s -> {
        try {
            // 1 comes from hasNext = true flag (see IterableLikeCoder)
            return 1 + StringUtf8Coder.of().getEncodedElementByteSize(s);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }).sum();
    observer.advance();
    // 5 comes from size and hasNext (see IterableLikeCoder)
    // observer receives scaled, StringUtf8Coder is not cheap so sampling may produce value that
    // is off
    assertEquals((float) iterateBytes + 5, (float) observer.total, 3);
}

