@Test
public void testWritePutItemsWithDuplicates() {
    List<Item> items = Item.range(0, 100);
    Supplier<List<List<Item>>> captureRequests = captureBatchWriteRequests(client, req -> req.putRequest().item());
    pipeline.apply(Create.of(items)).// generate identical duplicates
    apply(ParDo.of(new AddDuplicatesDoFn(3, false))).apply(DynamoDBIO.<Item>write().withWriteRequestMapperFn(putRequestMapper));
    pipeline.run().waitUntilFinish();
    List<List<Item>> requests = captureRequests.get();
    for (List<Item> reqItems : requests) {
