@Test
public void testAggregationCompatibilityWithKcl() {
    LongStream.range(0, 1000).forEach(n -> aggregator.addRecord(PARTITION_KEY, HASH_KEY, getBytes(n)));
    byte[] aggBytes = aggregator.toBytes();
    KinesisClientRecord aggRecord = recordBuilder(aggBytes).build();
    List<KinesisClientRecord> expectedRecords = LongStream.range(0, 1000).mapToObj(n -> recordBuilder(getBytes(n)).aggregated(true).subSequenceNumber(n).build()).collect(toList());
    List<KinesisClientRecord> records = new AggregatorUtil().deaggregate(ImmutableList.of(aggRecord));
    assertThat(records).hasSize(1000);
