public void poolWatermarkReturnsTsOfOldestAcknowledgedRecord() throws TransientKinesisException {
    KinesisReaderCheckpoint initialCheckpoint = new KinesisReaderCheckpoint(ImmutableList.of(new ShardCheckpoint(STREAM, "0", ShardIteratorType.TRIM_HORIZON, null, null), new ShardCheckpoint(STREAM, "1", ShardIteratorType.TRIM_HORIZON, null, null)));
