}

@Test
public void testResolve() {
    for (TestCase testCase : PATH_TEST_CASES) {
        ResourceId resourceId = S3ResourceId.fromUri(testCase.baseUri);
        ResourceId resolved = resourceId.resolve(testCase.relativePath, testCase.resolveOptions);
        assertEquals(testCase.expectedResult, resolved.toString());
    }
    // Tests for common s3 paths.
    assertEquals(S3ResourceId.fromUri("s3://bucket/tmp/aa"), S3ResourceId.fromUri("s3://bucket/tmp/").resolve("aa", RESOLVE_FILE));
    assertEquals(S3ResourceId.fromUri("s3://bucket/tmp/aa/bb/cc/"), S3ResourceId.fromUri("s3://bucket/tmp/").resolve("aa", RESOLVE_DIRECTORY).resolve("bb", RESOLVE_DIRECTORY).resolve("cc", RESOLVE_DIRECTORY));
    // Tests absolute path.
    assertEquals(S3ResourceId.fromUri("s3://bucket/tmp/aa"), S3ResourceId.fromUri("s3://bucket/tmp/bb/").resolve("s3://bucket/tmp/aa", RESOLVE_FILE));
    // Tests bucket with no ending '/'.
    assertEquals(S3ResourceId.fromUri("s3://my-bucket/tmp"), S3ResourceId.fromUri("s3://my-bucket").resolve("tmp", RESOLVE_FILE));
    // Tests path with unicode
    assertEquals(S3ResourceId.fromUri("s3://bucket/输出 目录/输出 文件01.txt"), S3ResourceId.fromUri("s3://bucket/输出 目录/").resolve("输出 文件01.txt", RESOLVE_FILE));
}

