@Test
public void testReadOnce() {
    List<Message> expected = range(0, 10).mapToObj(this::message).collect(toList());
    when(sqs.receiveMessage(any(ReceiveMessageRequest.class))).thenReturn(ReceiveMessageResponse.builder().messages(expected).build(), ReceiveMessageResponse.builder().build());
    ArgumentCaptor<DeleteMessageBatchRequest> deleteReq = ArgumentCaptor.forClass(DeleteMessageBatchRequest.class);
    when(sqs.deleteMessageBatch(deleteReq.capture())).thenReturn(DeleteMessageBatchResponse.builder().build());
    SqsReadSchemaTransformProvider provider = new SqsReadSchemaTransformProvider();
    Row readConfig = Row.withSchema(provider.configurationSchema()).withFieldValue("queue_url", "https://somedummy.url").withFieldValue("max_read_time_secs", 10L).build();
    PCollection<Message> result = PCollectionRowTuple.empty(p).apply(provider.from(readConfig)).get(SqsReadSchemaTransformProvider.OUTPUT_TAG).apply(ParDo.of(new ToMessage()));
    // all expected messages are read
    PAssert.that(result).containsInAnyOrder(expected);
    p.run();
}

@Test
public void testReadOnce() {
    List<Message> expected = range(0, 10).mapToObj(this::message).collect(toList());
    when(sqs.receiveMessage(any(ReceiveMessageRequest.class))).thenReturn(ReceiveMessageResponse.builder().messages(expected).build(), ReceiveMessageResponse.builder().build());
    ArgumentCaptor<DeleteMessageBatchRequest> deleteReq = ArgumentCaptor.forClass(DeleteMessageBatchRequest.class);
    when(sqs.deleteMessageBatch(deleteReq.capture())).thenReturn(DeleteMessageBatchResponse.builder().build());
    PCollection<Message> result = p.apply(SqsIO.read().withMaxNumRecords(expected.size())).apply(ParDo.of(new ToMessage()));
    // all expected messages are read
    PAssert.that(result).containsInAnyOrder(expected);
    p.run();
    List<String> deletedHandles = deleteReq.getAllValues().stream().flatMap(b -> b.entries().stream()).map(r -> r.receiptHandle()).collect(toList());
    // all messages are deleted
    assertThat(deletedHandles).containsExactlyInAnyOrderElementsOf(Lists.transform(expected, Message::receiptHandle));
}

