@Test
public void testWriteBatchesToDynamicWithStrictTimeoutAtHighVolume() {
    when(sqs.sendMessageBatch(any(SendMessageBatchRequest.class))).thenReturn(completedFuture(SendMessageBatchResponse.builder().build()));
    // Use sqrt to change the rate of newly created dynamic destinations over time
    DynamicDestination<String> dynamicDestination = msg -> String.valueOf(RandomUtils.nextInt(0, (int) (1 + sqrt(Integer.valueOf(msg)))));
    p.apply(Create.of(100000)).apply(ParDo.of(new CreateMessages())).apply(SqsIO.<String>writeBatches().withEntryMapper(SET_MESSAGE_BODY).withBatchTimeout(millis(10), true).to(dynamicDestination));
    p.run().waitUntilFinish();
    ArgumentCaptor<SendMessageBatchRequest> reqCaptor = ArgumentCaptor.forClass(SendMessageBatchRequest.class);
    verify(sqs, atLeastOnce()).sendMessageBatch(reqCaptor.capture());
    Set<String> capturedMessages = new HashSet<>();
    for (SendMessageBatchRequest req : reqCaptor.getAllValues()) {
        for (SendMessageBatchRequestEntry entry : req.entries()) {
            assertTrue("duplicate message", capturedMessages.add(entry.messageBody()));
        }
    }
    assertEquals("Invalid message count", 100000, capturedMessages.size());
}

