    PipelineResult writeResult = writePipeline.run();
    writeResult.waitUntilFinish();
    PCollection<String> consolidatedHashcode = readPipeline.apply("Read using CdapIO", readFromDB(getReadTestParamsFromOptions(options))).apply("Collect read time", ParDo.of(new TimeMonitor<>(NAMESPACE, "read_time"))).apply("Get values only", Values.create()).apply("Values as string", ParDo.of(new TestRow.SelectNameFn())).apply("Calculate hashcode", Combine.globally(new HashingFn()));
    PAssert.thatSingleton(consolidatedHashcode).isEqualTo(getExpectedHashForRowCount(numberOfRows));
