@Test
public void headersWithCommentsWrittenFirstOnEachShard() {
    File folder = createFolder(AllPrimitiveDataTypes.class.getSimpleName(), "headersWithCommentsWrittenFirstOnEachShard");
    PCollection<Row> input = writePipeline.apply(Create.of(DATA.allPrimitiveDataTypeRows).withRowSchema(ALL_PRIMITIVE_DATA_TYPES_SCHEMA));
    String expectedHeader = "aBoolean,aDecimal,aDouble,aFloat,aLong,aString,anInteger";
    CSVFormat csvFormat = CSVFormat.DEFAULT.withHeaderComments("foo", "bar", "baz").withCommentMarker('#');
    input.apply(CsvIO.writeRows(toFilenamePrefix(folder), csvFormat).withNumShards(3));
    writePipeline.run().waitUntilFinish();
    PCollection<FileIO.ReadableFile> files = readPipeline.apply(FileIO.match().filepattern(toFilenamePrefix(folder) + "*")).apply(FileIO.readMatches());
    PAssert.that(files).satisfies((Iterable<FileIO.ReadableFile> itr) -> {
        Iterable<FileIO.ReadableFile> safeItr = requireNonNull(itr);
        for (FileIO.ReadableFile file : safeItr) {
            try {
                List<String> lines = Splitter.on('\n').splitToList(file.readFullyAsUTF8String());
                assertFalse(lines.isEmpty());
                assertEquals("# foo", lines.get(0));
                assertEquals("# bar", lines.get(1));
                assertEquals("# baz", lines.get(2));
                assertEquals(expectedHeader, lines.get(3));
                assertTrue(lines.subList(4, lines.size()).stream().noneMatch(expectedHeader::equals));
            } catch (IOException e) {
                fail(e.getMessage());
            }
        }
        return null;
    });
    readPipeline.run();
}

