    assertEquals("Schema has no fields", emptySchemaError.getMessage());
    IllegalArgumentException invalidArrayFieldsError = assertThrows(IllegalArgumentException.class, () -> CsvRowConversions.RowToCsv.builder().setCSVFormat(CSVFormat.DEFAULT.withHeader("instant", "instantList")).setSchema(TIME_CONTAINING_SCHEMA).build());
    assertEquals("columns in header match fields in Schema with invalid types: instantList. See CsvIO#VALID_FIELD_TYPE_SET for a list of valid field types.", invalidArrayFieldsError.getMessage());
    // Should not throw Exception when limited to valid fields.
    CsvRowConversions.RowToCsv.builder().setCSVFormat(CSVFormat.DEFAULT.withHeader("instant")).setSchema(TIME_CONTAINING_SCHEMA).build();
}

