@Test
public void testDebeziumSchemaTransformMysqlRead() throws InterruptedException {
    long writeSize = 500L;
    long testTime = writeSize * 200L;
    PipelineOptions options = PipelineOptionsFactory.create();
    Pipeline writePipeline = Pipeline.create(options);
    writePipeline.apply(GenerateSequence.from(0).to(writeSize).withRate(10, org.joda.time.Duration.standardSeconds(1))).apply(MapElements.into(TypeDescriptors.rows()).via(num -> Row.withSchema(TABLE_SCHEMA).withFieldValue("id", // We need this tricky conversion because the original "customers"
    // table already
    // contains rows 1001, 1002, 1003, 1004.
    num <= 1000 ? Long.valueOf(num).intValue() : Long.valueOf(num).intValue() + 4).withFieldValue("first_name", Long.toString(num)).withFieldValue("last_name", Long.toString(writeSize - num)).withFieldValue("email", Long.toString(num) + "@beamail.com").// TODO(pabloem): Add other data types
    build())).setRowSchema(TABLE_SCHEMA).apply(JdbcIO.<Row>write().withTable("inventory.customers").withDataSourceProviderFn(DebeziumIOMySqlConnectorIT::getMysqlDatasource));
    Pipeline readPipeline = Pipeline.create(options);
    PCollection<Row> result = PCollectionRowTuple.empty(readPipeline).apply(new DebeziumReadSchemaTransformProvider(true, Long.valueOf(writeSize).intValue() + 4, testTime).from(DebeziumReadSchemaTransformProvider.DebeziumReadSchemaTransformConfiguration.builder().setDatabase("MYSQL").setPassword("dbz").setUsername("debezium").setHost("localhost").setTable("inventory.customers").setPort(MY_SQL_CONTAINER.getMappedPort(3306)).setDebeziumConnectionProperties(Lists.newArrayList("database.server.id=1849055", "schema.history.internal.kafka.bootstrap.servers=" + KAFKA_CONTAINER.getBootstrapServers(), "schema.history.internal.kafka.topic=schema-history-mysql-transform-" + System.nanoTime(), "schema.history.internal=io.debezium.storage.kafka.history.KafkaSchemaHistory", "schema.history.internal.store.only.captured.tables.ddl=false", "table.include.list=inventory.customers", "snapshot.mode=initial_only")).build())).get("output");
    PAssert.that(result).satisfies(rows -> {
        assertThat(Lists.newArrayList(rows).size(), equalTo(Long.valueOf(writeSize + 4).intValue()));
        return null;
    });
    Thread writeThread = new Thread(() -> writePipeline.run().waitUntilFinish());
    Thread monitorThread = new Thread(() -> {
        try {
            monitorEssentialMetrics();
        } catch (SQLException e) {
            e.printStackTrace();
            fail("Failed because of SQLException in monitorEssentialMetrics!");
        }
    });
    monitorThread.start();
    writeThread.start();
    writeThread.join();
    LOG.info("Write thread for SchemaTransform test joined.");
    LOG.info("Starting read pipeline for SchemaTransform test...");
    readPipeline.run().waitUntilFinish();
    LOG.info("Read pipeline for SchemaTransform test finished.");
    monitorThread.interrupt();
    monitorThread.join();
    LOG.info("Monitor thread for SchemaTransform test joined.");
}

