@Test
public void testKafkaOffsetHolderEquality() {
    EqualsTester tester = new EqualsTester();
    HashMap<String, Integer> map = new HashMap<>();
    map.put("a", 1);
    map.put("b", 2);
    ArrayList<byte[]> list = new ArrayList<>();
    list.add("abc".getBytes(StandardCharsets.US_ASCII));
    list.add(new byte[0]);
    tester.addEqualityGroup(new OffsetHolder(ImmutableMap.of("a", 1, "b", 2), ImmutableList.of("abc".getBytes(StandardCharsets.US_ASCII), new byte[0]), 1, null, -1L), new OffsetHolder(map, list, 1, null, -1L), new OffsetHolder(map, list, 1, null, -1L), new OffsetHolder(map, list, 1));
    tester.addEqualityGroup(new OffsetHolder(null, null, null, null, null));
    tester.addEqualityGroup(new OffsetHolder(ImmutableMap.of("a", 1), ImmutableList.of("abc".getBytes(StandardCharsets.US_ASCII)), 1));
    tester.addEqualityGroup(new OffsetHolder(ImmutableMap.of("a", 1), ImmutableList.of("abc".getBytes(StandardCharsets.US_ASCII)), 2));
    tester.addEqualityGroup(new OffsetHolder(ImmutableMap.of("a", 1), ImmutableList.of("abc".getBytes(StandardCharsets.US_ASCII)), 1, 2, null));
    tester.addEqualityGroup(new OffsetHolder(ImmutableMap.of("a", 1), ImmutableList.of("abc".getBytes(StandardCharsets.US_ASCII)), 1, 3, null));
    tester.testEquals();
}

