@Test
public void testStreamingRead() {
    Schema schema = ALL_PRIMITIVE_DATA_TYPES_SCHEMA;
    List<Row> rows = DATA.allPrimitiveDataTypesRows;
    String folder = getFolder();
    ResourceId dir = FileSystems.matchNewResource(folder, true);
    org.apache.avro.Schema avroSchema = AvroUtils.toAvroSchema(schema);
    String stringSchema = avroSchema.toString();
    FileReadSchemaTransformConfiguration config = FileReadSchemaTransformConfiguration.builder().setFormat(getFormat()).setFilepattern(folder + "/test_*").setSchema(stringSchema).setPollIntervalMillis(100L).setTerminateAfterSecondsSinceNewOutput(3L).build();
    SchemaTransform readTransform = new FileReadSchemaTransformProvider().from(config);
    PCollectionRowTuple output = PCollectionRowTuple.empty(readPipeline).apply(readTransform);
    // Write to three different files (test_1..., test_2..., test_3)
    // All three new files should be picked up and read.
    readPipeline.apply(GenerateSequence.from(0).to(3).withRate(1, Duration.millis(300))).apply(Window.<Long>into(FixedWindows.of(Duration.millis(100))).withAllowedLateness(Duration.ZERO).triggering(Repeatedly.forever(AfterPane.elementCountAtLeast(1))).discardingFiredPanes()).apply(MapElements.via(new CreateAvroPrimitiveGenericRecord(schema))).setCoder(AvroCoder.of(avroSchema)).apply(AvroIO.writeGenericRecords(avroSchema).to(new TestDynamicDestinations(dir)).withTempDirectory(dir).withNumShards(1).withWindowedWrites());
    // Check output matches the expected rows
    PAssert.that(output.get(FileReadSchemaTransformProvider.OUTPUT_TAG)).containsInAnyOrder(rows);
    readPipeline.run();
}

