public void testWriteAndReadWithSchemaTransforms() {
    Schema schema = ALL_PRIMITIVE_DATA_TYPES_SCHEMA;
    List<Row> rows = DATA.allPrimitiveDataTypesRows;
    String folder = getFolder();
    FileWriteSchemaTransformConfiguration writeConfig = FileWriteSchemaTransformConfiguration.builder().setFormat(getFormat()).setFilenamePrefix(folder).build();
    if (getFormat().equals("parquet")) {
        writeConfig = writeConfig.toBuilder().setParquetConfiguration(parquetConfigurationBuilder().setCompressionCodecName(CompressionCodecName.GZIP.name()).build()).build();
    }
    FileReadSchemaTransformConfiguration readConfig = FileReadSchemaTransformConfiguration.builder().setFormat(getFormat()).setSchema(getStringSchemaFromBeamSchema(schema)).build();
    SchemaTransform writeTransform = new FileWriteSchemaTransformProvider().from(writeConfig);
    SchemaTransform readTransform = new FileReadSchemaTransformProvider().from(readConfig);
    Schema filePatternSchema = getFilepatternSchema();
    PCollection<Row> inputRows = writePipeline.apply(Create.of(rows).withRowSchema(schema));
    PCollection<Row> filePatterns = PCollectionRowTuple.of("input", inputRows).apply(writeTransform).get("output").setRowSchema(FileWriteSchemaTransformProvider.OUTPUT_SCHEMA).apply(MapElements.into(TypeDescriptors.rows()).via((Row row) -> {
        String file = row.getString("fileName");
        return Row.withSchema(filePatternSchema).withFieldValue(FILEPATTERN_ROW_FIELD_NAME, file).build();
    })).setRowSchema(filePatternSchema);
    PCollection<Row> outputRows = PCollectionRowTuple.of("input", filePatterns).apply(readTransform).get("output");
    if (getFormat().equals("json")) {
        rows = rows.stream().map(row -> JsonReadSchemaTransformFormatProviderTest.getExpectedRow(row)).collect(Collectors.toList());
    }
    PAssert.that(outputRows).containsInAnyOrder(rows);
    writePipeline.run().waitUntilFinish();
}

