@Test
public void withCompression() {
    String to = folder(AllPrimitiveDataTypes.class, "with_compression");
    Compression compression = Compression.GZIP;
    FileWriteSchemaTransformConfiguration configuration = buildConfiguration(to).toBuilder().setCompression(compression.name()).build();
    FileWriteSchemaTransformProvider provider = new FileWriteSchemaTransformProvider();
    if (expectedErrorWhenCompressionSet().isPresent()) {
        IllegalArgumentException invalidConfiguration = assertThrows(IllegalArgumentException.class, () -> provider.from(configuration));
        assertEquals(expectedErrorWhenCompressionSet().get(), invalidConfiguration.getMessage());
        return;
    }
    PCollection<String> files = applyProviderAndAssertFilesWritten(DATA.allPrimitiveDataTypesRows, ALL_PRIMITIVE_DATA_TYPES_SCHEMA, configuration);
    PCollection<String> extension = files.apply("extract extension", MapElements.into(strings()).via(fullName -> fullName != null ? Files.getFileExtension(fullName) : null)).apply("distinct extensions", Distinct.create());
    PCollection<Boolean> isCompressed = files.apply("isCompressed", MapElements.into(booleans()).via(filename -> filename != null && compression.isCompressed(filename))).apply("distinct isCompressed", Distinct.create());
    PAssert.thatSingleton("Filenames end with compression name", extension).isEqualTo("gz");
    PAssert.thatSingleton("Files should be compressed", isCompressed).isEqualTo(true);
    writePipeline.run();
}

