@Test
public void shardNameTemplateSetConfiguration() {
    String to = folder(AllPrimitiveDataTypes.class, "shard_name_template");
    String shardNameTemplate = "-SS-of-NN";
    FileWriteSchemaTransformConfiguration configuration = buildConfiguration(to).toBuilder().setShardNameTemplate(shardNameTemplate).build();
    if (expectedErrorWhenShardNameTemplateSet().isPresent()) {
        FileWriteSchemaTransformProvider provider = new FileWriteSchemaTransformProvider();
        IllegalArgumentException configurationError = assertThrows(IllegalArgumentException.class, () -> provider.from(configuration));
        assertEquals(expectedErrorWhenShardNameTemplateSet().get(), configurationError.getMessage());
        return;
    }
    PCollection<String> files = applyProviderAndAssertFilesWritten(DATA.allPrimitiveDataTypesRows, ALL_PRIMITIVE_DATA_TYPES_SCHEMA, configuration);
    PAssert.that("All file names match shard name template", files).satisfies((Iterable<String> names) -> {
