@Test
public void testDescriptorFromSchema() {
    DescriptorProto descriptor = TableRowToStorageApiProto.descriptorSchemaFromTableSchema(BeamRowToStorageApiProto.protoTableSchemaFromBeamSchema(BASE_SCHEMA), true, false);
    Map<String, Type> types = descriptor.getFieldList().stream().collect(Collectors.toMap(FieldDescriptorProto::getName, FieldDescriptorProto::getType));
    Map<String, Type> expectedTypes = BASE_SCHEMA_PROTO.getFieldList().stream().collect(Collectors.toMap(FieldDescriptorProto::getName, FieldDescriptorProto::getType));
    assertEquals(expectedTypes, types);
    Map<String, String> nameMapping = BASE_SCHEMA.getFields().stream().collect(Collectors.toMap(f -> f.getName().toLowerCase(), Field::getName));
    descriptor.getFieldList().forEach(p -> {
        FieldType schemaFieldType = BASE_SCHEMA.getField(nameMapping.get(p.getName())).getType();
        Label label = schemaFieldType.getTypeName().isCollectionType() ? Label.LABEL_REPEATED : schemaFieldType.getNullable() ? Label.LABEL_OPTIONAL : Label.LABEL_REQUIRED;
        assertEquals(label, p.getLabel());
    });
}

@Test
public void testNestedFromSchema() {
    DescriptorProto descriptor = TableRowToStorageApiProto.descriptorSchemaFromTableSchema(BeamRowToStorageApiProto.protoTableSchemaFromBeamSchema((NESTED_SCHEMA)), true, false);
    Map<String, Type> expectedBaseTypes = BASE_SCHEMA_PROTO.getFieldList().stream().collect(Collectors.toMap(FieldDescriptorProto::getName, FieldDescriptorProto::getType));
    Map<String, Type> types = descriptor.getFieldList().stream().collect(Collectors.toMap(FieldDescriptorProto::getName, FieldDescriptorProto::getType));
    Map<String, String> typeNames = descriptor.getFieldList().stream().collect(Collectors.toMap(FieldDescriptorProto::getName, FieldDescriptorProto::getTypeName));
    Map<String, Label> typeLabels = descriptor.getFieldList().stream().collect(Collectors.toMap(FieldDescriptorProto::getName, FieldDescriptorProto::getLabel));
    assertEquals(4, types.size());
    Map<String, DescriptorProto> nestedTypes = descriptor.getNestedTypeList().stream().collect(Collectors.toMap(DescriptorProto::getName, Functions.identity()));
    assertEquals(4, nestedTypes.size());
    assertEquals(Type.TYPE_MESSAGE, types.get("nested"));
    assertEquals(Label.LABEL_OPTIONAL, typeLabels.get("nested"));
    String nestedTypeName1 = typeNames.get("nested");
    Map<String, Type> nestedTypes1 = nestedTypes.get(nestedTypeName1).getFieldList().stream().collect(Collectors.toMap(FieldDescriptorProto::getName, FieldDescriptorProto::getType));
    assertEquals(expectedBaseTypes, nestedTypes1);
    assertEquals(Type.TYPE_MESSAGE, types.get("nestedarray"));
    assertEquals(Label.LABEL_REPEATED, typeLabels.get("nestedarray"));
    String nestedTypeName2 = typeNames.get("nestedarray");
    Map<String, Type> nestedTypes2 = nestedTypes.get(nestedTypeName2).getFieldList().stream().collect(Collectors.toMap(FieldDescriptorProto::getName, FieldDescriptorProto::getType));
    assertEquals(expectedBaseTypes, nestedTypes2);
    assertEquals(Type.TYPE_MESSAGE, types.get("nestediterable"));
    assertEquals(Label.LABEL_REPEATED, typeLabels.get("nestediterable"));
    String nestedTypeName3 = typeNames.get("nestediterable");
    Map<String, Type> nestedTypes3 = nestedTypes.get(nestedTypeName3).getFieldList().stream().collect(Collectors.toMap(FieldDescriptorProto::getName, FieldDescriptorProto::getType));
    assertEquals(expectedBaseTypes, nestedTypes3);
    assertEquals(Type.TYPE_MESSAGE, types.get("nestedmap"));
    assertEquals(Label.LABEL_REPEATED, typeLabels.get("nestedmap"));
    String nestedTypeName4 = typeNames.get("nestedmap");
    // expects 2 fields in the nested map, key and value
    assertEquals(2, nestedTypes.get(nestedTypeName4).getFieldList().size());
    Supplier<Stream<FieldDescriptorProto>> stream = () -> nestedTypes.get(nestedTypeName4).getFieldList().stream();
    assertTrue(stream.get().anyMatch(fdp -> fdp.getName().equals("key")));
    assertTrue(stream.get().anyMatch(fdp -> fdp.getName().equals("value")));
    Map<String, Type> nestedTypes4 = nestedTypes.get(nestedTypeName4).getNestedTypeList().stream().flatMap(vdesc -> vdesc.getFieldList().stream()).collect(Collectors.toMap(FieldDescriptorProto::getName, FieldDescriptorProto::getType));
    assertEquals(expectedBaseTypes, nestedTypes4);
}

@Test
public void testParticularMapsFromSchemas() {
    Schema nestedMapSchemaVariations = Schema.builder().addField("nestedMultiMap", FieldType.map(FieldType.STRING, FieldType.array(FieldType.STRING))).addField("nestedMapNullable", FieldType.map(FieldType.STRING, FieldType.DOUBLE).withNullable(true)).build();
    DescriptorProto descriptor = TableRowToStorageApiProto.descriptorSchemaFromTableSchema(BeamRowToStorageApiProto.protoTableSchemaFromBeamSchema((nestedMapSchemaVariations)), true, false);
    Map<String, Type> types = descriptor.getFieldList().stream().collect(Collectors.toMap(FieldDescriptorProto::getName, FieldDescriptorProto::getType));
    Map<String, String> typeNames = descriptor.getFieldList().stream().collect(Collectors.toMap(FieldDescriptorProto::getName, FieldDescriptorProto::getTypeName));
    Map<String, Label> typeLabels = descriptor.getFieldList().stream().collect(Collectors.toMap(FieldDescriptorProto::getName, FieldDescriptorProto::getLabel));
    Map<String, DescriptorProto> nestedTypes = descriptor.getNestedTypeList().stream().collect(Collectors.toMap(DescriptorProto::getName, Functions.identity()));
    assertEquals(2, nestedTypes.size());
    assertEquals(Type.TYPE_MESSAGE, types.get("nestedmultimap"));
    assertEquals(Label.LABEL_REPEATED, typeLabels.get("nestedmultimap"));
    String nestedMultiMapName = typeNames.get("nestedmultimap");
    // expects 2 fields for the nested array of maps, key and value
    assertEquals(2, nestedTypes.get(nestedMultiMapName).getFieldList().size());
    Supplier<Stream<FieldDescriptorProto>> stream = () -> nestedTypes.get(nestedMultiMapName).getFieldList().stream();
    assertTrue(stream.get().filter(fdp -> fdp.getName().equals("key")).count() == 1);
    assertTrue(stream.get().filter(fdp -> fdp.getName().equals("value")).count() == 1);
    assertTrue(stream.get().filter(fdp -> fdp.getName().equals("value")).filter(fdp -> fdp.getLabel().equals(Label.LABEL_REPEATED)).count() == 1);
    assertEquals(Type.TYPE_MESSAGE, types.get("nestedmapnullable"));
    // even though the field is marked as optional in the row we will should see repeated in proto
    assertEquals(Label.LABEL_REPEATED, typeLabels.get("nestedmapnullable"));
    String nestedMapNullableName = typeNames.get("nestedmapnullable");
    // expects 2 fields in the nullable maps, key and value
    assertEquals(2, nestedTypes.get(nestedMapNullableName).getFieldList().size());
    stream = () -> nestedTypes.get(nestedMapNullableName).getFieldList().stream();
    assertTrue(stream.get().filter(fdp -> fdp.getName().equals("key")).count() == 1);
    assertTrue(stream.get().filter(fdp -> fdp.getName().equals("value")).count() == 1);
}

