@Test
public void testMessageFromTableRowForArraysAndMaps() throws Exception {
    Schema nestedMapSchemaVariations = Schema.builder().addField("nestedArrayNullable", FieldType.array(FieldType.STRING).withNullable(true)).addField("nestedMap", FieldType.map(FieldType.STRING, FieldType.STRING)).addField("nestedMultiMap", FieldType.map(FieldType.STRING, FieldType.iterable(FieldType.STRING))).addField("nestedMapNullable", FieldType.map(FieldType.STRING, FieldType.DOUBLE).withNullable(true)).build();
    Row nestedRow = Row.withSchema(nestedMapSchemaVariations).withFieldValue("nestedArrayNullable", null).withFieldValue("nestedMap", ImmutableMap.of("key1", "value1")).withFieldValue("nestedMultiMap", ImmutableMap.of("multikey1", ImmutableList.of("multivalue1", "multivalue2"))).withFieldValue("nestedMapNullable", null).build();
    Descriptor descriptor = TableRowToStorageApiProto.getDescriptorFromTableSchema(BeamRowToStorageApiProto.protoTableSchemaFromBeamSchema(nestedMapSchemaVariations), true, false);
    DynamicMessage msg = BeamRowToStorageApiProto.messageFromBeamRow(descriptor, nestedRow, null, -1);
    Map<String, FieldDescriptor> fieldDescriptors = descriptor.getFields().stream().collect(Collectors.toMap(FieldDescriptor::getName, Functions.identity()));
    DynamicMessage nestedMapEntryMsg = (DynamicMessage) msg.getRepeatedField(fieldDescriptors.get("nestedmap"), 0);
    String value = (String) nestedMapEntryMsg.getField(fieldDescriptors.get("nestedmap").getMessageType().findFieldByName("value"));
    assertEquals("value1", value);
    DynamicMessage nestedMultiMapEntryMsg = (DynamicMessage) msg.getRepeatedField(fieldDescriptors.get("nestedmultimap"), 0);
    List<String> values = (List<String>) nestedMultiMapEntryMsg.getField(fieldDescriptors.get("nestedmultimap").getMessageType().findFieldByName("value"));
    assertTrue(values.size() == 2);
    assertEquals("multivalue1", values.get(0));
    assertTrue(msg.getRepeatedFieldCount(fieldDescriptors.get("nestedarraynullable")) == 0);
    assertTrue(msg.getRepeatedFieldCount(fieldDescriptors.get("nestedmapnullable")) == 0);
}

