        assertEquals(expected, row);
        assertEquals(expected, row.clone());
    }
    {
        // null
        GenericRecord record = new GenericRecordBuilder(avroSchema(f -> f.type().optional().booleanType())).build();
        TableRow expected = new TableRow();
        TableRow row = BigQueryAvroUtils.convertGenericRecordToTableRow(record);
        assertEquals(expected, row);
        assertEquals(expected, row.clone());
    }
    {
        // array
        GenericRecord record = new GenericRecordBuilder(avroSchema(f -> f.type().array().items().booleanType().noDefault())).set("value", Lists.newArrayList(true, false)).build();
        TableRow expected = new TableRow().set("value", Lists.newArrayList(true, false));
        TableRow row = BigQueryAvroUtils.convertGenericRecordToTableRow(record);
        assertEquals(expected, row);
        assertEquals(expected, row.clone());
    }
    {
        // map
        Map<String, Integer> map = new HashMap<>();
        map.put("left", 1);
        map.put("right", -1);
        GenericRecord record = new GenericRecordBuilder(avroSchema(f -> f.type().map().values().intType().noDefault())).set("value", map).build();
        TableRow expected = new TableRow().set("value", Lists.newArrayList(new TableRow().set("key", "left").set("value", "1"), new TableRow().set("key", "right").set("value", "-1")));
        TableRow row = BigQueryAvroUtils.convertGenericRecordToTableRow(record);
        assertEquals(expected, row);
        assertEquals(expected, row.clone());
    }
    {
        // record
        Schema subSchema = SchemaBuilder.builder().record("record").fields().name("int").type().intType().noDefault().name("float").type().floatType().noDefault().endRecord();
        GenericRecord subRecord = new GenericRecordBuilder(subSchema).set("int", 5).set("float", 5.5f).build();
        GenericRecord record = new GenericRecordBuilder(avroSchema(f -> f.type(subSchema).noDefault())).set("value", subRecord).build();
        TableRow expected = new TableRow().set("value", new TableRow().set("int", "5").set("float", 5.5));
        TableRow row = BigQueryAvroUtils.convertGenericRecordToTableRow(record);
        assertEquals(expected, row);
        assertEquals(expected, row.clone());
    }
}

