@Test
public void testBigQueryStorageQueryWithErrorHandling1M() throws Exception {
    setUpTestEnvironment("1M");
    Pipeline p = Pipeline.create(options);
    ErrorHandler<BadRecord, PCollection<Long>> errorHandler = p.registerBadRecordErrorHandler(new ErrorSinkTransform());
    PCollection<Long> count = p.apply("Read", BigQueryIO.read(FailingTableRowParser.INSTANCE).fromQuery("SELECT * FROM `" + options.getInputTable() + "`").usingStandardSql().withMethod(Method.DIRECT_READ).withErrorHandler(errorHandler)).apply("Count", Count.globally());
    errorHandler.close();
    // When 1/50 elements fail sequentially, this is the expected success count
    PAssert.thatSingleton(count).isEqualTo(10381L);
    // this is the total elements, less the successful elements
    PAssert.thatSingleton(errorHandler.getOutput()).isEqualTo(10592L - 10381L);
    p.run().waitUntilFinish();
}

