    org.apache.beam.sdk.schemas.Schema schema = org.apache.beam.sdk.schemas.Schema.builder().addStringField("foo").addStringField("bar").build();
    TypedRead<Row> read = BigQueryIO.read(record -> BigQueryUtils.toBeamRow(record.getRecord(), schema, ConversionOptions.builder().build())).withMethod(Method.DIRECT_READ).withCoder(SchemaCoder.of(schema));
    assertTrue(read.supportsProjectionPushdown());
    PTransform<PBegin, PCollection<Row>> pushdownT = read.actuateProjectionPushdown(ImmutableMap.of(new TupleTag<>("output"), FieldAccessDescriptor.withFieldNames("foo")));
    TypedRead<Row> pushdownRead = (TypedRead<Row>) pushdownT;
    assertEquals(Method.DIRECT_READ, pushdownRead.getMethod());
    assertThat(pushdownRead.getSelectedFields().get(), Matchers.containsInAnyOrder("foo"));
