        assertTrue("Field name " + fieldName + " was not found in the transform schema defined in " + "BigQueryIOTranslation.BigQueryIOWriteTranslator.", BigQueryIOTranslation.BigQueryIOWriteTranslator.schema.getFieldNames().contains(fieldName));
