@Test
public void testStorageApiErrorsWriteProto() throws Exception {
    assumeTrue(useStorageApi);
    final Method method = useStorageApiApproximate ? Method.STORAGE_API_AT_LEAST_ONCE : Method.STORAGE_WRITE_API;
    final int failFrom = 10;
    Function<Integer, Proto3SchemaMessages.Primitive> getPrimitive = (Integer i) -> Proto3SchemaMessages.Primitive.newBuilder().setPrimitiveDouble(i).setPrimitiveFloat(i).setPrimitiveInt32(i).setPrimitiveInt64(i).setPrimitiveUint32(i).setPrimitiveUint64(i).setPrimitiveSint32(i).setPrimitiveSint64(i).setPrimitiveFixed32(i).setPrimitiveFixed64(i).setPrimitiveBool(true).setPrimitiveString(Integer.toString(i)).setPrimitiveBytes(ByteString.copyFrom(Integer.toString(i).getBytes(StandardCharsets.UTF_8))).build();
    List<Proto3SchemaMessages.Primitive> goodRows = IntStream.range(1, 20).mapToObj(getPrimitive::apply).collect(Collectors.toList());
    Function<Integer, TableRow> getPrimitiveRow = (Integer i) -> new TableRow().set("primitive_double", Double.valueOf(i)).set("primitive_float", Float.valueOf(i).doubleValue()).set("primitive_int32", i.intValue()).set("primitive_int64", i.toString()).set("primitive_uint32", i.toString()).set("primitive_uint64", i.toString()).set("primitive_sint32", i.toString()).set("primitive_sint64", i.toString()).set("primitive_fixed32", i.toString()).set("primitive_fixed64", i.toString()).set("primitive_bool", true).set("primitive_string", i.toString()).set("primitive_bytes", BaseEncoding.base64().encode(ByteString.copyFrom(i.toString().getBytes(StandardCharsets.UTF_8)).toByteArray()));
    Function<TableRow, Boolean> shouldFailRow = (Function<TableRow, Boolean> & Serializable) tr -> tr.containsKey("primitive_int32") && (Integer) tr.get("primitive_int32") >= failFrom;
    fakeDatasetService.setShouldFailRow(shouldFailRow);
    SerializableFunction<Proto3SchemaMessages.Primitive, TableRow> formatRecordOnFailureFunction = input -> {
        TableRow failedTableRow = new TableRow().set("testFailureFunctionField", "testValue");
        failedTableRow.set("originalValue", input.getPrimitiveFixed32());
        return failedTableRow;
    };
    WriteResult result = p.apply(Create.of(goodRows)).apply(BigQueryIO.writeProtos(Proto3SchemaMessages.Primitive.class).to("project-id:dataset-id.table").withCreateDisposition(CreateDisposition.CREATE_IF_NEEDED).withMethod(method).withoutValidation().withFormatRecordOnFailureFunction(formatRecordOnFailureFunction).withPropagateSuccessfulStorageApiWrites(true).withTestServices(fakeBqServices));
    PCollection<TableRow> deadRows = result.getFailedStorageApiInserts().apply(MapElements.into(TypeDescriptor.of(TableRow.class)).via(BigQueryStorageApiInsertError::getRow));
    List<TableRow> expectedFailedRows = goodRows.stream().filter(primitive -> primitive.getPrimitiveFixed32() >= failFrom).map(formatRecordOnFailureFunction::apply).collect(Collectors.toList());
    PAssert.that(deadRows).containsInAnyOrder(expectedFailedRows);
    p.run();
    // Round trip through the coder to make sure the types match our expected types.
    assertThat(fakeDatasetService.getAllRows("project-id", "dataset-id", "table").stream().map(tr -> {
        try {
            byte[] bytes = CoderUtils.encodeToByteArray(TableRowJsonCoder.of(), tr);
            return CoderUtils.decodeFromByteArray(TableRowJsonCoder.of(), bytes);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }).collect(Collectors.toList()), containsInAnyOrder(Iterables.toArray(Iterables.filter(goodRows.stream().map(primitive -> getPrimitiveRow.apply(primitive.getPrimitiveFixed32())).collect(Collectors.toList()), r -> !shouldFailRow.apply(r)), TableRow.class)));
}

