    TableRow goodNested = new TableRow().set("number", "42");
    TableRow badNested = new TableRow().set("number", "nAn");
    final String failValue = "failme";
    List<TableRow> goodRows = ImmutableList.of(new TableRow().set("name", "n1").set("number", "1"), new TableRow().set("name", failValue).set("number", "1"), new TableRow().set("name", "n2").set("number", "2"), new TableRow().set("name", failValue).set("number", "2"), new TableRow().set("name", "parent1").set("nested", goodNested), new TableRow().set("name", failValue).set("number", "1"));
    List<TableRow> badRows = ImmutableList.of(// Unknown field.
    new TableRow().set("name", "n3").set("number", "3").set("badField", "foo"), // Unknown field.
    new TableRow().setF(ImmutableList.of(new TableCell().setV("n3"), new TableCell().setV("3"), new TableCell(), new TableCell().setV("foo"))), // Wrong type.
    new TableRow().set("name", "n4").set("number", "baadvalue"), // Wrong type.
    new TableRow().setF(ImmutableList.of(new TableCell().setV("n4"), new TableCell().setV("baadvalue"), new TableCell())), // Missing required field.
    new TableRow().set("number", "42"), // Invalid nested row
    new TableRow().set("name", "parent2").set("nested", badNested));
    Function<TableRow, Boolean> shouldFailRow = (Function<TableRow, Boolean> & Serializable) tr -> tr.containsKey("name") && tr.get("name").equals(failValue);
    fakeDatasetService.setShouldFailRow(shouldFailRow);
    SerializableFunction<TableRow, TableRow> formatRecordOnFailureFunction = input -> {
        TableRow failedTableRow = new TableRow().set("testFailureFunctionField", "testValue");
        if (input != null) {
            Object name = input.get("name");
            if (name != null) {
                failedTableRow.set("name", name);
            }
            Object number = input.get("number");
            if (number != null) {
                failedTableRow.set("number", number);
            }
        }
        return failedTableRow;
    };
    WriteResult result = p.apply(Create.of(Iterables.concat(goodRows, badRows))).apply(BigQueryIO.writeTableRows().to("project-id:dataset-id.table").withMethod(method).withCreateDisposition(BigQueryIO.Write.CreateDisposition.CREATE_IF_NEEDED).withSchema(tableSchema).withFailedInsertRetryPolicy(InsertRetryPolicy.retryTransientErrors()).withPropagateSuccessfulStorageApiWrites(true).withTestServices(fakeBqServices).withFormatRecordOnFailureFunction(formatRecordOnFailureFunction).withoutValidation());
