    List<TableRow> expectedFailedRows = badRows.stream().map(formatRecordOnFailureFunction::apply).collect(Collectors.toList());
    expectedFailedRows.addAll(goodRows.stream().filter(shouldFailRow::apply).map(formatRecordOnFailureFunction::apply).collect(Collectors.toList()));
    PAssert.that(deadRows).containsInAnyOrder(expectedFailedRows);
    PAssert.that(successfulRows).containsInAnyOrder(Iterables.toArray(Iterables.filter(goodRows, r -> !shouldFailRow.apply(r)), TableRow.class));
    p.run();
    assertThat(fakeDatasetService.getAllRows("project-id", "dataset-id", "table"), containsInAnyOrder(Iterables.toArray(Iterables.filter(goodRows, r -> !shouldFailRow.apply(r)), TableRow.class)));
