    WriteResult res = p.apply(PeriodicImpulse.create().startAt(Instant.ofEpochMilli(0)).stopAfter(Duration.millis(numRows - 1)).withInterval(Duration.millis(1))).apply("Convert to longs", MapElements.into(TypeDescriptor.of(TableRow.class)).via(instant -> new TableRow().set("long", instant.getMillis()))).apply(BigQueryIO.writeTableRows().to(ref).withSchema(schema).withTestServices(new FakeBigQueryServices().withDatasetService(throwingService).withJobService(fakeJobService)));
