@Test
public void runWriteTestTempTableAndDynamicDestination() throws Exception {
    final int numPerAnimal = 10;
    String tableNameCat = makeTestTable();
    String tableNameDog = makeTestTable();
    WriteToBqDynamic dynamicDestination = new WriteToBqDynamic(project, BIG_QUERY_DATASET_ID, tableNameCat, tableNameDog);
    Set<SchemaUpdateOption> schemaUpdateOptions = EnumSet.of(BigQueryIO.Write.SchemaUpdateOption.ALLOW_FIELD_ADDITION);
    String[] values = { "meow", "bark" };
    List<Set<String>> expectedCat = new ArrayList<>();
    List<Set<String>> expectedDog = new ArrayList<>();
    List<TableRow> inputRows = new ArrayList<>();
    for (int i = 0; i < numPerAnimal; ++i) {
        expectedCat.add(ImmutableSet.of(values[0], String.valueOf(i)));
        expectedDog.add(ImmutableSet.of(values[1], String.valueOf(i)));
        // cat and dog tables have different schema
        inputRows.add(new TableRow().set("required_field", values[0]).set("cat_new_field", String.valueOf(i)));
        inputRows.add(new TableRow().set("required_field", values[1]).set("dog_new_field", (long) i));
    }
    Options options = TestPipeline.testingPipelineOptions().as(Options.class);
    options.setTempLocation(FileSystems.matchNewDirectory(options.getTempRoot(), "bq_it_temp").toString());
    Pipeline p = Pipeline.create(options);
    p.apply(Create.of(inputRows)).apply(BigQueryIO.writeTableRows().to(dynamicDestination).withCreateDisposition(CreateDisposition.CREATE_NEVER).withWriteDisposition(BigQueryIO.Write.WriteDisposition.WRITE_APPEND).withSchemaUpdateOptions(schemaUpdateOptions).withMaxFileSize(10).withMaxFilesPerPartition(2));
    PipelineResult.State state = p.run().waitUntilFinish();
    assertEquals(PipelineResult.State.DONE, state);
    String testCatQuery = String.format("SELECT cat_new_field, required_field FROM [%s.%s];", BIG_QUERY_DATASET_ID, tableNameCat);
    String testDogQuery = String.format("SELECT dog_new_field, required_field FROM [%s.%s];", BIG_QUERY_DATASET_ID, tableNameDog);
    List<Set<String>> catResult = runQuery(testCatQuery);
    assertEquals(new HashSet<>(expectedCat), new HashSet<>(catResult));
    List<Set<String>> dogResult = runQuery(testDogQuery);
    assertEquals(new HashSet<>(expectedDog), new HashSet<>(dogResult));
}

