/**
 * Tests that {@link DatasetServiceImpl#insertAll} sets perWorkerMetrics properly when the Backoff
 * limit is hit.
 */
@Test
public void testInsertAll_InternalBigQueryErrors() throws Exception {
    BigQuerySinkMetrics.setSupportStreamingInsertsMetrics(true);
    BigQuerySinkMetricsTest.TestMetricsContainer testMetricsContainer = new BigQuerySinkMetricsTest.TestMetricsContainer();
    MetricsEnvironment.setCurrentContainer(testMetricsContainer);
    BigQuerySinkMetrics.setSupportMetricsDeletion(true);
    TableReference ref = new TableReference().setProjectId("project").setDatasetId("dataset").setTableId("table");
    List<FailsafeValueInSingleWindow<TableRow, TableRow>> rows = ImmutableList.of(wrapValue(new TableRow().set("row", "a")), wrapValue(new TableRow().set("row", "b")));
    List<String> insertIds = ImmutableList.of("a", "b");
    final TableDataInsertAllResponse aFailed = new TableDataInsertAllResponse().setInsertErrors(ImmutableList.of(new InsertErrors().setIndex(0L).setErrors(ImmutableList.of(new ErrorProto()))));
    MockSetupFunction aFailedResponse = response -> {
        when(response.getContentType()).thenReturn(Json.MEDIA_TYPE);
        when(response.getStatusCode()).thenReturn(200);
        when(response.getContent()).thenReturn(toStream(aFailed));
    };
    // Expect 4 InsertAll RPCS:
    // 1st request will return an RPC error that should be retried
    // 2nd-4th RPCs will fail to insert Row A.
    // Expect client throw an exception after 4th RPC due to hitting backoff limits.
    setupMockResponses(response -> {
        when(response.getStatusCode()).thenReturn(403);
        when(response.getContentType()).thenReturn(Json.MEDIA_TYPE);
        when(response.getContent()).thenReturn(toStream(errorWithReasonAndStatus("rateLimitExceeded", 403)));
    }, aFailedResponse, aFailedResponse, aFailedResponse, aFailedResponse);
    DatasetServiceImpl dataService = new DatasetServiceImpl(bigquery, PipelineOptionsFactory.create());
    try {
        dataService.insertAll(ref, rows, insertIds, BackOffAdapter.toGcpBackOff(TEST_BACKOFF.backoff()), TEST_BACKOFF, new MockSleeper(), InsertRetryPolicy.alwaysRetry(), null, null, false, false, false, null);
        fail();
    } catch (Exception e) {
    }
    verifyAllResponsesAreRead();
    String tableId = "datasets/dataset/tables/table";
    BigQuerySinkMetrics.RpcMethod method = BigQuerySinkMetrics.RpcMethod.STREAMING_INSERTS;
    MetricName okRpcRequestName = BigQuerySinkMetrics.createRPCRequestCounter(method, "OK", tableId).getName();
    MetricName rateLimitRpcRequestName = BigQuerySinkMetrics.createRPCRequestCounter(method, "rateLimitExceeded", tableId).getName();
    MetricName okRowsAppendedName = BigQuerySinkMetrics.appendRowsRowStatusCounter(RowStatus.SUCCESSFUL, "OK", tableId).getName();
    MetricName internalRowsAppendedName = BigQuerySinkMetrics.appendRowsRowStatusCounter(RowStatus.RETRIED, "INTERNAL", tableId).getName();
    MetricName rateLimitRowsAppendedName = BigQuerySinkMetrics.appendRowsRowStatusCounter(RowStatus.RETRIED, "rateLimitExceeded", tableId).getName();
    MetricName failedRowsName = BigQuerySinkMetrics.appendRowsRowStatusCounter(RowStatus.FAILED, "INTERNAL", tableId).getName();
    testMetricsContainer.assertPerWorkerCounterValue(okRpcRequestName, 4L);
    testMetricsContainer.assertPerWorkerCounterValue(rateLimitRpcRequestName, 1L);
    testMetricsContainer.assertPerWorkerCounterValue(okRowsAppendedName, 1L);
    testMetricsContainer.assertPerWorkerCounterValue(internalRowsAppendedName, 3L);
    testMetricsContainer.assertPerWorkerCounterValue(rateLimitRowsAppendedName, 2L);
    testMetricsContainer.assertPerWorkerCounterValue(failedRowsName, 1L);
    assertThat(testMetricsContainer.perWorkerHistograms.size(), equalTo(1));
}

