@Test
public void testWriteTransformProtoTranslation() throws InvalidProtocolBufferException, IOException {
    // First build a pipeline
    Pipeline p = Pipeline.create();
    Schema inputSchema = Schema.builder().addByteArrayField("b").build();
    PCollection<Row> input = p.apply(Create.of(Collections.singletonList(Row.withSchema(inputSchema).addValue(new byte[] { 1, 2, 3 }).build()))).setRowSchema(inputSchema);
    BigQueryWriteSchemaTransform writeTransform = (BigQueryWriteSchemaTransform) WRITE_PROVIDER.from(WRITE_CONFIG_ROW);
    PCollectionRowTuple.of("input", input).apply(writeTransform);
    // Then translate the pipeline to a proto and extract BigQueryWriteSchemaTransform proto
    RunnerApi.Pipeline pipelineProto = PipelineTranslation.toProto(p);
    List<RunnerApi.PTransform> writeTransformProto = pipelineProto.getComponents().getTransformsMap().values().stream().filter(tr -> {
        RunnerApi.FunctionSpec spec = tr.getSpec();
        try {
            return spec.getUrn().equals(BeamUrns.getUrn(SCHEMA_TRANSFORM)) && SchemaTransformPayload.parseFrom(spec.getPayload()).getIdentifier().equals(WRITE_PROVIDER.identifier());
        } catch (InvalidProtocolBufferException e) {
            throw new RuntimeException(e);
        }
    }).collect(Collectors.toList());
    assertEquals(1, writeTransformProto.size());
    RunnerApi.FunctionSpec spec = writeTransformProto.get(0).getSpec();
    // Check that the proto contains correct values
    SchemaTransformPayload payload = SchemaTransformPayload.parseFrom(spec.getPayload());
    Schema schemaFromSpec = SchemaTranslation.schemaFromProto(payload.getConfigurationSchema());
    assertEquals(WRITE_PROVIDER.configurationSchema(), schemaFromSpec);
    Row rowFromSpec = RowCoder.of(schemaFromSpec).decode(payload.getConfigurationRow().newInput());
    assertEquals(WRITE_CONFIG_ROW, rowFromSpec);
    // Use the information in the proto to recreate the BigQueryWriteSchemaTransform
    BigQueryWriteSchemaTransformTranslator translator = new BigQueryWriteSchemaTransformTranslator();
    BigQueryWriteSchemaTransform writeTransformFromSpec = translator.fromConfigRow(rowFromSpec, PipelineOptionsFactory.create());
    assertEquals(WRITE_CONFIG_ROW, writeTransformFromSpec.getConfigurationRow());
}

