@Test
public void testDirectWriteProtos() throws Exception {
    Function<Integer, Proto3SchemaMessages.Primitive> getPrimitiveProto = (Integer i) -> Proto3SchemaMessages.Primitive.newBuilder().setPrimitiveDouble(i).setPrimitiveFloat(i).setPrimitiveInt32(i).setPrimitiveInt64(i).setPrimitiveUint32(i).setPrimitiveUint64(i).setPrimitiveSint32(i).setPrimitiveSint64(i).setPrimitiveFixed32(i).setPrimitiveFixed64(i).setPrimitiveBool(true).setPrimitiveString(Integer.toString(i)).setPrimitiveBytes(ByteString.copyFrom(Integer.toString(i).getBytes(StandardCharsets.UTF_8))).build();
    Function<Integer, TableRow> getPrimitiveRow = (Integer i) -> new TableRow().set("primitive_double", Double.valueOf(i)).set("primitive_float", Float.valueOf(i).doubleValue()).set("primitive_int32", i.toString()).set("primitive_int64", i.toString()).set("primitive_uint32", i.toString()).set("primitive_uint64", i.toString()).set("primitive_sint32", i.toString()).set("primitive_sint64", i.toString()).set("primitive_fixed32", i.toString()).set("primitive_fixed64", i.toString()).set("primitive_bool", true).set("primitive_string", i.toString()).set("primitive_bytes", BaseEncoding.base64().encode(ByteString.copyFrom(i.toString().getBytes(StandardCharsets.UTF_8)).toByteArray()));
    List<Proto3SchemaMessages.Primitive> nestedItems = IntStream.range(1, 2).mapToObj(i -> getPrimitiveProto.apply(i)).collect(Collectors.toList());
    Iterable<Proto3SchemaMessages.Nested> items = nestedItems.stream().map(p -> Proto3SchemaMessages.Nested.newBuilder().setNested(p).addAllNestedList(Lists.newArrayList(p, p, p)).build()).collect(Collectors.toList());
    List<TableRow> expectedNestedItems = IntStream.range(1, 2).mapToObj(getPrimitiveRow::apply).collect(Collectors.toList());
    Iterable<TableRow> expectedItems = expectedNestedItems.stream().map(p -> new TableRow().set("nested_map", Lists.newArrayList()).set("nested", p).set("nested_list", Lists.newArrayList(p, p, p))).collect(Collectors.toList());
    String table = "table" + System.nanoTime();
    String tableSpec = PROJECT + "." + BIG_QUERY_DATASET_ID + "." + table;
    BigQueryIO.Write.Method method = getMethod();
    BigQueryIO.Write<Proto3SchemaMessages.Nested> write = BigQueryIO.writeProtos(Proto3SchemaMessages.Nested.class).to(tableSpec).withCreateDisposition(BigQueryIO.Write.CreateDisposition.CREATE_IF_NEEDED).withMethod(method);
    if (method == BigQueryIO.Write.Method.STORAGE_WRITE_API) {
        write = write.withNumStorageWriteApiStreams(1);
        if (useStreamingExactlyOnce) {
            write = write.withTriggeringFrequency(Duration.standardSeconds(1));
        }
    }
    Pipeline p = Pipeline.create();
    PCollection<Proto3SchemaMessages.Nested> input = p.apply("Create test cases", Create.of(items));
    if (useStreamingExactlyOnce) {
        input = input.setIsBoundedInternal(PCollection.IsBounded.UNBOUNDED);
    }
    input.apply("Write using Storage Write API", write);
    p.run().waitUntilFinish();
    assertRowsWritten(tableSpec, expectedItems);
}

