 * reading the first buffer, the first two RowRanges should be removed and the RowRange containing
 * [b00100,b00200) should be requested.
 *
 * @throws IOException
 */
@Test
public void testReadFillBuffer() throws IOException {
    RowSet.Builder ranges = RowSet.newBuilder();
    ranges.addRowRanges(generateRowRange(generateByteString(DEFAULT_PREFIX, 0), generateByteString(DEFAULT_PREFIX, SEGMENT_SIZE / 2)));
    ranges.addRowRanges(generateRowRange(generateByteString(DEFAULT_PREFIX, SEGMENT_SIZE / 2), generateByteString(DEFAULT_PREFIX, SEGMENT_SIZE)));
    ranges.addRowRanges(generateRowRange(generateByteString(DEFAULT_PREFIX, SEGMENT_SIZE), generateByteString(DEFAULT_PREFIX, SEGMENT_SIZE * 2)));
    List<List<Row>> expectedResults = ImmutableList.of(generateSegmentResult(DEFAULT_PREFIX, 0, SEGMENT_SIZE), generateSegmentResult(DEFAULT_PREFIX, SEGMENT_SIZE, SEGMENT_SIZE), ImmutableList.of());
    // Set up Callable to be returned by stub.createReadRowsCallable()
    ServerStreamingCallable<Query, Row> mockCallable = Mockito.mock(ServerStreamingCallable.class);
    // Return multiple answers when mockCallable is called
    doAnswer(new MultipleAnswer<Row>(expectedResults)).when(mockCallable).call(any(Query.class), any(ResponseObserver.class), any(ApiCallContext.class));
    when(mockStub.createReadRowsCallable(any(RowAdapter.class))).thenReturn(mockCallable);
    ServerStreamingCallable<Query, Row> callable = mockStub.createReadRowsCallable(new BigtableServiceImpl.BigtableRowProtoAdapter());
    // Set up client to return callable
    when(mockBigtableDataClient.readRowsCallable(any(RowAdapter.class))).thenReturn(callable);
    BigtableService.Reader underTest = new BigtableServiceImpl.BigtableSegmentReaderImpl(mockBigtableDataClient, bigtableDataSettings.getProjectId(), bigtableDataSettings.getInstanceId(), TABLE_ID, ranges.build(), RowFilter.getDefaultInstance(), SEGMENT_SIZE, DEFAULT_BYTE_SEGMENT_SIZE, mockCallMetric);
    List<Row> actualResults = new ArrayList<>();
    Assert.assertTrue(underTest.start());
    verify(callable, times(1)).call(queryCaptor.capture(), any(ResponseObserver.class), any(ApiCallContext.class));
    Assert.assertEquals(3, queryCaptor.getValue().toProto(requestContext).getRows().getRowRangesCount());
    do {
        actualResults.add(underTest.getCurrentRow());
    } while (underTest.advance());
    verify(callable, times(3)).call(queryCaptor.capture(), any(ResponseObserver.class), any(ApiCallContext.class));
    Assert.assertEquals(1, queryCaptor.getValue().toProto(requestContext).getRows().getRowRangesCount());
    Assert.assertEquals(expectedResults.stream().flatMap(Collection::stream).collect(Collectors.toList()), actualResults);
    Mockito.verify(mockCallMetric, Mockito.times(3)).call("ok");
}

/**
 * This test verifies that a refill request is sent before we read all the rows in the buffer.
 */
@Test
public void testRefillOnLowWatermark() throws IOException {
    int segmentSize = 30;
    RowSet.Builder ranges = RowSet.newBuilder();
    // generate 3 pages of rows
    ranges.addRowRanges(generateRowRange(generateByteString(DEFAULT_PREFIX, 0), generateByteString(DEFAULT_PREFIX, segmentSize * 3)));
    List<List<Row>> expectedResults = ImmutableList.of(generateSegmentResult(DEFAULT_PREFIX, 0, segmentSize), generateSegmentResult(DEFAULT_PREFIX, segmentSize, segmentSize), generateSegmentResult(DEFAULT_PREFIX, segmentSize * 2, segmentSize), ImmutableList.of());
    // Set up Callable to be returned by stub.createReadRowsCallable()
    ServerStreamingCallable<Query, Row> mockCallable = Mockito.mock(ServerStreamingCallable.class);
    // Return multiple answers when mockCallable is called
    doAnswer(new MultipleAnswer<Row>(expectedResults)).when(mockCallable).call(any(Query.class), any(ResponseObserver.class), any(ApiCallContext.class));
    when(mockStub.createReadRowsCallable(any(RowAdapter.class))).thenReturn(mockCallable);
    ServerStreamingCallable<Query, Row> callable = mockStub.createReadRowsCallable(new BigtableServiceImpl.BigtableRowProtoAdapter());
    // Set up client to return callable
    when(mockBigtableDataClient.readRowsCallable(any(RowAdapter.class))).thenReturn(callable);
    BigtableService.Reader underTest = new BigtableServiceImpl.BigtableSegmentReaderImpl(mockBigtableDataClient, bigtableDataSettings.getProjectId(), bigtableDataSettings.getInstanceId(), TABLE_ID, ranges.build(), RowFilter.getDefaultInstance(), segmentSize, DEFAULT_BYTE_SEGMENT_SIZE, mockCallMetric);
    Assert.assertTrue(underTest.start());
    int refillWatermark = Math.max(1, (int) (segmentSize * 0.1));
    Assert.assertTrue(refillWatermark > 1);
    // Make sure refill happens on the second page. At this point, there
    // should be 3 calls made on the callable.
    for (int i = 0; i < segmentSize * 2 - refillWatermark + 1; i++) {
        underTest.getCurrentRow();
        underTest.advance();
    }
    verify(callable, times(3)).call(queryCaptor.capture(), any(ResponseObserver.class), any(ApiCallContext.class));
}

/**
 * This test checks that the buffer will stop filling up once the byte limit is reached. It will
 * cancel the controller after reached the limit. This test completes one fill and contains one
 * Row after the first buffer has been completed. The test checks the current available memory in
 * the JVM and uses a percent of it to mock the original behavior. Range: [b00000, b00010)
 *
 * @throws IOException
 */
@Test
public void testReadByteLimitBuffer() throws IOException {
    long segmentByteLimit = DEFAULT_ROW_SIZE * (SEGMENT_SIZE / 2);
    int numOfRowsInsideBuffer = (int) (segmentByteLimit / DEFAULT_ROW_SIZE) + 1;
    RowRange mockRowRange = generateRowRange(generateByteString(DEFAULT_PREFIX, 0), generateByteString(DEFAULT_PREFIX, SEGMENT_SIZE));
    List<List<Row>> expectedResults = ImmutableList.of(generateLargeSegmentResult(DEFAULT_PREFIX, 0, numOfRowsInsideBuffer), generateSegmentResult(DEFAULT_PREFIX, numOfRowsInsideBuffer, SEGMENT_SIZE - numOfRowsInsideBuffer), ImmutableList.of());
    // Set up Callable to be returned by stub.createReadRowsCallable()
    ServerStreamingCallable<Query, Row> mockCallable = Mockito.mock(ServerStreamingCallable.class);
    // Create a mock stream controller
    StreamController mockController = Mockito.mock(StreamController.class);
    doAnswer(new Answer<Void>() {

        @Override
        public Void answer(InvocationOnMock invocation) throws Throwable {
            cancelled.set(true);
            return null;
        }
    }).when(mockController).cancel();
    // Return multiple answers when mockCallable is called
    doAnswer(new MultipleAnswer<Row>(expectedResults, mockController)).when(mockCallable).call(any(Query.class), any(ResponseObserver.class), any(ApiCallContext.class));
    when(mockStub.createReadRowsCallable(any(RowAdapter.class))).thenReturn(mockCallable);
    ServerStreamingCallable<Query, Row> callable = mockStub.createReadRowsCallable(new BigtableServiceImpl.BigtableRowProtoAdapter());
    // Set up client to return callable
    when(mockBigtableDataClient.readRowsCallable(any(RowAdapter.class))).thenReturn(callable);
    BigtableService.Reader underTest = new BigtableServiceImpl.BigtableSegmentReaderImpl(mockBigtableDataClient, bigtableDataSettings.getProjectId(), bigtableDataSettings.getInstanceId(), TABLE_ID, RowSet.newBuilder().addRowRanges(mockRowRange).build(), RowFilter.getDefaultInstance(), SEGMENT_SIZE, segmentByteLimit, mockCallMetric);
    List<Row> actualResults = new ArrayList<>();
    Assert.assertTrue(underTest.start());
    do {
        actualResults.add(underTest.getCurrentRow());
    } while (underTest.advance());
    Assert.assertEquals(expectedResults.stream().flatMap(Collection::stream).collect(Collectors.toList()), actualResults);
    Mockito.verify(mockCallMetric, Mockito.times(3)).call("ok");
}

/**
 * This test ensures the Exception handling inside of the scanHandler. This test will check if a
 * StatusRuntimeException was thrown.
 *
 * @throws IOException
 */
@Test
public void testReadSegmentExceptionHandling() throws IOException {
    RowSet.Builder ranges = RowSet.newBuilder();
    ranges.addRowRanges(generateRowRange(generateByteString(DEFAULT_PREFIX, 0), generateByteString(DEFAULT_PREFIX, 1)));
    // Set up Callable to be returned by stub.createReadRowsCallable()
    ServerStreamingCallable<Query, Row> mockCallable = Mockito.mock(ServerStreamingCallable.class);
    doAnswer(new Answer<Void>() {

        @Override
        public Void answer(InvocationOnMock invocationOnMock) throws Throwable {
            new Thread() {

                @Override
                public void run() {
                    ((ResponseObserver) invocationOnMock.getArgument(1)).onError(Status.INVALID_ARGUMENT.asRuntimeException());
                }
            }.start();
            return null;
        }
    }).when(mockCallable).call(any(Query.class), any(ResponseObserver.class), any(ApiCallContext.class));
    when(mockStub.createReadRowsCallable(any(RowAdapter.class))).thenReturn(mockCallable);
    ServerStreamingCallable<Query, Row> callable = mockStub.createReadRowsCallable(new BigtableServiceImpl.BigtableRowProtoAdapter());
    // Set up client to return callable
    when(mockBigtableDataClient.readRowsCallable(any(RowAdapter.class))).thenReturn(callable);
    BigtableService.Reader underTest = new BigtableServiceImpl.BigtableSegmentReaderImpl(mockBigtableDataClient, bigtableDataSettings.getProjectId(), bigtableDataSettings.getInstanceId(), TABLE_ID, ranges.build(), RowFilter.getDefaultInstance(), SEGMENT_SIZE, DEFAULT_BYTE_SEGMENT_SIZE, mockCallMetric);
    IOException returnedError = null;
    try {
        underTest.start();
    } catch (IOException e) {
        returnedError = e;
    }
    Assert.assertTrue(returnedError.getCause() instanceof StatusRuntimeException);
    Mockito.verify(mockCallMetric, Mockito.times(1)).call(Status.INVALID_ARGUMENT.getCode().toString());
}

/**
 * This test ensures that protobuf creation and interactions with {@link Batcher} work as
 * expected.
 *
 * @throws IOException
 * @throws InterruptedException
 */
@Test
public void testWrite() throws IOException {
    doReturn(mockBatcher).when(mockBigtableDataClient).newBulkMutationBatcher((String) any());
    SettableApiFuture<Void> fakeFuture = SettableApiFuture.create();
    when(mockBatcher.closeAsync()).thenReturn(fakeFuture);
    ArgumentCaptor<RowMutationEntry> captor = ArgumentCaptor.forClass(RowMutationEntry.class);
    ApiFuture<Void> fakeResponse = SettableApiFuture.create();
    when(mockBatcher.add(any(RowMutationEntry.class))).thenAnswer(invocation -> {
        fakeFuture.set(null);
        return fakeResponse;
    });
    BigtableService.Writer underTest = new BigtableServiceImpl.BigtableWriterImpl(mockBigtableDataClient, bigtableDataSettings.getProjectId(), bigtableDataSettings.getInstanceId(), TABLE_ID, Duration.millis(60000));
    ByteString key = ByteString.copyFromUtf8("key");
    Mutation mutation = Mutation.newBuilder().setSetCell(Mutation.SetCell.newBuilder().setFamilyName("Family").setColumnQualifier(ByteString.copyFromUtf8("q")).setValue(ByteString.copyFromUtf8("value")).build()).build();
    CompletableFuture<MutateRowResponse> unusedElementFuture = underTest.writeRecord(KV.of(key, ImmutableList.of(mutation)));
    verify(mockBatcher).add(captor.capture());
    assertEquals(key, captor.getValue().toProto().getRowKey());
    assertTrue(captor.getValue().toProto().getMutations(0).hasSetCell());
    assertEquals("Family", captor.getValue().toProto().getMutations(0).getSetCell().getFamilyName());
    underTest.close();
}

