@Test
public void testSetMutationsExistingColumn() {
    RowMutation rowMutation = RowMutation.create(tableId, "key-1").setCell(COLUMN_FAMILY_NAME_1, "col_a", 1000, "val-1-a").setCell(COLUMN_FAMILY_NAME_2, "col_c", 1000, "val-1-c");
    dataClient.mutateRow(rowMutation);
    Schema testSchema = Schema.builder().addByteArrayField("key").addStringField("type").addByteArrayField("value").addByteArrayField("column_qualifier").addStringField("family_name").addField("timestamp_micros", // Changed to INT64
    FieldType.INT64).build();
    Row mutationRow1 = Row.withSchema(testSchema).withFieldValue("key", "key-1".getBytes(StandardCharsets.UTF_8)).withFieldValue("type", "SetCell").withFieldValue("value", "new-val-1-a".getBytes(StandardCharsets.UTF_8)).withFieldValue("column_qualifier", "col_a".getBytes(StandardCharsets.UTF_8)).withFieldValue("family_name", COLUMN_FAMILY_NAME_1).withFieldValue("timestamp_micros", 2000L).build();
    Row mutationRow2 = Row.withSchema(testSchema).withFieldValue("key", "key-1".getBytes(StandardCharsets.UTF_8)).withFieldValue("type", "SetCell").withFieldValue("value", "new-val-1-c".getBytes(StandardCharsets.UTF_8)).withFieldValue("column_qualifier", "col_c".getBytes(StandardCharsets.UTF_8)).withFieldValue("family_name", COLUMN_FAMILY_NAME_2).withFieldValue("timestamp_micros", 2000L).build();
    PCollection<Row> inputPCollection = p.apply(Create.of(Arrays.asList(mutationRow1, mutationRow2)));
    inputPCollection.setRowSchema(testSchema);
    // Use the schema-set PCollection
    PCollectionRowTuple.of("input", inputPCollection).apply(writeTransform);
    p.run().waitUntilFinish();
    // get rows from table
    List<com.google.cloud.bigtable.data.v2.models.Row> rows = dataClient.readRows(Query.create(tableId)).stream().collect(Collectors.toList());
    // we should still have only one row with the same key
    assertEquals(1, rows.size());
    assertEquals("key-1", rows.get(0).getKey().toStringUtf8());
    // check that we now have two cells in each column we added to and that
    // the last cell in each column has the updated value
    com.google.cloud.bigtable.data.v2.models.Row row = rows.get(0);
    List<RowCell> cellsColA = row.getCells(COLUMN_FAMILY_NAME_1, "col_a").stream().sorted(RowCell.compareByNative()).collect(Collectors.toList());
    List<RowCell> cellsColC = row.getCells(COLUMN_FAMILY_NAME_2, "col_c").stream().sorted(RowCell.compareByNative()).collect(Collectors.toList());
    assertEquals(2, cellsColA.size());
    assertEquals(2, cellsColC.size());
    // Bigtable keeps cell history ordered by descending timestamp
    assertEquals("new-val-1-a", cellsColA.get(0).getValue().toStringUtf8());
    assertEquals("new-val-1-c", cellsColC.get(0).getValue().toStringUtf8());
    assertEquals("val-1-a", cellsColA.get(1).getValue().toStringUtf8());
    assertEquals("val-1-c", cellsColC.get(1).getValue().toStringUtf8());
}

