@Test
public void testDeleteCellsFromColumn() {
    RowMutation rowMutation = RowMutation.create(tableId, "key-1").setCell(COLUMN_FAMILY_NAME_1, "col_a", "val-1-a").setCell(COLUMN_FAMILY_NAME_1, "col_b", "val-1-b");
    dataClient.mutateRow(rowMutation);
    // write two cells in col_a. both should get deleted
    rowMutation = RowMutation.create(tableId, "key-1").setCell(COLUMN_FAMILY_NAME_1, "col_a", "new-val-1-a");
    dataClient.mutateRow(rowMutation);
    Schema testSchema = Schema.builder().addByteArrayField("key").addStringField("type").addByteArrayField("column_qualifier").addStringField("family_name").build();
    Row mutationRow = Row.withSchema(testSchema).withFieldValue("key", "key-1".getBytes(StandardCharsets.UTF_8)).withFieldValue("type", "DeleteFromColumn").withFieldValue("column_qualifier", "col_a".getBytes(StandardCharsets.UTF_8)).withFieldValue("family_name", COLUMN_FAMILY_NAME_1).build();
    PCollection<Row> inputPCollection = p.apply(Create.of(Arrays.asList(mutationRow)));
    inputPCollection.setRowSchema(testSchema);
    // Use the schema-set PCollection
    PCollectionRowTuple.of("input", inputPCollection).apply(writeTransform);
    p.run().waitUntilFinish();
    // get rows from table
    List<com.google.cloud.bigtable.data.v2.models.Row> rows = dataClient.readRows(Query.create(tableId)).stream().collect(Collectors.toList());
    // we should still have one row with the same key
    assertEquals(1, rows.size());
    assertEquals("key-1", rows.get(0).getKey().toStringUtf8());
    // get cells from this column family. we started with three cells and deleted two from one
    // column.
    // we should end up with one cell in the column we didn't touch.
    com.google.cloud.bigtable.data.v2.models.Row row = rows.get(0);
    List<RowCell> cells = row.getCells(COLUMN_FAMILY_NAME_1);
    assertEquals(1, cells.size());
    assertEquals("col_b", cells.get(0).getQualifier().toStringUtf8());
}

