    dataClient.mutateRow(RowMutation.create(tableId, "row-delete-col").setCell(COLUMN_FAMILY_NAME_1, "col_to_delete_A", 1000, "val_to_delete_A_old").setCell(COLUMN_FAMILY_NAME_1, "col_to_delete_A", 2000, "val_to_delete_A_new").setCell(COLUMN_FAMILY_NAME_1, "col_to_keep_B", "val_to_keep_B"));
    dataClient.mutateRow(RowMutation.create(tableId, "row-delete-col-ts").setCell(COLUMN_FAMILY_NAME_1, "ts_col", 1000, "ts_val_old").setCell(COLUMN_FAMILY_NAME_1, "ts_col", 2000, "ts_val_new").setCell(COLUMN_FAMILY_NAME_2, "ts_col_other_cf", "ts_val_other_cf"));
    dataClient.mutateRow(RowMutation.create(tableId, "row-delete-family").setCell(COLUMN_FAMILY_NAME_1, "col_to_delete_family", "val_delete_family").setCell(COLUMN_FAMILY_NAME_2, "col_to_keep_family", "val_keep_family"));
    dataClient.mutateRow(RowMutation.create(tableId, "row-delete-row").setCell(COLUMN_FAMILY_NAME_1, "col", "val_delete_row"));
    dataClient.mutateRow(RowMutation.create(tableId, "row-final-check").setCell(COLUMN_FAMILY_NAME_1, "col_final_1", "val_final_1"));
    // --- Define Schema for various mutation types ---
    Schema uberSchema = Schema.builder().addByteArrayField(// Key is always present and non-null
    "key").addStringField(// Type is always present and non-null (e.g., "SetCell", "DeleteFromRow")
    "type").// All other fields are conditional based on the 'type' of mutation, so they must be
    // nullable.
    addNullableField("value", // Used by SetCell
    FieldType.BYTES).addNullableField("column_qualifier", // Used by SetCell, DeleteFromColumn
    FieldType.BYTES).addNullableField("family_name", // Used by SetCell, DeleteFromColumn, DeleteFromFamily
    FieldType.STRING).addNullableField("timestamp_micros", // Optional for SetCell
    FieldType.INT64).addNullableField("start_timestamp_micros", // Used by DeleteFromColumn with range
    FieldType.INT64).addNullableField("end_timestamp_micros", // Used by DeleteFromColumn with range
    FieldType.INT64).build();
    // --- Create a list of mutation Rows ---
    List<Row> mutations = new ArrayList<>();
    // 1. SetCell (Update an existing cell, add a new cell)
    // Update "row-setcell", col_initial_1
    mutations.add(Row.withSchema(uberSchema).withFieldValue("key", "row-setcell".getBytes(StandardCharsets.UTF_8)).withFieldValue("type", "SetCell").withFieldValue("value", "updated_val_1".getBytes(StandardCharsets.UTF_8)).withFieldValue("column_qualifier", "col_initial_1".getBytes(StandardCharsets.UTF_8)).withFieldValue("family_name", COLUMN_FAMILY_NAME_1).withFieldValue("timestamp_micros", 3000L).build());
    // Add new cell to "row-setcell"
    mutations.add(Row.withSchema(uberSchema).withFieldValue("key", "row-setcell".getBytes(StandardCharsets.UTF_8)).withFieldValue("type", "SetCell").withFieldValue("value", "new_col_val".getBytes(StandardCharsets.UTF_8)).withFieldValue("column_qualifier", "new_col_A".getBytes(StandardCharsets.UTF_8)).withFieldValue("family_name", COLUMN_FAMILY_NAME_1).withFieldValue("timestamp_micros", 4000L).build());
    // 2. DeleteFromColumn
    // Delete "col_to_delete_A" from "row-delete-col"
    mutations.add(Row.withSchema(uberSchema).withFieldValue("key", "row-delete-col".getBytes(StandardCharsets.UTF_8)).withFieldValue("type", "DeleteFromColumn").withFieldValue("column_qualifier", "col_to_delete_A".getBytes(StandardCharsets.UTF_8)).withFieldValue("family_name", COLUMN_FAMILY_NAME_1).build());
    // 3. DeleteFromColumn with Timestamp Range
    // Delete "ts_col" with timestamp 1000 from "row-delete-col-ts"
    mutations.add(Row.withSchema(uberSchema).withFieldValue("key", "row-delete-col-ts".getBytes(StandardCharsets.UTF_8)).withFieldValue("type", "DeleteFromColumn").withFieldValue("column_qualifier", "ts_col".getBytes(StandardCharsets.UTF_8)).withFieldValue("family_name", COLUMN_FAMILY_NAME_1).withFieldValue("start_timestamp_micros", // Inclusive
    999L).withFieldValue("end_timestamp_micros", // Exclusive
    1001L).build());
    // 4. DeleteFromFamily
    // Delete COLUMN_FAMILY_NAME_1 from "row-delete-family"
    mutations.add(Row.withSchema(uberSchema).withFieldValue("key", "row-delete-family".getBytes(StandardCharsets.UTF_8)).withFieldValue("type", "DeleteFromFamily").withFieldValue("family_name", COLUMN_FAMILY_NAME_1).build());
    // 5. DeleteFromRow
    // Delete "row-delete-row"
    mutations.add(Row.withSchema(uberSchema).withFieldValue("key", "row-delete-row".getBytes(StandardCharsets.UTF_8)).withFieldValue("type", "DeleteFromRow").build());
    // --- Apply the mutations --
    PCollection<Row> inputPCollection = p.apply(Create.of(mutations));
    // Set the comprehensive schema for the PCollection
    inputPCollection.setRowSchema(uberSchema);
    // Use the schema-set PCollection
    PCollectionRowTuple.of("input", inputPCollection).apply(writeTransform);
    p.run().waitUntilFinish();
    // --- Assertions: Verify the final state of the table ---
    List<com.google.cloud.bigtable.data.v2.models.Row> rows = dataClient.readRows(Query.create(tableId)).stream().collect(Collectors.toList());
    // Expecting 'row-setcell', 'row-delete-col', 'row-delete-col-ts',
    assertEquals(5, rows.size());
    // 'row-final-check'
    // Verify "row-setcell"
    com.google.cloud.bigtable.data.v2.models.Row rowSetCell = rows.stream().filter(r -> r.getKey().toStringUtf8().equals("row-setcell")).findFirst().orElse(null);
    assertEquals("row-setcell", rowSetCell.getKey().toStringUtf8());
    List<RowCell> cellsSetCellCol1 = rowSetCell.getCells(COLUMN_FAMILY_NAME_1, "col_initial_1").stream().sorted(RowCell.compareByNative()).collect(Collectors.toList());
    // Original + updated
    assertEquals(2, cellsSetCellCol1.size());
    assertEquals("initial_val_1", // Newest value
    cellsSetCellCol1.get(0).getValue().toStringUtf8());
    assertEquals("updated_val_1", // Oldest value
    cellsSetCellCol1.get(1).getValue().toStringUtf8());
    List<RowCell> cellsSetCellNewCol = rowSetCell.getCells(COLUMN_FAMILY_NAME_1, "new_col_A");
    assertEquals(1, cellsSetCellNewCol.size());
    assertEquals("new_col_val", cellsSetCellNewCol.get(0).getValue().toStringUtf8());
    List<RowCell> cellsSetCellCol2 = rowSetCell.getCells(COLUMN_FAMILY_NAME_2, "col_initial_2");
    assertEquals(1, cellsSetCellCol2.size());
    assertEquals("initial_val_2", cellsSetCellCol2.get(0).getValue().toStringUtf8());
    // Verify "row-delete-col"
    com.google.cloud.bigtable.data.v2.models.Row rowDeleteCol = rows.stream().filter(r -> r.getKey().toStringUtf8().equals("row-delete-col")).findFirst().orElse(null);
    assertEquals("row-delete-col", rowDeleteCol.getKey().toStringUtf8());
    List<RowCell> cellsColToDeleteA = rowDeleteCol.getCells(COLUMN_FAMILY_NAME_1, "col_to_delete_A");
    // Should be deleted
    assertTrue(cellsColToDeleteA.isEmpty());
    List<RowCell> cellsColToKeepB = rowDeleteCol.getCells(COLUMN_FAMILY_NAME_1, "col_to_keep_B");
    assertEquals(1, cellsColToKeepB.size());
    assertEquals("val_to_keep_B", cellsColToKeepB.get(0).getValue().toStringUtf8());
    // Verify "row-delete-col-ts"
    com.google.cloud.bigtable.data.v2.models.Row rowDeleteColTs = rows.stream().filter(r -> r.getKey().toStringUtf8().equals("row-delete-col-ts")).findFirst().orElse(null);
    assertEquals("row-delete-col-ts", rowDeleteColTs.getKey().toStringUtf8());
    List<RowCell> cellsTsCol = rowDeleteColTs.getCells(COLUMN_FAMILY_NAME_1, "ts_col");
    // Only the 2000 timestamp cell should remain
    assertEquals(1, cellsTsCol.size());
    assertEquals("ts_val_new", cellsTsCol.get(0).getValue().toStringUtf8());
    assertEquals(2000, cellsTsCol.get(0).getTimestamp());
    List<RowCell> cellsTsColOtherCf = rowDeleteColTs.getCells(COLUMN_FAMILY_NAME_2, "ts_col_other_cf");
    assertEquals(1, cellsTsColOtherCf.size());
    assertEquals("ts_val_other_cf", cellsTsColOtherCf.get(0).getValue().toStringUtf8());
    // Verify "row-delete-family"
    com.google.cloud.bigtable.data.v2.models.Row rowDeleteFamily = rows.stream().filter(r -> r.getKey().toStringUtf8().equals("row-delete-family")).findFirst().orElse(null);
    assertEquals("row-delete-family", rowDeleteFamily.getKey().toStringUtf8());
    List<RowCell> cellsCf1 = rowDeleteFamily.getCells(COLUMN_FAMILY_NAME_1);
    // COLUMN_FAMILY_NAME_1 should be empty
    assertTrue(cellsCf1.isEmpty());
    List<RowCell> cellsCf2 = rowDeleteFamily.getCells(COLUMN_FAMILY_NAME_2);
    assertEquals(1, cellsCf2.size());
    assertEquals("val_keep_family", cellsCf2.get(0).getValue().toStringUtf8());
    // Verify "row-delete-row" is gone
    assertTrue(rows.stream().noneMatch(r -> r.getKey().toStringUtf8().equals("row-delete-row")));
    // Verify "row-final-check" still exists
    com.google.cloud.bigtable.data.v2.models.Row rowFinalCheck = rows.stream().filter(r -> r.getKey().toStringUtf8().equals("row-final-check")).findFirst().orElse(null);
    assertEquals("row-final-check", rowFinalCheck.getKey().toStringUtf8());
    List<RowCell> cellsFinalCheck = rowFinalCheck.getCells(COLUMN_FAMILY_NAME_1, "col_final_1");
    assertEquals(1, cellsFinalCheck.size());
    assertEquals("val_final_1", cellsFinalCheck.get(0).getValue().toStringUtf8());
}

@Test
public void testE2EBigtableWrite() throws Exception {
    final int numRows = 1000;
    final List<KV<ByteString, ByteString>> testData = generateTableData(numRows);
    createEmptyTable(tableId);
    Pipeline p = Pipeline.create(options);
    p.apply(GenerateSequence.from(0).to(numRows)).apply(ParDo.of(new DoFn<Long, KV<ByteString, Iterable<Mutation>>>() {

        @ProcessElement
        public void processElement(ProcessContext c) {
            int index = c.element().intValue();
            Iterable<Mutation> mutations = ImmutableList.of(Mutation.newBuilder().setSetCell(Mutation.SetCell.newBuilder().setValue(testData.get(index).getValue()).setFamilyName(COLUMN_FAMILY_NAME)).build());
            c.output(KV.of(testData.get(index).getKey(), mutations));
        }
    })).apply(BigtableIO.write().withProjectId(project).withInstanceId(options.getInstanceId()).withTableId(tableId));
    PipelineResult r = p.run();
    // Test number of column families and column family name equality
    Table table = getTable(tableId);
    assertThat(table.getColumnFamilies(), Matchers.hasSize(1));
    assertThat(table.getColumnFamilies().stream().map((c) -> c.getId()).collect(Collectors.toList()), Matchers.contains(COLUMN_FAMILY_NAME));
    // Test table data equality
    List<KV<ByteString, ByteString>> tableData = getTableData(tableId);
    assertThat(tableData, Matchers.containsInAnyOrder(testData.toArray()));
    checkLineageSinkMetric(r, tableId);
}

