@Test
public void testDeleteCellsFromColumn() {
    RowMutation rowMutation = RowMutation.create(tableId, "key-1").setCell(COLUMN_FAMILY_NAME_1, "col_a", "val-1-a").setCell(COLUMN_FAMILY_NAME_1, "col_b", "val-1-b");
    dataClient.mutateRow(rowMutation);
    // write two cells in col_a. both should get deleted
    rowMutation = RowMutation.create(tableId, "key-1").setCell(COLUMN_FAMILY_NAME_1, "col_a", "new-val-1-a");
    dataClient.mutateRow(rowMutation);
    List<Map<String, byte[]>> mutations = new ArrayList<>();
    // mutation to delete cells from a column
    mutations.add(ImmutableMap.of("type", "DeleteFromColumn".getBytes(StandardCharsets.UTF_8), "column_qualifier", "col_a".getBytes(StandardCharsets.UTF_8), "family_name", COLUMN_FAMILY_NAME_1.getBytes(StandardCharsets.UTF_8)));
