@Test
public void testReadingExistingStreamPartitions() throws InvalidProtocolBufferException {
    ByteStringRange partition1 = ByteStringRange.create("A", "B");
    Instant watermark1 = Instant.now();
    PartitionRecord partitionRecord1 = new PartitionRecord(partition1, watermark1, "1", watermark1, Collections.emptyList(), null);
    metadataTableDao.lockAndRecordPartition(partitionRecord1);
    ByteStringRange partition2 = ByteStringRange.create("B", "D");
    ChangeStreamContinuationToken partition2Token1 = ChangeStreamContinuationToken.create(ByteStringRange.create("B", "C"), "tokenBC");
    ChangeStreamContinuationToken partition2Token2 = ChangeStreamContinuationToken.create(ByteStringRange.create("C", "D"), "tokenCD");
    Instant watermark2 = Instant.now();
    PartitionRecord partitionRecord2 = new PartitionRecord(partition2, Arrays.asList(partition2Token1, partition2Token2), "2", watermark2, Collections.emptyList(), null);
    metadataTableDao.lockAndRecordPartition(partitionRecord2);
    List<PartitionRecord> partitionRecords = metadataTableDao.readAllStreamPartitions();
    assertThat(partitionRecords, containsInAnyOrder(partitionRecord1, partitionRecord2));
    // Update the watermark of partition2
    Instant watermark3 = watermark2.plus(Duration.standardSeconds(10));
    metadataTableDao.updateWatermark(partition2, watermark3, null);
    PartitionRecord partitionRecord2UpdatedWatermark = new PartitionRecord(partition2, Arrays.asList(partition2Token1, partition2Token2), "2", watermark3, Collections.emptyList(), null);
    partitionRecords = metadataTableDao.readAllStreamPartitions();
    assertThat(partitionRecords, containsInAnyOrder(partitionRecord1, partitionRecord2UpdatedWatermark));
    // Update partition1 with new watermark and continuation token
    Instant watermark4 = watermark1.plus(Duration.standardMinutes(1));
    ChangeStreamContinuationToken partition1Token = ChangeStreamContinuationToken.create(partition1, "tokenAB");
    metadataTableDao.updateWatermark(partition1, watermark4, partition1Token);
    PartitionRecord partitionRecord1UpdatedWatermark = new PartitionRecord(partition1, Collections.singletonList(partition1Token), "1", watermark4, Collections.emptyList(), null);
    partitionRecords = metadataTableDao.readAllStreamPartitions();
    assertThat(partitionRecords, containsInAnyOrder(partitionRecord1UpdatedWatermark, partitionRecord2UpdatedWatermark));
    // Release the lock on partition2, the results should be the same.
    metadataTableDao.releaseStreamPartitionLockForDeletion(partition2, partitionRecord2.getUuid());
    partitionRecords = metadataTableDao.readAllStreamPartitions();
    PartitionRecord partitionRecord2NoUuid = new PartitionRecord(partition2, Arrays.asList(partition2Token1, partition2Token2), watermark3, Collections.emptyList());
    assertThat(partitionRecords, containsInAnyOrder(partitionRecord1UpdatedWatermark, partitionRecord2NoUuid));
    // Delete partition2
    metadataTableDao.deleteStreamPartitionRow(partition2);
    partitionRecords = metadataTableDao.readAllStreamPartitions();
    assertThat(partitionRecords, containsInAnyOrder(partitionRecord1UpdatedWatermark));
}

