@Test
public void testManyMutations() throws InterruptedException {
    // Sleep to ensure clock discrepancy between client and server don't affect the start time.
    Thread.sleep(500);
    Instant startTime = Instant.now();
    Thread.sleep(500);
    // test set cell w size > 1MB so it triggers chunking
    char[] chars = new char[1024 * 3];
    // zero-width space
    Arrays.fill(chars, '\u200B');
    String largeString = String.valueOf(chars);
    ImmutableList.Builder<RowMutationEntry> originalWrites = ImmutableList.builder();
    for (int i = 0; i < 100; ++i) {
        String rowKey = "rowKey" + i;
        // SetCell.
        RowMutationEntry setLargeCell = RowMutationEntry.create(rowKey).setCell(COLUMN_FAMILY1, COLUMN_QUALIFIER, largeString);
        // DeleteFamily.
        RowMutationEntry deleteFamily = RowMutationEntry.create(rowKey).deleteFamily(COLUMN_FAMILY1);
        // DeleteCells.
        RowMutationEntry deleteCells = RowMutationEntry.create(rowKey).// need to set timestamp range to make change stream output match
        deleteCells(COLUMN_FAMILY1, ByteString.copyFromUtf8(COLUMN_QUALIFIER), Range.TimestampRange.create(startTime.getMillis() * 1000, startTime.plus(Duration.standardMinutes(2)).getMillis() * 1000));
        // Apply the mutations.
        originalWrites.add(setLargeCell);
        mutationBatcher.add(setLargeCell);
        mutationBatcher.flush();
        originalWrites.add(deleteFamily);
        mutationBatcher.add(deleteFamily);
        mutationBatcher.flush();
        originalWrites.add(deleteCells);
        mutationBatcher.add(deleteCells);
        mutationBatcher.flush();
    }
    Instant endTime = Instant.now().plus(Duration.standardSeconds(10));
    PCollection<MutateRowsRequest.Entry> changeStream = buildPipeline(startTime, endTime);
    PAssert.that(changeStream).containsInAnyOrder(originalWrites.build().stream().map(RowMutationEntry::toProto).collect(Collectors.toList()));
    pipeline.run().waitUntilFinish();
}

@Test
public void testOrphanedNewPartitions() {
    OrphanedMetadataCleaner orphanedMetadataCleaner = new OrphanedMetadataCleaner();
    // Not waiting long enough
    NewPartition newPartition1 = new NewPartition(ByteStringRange.create("A", "B"), Collections.emptyList(), Instant.EPOCH, Instant.now().minus(Duration.standardMinutes(10)));
    orphanedMetadataCleaner.addIncompleteNewPartitions(newPartition1);
    // Orphaned long enough. Should be cleaned up
    NewPartition newPartition2 = new NewPartition(ByteStringRange.create("B", "C"), Collections.emptyList(), Instant.EPOCH, Instant.now().minus(Duration.standardMinutes(15)).minus(Duration.standardSeconds(1)));
    orphanedMetadataCleaner.addIncompleteNewPartitions(newPartition2);
    // Just on the edge of not orphaned long enough
    NewPartition newPartition3 = new NewPartition(ByteStringRange.create("C", "D"), Collections.emptyList(), Instant.EPOCH, Instant.now().minus(Duration.standardMinutes(15)).plus(Duration.standardSeconds(1)));
    orphanedMetadataCleaner.addIncompleteNewPartitions(newPartition3);
    // Orphaned long enough, but it overlaps with a missing partition, so not cleaned up.
    NewPartition newPartition4 = new NewPartition(ByteStringRange.create("D", "F"), Collections.emptyList(), Instant.EPOCH, Instant.now().minus(Duration.standardMinutes(15)).minus(Duration.standardSeconds(1)));
    orphanedMetadataCleaner.addIncompleteNewPartitions(newPartition4);
    List<ByteStringRange> missingPartitions = new ArrayList<>();
    // Haven't called addMissingPartitions, so we don't know if there are any missing partitions.
    assertTrue(orphanedMetadataCleaner.getOrphanedNewPartitions().isEmpty());
    missingPartitions.add(ByteStringRange.create("E", "G"));
    missingPartitions.add(ByteStringRange.create("H", "I"));
    orphanedMetadataCleaner.addMissingPartitions(missingPartitions);
    assertEquals(Collections.singletonList(newPartition2), orphanedMetadataCleaner.getOrphanedNewPartitions());
}

