/**
 * Tests {@link DatastoreWriterFn} with large entities that need to be split into more batches.
 */
@Test
public void testDatastoreWriterFnWithLargeEntities() throws Exception {
    List<Mutation> mutations = new ArrayList<>();
    int entitySize = 0;
    for (int i = 0; i < 12; ++i) {
        Entity entity = Entity.newBuilder().setKey(makeKey("key" + i, i + 1)).putProperties("long", makeValue(new String(new char[900_000])).setExcludeFromIndexes(true).build()).build();
        // Take the size of any one entity.
        entitySize = entity.getSerializedSize();
        mutations.add(makeUpsert(entity).build());
    }
    int entitiesPerRpc = DATASTORE_BATCH_UPDATE_BYTES_LIMIT / entitySize;
    int start = 0;
    ArgumentCaptor<CommitRequest> requestCaptor = ArgumentCaptor.forClass(CommitRequest.class);
    CommitResponse response = CommitResponse.getDefaultInstance();
    while (start < mutations.size()) {
        int end = Math.min(mutations.size(), start + entitiesPerRpc);
        when(mockDatastore.commit(requestCaptor.capture())).thenReturn(response);
        start = end;
    }
    DatastoreWriterFn datastoreWriter = new DatastoreWriterFn(StaticValueProvider.of(PROJECT_ID), null, mockDatastoreFactory, new FakeWriteBatcher());
    DoFnTester<Mutation, DatastoreV1.WriteSuccessSummary> doFnTester = DoFnTester.of(datastoreWriter);
    doFnTester.setCloningBehavior(CloningBehavior.DO_NOT_CLONE);
    doFnTester.processBundle(mutations);
    // This test is over-specific currently; it requires that we split the 12 entity writes into 3
    // requests, but we only need each CommitRequest to be less than 10MB in size.
    start = 0;
    List<CommitRequest> requests = new ArrayList<>();
    while (start < mutations.size()) {
        int end = Math.min(mutations.size(), start + entitiesPerRpc);
        CommitRequest.Builder commitRequest = CommitRequest.newBuilder();
        commitRequest.setProjectId(PROJECT_ID);
        commitRequest.setDatabaseId(DATABASE_ID);
        commitRequest.setMode(CommitRequest.Mode.NON_TRANSACTIONAL);
        commitRequest.addAllMutations(mutations.subList(start, end));
        // Verify all the batch requests were made with the expected mutations.
        CommitRequest expectedRequest = commitRequest.build();
        verify(mockDatastore).commit(expectedRequest);
        requests.add(expectedRequest);
        start = end;
    }
    assertTrue(requestCaptor.getAllValues().containsAll(requests));
}

/**
 * Tests {@link DatastoreWriterFn} correctly flushes batch upon receive same entity keys.
 */
@Test
public void testDatastoreWriterFnWithDuplicateEntities() throws Exception {
    List<Mutation> mutations = new ArrayList<>();
    for (int i : Arrays.asList(0, 1, 0, 2)) {
        // this will generate entities having key 0, 1, 0, 2 and random values
        mutations.add(makeUpsert(Entity.newBuilder().setKey(makeKey("key" + i)).putProperties("value", makeValue(UUID.randomUUID().toString()).build()).build()).build());
    }
    ArgumentCaptor<CommitRequest> requestCaptor = ArgumentCaptor.forClass(CommitRequest.class);
    CommitResponse response = CommitResponse.getDefaultInstance();
    when(mockDatastore.commit(requestCaptor.capture())).thenReturn(response).thenReturn(response);
    DatastoreWriterFn datastoreWriter = new DatastoreWriterFn(StaticValueProvider.of(PROJECT_ID), null, mockDatastoreFactory, new FakeWriteBatcher());
    DoFnTester<Mutation, DatastoreV1.WriteSuccessSummary> doFnTester = DoFnTester.of(datastoreWriter);
    doFnTester.setCloningBehavior(CloningBehavior.DO_NOT_CLONE);
    doFnTester.processBundle(mutations);
    // first invocation has key [0, 1]
    CommitRequest.Builder commitRequest = CommitRequest.newBuilder();
    commitRequest.setMode(CommitRequest.Mode.NON_TRANSACTIONAL);
    commitRequest.addAllMutations(mutations.subList(0, 2));
    commitRequest.setProjectId(PROJECT_ID);
    commitRequest.setDatabaseId(DATABASE_ID);
    CommitRequest expectedRequest1 = commitRequest.build();
    verify(mockDatastore, times(1)).commit(expectedRequest1);
    // second invocation has key [0, 2] because the second 0 triggered a flush batch
    commitRequest = CommitRequest.newBuilder();
    commitRequest.setMode(CommitRequest.Mode.NON_TRANSACTIONAL);
    commitRequest.addAllMutations(mutations.subList(2, 4));
    commitRequest.setProjectId(PROJECT_ID);
    commitRequest.setDatabaseId(DATABASE_ID);
    CommitRequest expectedRequest2 = commitRequest.build();
    verify(mockDatastore, times(1)).commit(expectedRequest2);
    verifyMetricWasSet("BatchDatastoreWrite", "ok", "", 2);
    assertTrue(requestCaptor.getAllValues().containsAll(Arrays.asList(expectedRequest1, expectedRequest2)));
}

/**
 * Tests {@link DatastoreWriterFn} with a failed request which is retried.
 */
@Test
public void testDatastoreWriterFnRetriesErrors() throws Exception {
    List<Mutation> mutations = new ArrayList<>();
    int numRpcs = 2;
    for (int i = 0; i < DatastoreV1.DATASTORE_BATCH_UPDATE_ENTITIES_START * numRpcs; ++i) {
        mutations.add(makeUpsert(Entity.newBuilder().setKey(makeKey("key" + i, i + 1)).build()).build());
    }
    CommitResponse successfulCommit = CommitResponse.getDefaultInstance();
    when(mockDatastore.commit(any(CommitRequest.class))).thenReturn(successfulCommit).thenThrow(new DatastoreException("commit", Code.DEADLINE_EXCEEDED, "", null)).thenReturn(successfulCommit);
    DatastoreWriterFn datastoreWriter = new DatastoreWriterFn(StaticValueProvider.of(PROJECT_ID), null, mockDatastoreFactory, new FakeWriteBatcher());
    DoFnTester<Mutation, DatastoreV1.WriteSuccessSummary> doFnTester = DoFnTester.of(datastoreWriter);
    doFnTester.setCloningBehavior(CloningBehavior.DO_NOT_CLONE);
    doFnTester.processBundle(mutations);
    verifyMetricWasSet("BatchDatastoreWrite", "ok", "", 2);
    verifyMetricWasSet("BatchDatastoreWrite", "unknown", "", 1);
}

