    PCollection<String> actualCollectionIds = testPipeline.apply(Create.of("")).apply(getListCollectionIdsPTransform(testName.getMethodName())).apply(FirestoreIO.v1().read().listCollectionIds().withRpcQosOptions(RPC_QOS_OPTIONS).build());
    PAssert.that(actualCollectionIds).containsInAnyOrder(allCollectionIds);
