@Test
public void fromPubsubSchema() {
    assertThrows("null definition should throw an exception", NullPointerException.class, () -> PubsubClient.fromPubsubSchema(new com.google.api.services.pubsub.model.Schema().setType("AVRO")));
    assertThrows("null definition should throw an exception", SchemaParseException.class, () -> PubsubClient.fromPubsubSchema(com.google.pubsub.v1.Schema.newBuilder().setType(Schema.Type.AVRO).build()));
    String badSchema = "{\"type\": \"record\", \"name\": \"Avro\",\"fields\": [{\"name\": \"bad\", \"type\": \"notatype\"}]}";
    String goodSchema = "{" + " \"type\" : \"record\"," + " \"name\" : \"Avro\"," + " \"fields\" : [" + "   {" + "     \"name\" : \"StringField\"," + "     \"type\" : \"string\"" + "   }," + "   {" + "     \"name\" : \"FloatField\"," + "     \"type\" : \"float\"" + "   }," + "   {" + "     \"name\" : \"IntField\"," + "     \"type\" : \"int\"" + "   }," + "   {" + "     \"name\" : \"LongField\"," + "     \"type\" : \"long\"" + "   }," + "   {" + "     \"name\" : \"DoubleField\"," + "     \"type\" : \"double\"" + "   }," + "   {" + "     \"name\" : \"BytesField\"," + "     \"type\" : \"bytes\"" + "   }," + "   {" + "     \"name\" : \"BooleanField\"," + "     \"type\" : \"boolean\"" + "   }" + " ]" + "}";
    assertThrows("unsupported Schema type should throw an exception", IllegalArgumentException.class, () -> PubsubClient.fromPubsubSchema(new com.google.api.services.pubsub.model.Schema().setType("PROTOCOL_BUFFER").setDefinition(goodSchema)));
    assertThrows("'notatype' Avro type should throw an exception", SchemaParseException.class, () -> PubsubClient.fromPubsubSchema(new com.google.api.services.pubsub.model.Schema().setType("AVRO").setDefinition(badSchema)));
    assertEquals(org.apache.beam.sdk.schemas.Schema.of(org.apache.beam.sdk.schemas.Schema.Field.of("StringField", org.apache.beam.sdk.schemas.Schema.FieldType.STRING), org.apache.beam.sdk.schemas.Schema.Field.of("FloatField", org.apache.beam.sdk.schemas.Schema.FieldType.FLOAT), org.apache.beam.sdk.schemas.Schema.Field.of("IntField", org.apache.beam.sdk.schemas.Schema.FieldType.INT32), org.apache.beam.sdk.schemas.Schema.Field.of("LongField", org.apache.beam.sdk.schemas.Schema.FieldType.INT64), org.apache.beam.sdk.schemas.Schema.Field.of("DoubleField", org.apache.beam.sdk.schemas.Schema.FieldType.DOUBLE), org.apache.beam.sdk.schemas.Schema.Field.of("BytesField", org.apache.beam.sdk.schemas.Schema.FieldType.BYTES), org.apache.beam.sdk.schemas.Schema.Field.of("BooleanField", org.apache.beam.sdk.schemas.Schema.FieldType.BOOLEAN)), PubsubClient.fromPubsubSchema(new com.google.api.services.pubsub.model.Schema().setType("AVRO").setDefinition(goodSchema)));
}

@Test
public void pullOneMessage() throws IOException {
    initializeClient(null, null);
    String expectedSubscription = SUBSCRIPTION.getPath();
    final PullRequest expectedRequest = PullRequest.newBuilder().setSubscription(expectedSubscription).setReturnImmediately(true).setMaxMessages(10).build();
    Timestamp timestamp = Timestamp.newBuilder().setSeconds(PUB_TIME_MS / 1000).setNanos((int) (PUB_TIME_MS % 1000) * 1000 * 1000).build();
    PubsubMessage expectedPubsubMessage = PubsubMessage.newBuilder().setMessageId(MESSAGE_ID).setData(ByteString.copyFrom(DATA.getBytes(StandardCharsets.UTF_8))).setPublishTime(timestamp).build();
    ReceivedMessage expectedReceivedMessage = ReceivedMessage.newBuilder().setMessage(expectedPubsubMessage).setAckId(ACK_ID).build();
    final PullResponse response = PullResponse.newBuilder().addAllReceivedMessages(ImmutableList.of(expectedReceivedMessage)).build();
    final List<PullRequest> requestsReceived = new ArrayList<>();
    SubscriberImplBase subscriberImplBase = new SubscriberImplBase() {

        @Override
        public void pull(PullRequest request, StreamObserver<PullResponse> responseObserver) {
            requestsReceived.add(request);
            responseObserver.onNext(response);
            responseObserver.onCompleted();
        }
    };
    Server server = InProcessServerBuilder.forName(channelName).addService(subscriberImplBase).build().start();
    try {
        List<IncomingMessage> actualMessages = client.pull(REQ_TIME_MS, SUBSCRIPTION, 10, true);
        assertEquals(1, actualMessages.size());
        IncomingMessage actualMessage = actualMessages.get(0);
        assertEquals(ACK_ID, actualMessage.ackId());
        assertEquals(DATA, actualMessage.message().getData().toStringUtf8());
        assertEquals(MESSAGE_ID, actualMessage.recordId());
        assertEquals(REQ_TIME_MS, actualMessage.requestTimeMsSinceEpoch());
        assertEquals(PUB_TIME_MS, actualMessage.timestampMsSinceEpoch());
        assertEquals(expectedRequest, Iterables.getOnlyElement(requestsReceived));
    } finally {
        server.shutdownNow();
    }
}

