@Test
public void testBoundedWriteMessageWithAttributesAndOrderingKey() throws IOException {
    TopicPath testTopicPath = PubsubClient.topicPathFromName(project, "pubsub-write-ordering-key-" + Instant.now().getMillis());
    pubsubClient.createTopic(testTopicPath);
    SubscriptionPath testSubscriptionPath = pubsubClient.createRandomSubscription(PubsubClient.projectPathFromId(project), testTopicPath, 10);
    // U+1F9EA
    byte[] payload = new byte[] { -16, -97, -89, -86 };
    // Messages with and without ordering keys can be mixed together in a collection. The writer
    // ensures that a publish request only sends message batches with the same ordering key,
    // otherwise the Pub/Sub service will reject the request.
    // Outgoing messages may specify either null or empty string to represent messages without
    // ordering keys, but Protobuf treats strings as primitives so we explicitly use empty string in
    // this test for the round trip assertion.
    Map<String, PubsubMessage> outgoingMessages = new HashMap<>();
    outgoingMessages.put("0", new PubsubMessage(payload, ImmutableMap.of("id", "0")).withOrderingKey(// No ordering key
    ""));
    outgoingMessages.put("1", new PubsubMessage(payload, ImmutableMap.of("id", "1")).withOrderingKey(// Repeated ordering key
    "12"));
    outgoingMessages.put("2", new PubsubMessage(payload, ImmutableMap.of("id", "2")).withOrderingKey(// Repeated ordering key
    "12"));
    outgoingMessages.put("3", new PubsubMessage(payload, ImmutableMap.of("id", "3")).withOrderingKey(// Distinct ordering key
    "3"));
    pipeline.apply(Create.of(ImmutableList.copyOf(outgoingMessages.values())).withCoder(PubsubMessageSchemaCoder.getSchemaCoder())).apply(PubsubIO.writeMessages().withOrderingKey().to(testTopicPath.getPath()));
    pipeline.run().waitUntilFinish();
    // sometimes the first pull comes up short. try 4 pulls to avoid flaky false-negatives
    int numPulls = 0;
    while (!outgoingMessages.isEmpty()) {
        boolean emptyOrDuplicatePull = true;
        List<IncomingMessage> incomingMessages = pubsubClient.pull(Instant.now().getMillis(), testSubscriptionPath, 4, true);
        for (IncomingMessage incomingMessage : incomingMessages) {
            com.google.pubsub.v1.PubsubMessage message = incomingMessage.message();
            @Nullable
            PubsubMessage outgoingMessage = outgoingMessages.remove(message.getAttributesMap().get("id"));
            if (outgoingMessage != null) {
                emptyOrDuplicatePull = false;
                assertEquals(UnsafeByteOperations.unsafeWrap(outgoingMessage.getPayload()), message.getData());
                assertEquals(outgoingMessage.getAttributeMap(), message.getAttributesMap());
                assertEquals(outgoingMessage.getOrderingKey(), message.getOrderingKey());
            }
        }
        if (emptyOrDuplicatePull && ++numPulls > 4) {
            throw new RuntimeException(String.format("Pulled %s times from PubSub but retrieved no expected elements.", numPulls));
        }
    }
    pubsubClient.deleteSubscription(testSubscriptionPath);
    pubsubClient.deleteTopic(testTopicPath);
}

