    doReturn(minBlock).when(limiter).minBlockSize();
    for (int i = 0; i < 1000; ++i) {
        // Rebuffer many times with no data to bring down the target value
        bufferedSubscriber.rebuffer();
    }
    reset(limiter);
    doReturn(minBlock).when(limiter).minBlockSize();
