    "{\"SingerId\":\"0\"},DELETE\n", // Second batch of transactions.
    // Insert Singer 1 and 2 into the table,
    "{\"SingerId\":\"1\"}{\"SingerId\":\"2\"},INSERT\n" + // Delete Singer 1 and Insert Singer 3 into the table.
    "{\"SingerId\":\"1\"},DELETE\n" + "{\"SingerId\":\"3\"},INSERT\n" + // Delete Singers 2 and 3.
