@Test
public // Error code UNAVAILABLE is retried repeatedly until the RPC times out.
void testUnavailableExceptionRetries() throws InterruptedException {
    DirectOptions options = PipelineOptionsFactory.as(DirectOptions.class);
    options.setBlockOnRun(false);
    options.setRunner(DirectRunner.class);
    Pipeline nonBlockingPipeline = TestPipeline.create(options);
    mockSpannerService.setExecuteStreamingSqlExecutionTime(SimulatedExecutionTime.ofStickyException(Status.UNAVAILABLE.asRuntimeException()));
    final Timestamp startTimestamp = Timestamp.ofTimeSecondsAndNanos(0, 1000);
    final Timestamp endTimestamp = Timestamp.ofTimeSecondsAndNanos(startTimestamp.getSeconds(), startTimestamp.getNanos() + 1);
    try {
        nonBlockingPipeline.apply(SpannerIO.readChangeStream().withSpannerConfig(getSpannerConfig()).withChangeStreamName(TEST_CHANGE_STREAM).withMetadataDatabase(TEST_DATABASE).withMetadataTable(TEST_TABLE).withInclusiveStartAt(startTimestamp).withInclusiveEndAt(endTimestamp));
        PipelineResult result = nonBlockingPipeline.run();
        while (result.getState() != RUNNING) {
            Thread.sleep(50);
        }
        // The pipeline continues making requests to Spanner to retry the Unavailable errors.
        assertNull(result.waitUntilFinish(Duration.millis(500)));
    } finally {
        // databaseClient.getDialect does not currently bubble up the correct message.
        // Instead, the error returned is: "DEADLINE_EXCEEDED: Operation did not complete "
        // "in the given time"
        thrown.expectMessage("DEADLINE_EXCEEDED");
        assertThat(mockSpannerService.countRequestsOfType(ExecuteSqlRequest.class), Matchers.equalTo(0));
    }
}

