@Test
public void testSpannerReadValidations() {
    // Missing instanceId should throw
    assertThrows(IllegalStateException.class, () -> {
        SpannerReadSchemaTransformConfiguration.builder().setDatabaseId("db").setTableId("table").build().validate();
    });
    // Missing databaseId should throw
    assertThrows(IllegalStateException.class, () -> {
        SpannerReadSchemaTransformConfiguration.builder().setInstanceId("instance").setTableId("table").build().validate();
    });
    // Missing both tableId and query should throw
    assertThrows(IllegalArgumentException.class, () -> {
        SpannerReadSchemaTransformConfiguration.builder().setInstanceId("instance").setDatabaseId("db").build().validate();
    });
    // TableId without columns should throw
    assertThrows(IllegalArgumentException.class, () -> {
        SpannerReadSchemaTransformConfiguration.builder().setInstanceId("instance").setDatabaseId("db").setTableId("table").build().validate();
    });
    // Valid table-based read config
    SpannerReadSchemaTransformConfiguration.builder().setInstanceId("instance").setDatabaseId("db").setTableId("table").setColumns(Arrays.asList("col1")).build().validate();
    // Valid query-based config
    SpannerReadSchemaTransformConfiguration.builder().setInstanceId("instance").setDatabaseId("db").setQuery("SELECT * FROM table").build().validate();
    // Both query and tableId provided – should throw if mutually exclusive
    assertThrows(IllegalArgumentException.class, () -> {
        SpannerReadSchemaTransformConfiguration.builder().setInstanceId("instance").setDatabaseId("db").setQuery("SELECT * FROM table").setTableId("table").build().validate();
    });
}

