@Test
public void testErrorFnCapturesStructFailureAsRow() {
    Struct badStruct = Struct.newBuilder().set("non_existing_field").to(Value.string("bad_value")).build();
    // Define a mismatched schema (does not match the struct)
    // "id" not in struct
    Schema expectedSchema = Schema.builder().addStringField("id").build();
    TupleTag<Row> outputTag = SpannerReadSchemaTransformProvider.OUTPUT_TAG;
    TupleTag<Row> errorTag = SpannerReadSchemaTransformProvider.ERROR_TAG;
    PCollection<Struct> spannerRows = pipeline.apply("CreateBadStruct", Create.of(badStruct));
    PCollectionTuple result = spannerRows.apply(ParDo.of(new SpannerReadSchemaTransformProvider.ErrorFn("test-counter", SpannerReadSchemaTransformProvider.ERROR_SCHEMA, expectedSchema, true)).withOutputTags(outputTag, TupleTagList.of(errorTag)));
    result.get(outputTag).setRowSchema(expectedSchema);
    PCollection<Row> errorOutput = result.get(errorTag).setRowSchema(SpannerReadSchemaTransformProvider.ERROR_SCHEMA);
    PAssert.that(errorOutput).satisfies(rows -> {
        if (!rows.iterator().hasNext()) {
            throw new AssertionError("Expected at least one error row but got none.");
        }
        Row errorRow = rows.iterator().next();
        String errorMsg = errorRow.getString("error");
        String rowString = errorRow.getString("row");
        assert errorMsg != null && errorMsg.contains("Field not found: id") : "Missing expected error message. Got: " + errorMsg;
        assert rowString != null && rowString.contains("bad_value") : "Row string does not contain expected content. Got: " + rowString;
        return null;
    });
    pipeline.run().waitUntilFinish();
}

