@Test
public void testMatchForRecursiveGlob() throws Exception {
    create("1/testFile1", "testData1".getBytes(StandardCharsets.UTF_8));
    create("1/A/testFile1A", "testData1A".getBytes(StandardCharsets.UTF_8));
    create("1/A/A/testFile1AA", "testData1AA".getBytes(StandardCharsets.UTF_8));
    create("1/B/testFile1B", "testData1B".getBytes(StandardCharsets.UTF_8));
    // ensure files exist
    assertArrayEquals("testData1".getBytes(StandardCharsets.UTF_8), read("1/testFile1", 0));
    assertArrayEquals("testData1A".getBytes(StandardCharsets.UTF_8), read("1/A/testFile1A", 0));
    assertArrayEquals("testData1AA".getBytes(StandardCharsets.UTF_8), read("1/A/A/testFile1AA", 0));
    assertArrayEquals("testData1B".getBytes(StandardCharsets.UTF_8), read("1/B/testFile1B", 0));
    List<MatchResult> matchResults = fileSystem.match(ImmutableList.of(testPath("**testFile1*").toString()));
    assertThat(matchResults, hasSize(1));
    assertThat(Iterables.getOnlyElement(matchResults).metadata(), containsInAnyOrder(Metadata.builder().setResourceId(testPath("1/testFile1")).setIsReadSeekEfficient(true).setSizeBytes("testData1".getBytes(StandardCharsets.UTF_8).length).setLastModifiedMillis(lastModified("1/testFile1")).build(), Metadata.builder().setResourceId(testPath("1/A/testFile1A")).setIsReadSeekEfficient(true).setSizeBytes("testData1A".getBytes(StandardCharsets.UTF_8).length).setLastModifiedMillis(lastModified("1/A/testFile1A")).build(), Metadata.builder().setResourceId(testPath("1/A/A/testFile1AA")).setIsReadSeekEfficient(true).setSizeBytes("testData1AA".getBytes(StandardCharsets.UTF_8).length).setLastModifiedMillis(lastModified("1/A/A/testFile1AA")).build(), Metadata.builder().setResourceId(testPath("1/B/testFile1B")).setIsReadSeekEfficient(true).setSizeBytes("testData1B".getBytes(StandardCharsets.UTF_8).length).setLastModifiedMillis(lastModified("1/B/testFile1B")).build()));
    matchResults = fileSystem.match(ImmutableList.of(testPath("1**File1A").toString(), testPath("1**A**testFile1AA").toString(), testPath("1/B**").toString(), testPath("2**").toString()));
    final List<MatchResult> expected = ImmutableList.of(MatchResult.create(Status.OK, ImmutableList.of(Metadata.builder().setResourceId(testPath("1/A/testFile1A")).setIsReadSeekEfficient(true).setSizeBytes("testData1A".getBytes(StandardCharsets.UTF_8).length).setLastModifiedMillis(lastModified("1/A/testFile1A")).build())), MatchResult.create(Status.OK, ImmutableList.of(Metadata.builder().setResourceId(testPath("1/A/A/testFile1AA")).setIsReadSeekEfficient(true).setSizeBytes("testData1AA".getBytes(StandardCharsets.UTF_8).length).setLastModifiedMillis(lastModified("1/A/A/testFile1AA")).build())), MatchResult.create(Status.OK, ImmutableList.of(Metadata.builder().setResourceId(testPath("1/B/testFile1B")).setIsReadSeekEfficient(true).setSizeBytes("testData1B".getBytes(StandardCharsets.UTF_8).length).setLastModifiedMillis(lastModified("1/B/testFile1B")).build())), MatchResult.create(Status.NOT_FOUND, ImmutableList.of()));
    assertThat(matchResults, hasSize(4));
    assertThat(matchResults, equalTo(expected));
}

