@Test
public void testWritesPuts() throws Exception {
    Table table = TestHBaseUtils.createTable(htu);
    // Write two cells in one row mutations object
    RowMutations rowMutationsOnTwoColumnFamilies = new RowMutations(rowKey);
    rowMutationsOnTwoColumnFamilies.add(TestHBaseUtils.HBaseMutationBuilder.createPut(rowKey, colFamily, colQualifier, value, timeT));
    rowMutationsOnTwoColumnFamilies.add(TestHBaseUtils.HBaseMutationBuilder.createPut(rowKey, colFamily2, colQualifier2, value2, timeT));
    // Two mutations on same cell, later one should overwrite earlier one
    RowMutations overwritingRowMutations = new RowMutations(rowKey2);
    overwritingRowMutations.add(TestHBaseUtils.HBaseMutationBuilder.createPut(rowKey2, colFamily, colQualifier, value, timeT));
    overwritingRowMutations.add(// Overwrites previous mutation
    TestHBaseUtils.HBaseMutationBuilder.createPut(rowKey2, colFamily, colQualifier, value2, timeT));
    pipeline.apply("Create row mutations", Create.of(KV.of(rowKey, rowMutationsOnTwoColumnFamilies), KV.of(rowKey2, overwritingRowMutations))).apply("Write to hbase", HBaseIO.writeRowMutations().withConfiguration(htu.getConfiguration()).withTableId(table.getName().getNameAsString()));
    pipeline.run().waitUntilFinish();
    Assert.assertEquals(2, TestHBaseUtils.getRowResult(table, rowKey).size());
    Assert.assertArrayEquals(value, TestHBaseUtils.getCell(table, rowKey, colFamily, colQualifier));
    Assert.assertArrayEquals(value2, TestHBaseUtils.getCell(table, rowKey, colFamily2, colQualifier2));
    Assert.assertEquals(1, TestHBaseUtils.getRowResult(table, rowKey2).size());
    Assert.assertArrayEquals(value2, TestHBaseUtils.getCell(table, rowKey2, colFamily, colQualifier));
}

@Test
public void testWritesDeletes() throws Exception {
    Table table = TestHBaseUtils.createTable(htu);
    // Expect deletes to result in empty row.
    RowMutations deleteCellMutation = new RowMutations(rowKey);
    deleteCellMutation.add(TestHBaseUtils.HBaseMutationBuilder.createPut(rowKey, colFamily, colQualifier, value, timeT));
    deleteCellMutation.add(TestHBaseUtils.HBaseMutationBuilder.createDelete(rowKey, colFamily, colQualifier, timeT));
    // Expect delete family to delete entire row.
    RowMutations deleteColFamilyMutation = new RowMutations(rowKey2);
    deleteColFamilyMutation.add(TestHBaseUtils.HBaseMutationBuilder.createPut(rowKey2, colFamily, colQualifier, value, timeT));
    deleteColFamilyMutation.add(TestHBaseUtils.HBaseMutationBuilder.createPut(rowKey2, colFamily, colQualifier2, value2, timeT));
    deleteColFamilyMutation.add(TestHBaseUtils.HBaseMutationBuilder.createDeleteFamily(rowKey2, colFamily, Long.MAX_VALUE));
    pipeline.apply("Create row mutations", Create.of(KV.of(rowKey, deleteCellMutation), KV.of(rowKey2, deleteColFamilyMutation))).apply("Write to hbase", HBaseIO.writeRowMutations().withConfiguration(htu.getConfiguration()).withTableId(table.getName().getNameAsString()));
    pipeline.run().waitUntilFinish();
    Assert.assertTrue(TestHBaseUtils.getRowResult(table, rowKey).isEmpty());
    Assert.assertTrue(TestHBaseUtils.getRowResult(table, rowKey2).isEmpty());
}

@Test
public void testWritesDeletesThenPutsInOrderByTimestamp() throws Exception {
    Table table = TestHBaseUtils.createTable(htu);
    // RowMutations entry ordering does not guarantee mutation ordering, as Hbase operations
    // are ordered by timestamp. See https://issues.apache.org/jira/browse/HBASE-2256
    RowMutations putDeletePut = new RowMutations(rowKey);
    putDeletePut.add(TestHBaseUtils.HBaseMutationBuilder.createPut(rowKey, colFamily, colQualifier, value, timeT));
    putDeletePut.add(TestHBaseUtils.HBaseMutationBuilder.createDeleteFamily(rowKey, colFamily, timeT + 1));
    putDeletePut.add(TestHBaseUtils.HBaseMutationBuilder.createPut(rowKey, colFamily, colQualifier, value2, timeT + 2));
    pipeline.apply("Create row mutations", Create.of(KV.of(rowKey, putDeletePut))).apply("Write to hbase", HBaseIO.writeRowMutations().withConfiguration(htu.getConfiguration()).withTableId(table.getName().getNameAsString()));
    pipeline.run().waitUntilFinish();
    Assert.assertArrayEquals(value2, TestHBaseUtils.getCell(table, rowKey, colFamily, colQualifier));
}

