@Test
public void testScanFiles() throws IOException {
    Schema schema = new Schema(required(1, "id", Types.IntegerType.get()), required(2, "str", Types.StringType.get()));
    Table table = warehouse.createTable(TableIdentifier.parse("default.table"), schema);
    List<Record> recs = IntStream.range(0, 100).mapToObj(i -> {
        GenericRecord rec = GenericRecord.create(schema);
        rec.setField("id", i);
        rec.setField("str", "value_" + i);
        return rec;
    }).collect(Collectors.toList());
    ImmutableList<DataFile> files = ImmutableList.of(warehouse.writeRecords("file_0.parquet", schema, recs.subList(0, 10)), warehouse.writeRecords("file_10.parquet", schema, recs.subList(10, 20)), warehouse.writeRecords("file_20.parquet", schema, recs.subList(20, 30)), warehouse.writeRecords("file_30.parquet", schema, recs.subList(30, 40)), warehouse.writeRecords("file_40.parquet", schema, recs.subList(40, 50)), warehouse.writeRecords("file_50.parquet", schema, recs.subList(50, 60)), warehouse.writeRecords("file_60.parquet", schema, recs.subList(60, 70)), warehouse.writeRecords("file_70.parquet", schema, recs.subList(70, 80)), warehouse.writeRecords("file_80.parquet", schema, recs.subList(80, 90)), warehouse.writeRecords("file_90.parquet", schema, recs.subList(90, 100)));
    AppendFiles append = table.newAppend();
    files.forEach(append::appendFile);
    append.commit();
    TableScan scan = table.newScan().project(schema).filter(FilterUtils.convert("\"id\" < 58", schema));
    Set<String> expectedFiles = ImmutableSet.of("file_0.parquet", "file_10.parquet", "file_20.parquet", "file_30.parquet", "file_40.parquet", "file_50.parquet");
    ImmutableSet.Builder<String> actualFiles = ImmutableSet.builder();
    for (FileScanTask task : scan.planFiles()) {
        String fileName = Iterables.getLast(Splitter.on('/').split(task.file().path().toString()));
        actualFiles.add(fileName);
    }
    assertEquals(expectedFiles, actualFiles.build());
}

