@Test
public void testSimpleScan() throws Exception {
    String identifier = "default.table_" + Long.toString(UUID.randomUUID().hashCode(), 16);
    TableIdentifier tableId = TableIdentifier.parse(identifier);
    Table simpleTable = warehouse.createTable(tableId, TestFixtures.SCHEMA);
    final Schema schema = IcebergUtils.icebergSchemaToBeamSchema(TestFixtures.SCHEMA);
    List<List<Record>> expectedRecords = warehouse.commitData(simpleTable);
    Map<String, String> properties = new HashMap<>();
    properties.put("type", CatalogUtil.ICEBERG_CATALOG_TYPE_HADOOP);
    properties.put("warehouse", warehouse.location);
    Configuration.Builder readConfigBuilder = Configuration.builder().setTable(identifier).setCatalogName("name").setCatalogProperties(properties).setStartingStrategy("earliest").setToSnapshot(simpleTable.currentSnapshot().snapshotId());
    final List<Row> expectedRows = expectedRecords.stream().flatMap(List::stream).map(record -> IcebergUtils.icebergRecordToBeamRow(schema, record)).collect(Collectors.toList());
    PCollection<Row> output = PCollectionRowTuple.empty(testPipeline).apply(new IcebergCdcReadSchemaTransformProvider().from(readConfigBuilder.build())).getSinglePCollection();
    assertThat(output.isBounded(), equalTo(BOUNDED));
    PAssert.that(output).containsInAnyOrder(expectedRows);
    testPipeline.run();
}

@Test
public void testStreamingReadUsingManagedTransform() throws Exception {
    String identifier = "default.table_" + Long.toString(UUID.randomUUID().hashCode(), 16);
    TableIdentifier tableId = TableIdentifier.parse(identifier);
    Table simpleTable = warehouse.createTable(tableId, TestFixtures.SCHEMA);
    final Schema schema = IcebergUtils.icebergSchemaToBeamSchema(TestFixtures.SCHEMA);
    List<List<Record>> expectedRecords = warehouse.commitData(simpleTable).subList(3, 9);
    List<Snapshot> snapshots = Lists.newArrayList(simpleTable.snapshots());
    long second = snapshots.get(1).snapshotId();
    long third = snapshots.get(2).snapshotId();
    String yamlConfig = String.format("table: %s\n" + "catalog_name: test-name\n" + "catalog_properties: \n" + "  type: %s\n" + "  warehouse: %s\n" + "from_snapshot: %s\n" + "to_snapshot: %s\n" + "streaming: true", identifier, CatalogUtil.ICEBERG_CATALOG_TYPE_HADOOP, warehouse.location, second, third);
    final List<Row> expectedRows = expectedRecords.stream().flatMap(List::stream).map(record -> IcebergUtils.icebergRecordToBeamRow(schema, record)).collect(Collectors.toList());
    Map<String, Object> configMap = new Yaml().load(yamlConfig);
    PCollection<Row> output = testPipeline.apply(Managed.read(Managed.ICEBERG_CDC).withConfig(configMap)).getSinglePCollection();
    assertThat(output.isBounded(), equalTo(UNBOUNDED));
    PAssert.that(output).containsInAnyOrder(expectedRows);
    testPipeline.run();
}

