@Test
public void testProjectedSchema() {
    org.apache.iceberg.Schema original = new org.apache.iceberg.Schema(required(1, "a", StringType.get()), required(2, "b", StructType.of(required(5, "b.a", StringType.get()))), required(3, "c", StringType.get()), required(4, "d", StringType.get()));
    org.apache.iceberg.Schema projectDrop = resolveSchema(original, null, asList("a", "c"));
    org.apache.iceberg.Schema expectedDrop = new org.apache.iceberg.Schema(required(2, "b", StructType.of(required(5, "b.a", StringType.get()))), required(4, "d", StringType.get()));
    assertTrue(projectDrop.sameSchema(expectedDrop));
    org.apache.iceberg.Schema projectKeep = resolveSchema(original, asList("a", "c"), null);
    org.apache.iceberg.Schema expectedKeep = new org.apache.iceberg.Schema(required(1, "a", StringType.get()), required(3, "c", StringType.get()));
    assertTrue(projectKeep.sameSchema(expectedKeep));
}

