@Test
public void testTimestampWithZone() {
    String val = "2024-10-08T13:18:20.053+03:27";
    DateTime dateTime = DateTime.parse(val);
    OffsetDateTime offsetDateTime = OffsetDateTime.parse(val);
    LocalDateTime localDateTime = offsetDateTime.withOffsetSameInstant(ZoneOffset.UTC).toLocalDateTime();
    // SqlTypes.DATETIME
    checkRowValueToRecordValue(Schema.FieldType.logicalType(SqlTypes.DATETIME), localDateTime, Types.TimestampType.withZone(), offsetDateTime.withOffsetSameInstant(ZoneOffset.UTC));
    // Schema.FieldType.DATETIME
    checkRowValueToRecordValue(Schema.FieldType.DATETIME, dateTime, Types.TimestampType.withZone(), offsetDateTime.withOffsetSameInstant(ZoneOffset.UTC));
    // Schema.FieldType.INT64
    checkRowValueToRecordValue(Schema.FieldType.INT64, DateTimeUtil.microsFromTimestamptz(offsetDateTime), Types.TimestampType.withZone(), offsetDateTime.withOffsetSameInstant(ZoneOffset.UTC));
    // Schema.FieldType.STRING
    checkRowValueToRecordValue(Schema.FieldType.STRING, val, Types.TimestampType.withZone(), offsetDateTime.withOffsetSameInstant(ZoneOffset.UTC));
}

