    Map<String, List<Record>> data = ImmutableMap.<String, List<Record>>builder().put("files1s1.parquet", TestFixtures.FILE1SNAPSHOT1).put("file2s2.parquet", TestFixtures.FILE2SNAPSHOT2).put("file3s3.parquet", TestFixtures.FILE3SNAPSHOT3).build();
