}

@Test
public void testResolveFromSnapshotExclusive() throws IOException {
    TableIdentifier tableId = TableIdentifier.of("default", testName.getMethodName());
    Table simpleTable = warehouse.createTable(tableId, TestFixtures.SCHEMA);
    // creates 4 snapshots
    warehouse.commitData(simpleTable);
    List<Snapshot> snapshots = Lists.newArrayList(simpleTable.snapshots()).stream().sorted(Comparator.comparingLong(Snapshot::sequenceNumber)).collect(Collectors.toList());
    ;
    Snapshot earliest = snapshots.get(0);
    Snapshot third = snapshots.get(2);
    Snapshot latest = snapshots.get(3);
    IcebergScanConfig baseScanConfig = IcebergScanConfig.builder().setCatalogConfig(IcebergCatalogConfig.builder().build()).setScanType(IcebergScanConfig.ScanType.TABLE).setTableIdentifier(tableId).setSchema(IcebergUtils.icebergSchemaToBeamSchema(simpleTable.schema())).build();
    IcebergScanConfig streamingScanConfig = baseScanConfig.toBuilder().setStreaming(true).build();
    // Note that the incremental append scan is configured with an _exclusive_ starting snapshot,
    // so we always return the _parent_ of the target snapshot.
    List<TestCase> scanConfigCases = Arrays.asList(// batch
    TestCase.of(baseScanConfig, earliest.parentId(), "default batch read"), TestCase.of(baseScanConfig.toBuilder().setFromSnapshotInclusive(third.snapshotId()).build(), third.parentId(), "batch with from_snapshot"), TestCase.of(baseScanConfig.toBuilder().setFromTimestamp(third.timestampMillis()).build(), third.parentId(), "batch with from_timestamp"), TestCase.of(baseScanConfig.toBuilder().setStartingStrategy(EARLIEST).build(), earliest.parentId(), "batch with starting_strategy=earliest"), TestCase.of(baseScanConfig.toBuilder().setStartingStrategy(LATEST).build(), latest.parentId(), "batch with starting_strategy=latest"), // streaming
    TestCase.of(streamingScanConfig, latest.parentId(), "default streaming read"), TestCase.of(streamingScanConfig.toBuilder().setFromSnapshotInclusive(third.snapshotId()).build(), third.parentId(), "streaming with from_snapshot"), TestCase.of(streamingScanConfig.toBuilder().setFromTimestamp(third.timestampMillis()).build(), third.parentId(), "streaming with from_timestamp"), TestCase.of(streamingScanConfig.toBuilder().setStartingStrategy(EARLIEST).build(), earliest.parentId(), "streaming with starting_strategy=earliest"), TestCase.of(streamingScanConfig.toBuilder().setStartingStrategy(LATEST).build(), latest.parentId(), "streaming with starting_strategy=latest"));
    List<String> errors = new ArrayList<>();
    for (TestCase testCase : scanConfigCases) {
        @Nullable
        Long snapshotId = ReadUtils.getFromSnapshotExclusive(simpleTable, testCase.scanConfig);
        if (!Objects.equals(testCase.expectedSnapshotId, snapshotId)) {
            errors.add(String.format("\t%s: expected %s but got %s", testCase.description, testCase.expectedSnapshotId, snapshotId));
        }
    }
    if (!errors.isEmpty()) {
        List<Long> snapshotIds = snapshots.stream().map(Snapshot::snapshotId).collect(Collectors.toList());
        throw new RuntimeException("Errors for table with snapshots " + snapshotIds + ". Test cases that failed:\n" + String.join("\n", errors));
    }
}

