@Test
public void testIdentityPartitioning() throws IOException {
    Schema primitiveTypeSchema = Schema.builder().addBooleanField("bool").addInt32Field("int").addInt64Field("long").addFloatField("float").addDoubleField("double").addStringField("str").addLogicalTypeField("date", SqlTypes.DATE).addLogicalTypeField("time", SqlTypes.TIME).addLogicalTypeField("datetime", SqlTypes.DATETIME).addDateTimeField("datetime_tz").build();
    String timestamp = "2025-01-21T13:18:20.053";
    LocalDateTime localDateTime = LocalDateTime.parse(timestamp);
    Row row = Row.withSchema(primitiveTypeSchema).addValues(true, 1, 1L, 1.23f, 4.56, "str", localDateTime.toLocalDate(), localDateTime.toLocalTime(), localDateTime, DateTime.parse(timestamp)).build();
    org.apache.iceberg.Schema icebergSchema = IcebergUtils.beamSchemaToIcebergSchema(primitiveTypeSchema);
    PartitionSpec spec = PartitionSpec.builderFor(icebergSchema).identity("bool").identity("int").identity("long").identity("float").identity("double").identity("str").identity("date").identity("time").identity("datetime").identity("datetime_tz").build();
    WindowedValue<IcebergDestination> dest = getWindowedDestination("identity_partitioning", icebergSchema, spec);
    RecordWriterManager writer = new RecordWriterManager(catalog, "test_prefix", Long.MAX_VALUE, Integer.MAX_VALUE);
    writer.write(dest, row);
    writer.close();
    List<SerializableDataFile> files = writer.getSerializableDataFiles().get(dest);
    assertEquals(1, files.size());
    SerializableDataFile dataFile = files.get(0);
    assertEquals(1, dataFile.getRecordCount());
    // build this string: bool=true/int=1/long=1/float=1.0/double=1.0/str=str
    List<String> expectedPartitions = new ArrayList<>();
    for (PartitionField field : spec.fields()) {
        String name = field.name();
        Type type = spec.schema().findType(name);
        Transform<Object, Object> transform = (Transform<Object, Object>) field.transform();
        String val;
        switch(name) {
            case "date":
                LocalDate localDate = checkStateNotNull(row.getValue(name));
                Integer day = Integer.parseInt(String.valueOf(localDate.toEpochDay()));
                val = transform.toHumanString(type, day);
                break;
            case "time":
                LocalTime localTime = checkStateNotNull(row.getValue(name));
                val = transform.toHumanString(type, localTime.toNanoOfDay() / 1000);
                break;
            case "datetime":
                LocalDateTime ldt = checkStateNotNull(row.getValue(name));
                val = transform.toHumanString(type, DateTimeUtil.microsFromTimestamp(ldt));
                break;
            case "datetime_tz":
                ReadableDateTime dt = checkStateNotNull(row.getDateTime(name));
                val = transform.toHumanString(type, dt.getMillis() * 1000);
                break;
            default:
                val = transform.toHumanString(type, checkStateNotNull(row.getValue(name)));
                break;
        }
        expectedPartitions.add(name + "=" + URLEncoder.encode(val, UTF_8.toString()));
    }
    String expectedPartitionPath = String.join("/", expectedPartitions);
    assertEquals(expectedPartitionPath, dataFile.getPartitionPath());
    assertThat(dataFile.getPath(), containsString(expectedPartitionPath));
}

