@Test
public void testTimePartitioning() throws IOException {
    Schema timePartitioningSchema = Schema.builder().addLogicalTypeField("y_date", SqlTypes.DATE).addLogicalTypeField("y_datetime", SqlTypes.DATETIME).addDateTimeField("y_datetime_tz").addLogicalTypeField("m_date", SqlTypes.DATE).addLogicalTypeField("m_datetime", SqlTypes.DATETIME).addDateTimeField("m_datetime_tz").addLogicalTypeField("d_date", SqlTypes.DATE).addLogicalTypeField("d_datetime", SqlTypes.DATETIME).addDateTimeField("d_datetime_tz").addLogicalTypeField("h_datetime", SqlTypes.DATETIME).addDateTimeField("h_datetime_tz").build();
    org.apache.iceberg.Schema icebergSchema = IcebergUtils.beamSchemaToIcebergSchema(timePartitioningSchema);
    PartitionSpec spec = PartitionSpec.builderFor(icebergSchema).year("y_date").year("y_datetime").year("y_datetime_tz").month("m_date").month("m_datetime").month("m_datetime_tz").day("d_date").day("d_datetime").day("d_datetime_tz").hour("h_datetime").hour("h_datetime_tz").build();
    WindowedValue<IcebergDestination> dest = getWindowedDestination("time_partitioning", icebergSchema, spec);
    String timestamp = "2024-10-08T13:18:20.053";
    LocalDateTime localDateTime = LocalDateTime.parse(timestamp);
    LocalDate localDate = localDateTime.toLocalDate();
    String timestamptz = "2024-10-08T13:18:20.053+03:27";
    DateTime dateTime = DateTime.parse(timestamptz);
    Row row = Row.withSchema(timePartitioningSchema).addValues(localDate, localDateTime, // year
    dateTime).addValues(localDate, localDateTime, // month
    dateTime).addValues(localDate, localDateTime, // day
    dateTime).addValues(localDateTime, // hour
    dateTime).build();
    // write some rows
    RecordWriterManager writer = new RecordWriterManager(catalog, "test_prefix", Long.MAX_VALUE, Integer.MAX_VALUE);
    writer.write(dest, row);
    writer.close();
    List<SerializableDataFile> files = writer.getSerializableDataFiles().get(dest);
    assertEquals(1, files.size());
    SerializableDataFile serializableDataFile = files.get(0);
    assertEquals(1, serializableDataFile.getRecordCount());
    int year = localDateTime.getYear();
    int month = localDateTime.getMonthValue();
    int day = localDateTime.getDayOfMonth();
    int hour = localDateTime.getHour();
    List<String> expectedPartitions = new ArrayList<>();
    for (Schema.Field field : timePartitioningSchema.getFields()) {
        String name = field.getName();
        String expected = "";
        if (name.startsWith("y_")) {
            expected = String.format("%s_year=%s", name, year);
        } else if (name.startsWith("m_")) {
            expected = String.format("%s_month=%s-%02d", name, year, month);
        } else if (name.startsWith("d_")) {
            expected = String.format("%s_day=%s-%02d-%02d", name, year, month, day);
        } else if (name.startsWith("h_")) {
            if (name.contains("tz")) {
                hour = dateTime.withZone(DateTimeZone.UTC).getHourOfDay();
            }
            expected = String.format("%s_hour=%s-%02d-%02d-%02d", name, year, month, day, hour);
        }
        expectedPartitions.add(expected);
    }
    String expectedPartition = String.join("/", expectedPartitions);
    DataFile dataFile = serializableDataFile.createDataFile(catalog.loadTable(dest.getValue().getTableIdentifier()).specs());
    assertThat(dataFile.path().toString(), containsString(expectedPartition));
}

@Test
public void testWriterExceptionGetsCaught() throws IOException {
    RecordWriterManager writerManager = new RecordWriterManager(catalog, "test_file_name", 100, 2);
    Row row = Row.withSchema(BEAM_SCHEMA).addValues(1, "abcdef", true).build();
    PartitionKey partitionKey = new PartitionKey(PARTITION_SPEC, ICEBERG_SCHEMA);
    partitionKey.partition(IcebergUtils.beamRowToIcebergRecord(ICEBERG_SCHEMA, row));
    writerManager.write(windowedDestination, row);
    RecordWriterManager.DestinationState state = writerManager.destinations.get(windowedDestination);
    // replace with a failing record writer
    FailingRecordWriter failingWriter = new FailingRecordWriter(catalog, windowedDestination.getValue(), "test_failing_writer", partitionKey);
    state.writers.put(partitionKey, failingWriter);
    writerManager.write(windowedDestination, row);
    // this tests that we indeed enter the catch block
    thrown.expect(IllegalStateException.class);
    thrown.expectMessage("Encountered 1 failed writer(s)");
    try {
        writerManager.close();
    } catch (IllegalStateException e) {
        // fetch underlying exceptions and validate
        Throwable[] underlyingExceptions = e.getSuppressed();
        assertEquals(1, underlyingExceptions.length);
        for (Throwable t : underlyingExceptions) {
            assertThat(t.getMessage(), containsString("Encountered an error when closing data writer for table"));
            assertThat(t.getMessage(), containsString(windowedDestination.getValue().getTableIdentifier().toString()));
            assertThat(t.getMessage(), containsString(failingWriter.path()));
            Throwable realCause = t.getCause();
            assertEquals("I am failing!", realCause.getMessage());
        }
        throw e;
    }
}

