@Test
public void testFieldsInEqualsMethodInSyncWithGetterFields() {
    List<String> getMethodNames = Arrays.stream(SerializableDataFile.class.getDeclaredMethods()).map(Method::getName).filter(methodName -> methodName.startsWith("get")).collect(Collectors.toList());
    List<String> lowerCaseFields = FIELDS_SET.stream().map(String::toLowerCase).collect(Collectors.toList());
    List<String> extras = new ArrayList<>();
    for (String field : getMethodNames) {
        if (!lowerCaseFields.contains(field.substring(3).toLowerCase())) {
            extras.add(field);
        }
    }
    if (!extras.isEmpty()) {
        throw new IllegalStateException("Detected new field(s) added to SerializableDataFile: " + extras + "\nPlease include the new field(s) in SerializableDataFile's equals() and hashCode() methods, then add them " + "to this test class's FIELDS_SET.");
    }
}

