    schemaBuilder.addField("column_double", Schema.FieldType.DOUBLE.withNullable(true));
    schemaBuilder.addField("column_decimal", FieldType.logicalType(FixedPrecisionNumeric.of(13, 0)).withNullable(true));
    Schema schema = schemaBuilder.build();
    // some types not supported in derby (e.g. tinyint) are not tested here
    String tableName = DatabaseTestHelper.getTestTableName("UT_READ_NULLABLE_LG");
    StringBuilder stmt = new StringBuilder("CREATE TABLE ");
    stmt.append(tableName);
    stmt.append(" (");
    // Integer
    stmt.append("column_id      INTEGER NOT NULL,");
    // int64
    stmt.append("column_bigint  BIGINT,");
    // boolean
    stmt.append("column_boolean BOOLEAN,");
    // float
    stmt.append("column_float  REAL,");
    // double
    stmt.append("column_double  DOUBLE PRECISION,");
    // BigDecimal
    stmt.append("column_decimal    DECIMAL(13,0)");
    stmt.append(" )");
    DatabaseTestHelper.createTableWithStatement(DATA_SOURCE, stmt.toString());
    final int rowsToAdd = 10;
    try {
        // run write pipeline
        ArrayList<Row> data = getNullableRowsToWrite(rowsToAdd, schema);
        pipeline.apply(Create.of(data)).setRowSchema(schema).apply(JdbcIO.<Row>write().withDataSourceConfiguration(DATA_SOURCE_CONFIGURATION).withBatchSize(10L).withTable(tableName));
        pipeline.run();
        assertRowCount(DATA_SOURCE, tableName, rowsToAdd);
        // run read pipeline
        PCollection<Row> rows = secondPipeline.apply(JdbcIO.readRows().withDataSourceConfiguration(DATA_SOURCE_CONFIGURATION).withQuery("SELECT * FROM " + tableName));
        PAssert.thatSingleton(rows.apply("Count All", Count.globally())).isEqualTo((long) rowsToAdd);
        PAssert.that(rows).containsInAnyOrder(data);
        secondPipeline.run();
    } finally {
        DatabaseTestHelper.deleteTable(DATA_SOURCE, tableName);
    }
}

