    config.setJdbcUrl("jdbc:mysql:///db");
    config.setUsername("root");
    config.addDataSourceProperty("cloudSqlInstance", "some-project:US:instance-name");
    // instead of `new HikariDataSource(config)`, initialize an empty source to avoid creation
    // of actual connection pool
    DataSource dataSource = new HikariDataSource();
    config.validate();
    config.copyStateTo((HikariConfig) dataSource);
    JdbcUtil.FQNComponents components = JdbcUtil.FQNComponents.of(dataSource);
    assertEquals("cloudsql_mysql", components.getScheme());
    assertEquals(ImmutableList.of("some-project", "US", "instance-name", "db"), components.getSegments());
}

@Test
public void testExtractTableFromQuery() {
    ImmutableList<KV<String, @Nullable KV<String, String>>> readCases = ImmutableList.of(KV.of("select * from table_1", KV.of(null, "table_1")), KV.of("select * from public.table_1", KV.of("public", "table_1")), KV.of("select * from `select`", KV.of(null, "select")), KV.of("select * from `public`.`select`", KV.of("public", "select")), KV.of("SELECT a, b FROM [table-2]", KV.of(null, "table-2")), KV.of("SELECT a, b FROM [public].[table-2]", KV.of("public", "table-2")), KV.of("drop table not-select", null));
    for (KV<String, @Nullable KV<String, String>> testCase : readCases) {
        assertEquals(testCase.getValue(), JdbcUtil.extractTableFromReadQuery(testCase.getKey()));
    }
    ImmutableList<KV<String, @Nullable KV<String, String>>> writeCases = ImmutableList.of(KV.of("insert into table_1 values ...", KV.of(null, "table_1")), KV.of("INSERT INTO [table-2] values ...", KV.of(null, "table-2")), KV.of("INSERT INTO [foo].[table-2] values ...", KV.of("foo", "table-2")), KV.of("drop table not-select", null));
    for (KV<String, @Nullable KV<String, String>> testCase : writeCases) {
        assertEquals(testCase.getValue(), JdbcUtil.extractTableFromWriteQuery(testCase.getKey()));
    }
}

