@Test
public void testCustomRowDeserializerWithViaSDF() throws IOException {
    // This test verifies that the SDF implementation of KafkaIO correctly handles
    // custom deserializers with explicit coders. It uses a Row deserializer which
    // requires an explicit coder to be provided since Beam cannot infer one automatically.
    // The test ensures that both the deserializer and coder are properly passed to
    // the ReadSourceDescriptors transform.
    // Create a simple Row schema for test
    Schema testSchema = Schema.builder().addStringField("field1").addInt32Field("field2").build();
    RowCoder rowCoder = RowCoder.of(testSchema);
    // Set up sample data
    String testId = UUID.randomUUID().toString();
    String topicName = options.getKafkaTopic() + "-row-deserializer-" + testId;
    // Create test data
    Map<String, Row> testData = new HashMap<>();
    for (int i = 0; i < 5; i++) {
        testData.put("key" + i, Row.withSchema(testSchema).withFieldValue("field1", "value" + i).withFieldValue("field2", i).build());
    }
    // Write the test data to Kafka using a custom serializer
    writePipeline.apply("Create test data", Create.of(testData)).apply("Write to Kafka", KafkaIO.<String, Row>write().withBootstrapServers(options.getKafkaBootstrapServerAddresses()).withTopic(topicName).withKeySerializer(StringSerializer.class).withValueSerializer(RowSerializer.class).withProducerConfigUpdates(ImmutableMap.of("test.schema", testSchema.toString())));
    PipelineResult writeResult = writePipeline.run();
    writeResult.waitUntilFinish();
    // Read the data using SDF-based KafkaIO with a custom deserializer
    PCollection<KV<String, Row>> resultSDF = sdfReadPipeline.apply("Read from Kafka via SDF", KafkaIO.<String, Row>read().withBootstrapServers(options.getKafkaBootstrapServerAddresses()).withTopic(topicName).withConsumerConfigUpdates(ImmutableMap.of("auto.offset.reset", "earliest", "test.schema", testSchema.toString())).withKeyDeserializer(StringDeserializer.class).withValueDeserializerAndCoder(RowDeserializer.class, rowCoder).withoutMetadata());
    // Compare with the original data
    PAssert.that(resultSDF).containsInAnyOrder(testData.entrySet().stream().map(entry -> KV.of(entry.getKey(), entry.getValue())).collect(Collectors.toList()));
    // Run and verify
    PipelineResult resultSDFResult = sdfReadPipeline.run();
    PipelineResult.State resultSDFState = resultSDFResult.waitUntilFinish(Duration.standardSeconds(options.getReadTimeout()));
    cancelIfTimeouted(resultSDFResult, resultSDFState);
    assertNotEquals(PipelineResult.State.FAILED, resultSDFState);
    // Clean up
    tearDownTopic(topicName);
}

