// This test verifies that the schema for KafkaReadSchemaTransformConfiguration is correctly
// generated. This schema is used when KafkaReadSchemaTransformConfiguration are
// serialized/deserialized with
// SchemaCoder.
@Test
public void testKafkaReadSchemaTransformConfigurationSchema() throws NoSuchSchemaException {
    Schema schema = SchemaRegistry.createDefault().getSchema(KafkaReadSchemaTransformConfiguration.class);
    assertEquals(17, schema.getFieldCount());
    // Check field name, type, and nullability. Descriptions are not checked as they are not
    // critical for serialization.
    assertEquals(Schema.Field.of("bootstrapServers", Schema.FieldType.STRING).withDescription(schema.getField(0).getDescription()), schema.getField(0));
    assertEquals(Schema.Field.nullable("confluentSchemaRegistryUrl", Schema.FieldType.STRING).withDescription(schema.getField(1).getDescription()), schema.getField(1));
    assertEquals(Schema.Field.nullable("format", Schema.FieldType.STRING).withDescription(schema.getField(2).getDescription()), schema.getField(2));
    assertEquals(Schema.Field.nullable("confluentSchemaRegistrySubject", Schema.FieldType.STRING).withDescription(schema.getField(3).getDescription()), schema.getField(3));
    assertEquals(Schema.Field.nullable("schema", Schema.FieldType.STRING).withDescription(schema.getField(4).getDescription()), schema.getField(4));
    assertEquals(Schema.Field.nullable("fileDescriptorPath", Schema.FieldType.STRING).withDescription(schema.getField(5).getDescription()), schema.getField(5));
    assertEquals(Schema.Field.nullable("messageName", Schema.FieldType.STRING).withDescription(schema.getField(6).getDescription()), schema.getField(6));
    assertEquals(Schema.Field.nullable("autoOffsetResetConfig", Schema.FieldType.STRING).withDescription(schema.getField(7).getDescription()), schema.getField(7));
    assertEquals(Schema.Field.nullable("consumerConfigUpdates", Schema.FieldType.map(Schema.FieldType.STRING, Schema.FieldType.STRING)).withDescription(schema.getField(8).getDescription()), schema.getField(8));
    assertEquals(Schema.Field.of("topic", Schema.FieldType.STRING).withDescription(schema.getField(9).getDescription()), schema.getField(9));
