public void testReadDeclaredTopicExchange() throws Exception {
    final int numRecords = 10;
    RabbitMqIO.Read read = RabbitMqIO.read().withExchange("DeclaredTopicExchange", "topic", "user.create.#");
    final Supplier<String> publishRoutingKeyGen = new Supplier<String>() {

        private AtomicInteger counter = new AtomicInteger(0);

        @Override
        public String get() {
            int count = counter.getAndIncrement();
            if (count % 2 == 0) {
                return "user.create." + count;
            }
            return "user.delete." + count;
        }
    };
    ExchangeTestPlan plan = new ExchangeTestPlan(read, numRecords / 2, numRecords) {

        @Override
        public Supplier<String> publishRoutingKeyGen() {
            return publishRoutingKeyGen;
        }

