@Test
public void givenCallerOnly_thenProcessesRequestsWithDefaultFeatures() {
    Caller<Request, Response> caller = new CallerImpl();
    RequestResponseIO<Request, Response> transform = RequestResponseIO.of(caller, RESPONSE_CODER).withMonitoringConfiguration(Monitoring.builder().build().withEverythingCountedExceptedCaching());
    Result<Response> result = requests().apply("rrio", transform);
    PAssert.that(result.getFailures()).empty();
    PAssert.that(result.getResponses()).containsInAnyOrder(responses());
    PipelineResult pipelineResult = pipeline.run();
    MetricResults metrics = pipelineResult.metrics();
    pipelineResult.waitUntilFinish();
    assertThat(getCounterResult(metrics, Call.class, Monitoring.REQUESTS_COUNTER_NAME), greaterThan(0L));
    assertThat(getCounterResult(metrics, Call.class, Monitoring.RESPONSES_COUNTER_NAME), greaterThan(0L));
    assertThat(getCounterResult(metrics, Call.class, Monitoring.callCounterNameOf(caller)), greaterThan(0L));
    assertThat(getCounterResult(metrics, Call.class, Monitoring.setupCounterNameOf(new Call.NoopSetupTeardown())), greaterThan(0L));
    // We expect remaining metrics to be 0.
    assertThat(getCounterResult(metrics, Call.class, Monitoring.FAILURES_COUNTER_NAME), equalTo(0L));
    assertThat(getCounterResult(metrics, Call.class, Monitoring.shouldBackoffCounterName(transform.getCallConfiguration().getCallShouldBackoff())), equalTo(0L));
    assertThat(getCounterResult(metrics, Call.class, Monitoring.sleeperCounterNameOf(transform.getCallConfiguration().getSleeperSupplier().get())), equalTo(0L));
    assertThat(getCounterResult(metrics, Call.class, Monitoring.backoffCounterNameOf(transform.getCallConfiguration().getBackOffSupplier().get())), equalTo(0L));
}

