    Mockito.when(res.getTimestamp(Mockito.eq(9), Mockito.any())).thenReturn(Timestamp.valueOf("2022-10-10 10:10:10"));
    Mockito.when(res.getObject(10, java.time.LocalDate.class)).thenReturn(LocalDate.of(2022, 10, 10));
