    addElements(event(SECOND_WIN_WORDS.get(0), 67L), event(SECOND_WIN_WORDS.get(1), 68L)).advanceWatermarkToInfinity();
    dataSourceConfiguration = SnowflakeIO.DataSourceConfiguration.create().withKeyPairPathAuth(options.getUsername(), TestUtils.getValidEncryptedPrivateKeyPath(getClass()), TestUtils.getPrivateKeyPassphrase()).withServerName(options.getServerName()).withSchema("PUBLIC").withDatabase("DATABASE").withWarehouse("WAREHOUSE");
    pipeline.apply(stringsStream).apply(Window.into(FixedWindows.of(WINDOW_DURATION))).apply(SnowflakeIO.<String>write().withDataSourceConfiguration(dataSourceConfiguration).withStagingBucketName(STAGING_BUCKET_NAME).withStorageIntegrationName(STORAGE_INTEGRATION_NAME).withSnowPipe(SNOW_PIPE).withFlushRowLimit(4).withFlushTimeLimit(WINDOW_DURATION).withUserDataMapper(TestUtils.getStringCsvMapper()).withSnowflakeServices(snowflakeServices));
    pipeline.run(options).waitUntilFinish();
    List<String> actualDataFirstWin = parseResults(FakeSnowflakeDatabase.getElements(String.format(FAKE_TABLE)), quotationMark);
    Map<String, List<String>> mapOfResults = getMapOfFilesAndResults();
    String firstFileKey = "0";
    List<String> filesResult = parseResults(mapOfResults.get(firstFileKey), quotationMark);
    int amountOfCreatedFiles = 2;
    MatcherAssert.assertThat(mapOfResults.size(), equalTo(amountOfCreatedFiles));
    MatcherAssert.assertThat(filesResult, equalTo(FIRST_WIN_WORDS));
    MatcherAssert.assertThat(actualDataFirstWin, equalTo(SENTENCES));
}

