/**
 * This test verifies ability to create a custom {@link
 * org.apache.beam.sdk.io.solace.broker.SessionServiceFactory} and presents an example of doing
 * that with the custom {@link FixedCredentialsBasicAuthJcsmpSessionServiceFactory}.
 */
@Test
public void test01writeAndReadWithCustomSessionServiceFactory() {
    Pipeline writerPipeline = createWriterPipeline(WriterType.BATCHED);
    writerPipeline.apply("Read from Solace", SolaceIO.read().from(Queue.fromName(QUEUE_NAME)).withMaxNumConnections(1).withDeduplicateRecords(true).withSempClientFactory(BasicAuthSempClientFactory.builder().host("http://localhost:" + solaceContainerManager.sempPortMapped).username("admin").password("admin").vpnName(SolaceContainerManager.VPN_NAME).build()).withSessionServiceFactory(new FixedCredentialsBasicAuthJcsmpSessionServiceFactory("localhost:" + solaceContainerManager.jcsmpPortMapped))).apply("Count", ParDo.of(new CountingFn<>(NAMESPACE, READ_COUNT)));
