@Test
public void testProtoTranslation() throws Exception {
    // First build a pipeline
    Pipeline p = Pipeline.create();
    Schema inputSchema = Schema.builder().addStringField("str").build();
    PCollection<Row> input = p.apply(Create.of(Arrays.asList(Row.withSchema(inputSchema).addValue("a").build(), Row.withSchema(inputSchema).addValue("b").build(), Row.withSchema(inputSchema).addValue("c").build()))).setRowSchema(inputSchema);
    Map<String, Object> underlyingConfig = ImmutableMap.<String, Object>builder().put("extra_string", "abc").put("extra_integer", 123).build();
    String yamlStringConfig = YamlUtils.yamlStringFromMap(underlyingConfig);
    Managed.ManagedTransform transform = // give a supported source to get around the check
    Managed.read(Managed.ICEBERG).withSupportedIdentifiers(Arrays.asList(TestSchemaTransformProvider.IDENTIFIER)).toBuilder().setIdentifier(TestSchemaTransformProvider.IDENTIFIER).build().withConfig(underlyingConfig);
    input.apply(transform);
    // Then translate the pipeline to a proto and extract the ManagedSchemaTransform's proto
    RunnerApi.Pipeline pipelineProto = PipelineTranslation.toProto(p);
    List<RunnerApi.PTransform> managedTransformProto = pipelineProto.getComponents().getTransformsMap().values().stream().filter(tr -> {
        RunnerApi.FunctionSpec spec = tr.getSpec();
        try {
            return spec.getUrn().equals(BeamUrns.getUrn(SCHEMA_TRANSFORM)) && SchemaTransformPayload.parseFrom(spec.getPayload()).getIdentifier().equals(PROVIDER.identifier());
        } catch (InvalidProtocolBufferException e) {
            throw new RuntimeException(e);
        }
    }).collect(Collectors.toList());
    assertEquals(1, managedTransformProto.size());
    RunnerApi.PTransform convertedTransform = managedTransformProto.get(0);
    // Check the transform proto contains the correct annotations.
    // These annotations can be accessed and used by the runner to make decisions
    Row managedConfigRow = Row.withSchema(PROVIDER.configurationSchema()).withFieldValue("transform_identifier", TestSchemaTransformProvider.IDENTIFIER).withFieldValue("config", yamlStringConfig).build();
    assertEquals(ImmutableSet.of(BeamUrns.getConstant(SCHEMATRANSFORM_URN_KEY), BeamUrns.getConstant(MANAGED_UNDERLYING_TRANSFORM_URN_KEY), BeamUrns.getConstant(CONFIG_ROW_KEY), BeamUrns.getConstant(CONFIG_ROW_SCHEMA_KEY)), convertedTransform.getAnnotationsMap().keySet());
    assertEquals(ByteString.copyFromUtf8(MANAGED_TRANSFORM_URN), convertedTransform.getAnnotationsMap().get(BeamUrns.getConstant(SCHEMATRANSFORM_URN_KEY)));
    assertEquals(ByteString.copyFromUtf8(TestSchemaTransformProvider.IDENTIFIER), convertedTransform.getAnnotationsMap().get(BeamUrns.getConstant(MANAGED_UNDERLYING_TRANSFORM_URN_KEY)));
    Schema annotationSchema = SchemaTranslation.schemaFromProto(SchemaApi.Schema.parseFrom(convertedTransform.getAnnotationsMap().get(BeamUrns.getConstant(CONFIG_ROW_SCHEMA_KEY))));
    assertEquals(PROVIDER.configurationSchema(), annotationSchema);
    assertEquals(managedConfigRow, CoderUtils.decodeFromByteString(RowCoder.of(annotationSchema), convertedTransform.getAnnotationsMap().get(BeamUrns.getConstant(CONFIG_ROW_KEY))));
    // Check that the spec proto contains correct values
    RunnerApi.FunctionSpec spec = convertedTransform.getSpec();
    SchemaTransformPayload payload = SchemaTransformPayload.parseFrom(spec.getPayload());
    assertEquals(PROVIDER.identifier(), payload.getIdentifier());
    Schema schemaFromSpec = SchemaTranslation.schemaFromProto(payload.getConfigurationSchema());
    assertEquals(PROVIDER.configurationSchema(), schemaFromSpec);
    Row rowFromSpec = RowCoder.of(schemaFromSpec).decode(payload.getConfigurationRow().newInput());
    // Translation logic outputs a Row with snake_case naming convention
    Row expectedRow = Row.withSchema(PROVIDER.configurationSchema()).withFieldValue("transform_identifier", TestSchemaTransformProvider.IDENTIFIER).withFieldValue("config_url", null).withFieldValue("config", yamlStringConfig).build();
    assertEquals(expectedRow, rowFromSpec);
    // Use the information in the proto to recreate the ManagedSchemaTransform
    ManagedSchemaTransformTranslator translator = new ManagedSchemaTransformTranslator();
    ManagedSchemaTransform transformFromSpec = translator.fromConfigRow(rowFromSpec, PipelineOptionsFactory.create());
    assertEquals(TestSchemaTransformProvider.IDENTIFIER, transformFromSpec.getManagedConfig().getTransformIdentifier());
    assertEquals(yamlStringConfig, transformFromSpec.getManagedConfig().getConfig());
    assertNull(transformFromSpec.getManagedConfig().getConfigUrl());
}

